/* ---- API Centro de Capacitación: contenido y archivos (guardado en carpeta local) ---- */
const CAPACITACION_DIR = path.join(__dirname, 'public', 'capacitacion');
const CAPACITACION_CONTENIDO_PATH = path.join(CAPACITACION_DIR, 'contenido.json');
const CAPACITACION_UPLOAD = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 60 * 1024 * 1024 }
});

function canRequestEditCapacitacion(req) {
    const session = readErpSessionFromRequest(req);
    if (session && isImplementerPermissionName(session.permissionName)) return true;
    const modules = readPermissionModulesFromRequest(req);
    if (!modules) return false;
    const capacitacion = sanitizePermissionAccess(modules['capacitacion']);
    const configGeneral = sanitizePermissionAccess(modules['configuracion-general']);
    return Boolean(capacitacion.edit || configGeneral.edit);
}

function sanitizeCapacitacionNombreArchivo(value) {
    const base = path.basename(String(value || 'archivo'));
    return base.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120) || 'archivo';
}

app.get('/capacitacion/api/contenido', (req, res) => {
    res.sendFile(CAPACITACION_CONTENIDO_PATH);
});

app.post('/capacitacion/api/contenido', async (req, res) => {
    try {
        if (!canRequestEditCapacitacion(req)) {
            return res.status(403).json({ error: 'No tienes permiso para editar la capacitación.' });
        }
        const datos = req.body;
        if (!datos || !Array.isArray(datos.categorias) || !Array.isArray(datos.articulos)) {
            return res.status(400).json({ error: 'Contenido inválido.' });
        }
        await fs.promises.writeFile(CAPACITACION_CONTENIDO_PATH, JSON.stringify(datos, null, 4), 'utf8');
        res.json({ ok: true });
    } catch (error) {
        console.error('[capacitacion] Error guardando contenido:', error);
        res.status(500).json({ error: 'Error guardando el contenido.' });
    }
});

app.post('/capacitacion/api/archivos', CAPACITACION_UPLOAD.single('archivo'), async (req, res) => {
    try {
        if (!canRequestEditCapacitacion(req)) {
            return res.status(403).json({ error: 'No tienes permiso para subir archivos a la capacitación.' });
        }
        const archivo = req.file;
        if (!archivo) return res.status(400).json({ error: 'No se recibió ningún archivo.' });

        const esVideo = String(archivo.mimetype || '').startsWith('video/');
        const carpeta = esVideo ? 'videos' : 'imagenes';
        const modulo = sanitizeCapacitacionNombreArchivo(req.body?.modulo || 'general').replace(/\.(png|jpe?g|gif|webp|mp4|webm|mov)$/i, '');
        const ext = path.extname(sanitizeCapacitacionNombreArchivo(archivo.originalname)).toLowerCase() || (esVideo ? '.mp4' : '.png');
        const nombreBase = Date.now() + '-' + Math.random().toString(36).slice(2, 8);
        const nombreArchivo = nombreBase + ext;

        const dirDestino = path.join(CAPACITACION_DIR, carpeta, modulo);
        await fs.promises.mkdir(dirDestino, { recursive: true });
        await fs.promises.writeFile(path.join(dirDestino, nombreArchivo), archivo.buffer);

        res.json({
            ok: true,
            tipo: esVideo ? 'video' : 'imagen',
            ruta: `/capacitacion/${carpeta}/${modulo}/${nombreArchivo}`,
            nombreOriginal: archivo.originalname
        });
    } catch (error) {
        console.error('[capacitacion] Error subiendo archivo:', error);
        res.status(500).json({ error: 'Error guardando el archivo.' });
    }
});
