async function ensureProductSkuSchema() {
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS product_departments (
            id SERIAL PRIMARY KEY,
            code TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            active BOOLEAN NOT NULL DEFAULT true,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS product_types (
            id SERIAL PRIMARY KEY,
            code TEXT NOT NULL,
            name TEXT NOT NULL,
            department_id INTEGER NOT NULL REFERENCES product_departments(id),
            active BOOLEAN NOT NULL DEFAULT true,
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            UNIQUE (code, department_id)
        )
    `);
    await pgQuery(`
        CREATE INDEX IF NOT EXISTS idx_product_types_department ON product_types(department_id);
    `);
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS product_sku_sequences (
            id SERIAL PRIMARY KEY,
            client_code TEXT NOT NULL,
            department_code TEXT NOT NULL,
            type_code TEXT NOT NULL,
            last_correlative INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            UNIQUE (client_code, department_code, type_code)
        )
    `);
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS product_lot_sequences (
            id SERIAL PRIMARY KEY,
            date_code TEXT NOT NULL UNIQUE,
            last_correlative INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    await pgQuery(`ALTER TABLE flexo_products ADD COLUMN IF NOT EXISTS finished_product_sku TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS finished_product_sku TEXT`);
    await pgQuery(`ALTER TABLE flexo_calculations ADD COLUMN IF NOT EXISTS finished_product_sku TEXT`);

    // Trazabilidad del origen del sustrato al momento de guardar el cálculo. Permite auditar
    // después de dónde salieron los datos: 'local' (tabla material del sistema) o 'sap'
    // (espejo de artículos de SAP). `sustrato_origen_config` guarda cómo estaba el interruptor
    // de "Origen de Inventario" en ese momento; `sustrato_sap_item_code` el código de artículo
    // de SAP si vino de ahí; `sustrato_ficha_origen` de dónde salieron ancho/gramaje/calibre.
    await pgQuery(`ALTER TABLE flexo_calculations ADD COLUMN IF NOT EXISTS sustrato_origen_inventario TEXT`);
    await pgQuery(`ALTER TABLE flexo_calculations ADD COLUMN IF NOT EXISTS sustrato_origen_config TEXT`);
    await pgQuery(`ALTER TABLE flexo_calculations ADD COLUMN IF NOT EXISTS sustrato_sap_item_code TEXT`);
    await pgQuery(`ALTER TABLE flexo_calculations ADD COLUMN IF NOT EXISTS sustrato_ficha_origen TEXT`);

    // Departamento del producto (nomenclatura / clasificación). El nombre viaja en
    // la columna existente `department`; `departamento_codigo` guarda el código de 2
    // dígitos (ej. '11' = Flexografía) derivado de product_departments. Se rellena
    // automáticamente vía trigger en cada INSERT/UPDATE, de modo que todo cálculo,
    // orden y producto queda identificado desde su creación sin selección manual.
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS department TEXT`);
    await pgQuery(`ALTER TABLE flexo_calculations ADD COLUMN IF NOT EXISTS departamento_codigo TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS departamento_codigo TEXT`);
    await pgQuery(`ALTER TABLE flexo_products ADD COLUMN IF NOT EXISTS departamento_codigo TEXT`);
    await pgQuery(`
        CREATE OR REPLACE FUNCTION flexo_set_departamento_codigo() RETURNS trigger AS $func$
        BEGIN
            IF (NEW.departamento_codigo IS NULL OR NEW.departamento_codigo = '')
               OR (TG_OP = 'UPDATE' AND NEW.department IS DISTINCT FROM OLD.department) THEN
                SELECT pd.code INTO NEW.departamento_codigo
                  FROM product_departments pd
                 WHERE LOWER(TRANSLATE(pd.name, 'áéíóúÁÉÍÓÚüÜñÑ', 'aeiouAEIOUuUnN'))
                     = LOWER(TRANSLATE(COALESCE(NULLIF(NEW.department, ''), 'Flexografia'), 'áéíóúÁÉÍÓÚüÜñÑ', 'aeiouAEIOUuUnN'))
                 LIMIT 1;
                IF NEW.departamento_codigo IS NULL THEN
                    NEW.departamento_codigo := '11';
                END IF;
            END IF;
            RETURN NEW;
        END;
        $func$ LANGUAGE plpgsql
    `);
    for (const tabla of ['flexo_calculations', 'flexo_orders', 'flexo_products']) {
        await pgQuery(`DROP TRIGGER IF EXISTS trg_${tabla}_departamento_codigo ON ${tabla}`);
        await pgQuery(`
            CREATE TRIGGER trg_${tabla}_departamento_codigo
            BEFORE INSERT OR UPDATE OF department, departamento_codigo ON ${tabla}
            FOR EACH ROW EXECUTE FUNCTION flexo_set_departamento_codigo()
        `);
    }
    // Backfill de filas existentes
    await pgQuery(`UPDATE flexo_orders SET department = COALESCE(NULLIF(raw_data->>'departamento', ''), NULLIF(raw_data->>'DEPARTAMENTO', ''), 'Flexografia') WHERE department IS NULL OR department = ''`);
    for (const tabla of ['flexo_calculations', 'flexo_orders', 'flexo_products']) {
        await pgQuery(`
            UPDATE ${tabla} SET departamento_codigo = COALESCE(
                (SELECT pd.code FROM product_departments pd
                  WHERE LOWER(TRANSLATE(pd.name, 'áéíóúÁÉÍÓÚüÜñÑ', 'aeiouAEIOUuUnN'))
                      = LOWER(TRANSLATE(COALESCE(NULLIF(${tabla}.department, ''), 'Flexografia'), 'áéíóúÁÉÍÓÚüÜñÑ', 'aeiouAEIOUuUnN'))
                  LIMIT 1),
                '11')
             WHERE departamento_codigo IS NULL OR departamento_codigo = ''
        `);
    }
    // Integración SAP: Orden de Venta (al liberar la orden), Producto Terminado y
    // Factura (al cerrar Empaque) — guardan el DocEntry devuelto por SAP para
    // cada documento. La factura se crea por copy-from de la Orden de Venta,
    // por eso necesita el DocEntry de esta última.
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_orden_venta_doc_entry TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_producto_terminado_doc_entry TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_factura_doc_entry TEXT`);
    // Artículo terminado (OITM) creado al generar la orden; BOM (OITT), Orden de
    // Producción (OWOR) y Salida de Materiales (IGE1) al liberar planificación.
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_articulo_creado TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_bom_creado TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_orden_produccion_doc_entry TEXT`);
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_salida_materiales_doc_entry TEXT`);
    // Paso 5: aviso "producto terminado listo, confirmar factura".
    await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS sap_factura_confirmacion TEXT`);

    // Muestras / Visto Bueno / Entrega en columnas tipadas (reemplazan raw_data
    // 'MUESTRAS | *' y 'ENTREGA | *'). Ver sql/migration-orden-entrega-direccion-columns.sql
    for (const col of [
        'muestras_tipo', 'muestras_detalle',
        'vb_direccion_nombre', 'vb_direccion_tipo', 'vb_direccion_pais',
        'vb_direccion_departamento', 'vb_direccion_zona', 'vb_direccion_codigo_postal',
        'entrega_tipo', 'entrega_contacto', 'entrega_telefono', 'entrega_correo', 'entrega_detalle',
        'entrega_direccion', 'entrega_direccion_nombre', 'entrega_direccion_tipo', 'entrega_direccion_pais',
        'entrega_direccion_departamento', 'entrega_direccion_zona', 'entrega_direccion_codigo_postal',
        'vb_direccion_subnivel', 'entrega_direccion_subnivel'
    ]) {
        await pgQuery(`ALTER TABLE flexo_orders ADD COLUMN IF NOT EXISTS ${col} TEXT`);
    }

    // Seed departments if empty
    const deptCount = await pgQuery(`SELECT COUNT(*) AS cnt FROM product_departments`);
    if (parseInt(deptCount.rows[0].cnt) === 0) {
        await pgQuery(`INSERT INTO product_departments (code, name, sort_order) VALUES ('10', 'Offset', 1)`);
        await pgQuery(`INSERT INTO product_departments (code, name, sort_order) VALUES ('11', 'Flexograf\u00eda', 2)`);
        await pgQuery(`INSERT INTO product_departments (code, name, sort_order) VALUES ('12', 'Digital', 3)`);
    }

    // Seed product types if empty
    const typeCount = await pgQuery(`SELECT COUNT(*) AS cnt FROM product_types`);
    if (parseInt(typeCount.rows[0].cnt) === 0) {
        const deptMap = {};
        const depts = await pgQuery(`SELECT id, code FROM product_departments`);
        depts.rows.forEach((r) => { deptMap[r.code] = r.id; });

        const flexoTypes = [
            ['01', 'Etiqueta'], ['02', 'Bolsa'], ['03', 'Caja'], ['04', 'Cinta Continua'],
            ['05', 'Plegadiza'], ['06', 'Saco'], ['07', 'Empaque Flexible'], ['08', 'Sobre'],
            ['09', 'Funda'], ['10', 'Stand'], ['11', 'Corrugado'], ['12', 'Exhibidor'],
            ['13', 'Etiqueta Termoencogible'], ['14', 'Etiqueta Sleeve'], ['15', 'Film'],
            ['16', 'Laminado'], ['17', 'Blister'], ['18', 'Display'], ['19', 'Cobertor'],
            ['20', 'Manga'], ['21', 'Bolsa Ziploc'], ['22', 'Cinta Adhesiva']
        ];
        for (const [code, name] of flexoTypes) {
            await pgQuery(`INSERT INTO product_types (code, name, department_id, sort_order) VALUES ($1, $2, $3, $4)`,
                [code, name, deptMap['11'], parseInt(code)]);
        }

        const offsetTypes = [
            ['01', 'Tarjeta'], ['02', 'Folleto'], ['03', 'Cat\u00e1logo'], ['04', 'Revista'],
            ['05', 'Libro'], ['06', 'Volante'], ['07', 'Afiche'], ['08', 'Folder'], ['09', 'Block']
        ];
        for (const [code, name] of offsetTypes) {
            await pgQuery(`INSERT INTO product_types (code, name, department_id, sort_order) VALUES ($1, $2, $3, $4)`,
                [code, name, deptMap['10'], parseInt(code)]);
        }

        const digitalTypes = [
            ['01', 'Impresi\u00f3n Digital'], ['02', 'Fotocopia'], ['03', 'Ploteado'],
            ['04', 'Lona'], ['05', 'Vinilo']
        ];
        for (const [code, name] of digitalTypes) {
            await pgQuery(`INSERT INTO product_types (code, name, department_id, sort_order) VALUES ($1, $2, $3, $4)`,
                [code, name, deptMap['12'], parseInt(code)]);
        }
    }
}

