// Calculadora y solicitud técnica de troquel: especificación técnica generada desde una
// cotización, independiente de si el troquel físico ya existe en el inventario `troquel`.
async function ensureCalculoTroquelSchema() {
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS calculo_troquel (
            id_calculo_troquel UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            codigo_calculo TEXT UNIQUE,
            quote_code TEXT NOT NULL,
            line_code TEXT NOT NULL,
            product_code TEXT,
            estado TEXT NOT NULL DEFAULT 'Borrador',
            origen TEXT,
            ancho_producto_in NUMERIC(10,4),
            alto_producto_in NUMERIC(10,4),
            forma TEXT,
            radio_esquina_in NUMERIC(10,4),
            cantidad NUMERIC(14,2),
            ancho_material_in NUMERIC(10,4),
            direccion_avance TEXT,
            separacion_lateral_in NUMERIC(10,4),
            separacion_longitudinal_in NUMERIC(10,4),
            margen_in NUMERIC(10,4),
            numero_cavidades INTEGER,
            numero_repeticiones INTEGER,
            paso_transversal_in NUMERIC(10,4),
            paso_longitudinal_in NUMERIC(10,4),
            desarrollo_in NUMERIC(10,4),
            ancho_total_in NUMERIC(10,4),
            alto_total_in NUMERIC(10,4),
            area_util_in2 NUMERIC(14,6),
            area_total_in2 NUMERIC(14,6),
            aprovechamiento_pct NUMERIC(10,4),
            id_troquel_fisico UUID REFERENCES troquel(id) ON DELETE SET NULL,
            codigo_troquel_fisico TEXT,
            id_orden_asociada TEXT,
            observaciones TEXT,
            usuario_creacion TEXT,
            fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            usuario_actualizacion TEXT,
            fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            fecha_solicitud_fabricacion TIMESTAMPTZ,
            fecha_troquel_creado TIMESTAMPTZ
        )
    `);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_calculo_troquel_quote_line ON calculo_troquel(quote_code, line_code)`);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_calculo_troquel_estado ON calculo_troquel(estado)`);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_calculo_troquel_orden ON calculo_troquel(id_orden_asociada)`);
    // Campos retirados: no aportaban al montaje del troquel (material/máquina ya viven en el
    // resto del cálculo; sangrado es un concepto de preprensa, no de troquelado; gap era
    // redundante con separación_longitudinal_in).
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS tipo_producto`);
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS orientacion`);
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS sangrado_in`);
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS material_code`);
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS espesor_in`);
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS machine_name`);
    await pgQuery(`ALTER TABLE calculo_troquel DROP COLUMN IF EXISTS gap_in`);
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS margen_in NUMERIC(10,4)`);
    // Dato informativo del troquel nuevo (dientes del cilindro porta-troquel); no afecta el
    // cálculo de montaje, solo se guarda para tenerlo registrado.
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS dientes INTEGER`);
    // Costo del troquel nuevo (no es de inventario, hay que cobrarlo): pulgadas lineales de
    // corte se calculan del perímetro de la figura, se multiplican por el costo configurado
    // por pulgada, y ese total es lo que se cobra en el proceso Troquel (modo Costo Externo).
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS pulgadas_lineales_in NUMERIC(10,4)`);
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS costo_pulgada_lineal NUMERIC(10,4)`);
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS costo_total_troquel NUMERIC(14,4)`);
    // Imagen del contorno de la forma Especial (data URL); el dibujo automático solo cubre
    // cuadrado/rectangular/circular/ovalado, para el resto el usuario carga el arte de preprensa.
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS imagen_contorno TEXT`);
    // Desarrollo total del rollo (dientes × paso del engranaje); dato informativo del montaje.
    await pgQuery(`ALTER TABLE calculo_troquel ADD COLUMN IF NOT EXISTS roll_repeat_in NUMERIC(10,4)`);
}

function normalizeAttachmentBase64(value) {
    return String(value || '')
        .trim()
        .replace(/^data:[^;]+;base64,/i, '')
        .replace(/\s/g, '');
}

function sanitizeStorageSegment(value, fallback) {
    const clean = String(value || '')
        .trim()
        .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
        .replace(/\s+/g, '_')
        .replace(/_+/g, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 80);
    return clean || fallback;
}

function sanitizeAttachmentFileName(fileName) {
    const clean = path.basename(String(fileName || 'archivo'))
        .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
        .trim()
        .slice(0, 180);
    return clean || 'archivo';
}

function ensureQuoteAttachmentStorageDir(quoteCode, lineCode) {
    const dir = path.join(
        QUOTE_ATTACHMENT_STORAGE_DIR,
        sanitizeStorageSegment(quoteCode, 'cotizacion'),
        sanitizeStorageSegment(lineCode, 'linea')
    );
    fs.mkdirSync(dir, { recursive: true });
    return dir;
}

function resolveQuoteAttachmentStoragePath(storagePath) {
    if (!storagePath) return '';
    const root = path.resolve(QUOTE_ATTACHMENT_STORAGE_DIR);
    const absolute = path.resolve(APP_ROOT, String(storagePath));
    if (absolute !== root && !absolute.startsWith(root + path.sep)) return '';
    return absolute;
}

function writeQuoteLineAttachmentFile({ id, quoteCode, lineCode, fileName, contentBase64 }) {
    const normalizedBase64 = normalizeAttachmentBase64(contentBase64);
    const buffer = Buffer.from(normalizedBase64, 'base64');
    if (!normalizedBase64 || !buffer.length) {
        throw new Error('Contenido del adjunto inválido.');
    }
    const safeFileName = sanitizeAttachmentFileName(fileName);
    const extension = path.extname(safeFileName);
    const storageDir = ensureQuoteAttachmentStorageDir(quoteCode, lineCode);
    const absolutePath = path.join(storageDir, `${id}${extension || ''}`);
    fs.writeFileSync(absolutePath, buffer);
    return {
        storagePath: path.relative(APP_ROOT, absolutePath).split(path.sep).join('/'),
        sizeBytes: buffer.length,
        contentSha256: crypto.createHash('sha256').update(buffer).digest('hex')
    };
}

function deleteQuoteAttachmentFile(storagePath) {
    const absolutePath = resolveQuoteAttachmentStoragePath(storagePath);
    if (!absolutePath) return;
    try {
        if (fs.existsSync(absolutePath) && fs.statSync(absolutePath).isFile()) {
            fs.unlinkSync(absolutePath);
        }
    } catch (error) {
        console.error('No fue posible eliminar el archivo adjunto local:', error.message);
    }
}

function deleteQuoteAttachmentFiles(rows) {
    (rows || []).forEach((row) => deleteQuoteAttachmentFile(row?.storage_path || row?.storagePath || row));
}

