// ── Archivos Técnicos del Panel de Diseño ────────────────────────────────────
// Sin blobs en la base de datos: los archivos viven en la carpeta base
// configurable (Configuración → Seguridad → Rutas de Archivos). La tabla
// diseno_archivos solo guarda metadatos + ruta relativa a esa carpeta base.
async function getDisenoArchivosBaseDir() {
    let configured = '';
    try {
        const cfg = await loadGeneralConfig();
        configured = String(cfg?.general?.disenoArchivosDir || '').trim();
    } catch (error) {
        configured = '';
    }
    const base = configured ? path.resolve(configured) : DISENO_ARCHIVOS_STORAGE_DIR_DEFAULT;
    return base;
}

// Archivos técnicos del Panel de Tintas: mismo patrón, carpeta base propia (sin config dedicada,
// a diferencia de Diseño). Reusa ensureDisenoArchivoDir/resolveDisenoArchivoAbsolutePath/
// writeDisenoArchivoFile/deleteDisenoArchivoFile de abajo — son genéricas (reciben baseDir).
async function getTintasArchivosBaseDir() {
    return TINTAS_ARCHIVOS_STORAGE_DIR_DEFAULT;
}

function ensureDisenoArchivoDir(baseDir, ordenCodigo) {
    const dir = path.join(baseDir, sanitizeStorageSegment(ordenCodigo, 'orden'));
    fs.mkdirSync(dir, { recursive: true });
    return dir;
}

function resolveDisenoArchivoAbsolutePath(baseDir, rutaAlmacenamiento) {
    if (!rutaAlmacenamiento) return '';
    const root = path.resolve(baseDir);
    const absolute = path.resolve(root, String(rutaAlmacenamiento).split('/').join(path.sep));
    if (absolute !== root && !absolute.startsWith(root + path.sep)) return '';
    return absolute;
}

function writeDisenoArchivoFile({ baseDir, id, ordenCodigo, fileName, contentBase64 }) {
    const normalizedBase64 = normalizeAttachmentBase64(contentBase64);
    const buffer = Buffer.from(normalizedBase64, 'base64');
    if (!normalizedBase64 || !buffer.length) {
        throw new Error('Contenido del archivo inválido.');
    }
    const safeFileName = sanitizeAttachmentFileName(fileName);
    const extension = path.extname(safeFileName);
    const storageDir = ensureDisenoArchivoDir(baseDir, ordenCodigo);
    const absolutePath = path.join(storageDir, `${id}${extension || ''}`);
    fs.writeFileSync(absolutePath, buffer);
    return {
        rutaAlmacenamiento: path.relative(path.resolve(baseDir), absolutePath).split(path.sep).join('/'),
        tamanoBytes: buffer.length,
        sha256: crypto.createHash('sha256').update(buffer).digest('hex')
    };
}

function deleteDisenoArchivoFile(baseDir, rutaAlmacenamiento) {
    const absolutePath = resolveDisenoArchivoAbsolutePath(baseDir, rutaAlmacenamiento);
    if (!absolutePath) return;
    try {
        if (fs.existsSync(absolutePath) && fs.statSync(absolutePath).isFile()) {
            fs.unlinkSync(absolutePath);
        }
    } catch (error) {
        console.error('No fue posible eliminar el archivo técnico de diseño:', error.message);
    }
}

async function describeDisenoArchivosDir() {
    const baseDir = await getDisenoArchivosBaseDir();
    let cfg = null;
    try { cfg = await loadGeneralConfig(); } catch (e) { cfg = null; }
    const configurado = String(cfg?.general?.disenoArchivosDir || '').trim();
    let existe = false;
    let escribible = false;
    try {
        existe = fs.existsSync(baseDir) && fs.statSync(baseDir).isDirectory();
    } catch (e) { existe = false; }
    try {
        fs.mkdirSync(baseDir, { recursive: true });
        const probe = path.join(baseDir, `.probe-${crypto.randomUUID()}`);
        fs.writeFileSync(probe, 'ok');
        fs.unlinkSync(probe);
        escribible = true;
        existe = true;
    } catch (e) { escribible = false; }
    return { rutaConfigurada: configurado, rutaEfectiva: baseDir, porDefecto: !configurado, existe, escribible };
}

