async function ensureAdjuntosExpedienteSchema() {
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS adjuntos (
            id UUID PRIMARY KEY,
            origen TEXT NOT NULL,
            tipo_documento TEXT,
            nombre_archivo TEXT NOT NULL,
            cliente_codigo TEXT,
            cliente_nombre TEXT,
            cotizacion_codigo TEXT,
            linea_codigo TEXT,
            orden_codigo TEXT,
            producto_codigo TEXT,
            anio INTEGER,
            mes INTEGER,
            ruta_relativa TEXT NOT NULL,
            mime TEXT,
            tamano_bytes BIGINT,
            sha256 TEXT,
            notas TEXT,
            subido_por TEXT,
            creado_en TIMESTAMPTZ DEFAULT NOW()
        )
    `);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_adjuntos_cotizacion ON adjuntos(cotizacion_codigo, linea_codigo)`);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_adjuntos_orden ON adjuntos(orden_codigo)`);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_adjuntos_producto ON adjuntos(producto_codigo)`);
}

function construirSubrutaExpediente(ctx = {}, origen = 'cotizacion') {
    const clienteSeg = sanitizeStorageSegment(
        [ctx.clienteCodigo, ctx.clienteNombre].filter(Boolean).join(' - '),
        'cliente-sin-identificar'
    );
    const anioSeg = sanitizeStorageSegment(String(ctx.anio || 'sin-fecha'), 'sin-fecha');
    const mesSeg = sanitizeStorageSegment(
        ctx.mes ? String(ctx.mes).padStart(2, '0') : 'sin-mes',
        'sin-mes'
    );
    const productoSeg = sanitizeStorageSegment(ctx.productoCarpeta || 'sin-producto', 'sin-producto');
    const origenSeg = ADJUNTO_ORIGENES.includes(origen) ? origen : 'cotizacion';
    return path.join(clienteSeg, anioSeg, mesSeg, productoSeg, origenSeg);
}

function resolverRutaAbsolutaAdjunto(baseDir, rutaRelativa) {
    if (!rutaRelativa) return '';
    const root = path.resolve(baseDir);
    const absolute = path.resolve(root, String(rutaRelativa).split('/').join(path.sep));
    if (absolute !== root && !absolute.startsWith(root + path.sep)) return '';
    return absolute;
}

function escribirArchivoAdjuntoExpediente({ baseDir, id, subruta, fileName, contentBase64 }) {
    const normalizedBase64 = normalizeAttachmentBase64(contentBase64);
    const buffer = Buffer.from(normalizedBase64, 'base64');
    if (!normalizedBase64 || !buffer.length) {
        throw new Error('Contenido del archivo inválido.');
    }
    const safeFileName = sanitizeAttachmentFileName(fileName);
    const extension = path.extname(safeFileName);
    const storageDir = path.join(baseDir, subruta);
    fs.mkdirSync(storageDir, { recursive: true });
    const absolutePath = path.join(storageDir, `${id}${extension || ''}`);
    fs.writeFileSync(absolutePath, buffer);
    return {
        rutaRelativa: path.relative(path.resolve(baseDir), absolutePath).split(path.sep).join('/'),
        tamanoBytes: buffer.length,
        sha256: crypto.createHash('sha256').update(buffer).digest('hex')
    };
}

function eliminarArchivoAdjuntoExpediente(baseDir, rutaRelativa) {
    const absolutePath = resolverRutaAbsolutaAdjunto(baseDir, rutaRelativa);
    if (!absolutePath) return;
    try {
        if (fs.existsSync(absolutePath) && fs.statSync(absolutePath).isFile()) {
            fs.unlinkSync(absolutePath);
        }
    } catch (error) {
        console.error('No fue posible eliminar el archivo adjunto del producto:', error.message);
    }
}

// Reúne los códigos de cotización/línea/orden/producto, rellenando los que falten,
// más el cliente y la fecha (año/mes) del expediente.
async function resolverContextoExpediente({ cotizacion, linea, orden, producto } = {}) {
    const ctx = {
        cotizacionCodigo: String(cotizacion || '').trim() || null,
        lineaCodigo: String(linea || '').trim() || null,
        ordenCodigo: String(orden || '').trim() || null,
        productoCodigo: String(producto || '').trim() || null,
        clienteCodigo: '',
        clienteNombre: '',
        anio: null,
        mes: null,
        productoNombre: '',
        productoCarpeta: ''
    };

    let fechaExpediente = null;

    if (ctx.ordenCodigo) {
        const row = (await pgQuery(
            `SELECT quote_code, line_code, product_code, customer_code, customer_name, job_name, created_at
               FROM flexo_orders WHERE order_code = $1 LIMIT 1`,
            [ctx.ordenCodigo]
        )).rows[0];
        if (row) {
            ctx.cotizacionCodigo = ctx.cotizacionCodigo || row.quote_code || null;
            ctx.lineaCodigo = ctx.lineaCodigo || row.line_code || null;
            ctx.productoCodigo = ctx.productoCodigo || row.product_code || null;
            if (row.customer_code) ctx.clienteCodigo = row.customer_code;
            if (row.customer_name) ctx.clienteNombre = row.customer_name;
            if (row.job_name) ctx.productoNombre = row.job_name;
            fechaExpediente = fechaExpediente || row.created_at;
        }
    }

    if (ctx.productoCodigo) {
        const row = (await pgQuery(
            `SELECT quote_code, line_code, client_code, client_name, product_name, created_at
               FROM flexo_products WHERE product_code = $1 LIMIT 1`,
            [ctx.productoCodigo]
        )).rows[0];
        if (row) {
            ctx.cotizacionCodigo = ctx.cotizacionCodigo || row.quote_code || null;
            ctx.lineaCodigo = ctx.lineaCodigo || row.line_code || null;
            if (row.client_code) ctx.clienteCodigo = ctx.clienteCodigo || row.client_code;
            if (row.client_name) ctx.clienteNombre = ctx.clienteNombre || row.client_name;
            if (row.product_name) ctx.productoNombre = row.product_name;
        }
    }

    if (ctx.cotizacionCodigo) {
        const quoteRow = (await pgQuery(
            `SELECT customer_code, customer_name, created_at FROM quotes WHERE quote_code = $1 LIMIT 1`,
            [ctx.cotizacionCodigo]
        )).rows[0];
        if (quoteRow) {
            if (quoteRow.customer_code) ctx.clienteCodigo = ctx.clienteCodigo || quoteRow.customer_code;
            if (quoteRow.customer_name) ctx.clienteNombre = ctx.clienteNombre || quoteRow.customer_name;
            fechaExpediente = quoteRow.created_at || fechaExpediente;
        }
        if (ctx.lineaCodigo) {
            const calcRow = (await pgQuery(
                `SELECT product_code, job_name, customer_code, customer_name, created_at
                   FROM flexo_calculations
                  WHERE quote_code = $1 AND line_code = $2
                  ORDER BY created_at DESC NULLS LAST LIMIT 1`,
                [ctx.cotizacionCodigo, ctx.lineaCodigo]
            )).rows[0];
            if (calcRow) {
                ctx.productoCodigo = ctx.productoCodigo || calcRow.product_code || null;
                if (calcRow.job_name) ctx.productoNombre = ctx.productoNombre || calcRow.job_name;
                if (calcRow.customer_code) ctx.clienteCodigo = ctx.clienteCodigo || calcRow.customer_code;
                if (calcRow.customer_name) ctx.clienteNombre = ctx.clienteNombre || calcRow.customer_name;
            }
        }
        if (!ctx.ordenCodigo && ctx.lineaCodigo) {
            const ordRow = (await pgQuery(
                `SELECT order_code FROM flexo_orders WHERE quote_code = $1 AND line_code = $2
                  ORDER BY created_at DESC NULLS LAST LIMIT 1`,
                [ctx.cotizacionCodigo, ctx.lineaCodigo]
            )).rows[0];
            if (ordRow?.order_code) ctx.ordenCodigo = ordRow.order_code;
        }
    }

    const fecha = fechaExpediente ? new Date(fechaExpediente) : new Date();
    if (!Number.isNaN(fecha.getTime())) {
        ctx.anio = fecha.getFullYear();
        ctx.mes = fecha.getMonth() + 1;
    }

    if (ctx.productoCodigo) {
        ctx.productoCarpeta = [ctx.productoCodigo, ctx.productoNombre].filter(Boolean).join(' - ');
    } else if (ctx.lineaCodigo) {
        ctx.productoCarpeta = [ctx.lineaCodigo, ctx.productoNombre].filter(Boolean).join(' - ');
    } else {
        ctx.productoCarpeta = ctx.productoNombre || '';
    }

    return ctx;
}

function normalizarFilaAdjuntoExpediente(row = {}) {
    const mime = String(row.mime || '').toLowerCase();
    return {
        id: row.id,
        fuente: 'producto',
        origen: row.origen || 'cotizacion',
        tipoDocumento: row.tipo_documento || 'otro',
        nombre: row.nombre_archivo || 'Adjunto',
        mime: row.mime || '',
        tamanoBytes: Number(row.tamano_bytes || 0),
        notas: row.notas || '',
        subidoPor: row.subido_por || '',
        creadoEn: row.creado_en || null,
        descargarUrl: `/api/adjuntos-producto/${encodeURIComponent(row.id)}/descargar`,
        esImagen: mime.startsWith('image/'),
        esAudio: mime.startsWith('audio/')
    };
}

// Adjuntos que ya existían antes de esta carpeta unificada. Se leen tal cual y se
// muestran marcados con su origen; se migran a la carpeta nueva más adelante.
async function agregarAdjuntosLegado(ctx = {}) {
    const items = [];
    const { cotizacionCodigo, lineaCodigo, ordenCodigo } = ctx;

    if (cotizacionCodigo && lineaCodigo) {
        const rows = (await pgQuery(
            `SELECT id, file_name, mime_type, notes, uploaded_by, created_at, COALESCE(size_bytes,0) AS size_bytes
               FROM quote_line_attachments
              WHERE quote_code = $1 AND line_code = $2
              ORDER BY created_at DESC NULLS LAST`,
            [cotizacionCodigo, lineaCodigo]
        )).rows;
        rows.forEach((row) => {
            const nota = String(row.notes || '').toLowerCase();
            const mime = String(row.mime_type || '').toLowerCase();
            let origen = 'cotizacion';
            if (nota.includes('audio_orden') || nota.includes('arte_orden')) origen = 'produccion';
            else if (nota.includes('adjunto_orden') || nota.includes('orden')) origen = 'orden';
            let tipo = 'otro';
            if (mime.startsWith('audio/') || nota.includes('audio')) tipo = 'audio';
            else if (nota.includes('arte')) tipo = 'arte';
            else if (mime.startsWith('image/')) tipo = 'foto';
            items.push({
                id: `qla:${row.id}`,
                fuente: 'heredado',
                heredadoDe: 'Adjunto de línea',
                origen,
                tipoDocumento: tipo,
                nombre: row.file_name || 'Adjunto',
                mime: row.mime_type || '',
                tamanoBytes: Number(row.size_bytes || 0),
                notas: row.notes || '',
                subidoPor: row.uploaded_by || '',
                creadoEn: row.created_at || null,
                descargarUrl: `/api/adjuntos/${encodeURIComponent(row.id)}/download`,
                esImagen: mime.startsWith('image/'),
                esAudio: mime.startsWith('audio/')
            });
        });
    }

    if (ordenCodigo) {
        const artes = (await pgQuery(
            `SELECT id, nombre_arte, imagen_url, creado_por, creado_en, proceso_clave
               FROM produccion_artes WHERE orden_codigo = $1 ORDER BY creado_en DESC NULLS LAST`,
            [ordenCodigo]
        )).rows;
        artes.forEach((row) => {
            items.push({
                id: `arte:${row.id}`,
                fuente: 'heredado',
                heredadoDe: row.proceso_clave === 'tintas' ? 'Arte de Tintas' : 'Arte de Diseño',
                origen: 'produccion',
                tipoDocumento: 'arte',
                nombre: row.nombre_arte || 'Arte',
                mime: 'image/*',
                tamanoBytes: 0,
                notas: '',
                subidoPor: row.creado_por || '',
                creadoEn: row.creado_en || null,
                descargarUrl: row.imagen_url || '',
                esImagen: true,
                esAudio: false
            });
        });

        const disenoRows = (await pgQuery(
            `SELECT id, nombre_archivo, tipo, categoria, estado, tamano_bytes, creado_por, creado_en
               FROM diseno_archivos WHERE orden_codigo = $1 ORDER BY creado_en DESC NULLS LAST`,
            [ordenCodigo]
        )).rows;
        disenoRows.forEach((row) => {
            items.push({
                id: `dis:${row.id}`,
                fuente: 'heredado',
                heredadoDe: 'Archivo técnico de Diseño',
                origen: 'produccion',
                tipoDocumento: row.estado === 'aprobado' ? 'arte' : 'referencia',
                nombre: row.nombre_archivo || 'Archivo',
                mime: '',
                tamanoBytes: Number(row.tamano_bytes || 0),
                notas: row.categoria || '',
                subidoPor: row.creado_por || '',
                creadoEn: row.creado_en || null,
                descargarUrl: `/api/produccion/diseno-archivos/${encodeURIComponent(row.id)}/descargar`,
                esImagen: false,
                esAudio: false
            });
        });

        const tintasRows = (await pgQuery(
            `SELECT id, nombre_archivo, tipo, categoria, estado, tamano_bytes, creado_por, creado_en
               FROM tintas_archivos WHERE orden_codigo = $1 ORDER BY creado_en DESC NULLS LAST`,
            [ordenCodigo]
        )).rows;
        tintasRows.forEach((row) => {
            items.push({
                id: `tin:${row.id}`,
                fuente: 'heredado',
                heredadoDe: 'Archivo técnico de Tintas',
                origen: 'produccion',
                tipoDocumento: row.estado === 'aprobado' ? 'arte' : 'referencia',
                nombre: row.nombre_archivo || 'Archivo',
                mime: '',
                tamanoBytes: Number(row.tamano_bytes || 0),
                notas: row.categoria || '',
                subidoPor: row.creado_por || '',
                creadoEn: row.creado_en || null,
                descargarUrl: `/api/produccion/tintas-archivos/${encodeURIComponent(row.id)}/descargar`,
                esImagen: false,
                esAudio: false
            });
        });
    }

    return items;
}

async function listarAdjuntosExpediente(ctx = {}, { origenesVisibles = null } = {}) {
    const nuevos = [];
    const condiciones = [];
    const params = [];
    if (ctx.cotizacionCodigo && ctx.lineaCodigo) {
        params.push(ctx.cotizacionCodigo, ctx.lineaCodigo);
        condiciones.push(`(cotizacion_codigo = $${params.length - 1} AND linea_codigo = $${params.length})`);
    }
    if (ctx.ordenCodigo) {
        params.push(ctx.ordenCodigo);
        condiciones.push(`orden_codigo = $${params.length}`);
    }
    if (ctx.productoCodigo) {
        params.push(ctx.productoCodigo);
        condiciones.push(`producto_codigo = $${params.length}`);
    }
    if (condiciones.length) {
        const rows = (await pgQuery(
            `SELECT * FROM adjuntos WHERE ${condiciones.join(' OR ')} ORDER BY creado_en DESC NULLS LAST`,
            params
        )).rows;
        rows.forEach((row) => nuevos.push(normalizarFilaAdjuntoExpediente(row)));
    }

    const legado = await agregarAdjuntosLegado(ctx);
    let todos = [...nuevos, ...legado];

    if (Array.isArray(origenesVisibles) && origenesVisibles.length) {
        const set = new Set(origenesVisibles);
        todos = todos.filter((item) => set.has(item.origen));
    }
    return todos;
}

async function migrateExistingQuoteLineAttachmentsToDisk() {
    const result = await pgQuery(`
        SELECT id, quote_code, line_code, file_name, content_base64
          FROM quote_line_attachments
         WHERE (storage_path IS NULL OR storage_path = '')
           AND content_base64 IS NOT NULL
           AND content_base64 <> ''
    `);
    for (const row of result.rows) {
        try {
            const stored = writeQuoteLineAttachmentFile({
                id: row.id,
                quoteCode: row.quote_code,
                lineCode: row.line_code,
                fileName: row.file_name,
                contentBase64: row.content_base64
            });
            await pgQuery(
                `UPDATE quote_line_attachments
                    SET storage_path = $2,
                        size_bytes = $3,
                        content_sha256 = $4,
                        content_base64 = NULL
                  WHERE id = $1`,
                [row.id, stored.storagePath, stored.sizeBytes, stored.contentSha256]
            );
        } catch (error) {
            console.error(`No fue posible migrar el adjunto ${row.id} a disco:`, error.message);
        }
    }
}

