async function ensureValoresProduccionSchema() {
    // Se identifica por quote_code+line_code (no por order_code): el producto y la orden se crean
    // por separado y ambos deben poder sembrar/leer la misma copia de producción sin duplicarla.
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS valores_produccion_motivo (
            id SERIAL PRIMARY KEY,
            quote_code TEXT NOT NULL,
            line_code TEXT NOT NULL,
            motivo_indice INTEGER NOT NULL DEFAULT 0,
            proceso TEXT NOT NULL,
            campo TEXT NOT NULL,
            etiqueta TEXT,
            unidad TEXT,
            valor_cotizado TEXT,
            valor_producido TEXT,
            cambiado_por TEXT,
            cambiado_en TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            UNIQUE (quote_code, line_code, motivo_indice, proceso, campo)
        )
    `);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_valores_produccion_quote_line ON valores_produccion_motivo(quote_code, line_code, proceso)`);
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS valores_produccion_historial (
            id SERIAL PRIMARY KEY,
            valor_id INTEGER NOT NULL REFERENCES valores_produccion_motivo(id) ON DELETE CASCADE,
            valor_anterior TEXT,
            valor_nuevo TEXT,
            cambiado_por TEXT,
            justificacion TEXT,
            creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    await pgQuery(`CREATE INDEX IF NOT EXISTS idx_valores_produccion_historial_valor ON valores_produccion_historial(valor_id)`);
}

