// ── Lectura única del seguimiento de una orden ────────────────────────────
// Arma los 3 pasos sintéticos (creación / solicitud vendedor / planeación)
// desde orden_planificacion, y los procesos desde vista_orden_proceso.
// Devuelve { order, steps, comparisons, live } con el mismo contrato que
// consumían los lectores del modelo viejo. Traduce el estado nuevo
// (EN_MARCHA/PREPARACION/EN_PARO) al vocabulario de API (RUN/SETUP/PARO)
// para no tocar el front en este paso.
const SEGUIMIENTO_ESTADO_API = { EN_MARCHA: 'RUN', PREPARACION: 'SETUP', EN_PARO: 'PARO', COMPLETADO: 'COMPLETADO', PENDIENTE: 'PENDIENTE' };
const SEGUIMIENTO_MACHINE_KEYS = new Set(['sellos', 'impresion', 'acabados', 'barnizado', 'laminado', 'troquelado', 'estampado', 'embosado', 'numeracion', 'rebobinado']);

async function cargarSeguimientoOrden(codigo, { session = {}, costsConfig = null } = {}) {
    const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [codigo]);
    if (!orderResult.rows.length) {
        const err = new Error('Orden de producción no encontrada.');
        err.statusCode = 404;
        throw err;
    }
    const orderRow = orderResult.rows[0];
    if (orderRow.raw_data) normalizeCalculationKeys(orderRow.raw_data);
    const raw = orderRow.raw_data || {};
    const snapshot = raw.planning_snapshot || raw.planningSnapshot || {};
    const cfg = costsConfig || await loadCostsConfig();

    const [planRes, procRes] = await Promise.all([
        pgQuery(`SELECT * FROM orden_planificacion WHERE codigo_orden = $1 LIMIT 1`, [codigo]),
        pgQuery(`SELECT * FROM vista_orden_proceso WHERE codigo_orden = $1 ORDER BY secuencia`, [codigo])
    ]);
    const plan = planRes.rows[0] || {};
    const procesos = procRes.rows;

    // Último evento y último "completado" por proceso (production_route_events
    // ligada por orden_proceso_id).
    const eventosPorProceso = new Map();
    if (procesos.length) {
        const evRes = await pgQuery(`
            SELECT e.orden_proceso_id AS proceso_id, e.operator_name, e.event_type, e.notes, e.created_at
              FROM production_route_events e
             WHERE e.orden_proceso_id IN (SELECT id FROM orden_proceso WHERE codigo_orden = $1)
             ORDER BY e.created_at DESC
        `, [codigo]);
        evRes.rows.forEach((row) => {
            const bucket = eventosPorProceso.get(row.proceso_id) || { ultimo: null, completado: null };
            if (!bucket.ultimo) bucket.ultimo = row;
            if (!bucket.completado && String(row.event_type || '').toLowerCase() === 'completado') bucket.completado = row;
            eventosPorProceso.set(row.proceso_id, bucket);
        });
    }

    // Resolución de actores (nombre + foto) contra admin_users.
    const actorNames = new Set();
    const addActor = (v) => { const c = sanitizeAdminUserText(v).toLowerCase(); if (c) actorNames.add(c); };
    [
        raw.traceability?.created_by, raw.traceability?.createdBy, raw['TRAZABILIDAD | USUARIO'],
        raw.created_by, raw.createdBy, raw.usuario_creacion,
        plan.liberado_ventas_por, plan.lanzado_gantt_por, plan.seleccion_procesos_por
    ].forEach(addActor);
    eventosPorProceso.forEach((b) => { addActor(b.ultimo?.operator_name); addActor(b.completado?.operator_name); });

    const nameMap = new Map();
    const photoMap = new Map();
    const sessionName = pickFirstValue(sanitizeAdminUserText(session?.fullName), sanitizeAdminUserText(session?.name), sanitizeAdminUserText(session?.user), sanitizeAdminUserText(session?.username));
    const sessionPhoto = pickFirstValue(sanitizeAdminUserText(session?.photoUrl), sanitizeAdminUserText(session?.photo_url), sanitizeAdminUserText(session?.avatarUrl));
    [session?.username, session?.user, session?.name, session?.fullName].forEach((k) => {
        const n = sanitizeAdminUserText(k).toLowerCase();
        if (n && sessionName) { nameMap.set(n, sessionName); if (sessionPhoto) photoMap.set(n, sessionPhoto); }
    });
    if (actorNames.size) {
        const uRes = await pgQuery(
            `SELECT full_name, username, photo_url FROM admin_users
              WHERE LOWER(TRIM(username)) = ANY($1::text[]) OR LOWER(TRIM(full_name)) = ANY($1::text[])`,
            [Array.from(actorNames)]
        );
        uRes.rows.forEach((r) => {
            const display = sanitizeAdminUserText(r.full_name, r.username);
            const photo = sanitizeAdminUserText(r.photo_url);
            [r.username, r.full_name].forEach((k) => {
                const n = sanitizeAdminUserText(k).toLowerCase();
                if (!n) return;
                if (display && !nameMap.has(n)) nameMap.set(n, display);
                if (photo && !photoMap.has(n)) photoMap.set(n, photo);
            });
        });
    }
    const actorInfo = (v) => {
        const c = sanitizeAdminUserText(v);
        if (!c) return { name: '', photoUrl: '' };
        const n = c.toLowerCase();
        return { name: nameMap.get(n) || c, photoUrl: photoMap.get(n) || photoMap.get(sanitizeAdminUserText(nameMap.get(n) || '').toLowerCase()) || '' };
    };

    // ── 3 pasos sintéticos desde orden_planificacion ──
    const creadaAt = pickFirstValue(raw.traceability?.created_at, raw.traceability?.createdAt, raw['TRAZABILIDAD | FECHA'], raw.created_at, orderRow.created_at) || null;
    const creador = actorInfo(pickFirstValue(raw.traceability?.created_by, raw.traceability?.createdBy, raw['TRAZABILIDAD | USUARIO'], raw.created_by, raw.createdBy, raw.usuario_creacion, ''));
    const ventasActor = actorInfo(plan.liberado_ventas_por || raw.salesperson_name || raw.quote_snapshot?.salesperson_name || '');
    const planActor = actorInfo(plan.lanzado_gantt_por || plan.seleccion_procesos_por || '');
    const fixedSteps = [
        {
            processKey: 'orden_creada', processName: 'Creación de Orden', sequenceOrder: 1,
            routeStatus: 'COMPLETADO',
            completedBy: creador.name, completedByPhoto: creador.photoUrl,
            completedAt: creadaAt, startedAt: creadaAt, notes: ''
        },
        {
            processKey: 'solicitud_vendedor', processName: 'Solicitud de Vendedor', sequenceOrder: 2,
            routeStatus: plan.liberado_ventas ? 'COMPLETADO' : 'PENDIENTE',
            completedBy: ventasActor.name, completedByPhoto: ventasActor.photoUrl,
            completedAt: plan.liberado_ventas_en || null, startedAt: plan.liberado_ventas_en || null,
            notes: plan.motivo_devolucion || ''
        },
        {
            processKey: 'planeacion', processName: 'Seguimiento', sequenceOrder: 3,
            routeStatus: plan.lanzado_gantt ? 'COMPLETADO' : (plan.estado_planificacion === 'PENDIENTE_PLANIFICACION' ? 'RUN' : 'PENDIENTE'),
            completedBy: planActor.name, completedByPhoto: planActor.photoUrl,
            completedAt: plan.lanzado_gantt_en || null,
            startedAt: plan.seleccion_procesos_en || plan.liberado_ventas_en || null,
            notes: plan.motivo_devolucion || ''
        }
    ];

    // ── procesos desde vista_orden_proceso, en el orden de seguimiento ──
    const processKeys = resolveOrderTrackingProcessKeys(orderRow, cfg);
    const porClave = new Map();
    const rankProceso = (x) => x.estado === 'COMPLETADO' ? 0 : (['EN_MARCHA', 'PREPARACION', 'EN_PARO'].includes(x.estado) ? 1 : 2);
    procesos.forEach((p) => {
        const key = canonicalProductionFlowKey(p.clave_proceso) || p.clave_proceso;
        const prev = porClave.get(key);
        if (!prev || rankProceso(p) < rankProceso(prev)) porClave.set(key, p);
    });
    const snapshotByKey = new Map((Array.isArray(snapshot.processes) ? snapshot.processes : []).map((pr) => [canonicalProductionFlowKey(pr.processKey || pr.processName), pr]));

    const processSteps = processKeys.map((key, index) => {
        const p = porClave.get(key) || {};
        const extra = (p.datos_extra && typeof p.datos_extra === 'object') ? p.datos_extra : {};
        const ev = p.id ? eventosPorProceso.get(p.id) : null;
        const estado = p.estado || 'PENDIENTE';
        const routeStatus = SEGUIMIENTO_ESTADO_API[estado] || 'PENDIENTE';
        const done = estado === 'COMPLETADO';
        const completadoActor = done ? actorInfo(ev?.completado?.operator_name || ev?.ultimo?.operator_name || '') : { name: '', photoUrl: '' };
        const startAt = p.fecha_real_inicio ? new Date(p.fecha_real_inicio) : null;
        const endAt = p.fecha_real_fin ? new Date(p.fecha_real_fin) : null;
        let realMinutes = 0;
        if (startAt && !Number.isNaN(startAt.getTime())) {
            const end = endAt && !Number.isNaN(endAt.getTime()) ? endAt : new Date();
            realMinutes = Math.max(0, Math.round((end.getTime() - startAt.getTime()) / 60000));
        }
        const quotedMinutes = quotedProcessDurationMinutes(orderRow, key);
        const planned = snapshotByKey.get(key) || {};
        const plannedSrc = String(planned.source || '').toLowerCase();
        const src = String(extra.source || '').toLowerCase();
        const plannedDurationMinutes = (plannedSrc === 'fallback-estimate' || plannedSrc === 'missing-duration') ? 0 : Number(planned.durationHours || 0) * 60;
        const routeDurationMinutes = (src === 'fallback-estimate' || src === 'missing-duration') ? 0 : Number(p.duracion_horas || 0) * 60;
        const plannedMinutes = firstPositivePlanningNumber(quotedMinutes, plannedDurationMinutes, routeDurationMinutes);
        return {
            processKey: key,
            processName: PRODUCTION_FLOW_LABELS[key] || planned.processName || p.nombre_proceso || key,
            sequenceOrder: index + 4,
            routeStatus,
            completedBy: completadoActor.name || '',
            completedByPhoto: completadoActor.photoUrl || '',
            completedAt: p.fecha_real_fin || (done ? (ev?.completado?.created_at || null) : null),
            startedAt: p.fecha_real_inicio || null,
            notes: ev?.ultimo?.notes || '',
            advertencia: key === 'empaque' ? (orderRow.empaque_advertencia || '') : '',
            planned: {
                minutes: plannedMinutes,
                setupMinutes: Number(extra.setupMinutes || planned.setupMinutes || 0),
                machineName: SEGUIMIENTO_MACHINE_KEYS.has(key) ? (p.nombre_maquina || planned.machineName || '') : '',
                quantity: Number(extra.baseFeet || planned.baseFeet || snapshot.baseFeet || 0),
                unit: 'ft',
                scheduledStart: p.fecha_plan_inicio || null,
                scheduledEnd: p.fecha_plan_fin || null
            },
            real: {
                minutes: realMinutes,
                quantity: 0,
                usefulQuantity: 0,
                velocidad_m_min: done ? Number(extra.velocidad_m_min || 0) : 0,
                unit: 'ft'
            }
        };
    });

    const live = processSteps.some((s) => ['RUN', 'SETUP', 'PARO'].includes(s.routeStatus));
    return { order: orderRow, steps: [...fixedSteps, ...processSteps], comparisons: processSteps, live };
}

// [syncMarkToRouteTable eliminada 2026-09 — codigo muerto tras consolidacion produccion/planificacion]

// ── Transición de estado de un proceso — puerta ÚNICA de escritura ────────
// Todos los escritores (MES, Seguimiento, Gantt) pasan por aquí. Guardas:
//  · COMPLETADO → EN_MARCHA/PREPARACION/PENDIENTE: prohibido salvo
//    permitirReapertura (acción explícita "reabrir", con motivo).
//  · → EN_MARCHA: la dependencia (depende_de_id) debe estar COMPLETADO.
//  · Nunca toca filas hermanas.
// Durante la transición espeja el estado a production_order_routes +
// order_tracking_marks para los lectores aún no repuntados. Ese espejo se
// retira en el paso 7.
const ESTADO_PROCESO_VALIDOS = new Set(['PENDIENTE', 'PREPARACION', 'EN_MARCHA', 'EN_PARO', 'COMPLETADO']);
const ESTADO_API_A_PROCESO = { RUN: 'EN_MARCHA', SETUP: 'PREPARACION', PARO: 'EN_PARO', COMPLETADO: 'COMPLETADO', PENDIENTE: 'PENDIENTE' };

async function resolverOrdenProceso(ref, { codigoOrden = null, claveProceso = null } = {}) {
    const s = String(ref || '').trim();
    if (/^[0-9a-fA-F-]{36}$/.test(s)) {
        let r = await pgQuery(`SELECT * FROM orden_proceso WHERE id = $1::uuid LIMIT 1`, [s]);
        if (r.rows.length) return r.rows[0];
        r = await pgQuery(
            `SELECT * FROM orden_proceso WHERE datos_extra->>'migrado_de_route_id' = $1 LIMIT 1`, [s]
        );
        if (r.rows.length) return r.rows[0];
    }
    if (codigoOrden && claveProceso) {
        const key = canonicalProductionFlowKey(claveProceso) || claveProceso;
        const r = await pgQuery(
            `SELECT * FROM orden_proceso
              WHERE codigo_orden = $1
                AND (clave_proceso = $2 OR clave_proceso = $3)
              ORDER BY CASE estado WHEN 'COMPLETADO' THEN 0 ELSE 1 END, secuencia
              LIMIT 1`,
            [codigoOrden, key, claveProceso]
        );
        if (r.rows.length) return r.rows[0];
    }
    return null;
}

async function cambiarEstadoProceso(ref, nuevoEstadoRaw, opts = {}) {
    const {
        actor = '', motivo = '', permitirReapertura = false,
        registrarEvento = true, codigoOrden = null, claveProceso = null, fecha = null
    } = opts;
    const nuevoEstado = ESTADO_API_A_PROCESO[String(nuevoEstadoRaw || '').toUpperCase()]
        || String(nuevoEstadoRaw || '').toUpperCase();
    if (!ESTADO_PROCESO_VALIDOS.has(nuevoEstado)) {
        const e = new Error(`Estado inválido: ${nuevoEstadoRaw}`); e.statusCode = 400; throw e;
    }
    const proc = await resolverOrdenProceso(ref, { codigoOrden, claveProceso });
    if (!proc) {
        const e = new Error('No se encontró el proceso de la orden.'); e.statusCode = 404; throw e;
    }
    const anterior = proc.estado;
    if (anterior === nuevoEstado) return { ok: true, sinCambio: true, proceso: proc, estadoAnterior: anterior, estadoNuevo: nuevoEstado };

    // Guarda 0: la orden está detenida o anulada — bloqueo total, ningún proceso avanza.
    if (!opts.omitirBloqueoDetencion && proc.codigo_orden) {
        const det = await pgQuery(`SELECT estado_detencion FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [proc.codigo_orden]).catch(() => null);
        const estadoDet = det?.rows?.[0]?.estado_detencion || '';
        if (estadoDet === 'DETENIDA' || estadoDet === 'ANULADA') {
            const e = new Error(estadoDet === 'ANULADA'
                ? 'La orden está anulada. Hay que reactivarla antes de trabajar en ella.'
                : 'La orden está detenida. Hay que reanudarla antes de trabajar en ella.');
            e.statusCode = 409; throw e;
        }
    }

    // Guarda 0b: ninguna orden puede arrancar NI completar un proceso real de producción
    // sin Solicitud de Vendedor y Seguimiento (lanzado a Gantt) ya marcados. Cubre también
    // COMPLETADO porque la pantalla de Seguimiento marca los pasos directo a completado,
    // sin pasar por EN_MARCHA/PREPARACION. Diseño y Tintas no caen aquí para las órdenes
    // que no los necesitan porque se autocompletan por separado (ver autoCompleteDesignIfNotQuoted
    // y el autocompletado de Tintas más abajo), y esas llamadas ocurren después de que
    // liberado_ventas/lanzado_gantt ya quedaron en true.
    if ((nuevoEstado === 'EN_MARCHA' || nuevoEstado === 'PREPARACION' || nuevoEstado === 'COMPLETADO') && proc.codigo_orden) {
        const plan = await pgQuery(`SELECT liberado_ventas, lanzado_gantt FROM orden_planificacion WHERE codigo_orden = $1`, [proc.codigo_orden]);
        const marcas = plan.rows[0] || {};
        if (!marcas.liberado_ventas) {
            const e = new Error('Esta orden todavía no tiene la marca de Solicitud de Vendedor. No puede avanzar a producción sin esa marca.');
            e.statusCode = 409; throw e;
        }
        if (!marcas.lanzado_gantt) {
            const e = new Error('Esta orden todavía no tiene la marca de Seguimiento (lanzada a Gantt). No puede avanzar a producción sin esa marca.');
            e.statusCode = 409; throw e;
        }
    }

    // Guarda 1: reapertura de un proceso completado
    if (anterior === 'COMPLETADO' && nuevoEstado !== 'COMPLETADO' && !permitirReapertura) {
        const e = new Error('Este proceso ya está completado. Para reabrirlo hay que usar la acción de reapertura con un motivo.');
        e.statusCode = 409; throw e;
    }
    // Guarda 2: no se arranca NI se completa si la dependencia no está lista — EXCEPTO
    // Rebobinado y Empaque, que pueden empezar (y terminar) aunque el proceso anterior
    // (Impresión / Rebobinado) siga corriendo, porque a veces el mismo operario trabaja
    // las dos máquinas a la vez con trabajos largos. Cubre COMPLETADO además de EN_MARCHA
    // porque la pantalla de Seguimiento marca los pasos directo a completado.
    const claveCanonGuarda2 = canonicalProductionFlowKey(proc.clave_proceso) || proc.clave_proceso;
    if ((nuevoEstado === 'EN_MARCHA' || nuevoEstado === 'COMPLETADO') && proc.depende_de_id && !['rebobinado', 'empaque'].includes(claveCanonGuarda2)) {
        const dep = await pgQuery(`SELECT estado, nombre_proceso FROM orden_proceso WHERE id = $1`, [proc.depende_de_id]);
        if (dep.rows[0] && dep.rows[0].estado !== 'COMPLETADO') {
            const e = new Error(`No se puede marcar: falta completar "${dep.rows[0].nombre_proceso}".`);
            e.statusCode = 400; throw e;
        }
    }
    // Guarda 3: arranque sin programación en el Gantt (Configuración → Producción →
    // Control de Arranque sin Programación). 'abierto' no revisa nada; 'bloqueo' impide
    // arrancar; 'aviso' deja arrancar pero lo marca para que Seguimiento lo muestre.
    if ((nuevoEstado === 'EN_MARCHA' || nuevoEstado === 'PREPARACION') && anterior === 'PENDIENTE' && proc.codigo_orden) {
        const cfg = await loadGeneralConfig().catch(() => null);
        // Desactivado temporalmente a solicitud hasta arrancar la programación en Gantt real (el código queda preservado para futuro).
        const modo = 'abierto'; // cfg?.produccion?.controlProgramacion || 'abierto';
        if (modo !== 'abierto') {
            const plan = await pgQuery(`SELECT lanzado_gantt FROM orden_planificacion WHERE codigo_orden = $1`, [proc.codigo_orden]);
            const programada = !!plan.rows[0]?.lanzado_gantt;
            if (!programada) {
                if (modo === 'bloqueo') {
                    const e = new Error('Esta orden todavía no se ha programado en el Gantt. Prográmala antes de arrancarla en piso.');
                    e.statusCode = 409; throw e;
                }
                await pgQuery(`ALTER TABLE orden_planificacion
                    ADD COLUMN IF NOT EXISTS arranco_sin_programar boolean DEFAULT false,
                    ADD COLUMN IF NOT EXISTS arranco_sin_programar_en timestamptz,
                    ADD COLUMN IF NOT EXISTS arranco_sin_programar_proceso text`).catch(() => null);
                await pgQuery(
                    `UPDATE orden_planificacion
                        SET arranco_sin_programar = true, arranco_sin_programar_en = NOW(), arranco_sin_programar_proceso = $2
                      WHERE codigo_orden = $1`,
                    [proc.codigo_orden, proc.clave_proceso || null]
                ).catch(() => null);
            }
        }
    }

    const ahora = fecha ? new Date(fecha) : new Date();
    const sets = ['estado = $2', 'actualizado_en = NOW()'];
    const vals = [proc.id, nuevoEstado];
    if (nuevoEstado === 'EN_MARCHA' && !proc.fecha_real_inicio) { sets.push('fecha_real_inicio = $3'); vals.push(ahora); }
    else if (nuevoEstado === 'COMPLETADO') { sets.push(`fecha_real_fin = COALESCE(fecha_real_fin, $3)`); vals.push(ahora); }
    else if (anterior === 'COMPLETADO' && permitirReapertura) { sets.push('fecha_real_fin = NULL'); }
    await pgQuery(`UPDATE orden_proceso SET ${sets.join(', ')} WHERE id = $1`, vals);

    // ── bitácora del proceso (ligada por orden_proceso_id) ──
    if (registrarEvento) {
        const evType = nuevoEstado === 'COMPLETADO' ? 'completado'
            : nuevoEstado === 'EN_MARCHA' ? 'run'
            : nuevoEstado === 'PREPARACION' ? 'setup'
            : nuevoEstado === 'EN_PARO' ? 'paro' : 'revertido';
        await pgQuery(
            `INSERT INTO production_route_events (orden_proceso_id, route_id, operator_name, event_type, notes, event_payload, created_at)
             VALUES ($1::uuid, $2::uuid, $3, $4, $5, '{}'::jsonb, NOW())`,
            [proc.id, /^[0-9a-fA-F-]{36}$/.test(String(proc.datos_extra?.migrado_de_route_id || '')) ? proc.datos_extra.migrado_de_route_id : null,
             actor || null, evType, motivo || null]
        ).catch(() => null);
    }

    syncOrderProductionTimingSummary(proc.codigo_orden).catch(() => null);

    // ── estado_planificacion derivado ──
    await recalcularEstadoPlanificacion(proc.codigo_orden).catch(() => null);

    // Autocompletar Tintas si esta orden no lleva tinta especial — no va a pasar por
    // ese proceso, así que no debe quedar pendiente bloqueando la vista del flujo.
    if (nuevoEstado === 'COMPLETADO' && proc.codigo_orden && canonicalProductionFlowKey(proc.clave_proceso) === 'programacion') {
        const ordenRow = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [proc.codigo_orden]).then((r) => r.rows[0]).catch(() => null);
        if (ordenRow && !orderHasSpecialInk(ordenRow)) {
            await cambiarEstadoProceso(proc.codigo_orden, 'COMPLETADO', {
                actor, motivo: 'Automático — sin tinta especial, no pasa por Tintas',
                codigoOrden: proc.codigo_orden, claveProceso: 'tintas'
            }).catch(() => null);
        }
    }

    return { ok: true, proceso: { ...proc, estado: nuevoEstado }, estadoAnterior: anterior, estadoNuevo: nuevoEstado };
}

async function recalcularEstadoPlanificacion(codigoOrden) {
    const r = await pgQuery(
        `SELECT
            bool_and(estado = 'COMPLETADO') AS todo_completo,
            bool_or(estado IN ('EN_MARCHA','PREPARACION','EN_PARO','COMPLETADO')) AS algo_iniciado
           FROM orden_proceso WHERE codigo_orden = $1`,
        [codigoOrden]
    );
    const { todo_completo, algo_iniciado } = r.rows[0] || {};
    await pgQuery(
        `UPDATE orden_planificacion
            SET estado_planificacion = CASE
                    WHEN $2 THEN 'COMPLETADA'
                    WHEN $3 AND estado_planificacion NOT IN ('PENDIENTE_VENTAS','DEVUELTA_VENTAS') THEN 'EN_PRODUCCION'
                    ELSE estado_planificacion
                END,
                actualizado_en = NOW()
          WHERE codigo_orden = $1`,
        [codigoOrden, !!todo_completo, !!algo_iniciado]
    );
}

// [syncRouteStatusToMarkTable eliminada 2026-09 — codigo muerto tras consolidacion produccion/planificacion]

const ORDER_TIMING_TRACKED_KEYS = Object.freeze(['diseno', 'preprensa', 'visto_bueno', 'programacion', 'tintas', 'impresion', 'rebobinado', 'empaque']);
// Las 9 etapas resumidas en tiempo_real_<etapa>_horas / tiempo_proceso_<etapa>_horas
// (planeacion = "Seguimiento" + las 8 de ORDER_TIMING_TRACKED_KEYS), usadas tanto por el
// sync de tiempos como por la ficha ejecutiva de orden/producto.
const PRODUCTION_TIMING_SUMMARY_KEYS = Object.freeze(['planeacion', ...ORDER_TIMING_TRACKED_KEYS]);

// Espeja en flexo_orders/flexo_products el tiempo real (bruto, entre fin de la etapa
// anterior y fin de esta) y el tiempo de proceso (actual_end_at - actual_start_at,
// solo disponible si la etapa pasó por el flujo MES) de cada etapa productiva. Se
// invoca después de cualquier evento que mueva production_order_routes o el control
// de planificación de la orden (salesReleasedAt/launchedAt).
async function syncOrderProductionTimingSummary(orderCode) {
    try {
        const orderResult = await pgQuery(`SELECT quote_code, line_code, product_code, raw_data FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
        if (!orderResult.rows.length) return;
        const orderRow = orderResult.rows[0];
        const control = getOrderPlanningControl(orderRow.raw_data || {});

        const routesResult = await pgQuery(
            `SELECT id::text AS id, clave_proceso AS process_key, depende_de_id::text AS dependency_route_id,
                    fecha_real_inicio AS actual_start_at, fecha_real_fin AS actual_end_at
               FROM orden_proceso WHERE codigo_orden = $1`,
            [orderCode]
        );
        const routesById = new Map();
        const routeByKey = new Map();
        routesResult.rows.forEach((row) => {
            routesById.set(row.id, row);
            const key = canonicalProductionFlowKey(row.process_key);
            if (key && !routeByKey.has(key)) routeByKey.set(key, row);
        });

        const toHours = (endValue, startValue) => {
            if (!endValue || !startValue) return null;
            const end = new Date(endValue).getTime();
            const start = new Date(startValue).getTime();
            if (!Number.isFinite(end) || !Number.isFinite(start) || end < start) return null;
            return Math.round(((end - start) / 3600000) * 10000) / 10000;
        };

        const values = {};
        // Seguimiento (marca sintética "planeacion", sin ruta propia): tiempo real =
        // fin de Seguimiento menos Solicitud de Vendedor. No tiene reloj de trabajo propio.
        values.tiempo_real_planeacion_horas = toHours(control.launchedAt, control.salesReleasedAt);
        values.tiempo_proceso_planeacion_horas = null;

        ORDER_TIMING_TRACKED_KEYS.forEach((key) => {
            const route = routeByKey.get(key);
            if (!route) {
                values[`tiempo_real_${key}_horas`] = null;
                values[`tiempo_proceso_${key}_horas`] = null;
                return;
            }
            values[`tiempo_proceso_${key}_horas`] = toHours(route.actual_end_at, route.actual_start_at);
            const dependency = route.dependency_route_id ? routesById.get(route.dependency_route_id) : null;
            const predecessorEndAt = dependency ? dependency.actual_end_at : control.launchedAt;
            values[`tiempo_real_${key}_horas`] = toHours(route.actual_end_at, predecessorEndAt);
        });

        const columns = Object.keys(values);
        const setClause = columns.map((col, idx) => `${col} = $${idx + 2}`).join(', ');

        await pgQuery(
            `UPDATE flexo_orders SET ${setClause}, tiempos_actualizado_en = NOW() WHERE order_code = $1`,
            [orderCode, ...columns.map((col) => values[col])]
        );

        let productCodes = [];
        if (orderRow.quote_code && orderRow.line_code) {
            const productsResult = await pgQuery(
                `SELECT DISTINCT product_code FROM flexo_products WHERE quote_code = $1 AND line_code = $2 AND motivo_indice IS NOT NULL`,
                [orderRow.quote_code, orderRow.line_code]
            );
            productCodes = productsResult.rows.map((r) => r.product_code);
        }
        if (!productCodes.length && orderRow.product_code) productCodes = [orderRow.product_code];

        for (const productCode of productCodes) {
            await pgQuery(
                `UPDATE flexo_products SET ${setClause}, tiempos_actualizado_en = NOW() WHERE product_code = $1`,
                [productCode, ...columns.map((col) => values[col])]
            );
        }
    } catch (e) { /* non-critical sync */ }
}

