async function getQuoteLineContext(quoteCode, lineCode, client = null) {
    const executor = client || { query: pgQuery };
    const [quoteResult, calcResult] = await Promise.all([
        executor.query(`SELECT * FROM quotes WHERE quote_code = $1 LIMIT 1`, [quoteCode]),
        executor.query(
            `SELECT fc.*
               FROM flexo_calculations fc
               LEFT JOIN quotes q ON q.quote_code = fc.quote_code
              WHERE fc.quote_code = $1
                AND fc.line_code = $2
                AND ${quoteOwnedCalculationPredicate('fc', 'q')}
              ORDER BY fc.created_at DESC NULLS LAST, fc.calculation_code DESC NULLS LAST
              LIMIT 1`,
            [quoteCode, lineCode]
        )
    ]);
    return {
        quote: quoteResult.rows[0] || null,
        line: calcResult.rows[0] || null
    };
}

const QUOTE_TRACKING_MILESTONE_ORDER = ['solicitud', 'finalizacion', 'envio', 'cierre'];

function quoteTrackingAutoState(quote, line) {
    const raw = line?.raw_data || {};
    const sellerName = line?.salesperson_name || raw.VENDEDOR || raw['VENDEDOR | USUARIO'] || quote?.salesperson_name || 'Vendedor';
    const status = String(line?.line_status || raw['SOLICITUD ESTADO'] || raw['ESTADO LINEA'] || quote?.status || '').trim().toLowerCase();
    const quoteDone = ['cotizada', 'finalizada', 'proforma', 'enviada', 'cerrada', 'produccion', 'producción'].some((token) => status.includes(token));
    const requestDone = ['pendiente', 'solicitud', 'vendedor', 'cotiz', 'finaliz', 'proforma', 'enviad', 'cerrad'].some((token) => status.includes(token))
        || String(raw['TRAZABILIDAD | SOLICITUD VENDEDOR'] || '').trim().toLowerCase() === 'si';
    return {
        sellerName,
        solicitud: {
            done: requestDone,
            user: requestDone ? (raw['TRAZABILIDAD | USUARIO SOLICITUD VENDEDOR'] || sellerName) : '',
            date: requestDone ? (raw['TRAZABILIDAD | FECHA SOLICITUD VENDEDOR'] || raw['TRAZABILIDAD | FECHA'] || '') : ''
        },
        finalizacion: {
            done: quoteDone,
            user: quoteDone ? sellerName : '',
            date: quoteDone ? (raw['FECHA CREACION DATE'] || raw['FECHA CREACION'] || '') : ''
        }
    };
}

async function computeQuoteLineTracking(quoteCode, lineCode) {
    const context = await getQuoteLineContext(quoteCode, lineCode);
    const auto = quoteTrackingAutoState(context.quote, context.line);
    const storedResult = await pgQuery(
        `SELECT milestone_key, done, user_name, occurred_at, cr_comment, cr_by, cr_at, outcome, reason, comments, order_code, cantidad_aceptada
           FROM quote_line_tracking
          WHERE quote_code = $1 AND line_code = $2`,
        [quoteCode, lineCode]
    );
    const storedByKey = new Map(storedResult.rows.map((row) => [row.milestone_key, row]));

    const milestones = QUOTE_TRACKING_MILESTONE_ORDER.map((key) => {
        const stored = storedByKey.get(key);
        if (stored) {
            return {
                key,
                done: stored.done,
                user: stored.user_name || '',
                date: stored.occurred_at ? stored.occurred_at.toISOString() : '',
                cr: stored.cr_comment ? { comment: stored.cr_comment, by: stored.cr_by || '', date: stored.cr_at ? stored.cr_at.toISOString() : '' } : null
            };
        }
        if (key === 'solicitud') return { key, done: auto.solicitud.done, user: auto.solicitud.user, date: auto.solicitud.date, cr: null };
        if (key === 'finalizacion') return { key, done: auto.finalizacion.done, user: auto.finalizacion.user, date: auto.finalizacion.date, cr: null };
        return { key, done: false, user: '', date: '', cr: null };
    });

    const cierreRow = storedByKey.get('cierre');
    let closure = cierreRow && cierreRow.outcome
        ? { outcome: cierreRow.outcome, reason: cierreRow.reason || '', comments: cierreRow.comments || '', orderCode: cierreRow.order_code || '', cantidadAceptada: cierreRow.cantidad_aceptada != null ? Number(cierreRow.cantidad_aceptada) : null, by: cierreRow.user_name || '', at: cierreRow.occurred_at ? cierreRow.occurred_at.toISOString() : '' }
        : null;

    // Backward compatibility: quotes closed before the quote_line_tracking migration only
    // have their commercial closure recorded in the legacy raw_data['Cierre_Cotizacion']
    // field (written by the old localStorage-driven flow). If there is no stored 'cierre'
    // row, fall back to reading that field so already-closed quotes don't look re-closeable.
    if (!cierreRow) {
        const legacyClosure = context.line?.raw_data?.['Cierre_Cotizacion'];
        if (legacyClosure && typeof legacyClosure === 'object') {
            const legacyOutcome = legacyClosure.outcome === 'lost' ? 'rejected' : legacyClosure.outcome;
            if (['accepted', 'rejected', 'expired'].includes(legacyOutcome)) {
                closure = {
                    outcome: legacyOutcome,
                    reason: legacyClosure.reason || '',
                    comments: legacyClosure.comments || '',
                    orderCode: legacyClosure.orderCode || '',
                    by: legacyClosure.by || '',
                    at: legacyClosure.date || ''
                };
                const cierreMilestone = milestones.find((item) => item.key === 'cierre');
                if (cierreMilestone) {
                    cierreMilestone.done = true;
                    cierreMilestone.user = legacyClosure.by || '';
                    cierreMilestone.date = legacyClosure.date || '';
                }
            }
        }
    }

    return { milestones, closure };
}

// quotes.status was being set once at creation ("Solicitada") and never touched again —
// the cotizaciones list always showed "Solicitada" regardless of real progress because
// nothing else updated that column. Keep it in sync with the tracking milestones so the
// list reflects reality.
function deriveQuoteStatusFromTracking({ milestones = [], closure = null } = {}) {
    if (closure?.outcome === 'accepted') return 'Producción';
    if (closure?.outcome === 'rejected' || closure?.outcome === 'expired') return 'Cerrada';
    const finalizacion = milestones.find((item) => item.key === 'finalizacion');
    if (finalizacion?.done) return 'Cotizada';
    return 'Solicitada';
}

async function syncQuoteStatusFromTracking(quoteCode, trackingResult) {
    try {
        const nextStatus = deriveQuoteStatusFromTracking(trackingResult);
        await pgQuery(`UPDATE quotes SET status = $2 WHERE quote_code = $1 AND COALESCE(status, '') != $2`, [quoteCode, nextStatus]);
    } catch (error) {
        // Non-critical: the list falls back to line_statuses if this update fails.
    }
}

