// Abre el diálogo nativo de selección de carpeta de Windows en la máquina donde
// corre el servidor (mismo equipo que el navegador en la instalación local) y
// devuelve la ruta absoluta elegida para los campos de "Rutas de Archivos".
app.post('/api/config/seleccionar-carpeta', async (req, res) => {
    if (process.platform !== 'win32') {
        return res.status(400).json({ error: 'El explorador de carpetas solo está disponible en Windows.' });
    }
    const inicialRaw = String(req.body?.inicial || '').trim();
    const inicial = (/^[A-Za-z]:\\[^\r\n"*?<>|]*$/.test(inicialRaw) || /^\\\\[^\r\n"*?<>|]+$/.test(inicialRaw))
        ? inicialRaw
        : '';
    const inicialPs = inicial.replace(/'/g, "''");
    const script = [
        'Add-Type -AssemblyName System.Windows.Forms;',
        '$owner = New-Object System.Windows.Forms.Form;',
        '$owner.TopMost = $true; $owner.ShowInTaskbar = $false; $owner.Opacity = 0;',
        '$owner.Show(); $owner.Activate();',
        '$d = New-Object System.Windows.Forms.FolderBrowserDialog;',
        "$d.Description = 'Selecciona la carpeta base de archivos tecnicos';",
        '$d.ShowNewFolderButton = $true;',
        inicial ? `if (Test-Path -LiteralPath '${inicialPs}') { $d.SelectedPath = '${inicialPs}' };` : '',
        '$r = $d.ShowDialog($owner);',
        '$owner.Close();',
        "if ($r -eq [System.Windows.Forms.DialogResult]::OK) { [Console]::Out.Write($d.SelectedPath) }"
    ].filter(Boolean).join(' ');

    try {
        const child = spawn('powershell.exe', ['-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-Command', script], { windowsHide: true });
        let out = '';
        let errOut = '';
        child.stdout.on('data', (chunk) => { out += chunk.toString(); });
        child.stderr.on('data', (chunk) => { errOut += chunk.toString(); });
        const code = await new Promise((resolve) => {
            child.on('close', resolve);
            child.on('error', () => resolve(-1));
        });
        if (code !== 0) {
            return res.status(500).json({ error: 'No fue posible abrir el explorador de carpetas.', detalle: errOut.trim() || undefined });
        }
        const ruta = out.trim();
        if (!ruta) return res.json({ cancelado: true });
        return res.json({ ruta });
    } catch (error) {
        return res.status(500).json({ error: 'No fue posible abrir el explorador de carpetas.' });
    }
});

