app.delete('/api/admin-users/:id', async (req, res) => {
    try {
        const id = Number(req.params.id);
        if (!Number.isFinite(id) || id <= 0) {
            return res.status(400).json({ error: 'Identificador no válido.' });
        }
        const beforeResult = await pgQuery(
            `SELECT id, full_name, username, password, department, process, photo_url, signature_url, email, phone, phone_secondary,
                    notify_email, notify_whatsapp, notify_sms, is_active, permission_id, default_landing, sap_salesperson_code, sap_salesperson_name
               FROM admin_users
              WHERE id = $1
              LIMIT 1`,
            [id]
        );
        if (!beforeResult.rows.length) {
            return res.status(404).json({ error: 'Usuario no encontrado.' });
        }

        const definitivo = ['1', 'true', 'si', 'sí'].includes(String(req.query?.definitivo || '').trim().toLowerCase());
        if (!(await tieneFacultadUsuarios(req, definitivo ? 'puedeEliminarUsuarios' : 'puedeDarBajaUsuarios'))) {
            return res.status(403).json({ error: definitivo
                ? 'Tu permiso no incluye eliminar usuarios. Si lo necesitas, un administrador puede activarlo en tu permiso.'
                : 'Tu permiso no incluye dar de baja usuarios. Si lo necesitas, un administrador puede activarlo en tu permiso.' });
        }
        if (await bloqueaCambioSobreSuperAdmin(req, id)) {
            return res.status(403).json({ error: MENSAJE_USUARIO_PROTEGIDO });
        }

        if (definitivo) {
            await withTransaction(async (client) => {
                const fkRefs = await client.query(
                    `SELECT ns.nspname AS child_schema,
                            rel.relname AS child_table,
                            att.attname AS child_column,
                            att.attnotnull AS not_null,
                            con.confdeltype AS on_delete
                       FROM pg_constraint con
                       JOIN pg_class rel ON rel.oid = con.conrelid
                       JOIN pg_namespace ns ON ns.oid = rel.relnamespace
                       JOIN pg_class frel ON frel.oid = con.confrelid
                       JOIN pg_namespace fns ON fns.oid = frel.relnamespace
                       JOIN unnest(con.conkey) WITH ORDINALITY AS k(attnum, ord) ON true
                       JOIN pg_attribute att ON att.attrelid = con.conrelid AND att.attnum = k.attnum
                      WHERE con.contype = 'f'
                        AND fns.nspname = 'public'
                        AND frel.relname = 'admin_users'`
                );
                for (const ref of fkRefs.rows) {
                    // La BD resuelve por sí sola las FKs con ON DELETE CASCADE ('c') o SET NULL ('n').
                    if (ref.on_delete === 'c' || ref.on_delete === 'n') continue;
                    if (ref.not_null) {
                        throw new Error(
                            `No se puede eliminar: la columna ${ref.child_schema}.${ref.child_table}.${ref.child_column} referencia al usuario y no admite valor nulo.`
                        );
                    }
                    await client.query(
                        `UPDATE "${ref.child_schema}"."${ref.child_table}" SET "${ref.child_column}" = NULL WHERE "${ref.child_column}" = $1`,
                        [id]
                    );
                }
                await client.query(`DELETE FROM admin_users WHERE id = $1`, [id]);
            });
            await recordAuditDiff({
                moduleKey: 'seguridad',
                entityType: 'admin_users',
                entityKey: String(id),
                beforeValue: buildAdminUserAuditRecord(beforeResult.rows[0]),
                afterValue: {},
                changedBy: getAuditActorFromRequest(req),
                route: req.path
            });
            return res.json({ ok: true, deleted: true, id });
        }

        const result = await pgQuery(
            `UPDATE admin_users
                SET is_active = FALSE,
                    updated_at = NOW()
              WHERE id = $1
          RETURNING id, full_name, username, password, department, process, photo_url, signature_url, email, phone, phone_secondary,
                    notify_email, notify_whatsapp, notify_sms, is_active, permission_id, default_landing, sap_salesperson_code, sap_salesperson_name`,
            [id]
        );
        await recordAuditDiff({
            moduleKey: 'seguridad',
            entityType: 'admin_users',
            entityKey: String(id),
            beforeValue: buildAdminUserAuditRecord(beforeResult.rows[0]),
            afterValue: buildAdminUserAuditRecord(result.rows[0]),
            changedBy: getAuditActorFromRequest(req),
            route: req.path
        });
        res.json(normalizeAdminUserRecord(result.rows[0]));
    } catch (error) {
        const status = /no se puede eliminar/i.test(error.message || '') ? 409 : 400;
        res.status(status).json({ error: error.message || 'No fue posible eliminar el usuario.' });
    }
});

