app.post('/api/costos/procesos/:key/turnos/bulk', async (req, res) => {
    try {
        const { key } = req.params;
        const { turno_ids, fecha_inicio, fecha_fin, es_temporal } = req.body || {};
        if (!Array.isArray(turno_ids)) {
            return res.status(400).json({ ok: false, error: 'turno_ids debe ser un arreglo.' });
        }
        if (es_temporal && (!fecha_inicio || !fecha_fin)) {
            return res.status(400).json({ ok: false, error: 'fecha_inicio y fecha_fin son requeridos para configuracion temporal.' });
        }
        await pgQuery(
            `DELETE FROM costos_proceso_turnos
              WHERE proceso_key = $1 AND es_temporal = $2
                AND (fecha_inicio = $3 OR ($3 IS NULL AND fecha_inicio IS NULL))
                AND (fecha_fin = $4 OR ($4 IS NULL AND fecha_fin IS NULL))`,
            [key, es_temporal || false, fecha_inicio || null, fecha_fin || null]
        );
        for (const turnoId of turno_ids) {
            await pgQuery(
                `INSERT INTO costos_proceso_turnos (proceso_key, turno_id, fecha_inicio, fecha_fin, es_temporal)
                 VALUES ($1, $2, $3, $4, $5)`,
                [key, turnoId, fecha_inicio || null, fecha_fin || null, es_temporal || false]
            );
        }
        const result = await pgQuery(
            `SELECT pct.id, pct.turno_id, pct.fecha_inicio, pct.fecha_fin, pct.es_temporal,
                    t.nombre, t.hora_inicio, t.hora_fin, t.duracion_min, t.activo
               FROM costos_proceso_turnos pct
               JOIN costos_turnos t ON t.id = pct.turno_id
              WHERE pct.proceso_key = $1
              ORDER BY t.hora_inicio ASC`,
            [key]
        );
        res.json({ ok: true, data: result.rows });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar la disponibilidad del proceso.' });
    }
});

app.get('/api/audit-log', async (req, res) => {
    try {
        const values = [];
        const filters = [];
        const moduleKey = String(req.query.module || '').trim();
        const presentationKey = String(req.query.presentation || '').trim();
        const changedBy = String(req.query.user || '').trim();
        const fieldSearch = String(req.query.field || '').trim();
        const dateFrom = String(req.query.dateFrom || '').trim();
        const dateTo = String(req.query.dateTo || '').trim();
        const limit = Math.min(Math.max(Number(req.query.limit) || 300, 1), 1000);

        if (moduleKey) {
            values.push(moduleKey);
            filters.push(`module_key = $${values.length}`);
        }
        if (presentationKey) {
            values.push(presentationKey);
            filters.push(`presentation_key = $${values.length}`);
        }
        if (changedBy) {
            values.push(`%${changedBy}%`);
            filters.push(`changed_by ILIKE $${values.length}`);
        }
        if (fieldSearch) {
            values.push(`%${fieldSearch}%`);
            filters.push(`(
                field_label ILIKE $${values.length}
                OR field_key ILIKE $${values.length}
                OR COALESCE(section_label, '') ILIKE $${values.length}
                OR COALESCE(row_label, '') ILIKE $${values.length}
            )`);
        }
        if (dateFrom) {
            values.push(dateFrom);
            filters.push(`changed_at >= $${values.length}::timestamptz`);
        }
        if (dateTo) {
            values.push(`${dateTo} 23:59:59`);
            filters.push(`changed_at <= $${values.length}::timestamptz`);
        }

        values.push(limit);
        const whereClause = filters.length ? `WHERE ${filters.join(' AND ')}` : '';
        const result = await pgQuery(
            `SELECT id, module_key, entity_type, entity_key, presentation_key, presentation_label,
                    section_key, section_label, row_key, row_label, field_key, field_label,
                    old_value, new_value, old_value_display, new_value_display, changed_by, route, changed_at
               FROM audit_log
               ${whereClause}
              ORDER BY changed_at DESC, id DESC
              LIMIT $${values.length}`,
            values
        );

        res.json({
            items: result.rows.map((row) => ({
                id: row.id,
                module_key: row.module_key,
                entity_type: row.entity_type,
                entity_key: row.entity_key,
                presentation_key: row.presentation_key,
                presentation_label: row.presentation_label,
                section_key: row.section_key,
                section_label: row.section_label,
                row_key: row.row_key,
                row_label: row.row_label,
                field_key: row.field_key,
                field_label: row.field_label,
                old_value: row.old_value,
                new_value: row.new_value,
                old_value_display: row.old_value_display,
                new_value_display: row.new_value_display,
                changed_by: row.changed_by,
                route: row.route,
                changed_at: row.changed_at
            }))
        });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar la auditoría.' });
    }
});

