app.post('/api/cotizaciones/:codigo/lineas/:linea/seguimiento', async (req, res) => {
    try {
        const { codigo, linea } = req.params;
        const payload = req.body || {};
        const milestoneKey = String(payload.milestoneKey || '').trim();
        const action = String(payload.action || '').trim();
        if (!QUOTE_TRACKING_MILESTONE_ORDER.includes(milestoneKey)) {
            return res.status(400).json({ error: 'Hito de seguimiento inválido.' });
        }
        const actingUser = getRequestUserName(req, 'Vendedor');
        const keyIndex = QUOTE_TRACKING_MILESTONE_ORDER.indexOf(milestoneKey);
        const keysFromHere = QUOTE_TRACKING_MILESTONE_ORDER.slice(keyIndex);

        if (action === 'complete') {
            await pgQuery(
                `INSERT INTO quote_line_tracking (quote_code, line_code, milestone_key, done, user_name, occurred_at, cr_comment, cr_by, cr_at, updated_at)
                 VALUES ($1, $2, $3, true, $4, NOW(), '', '', NULL, NOW())
                 ON CONFLICT (quote_code, line_code, milestone_key) DO UPDATE SET
                    done = true, user_name = EXCLUDED.user_name, occurred_at = NOW(), cr_comment = '', cr_by = '', cr_at = NULL, updated_at = NOW()`,
                [codigo, linea, milestoneKey, actingUser]
            );
        } else if (action === 'undo') {
            // Upsert an explicit done=false "tombstone" row (instead of deleting) so that
            // milestones with a SAP-derived auto-fallback (solicitud, finalizacion) don't
            // silently reappear as done on the next GET. For envio/cierre, an explicit
            // done=false row is equivalent to no row at all, so a uniform upsert is safe
            // for the whole cascade.
            await pgQuery(
                `INSERT INTO quote_line_tracking (quote_code, line_code, milestone_key, done, user_name, occurred_at, cr_comment, cr_by, cr_at, outcome, reason, comments, order_code, updated_at)
                 SELECT $1, $2, key, false, '', NULL, '', '', NULL, NULL, '', '', '', NOW()
                   FROM UNNEST($3::text[]) AS key
                 ON CONFLICT (quote_code, line_code, milestone_key) DO UPDATE SET
                    done = false, user_name = '', occurred_at = NULL, cr_comment = '', cr_by = '', cr_at = NULL,
                    outcome = NULL, reason = '', comments = '', order_code = '', cantidad_aceptada = NULL, updated_at = NOW()`,
                [codigo, linea, keysFromHere]
            );
        } else if (action === 'request-changes') {
            const comment = String(payload.comment || '').trim();
            if (!comment) return res.status(400).json({ error: 'El comentario de la solicitud de cambios es obligatorio.' });
            await pgQuery(
                `DELETE FROM quote_line_tracking WHERE quote_code = $1 AND line_code = $2 AND milestone_key = ANY($3::text[])`,
                [codigo, linea, keysFromHere]
            );
            await pgQuery(
                `INSERT INTO quote_line_tracking (quote_code, line_code, milestone_key, done, user_name, cr_comment, cr_by, cr_at, updated_at)
                 VALUES ($1, $2, $3, false, '', $4, $5, NOW(), NOW())`,
                [codigo, linea, milestoneKey, comment, actingUser]
            );
        } else if (action === 'close') {
            if (milestoneKey !== 'cierre') return res.status(400).json({ error: 'El cierre solo aplica al hito de Finalización Comercial.' });
            const outcome = String(payload.outcome || '').trim();
            if (!['accepted', 'rejected', 'expired'].includes(outcome)) {
                return res.status(400).json({ error: 'Resultado de cierre inválido.' });
            }
            await pgQuery(
                `INSERT INTO quote_line_tracking (quote_code, line_code, milestone_key, done, user_name, occurred_at, outcome, reason, comments, order_code, cantidad_aceptada, updated_at)
                 VALUES ($1, $2, 'cierre', true, $3, NOW(), $4, $5, $6, $7, $8, NOW())
                 ON CONFLICT (quote_code, line_code, milestone_key) DO UPDATE SET
                    done = true, user_name = EXCLUDED.user_name, occurred_at = NOW(), outcome = EXCLUDED.outcome, reason = EXCLUDED.reason, comments = EXCLUDED.comments, order_code = EXCLUDED.order_code, cantidad_aceptada = EXCLUDED.cantidad_aceptada, updated_at = NOW()`,
                [codigo, linea, actingUser, outcome, String(payload.reason || ''), String(payload.comments || ''), String(payload.orderCode || ''), outcome === 'accepted' && Number(payload.cantidadAceptada) > 0 ? Number(payload.cantidadAceptada) : null]
            );
        } else {
            return res.status(400).json({ error: 'Acción de seguimiento inválida.' });
        }

        const result = await computeQuoteLineTracking(codigo, linea);
        await syncQuoteStatusFromTracking(codigo, result);
        res.json(result);
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible actualizar el seguimiento de la línea.' });
    }
});

app.get('/api/vendedores/mi-pipeline', async (req, res) => {
    try {
        const session = readErpSessionFromRequest(req);
        const username = String(session?.username || '').trim();
        if (!username) return res.json({ isVendedor: false, salespersonName: '', counts: {}, pendientes: [] });

        const requestedUsername = String(req.query?.usuarioVendedor || '').trim();
        const canOverrideSalesperson = requestedUsername && isImplementerPermissionName(session?.permissionName);
        const targetUsername = canOverrideSalesperson ? requestedUsername : username;

        const { fullName: salespersonName, isVendedor } = await resolveLocalVendedorIdentity(targetUsername);
        if (!isVendedor) {
            return res.json({ isVendedor: false, salespersonName: '', counts: {}, pendientes: [] });
        }

        const quotesResult = await pgQuery(
            `SELECT fc.quote_code, fc.line_code, q.customer_name, t.milestone_key, t.done, t.outcome
               FROM flexo_calculations fc
               JOIN quotes q ON q.quote_code = fc.quote_code AND q.salesperson_name = $1
               LEFT JOIN quote_line_tracking t ON t.quote_code = fc.quote_code AND t.line_code = fc.line_code
              WHERE ${quoteOwnedCalculationPredicate('fc', 'q')}`,
            [salespersonName]
        );

        const byLine = new Map();
        for (const row of quotesResult.rows) {
            const lineKey = `${row.quote_code}::${row.line_code || 'sin-linea'}`;
            if (!byLine.has(lineKey)) {
                byLine.set(lineKey, { quoteCode: row.quote_code, customerName: row.customer_name || '', lineCode: row.line_code || '', envioDone: false, cierreDone: false, outcome: null });
            }
            const entry = byLine.get(lineKey);
            if (row.milestone_key === 'envio' && row.done) entry.envioDone = true;
            if (row.milestone_key === 'cierre' && row.done) { entry.cierreDone = true; entry.outcome = row.outcome; }
        }

        const counts = { pendiente: 0, finalizadaSinEnviar: 0, enviada: 0, aceptada: 0, rechazada: 0, expirada: 0 };
        const pendientes = [];
        for (const entry of byLine.values()) {
            if (!entry.lineCode) continue;
            let stage;
            if (entry.cierreDone && entry.outcome === 'accepted') { stage = 'aceptada'; counts.aceptada += 1; }
            else if (entry.cierreDone && entry.outcome === 'rejected') { stage = 'rechazada'; counts.rechazada += 1; }
            else if (entry.cierreDone && entry.outcome === 'expired') { stage = 'expirada'; counts.expirada += 1; }
            else if (entry.envioDone) { stage = 'enviada'; counts.enviada += 1; pendientes.push({ quoteCode: entry.quoteCode, lineCode: entry.lineCode, customerName: entry.customerName, stage }); }
            else { stage = 'pendiente'; counts.pendiente += 1; }
        }

        res.json({ isVendedor: true, salespersonName, counts, pendientes: pendientes.slice(0, 8) });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar el pipeline de ventas.' });
    }
});

// sap_invoices.doc_date es TEXT y puede venir como 'YYYY-MM-DD...' o 'YYYYMMDD' (mismo caso que
// ya maneja ventasJoinSql() en services/socios-service.js) — se normaliza a DATE real aquí.
const SAP_INVOICE_DATE_SQL = `
    CASE
        WHEN f.doc_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN substring(f.doc_date, 1, 10)::date
        WHEN f.doc_date ~ '^[0-9]{8}$' THEN to_date(f.doc_date, 'YYYYMMDD')
        ELSE NULL
    END`;

app.get('/api/vendedores/dashboard', async (req, res) => {
    try {
        const session = readErpSessionFromRequest(req);
        const username = String(session?.username || '').trim();
        if (!username) return res.json({ isVendedor: false, salespersonName: '' });

        const requestedUsername = String(req.query?.usuarioVendedor || '').trim();
        const canOverrideSalesperson = requestedUsername && isImplementerPermissionName(session?.permissionName);
        const targetUsername = canOverrideSalesperson ? requestedUsername : username;

        const { fullName: salespersonName, isVendedor } = await resolveLocalVendedorIdentity(targetUsername);
        if (!isVendedor) {
            return res.json({ isVendedor: false, salespersonName: '' });
        }

        const [ordenesResult, cotizadoResult, facturadoResult, facturasResult, leadsResult, topClientesResult, seguimientoResult, pendientesCotizadorResult] = await Promise.all([
            pgQuery(
                `SELECT o.order_code, o.quote_code, o.line_code, q.customer_name, o.order_status,
                        o.created_at, o.delivered_on, o.ordered_quantity,
                        cur.process_name AS current_process_name,
                        cur.route_status AS current_process_status,
                        COALESCE(cur.stage_started_at, o.created_at) AS current_process_since
                   FROM flexo_orders o
                   JOIN quotes q ON q.quote_code = o.quote_code AND q.salesperson_name = $1
                   LEFT JOIN LATERAL (
                       SELECT r.nombre_proceso AS process_name,
                              CASE r.estado
                                  WHEN 'EN_MARCHA' THEN 'RUN'
                                  WHEN 'PREPARACION' THEN 'SETUP'
                                  WHEN 'EN_PARO' THEN 'PARO'
                                  ELSE r.estado
                              END AS route_status,
                              COALESCE(r.fecha_real_inicio, r.actualizado_en) AS stage_started_at
                         FROM orden_proceso r
                        WHERE r.codigo_orden = o.order_code
                        ORDER BY
                          CASE WHEN r.estado IN ('EN_MARCHA', 'PREPARACION', 'EN_PARO') THEN 0
                               WHEN r.estado = 'PENDIENTE' THEN 1
                               ELSE 2 END,
                          r.secuencia ASC
                        LIMIT 1
                   ) cur ON true
                  WHERE LOWER(COALESCE(o.order_status, o.raw_data->>'status', '')) NOT IN
                        ('entregada', 'entregado', 'completada', 'completado', 'cerrada', 'cerrado', 'cancelada', 'cancelado')
                  ORDER BY o.created_at DESC
                  LIMIT 20`,
                [salespersonName]
            ),
            pgQuery(
                `SELECT to_char(t.occurred_at, 'YYYY-MM') AS mes,
                        COUNT(*)::int AS cantidad,
                        COALESCE(SUM(fc.total_cost), 0)::numeric AS monto
                   FROM quote_line_tracking t
                   JOIN quotes q ON q.quote_code = t.quote_code AND q.salesperson_name = $1
                   LEFT JOIN flexo_calculations fc ON fc.quote_code = t.quote_code AND fc.line_code = t.line_code
                  WHERE t.milestone_key = 'cierre' AND t.done = true AND t.outcome = 'accepted'
                    AND t.occurred_at >= date_trunc('month', CURRENT_DATE - INTERVAL '5 months')
                  GROUP BY 1
                  ORDER BY 1`,
                [salespersonName]
            ),
            pgQuery(
                `WITH norm AS (
                    SELECT f.doc_total, ${SAP_INVOICE_DATE_SQL} AS fecha
                      FROM sap_invoices f
                      JOIN business_partners bp ON UPPER(TRIM(f.card_code)) = UPPER(TRIM(bp.partner_code))
                     WHERE bp.salesperson_name = $1
                 )
                 SELECT to_char(fecha, 'YYYY-MM') AS mes,
                        COUNT(*)::int AS cantidad,
                        COALESCE(SUM(doc_total), 0)::numeric AS monto
                   FROM norm
                  WHERE fecha IS NOT NULL AND fecha >= date_trunc('month', CURRENT_DATE - INTERVAL '5 months')
                  GROUP BY 1
                  ORDER BY 1`,
                [salespersonName]
            ),
            pgQuery(
                `SELECT f.doc_num, f.card_code, f.card_name, f.doc_total, f.currency, f.document_status, ${SAP_INVOICE_DATE_SQL} AS fecha
                   FROM sap_invoices f
                   JOIN business_partners bp ON UPPER(TRIM(f.card_code)) = UPPER(TRIM(bp.partner_code))
                  WHERE bp.salesperson_name = $1
                  ORDER BY fecha DESC NULLS LAST
                  LIMIT 20`,
                [salespersonName]
            ),
            pgQuery(
                `SELECT bp.partner_code, bp.partner_name, bp.email, bp.created_at
                   FROM business_partners bp
                  WHERE bp.salesperson_name = $1 AND bp.estado_socio = 'PROSPECTO'
                  ORDER BY bp.created_at DESC
                  LIMIT 20`,
                [salespersonName]
            ),
            pgQuery(
                `WITH norm AS (
                    SELECT f.doc_total, f.card_code, ${SAP_INVOICE_DATE_SQL} AS fecha
                      FROM sap_invoices f
                      JOIN business_partners bp ON UPPER(TRIM(f.card_code)) = UPPER(TRIM(bp.partner_code))
                     WHERE bp.salesperson_name = $1
                 )
                 SELECT bp.partner_name, bp.partner_code,
                        COALESCE(SUM(norm.doc_total), 0)::numeric AS total,
                        COUNT(norm.*)::int AS facturas
                   FROM norm
                   JOIN business_partners bp ON UPPER(TRIM(norm.card_code)) = UPPER(TRIM(bp.partner_code))
                  WHERE norm.fecha IS NULL OR norm.fecha >= CURRENT_DATE - INTERVAL '12 months'
                  GROUP BY bp.partner_name, bp.partner_code
                  ORDER BY total DESC
                  LIMIT 5`,
                [salespersonName]
            ),
            pgQuery(
                `SELECT envio.quote_code, envio.line_code, q.customer_name, envio.occurred_at AS enviada_en
                   FROM quote_line_tracking envio
                   JOIN quotes q ON q.quote_code = envio.quote_code AND q.salesperson_name = $1
                   LEFT JOIN quote_line_tracking cierre
                          ON cierre.quote_code = envio.quote_code AND cierre.line_code = envio.line_code
                         AND cierre.milestone_key = 'cierre' AND cierre.done = true
                  WHERE envio.milestone_key = 'envio' AND envio.done = true
                    AND cierre.id IS NULL
                    AND envio.occurred_at < NOW() - INTERVAL '7 days'
                  ORDER BY envio.occurred_at ASC
                  LIMIT 20`,
                [salespersonName]
            ),
            pgQuery(
                `SELECT fc.quote_code, fc.line_code, q.customer_name,
                        COALESCE(sol.occurred_at, fc.created_at) AS solicitada_en,
                        (sol.id IS NOT NULL) AS enviada_a_cotizador
                   FROM flexo_calculations fc
                   JOIN quotes q ON q.quote_code = fc.quote_code AND q.salesperson_name = $1
                   LEFT JOIN quote_line_tracking sol
                          ON sol.quote_code = fc.quote_code AND sol.line_code = fc.line_code
                         AND sol.milestone_key = 'solicitud' AND sol.done = true
                   LEFT JOIN quote_line_tracking fin
                          ON fin.quote_code = fc.quote_code AND fin.line_code = fc.line_code
                         AND fin.milestone_key = 'finalizacion' AND fin.done = true
                   LEFT JOIN quote_line_tracking env
                          ON env.quote_code = fc.quote_code AND env.line_code = fc.line_code
                         AND env.milestone_key = 'envio' AND env.done = true
                   LEFT JOIN quote_line_tracking cierre
                          ON cierre.quote_code = fc.quote_code AND cierre.line_code = fc.line_code
                         AND cierre.milestone_key = 'cierre' AND cierre.done = true
                  WHERE fin.id IS NULL AND env.id IS NULL AND cierre.id IS NULL
                  ORDER BY solicitada_en ASC
                  LIMIT 20`,
                [salespersonName]
            )
        ]);

        res.json({
            isVendedor: true,
            salespersonName,
            ordenesEnProceso: ordenesResult.rows,
            ventasMensuales: { cotizadoAceptado: cotizadoResult.rows, facturado: facturadoResult.rows },
            facturas: facturasResult.rows,
            leads: leadsResult.rows,
            topClientes: topClientesResult.rows,
            cotizacionesPendientesCotizador: pendientesCotizadorResult.rows,
            cotizacionesPendientesSeguimiento: seguimientoResult.rows
        });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar el dashboard de ventas.' });
    }
});

app.get('/api/cotizaciones/:codigo/lineas/:linea/adjuntos', async (req, res) => {
    try {
        const { codigo, linea } = req.params;
        const context = await getQuoteLineContext(codigo, linea);
        if (!context.line) {
            return res.status(404).json({ error: 'No se encontró la línea.' });
        }
        const stored = await getStoredAttachments(codigo, linea);
        res.json({
            items: [
                ...stored.map((item) => ({
                    id: item.id,
                    key: item.file_name,
                    label: item.file_name,
                    value: item.file_name,
                    mime_type: item.mime_type,
                    file_ext: item.file_ext,
                    notes: item.notes,
                    uploaded_by: item.uploaded_by,
                    created_at: item.created_at,
                    size_bytes: Number(item.size_bytes || 0),
                    isStored: true
                })),
                ...extractLineAttachments(context.line)
            ]
        });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar los adjuntos de la línea.' });
    }
});

app.post('/api/cotizaciones/:codigo/lineas/:linea/adjuntos', async (req, res) => {
    try {
        const { codigo, linea } = req.params;
        const payload = req.body || {};
        const fileName = String(payload.fileName || '').trim();
        const contentBase64 = normalizeAttachmentBase64(payload.contentBase64);
        if (!fileName || !contentBase64) {
            return res.status(400).json({ error: 'Debes indicar el nombre y contenido del archivo.' });
        }
        const context = await getQuoteLineContext(codigo, linea);
        if (!context.line) {
            return res.status(404).json({ error: 'No se encontró la línea para adjuntar archivos.' });
        }

        const attachmentId = crypto.randomUUID();
        let stored = null;
        let insert = null;
        try {
            stored = writeQuoteLineAttachmentFile({ id: attachmentId, quoteCode: codigo, lineCode: linea, fileName, contentBase64 });
            insert = await pgQuery(
                `INSERT INTO quote_line_attachments (
                    id, quote_code, line_code, file_name, mime_type, file_ext, content_base64, storage_path, size_bytes, content_sha256, notes, uploaded_by
                 ) VALUES ($1,$2,$3,$4,$5,$6,NULL,$7,$8,$9,$10,$11)
                 RETURNING id, quote_code, line_code, file_name, mime_type, file_ext, notes, uploaded_by, created_at,
                           COALESCE(size_bytes, 0) AS size_bytes`,
                [
                    attachmentId,
                    codigo,
                    linea,
                    fileName,
                    pickFirstValue(payload.mimeType, 'application/octet-stream'),
                    pickFirstValue(payload.fileExt, path.extname(fileName).replace('.', '')),
                    stored.storagePath,
                    stored.sizeBytes,
                    stored.contentSha256,
                    pickFirstValue(payload.notes),
                    pickFirstValue(payload.uploadedBy, 'admin')
                ]
            );
        } catch (error) {
            if (stored?.storagePath) deleteQuoteAttachmentFile(stored.storagePath);
            throw error;
        }

        res.json({ ok: true, adjunto: insert.rows[0] });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible guardar el adjunto.' });
    }
});

app.get('/api/adjuntos/:id/download', async (req, res) => {
    try {
        const result = await pgQuery(
            `SELECT file_name, mime_type, content_base64, storage_path
               FROM quote_line_attachments
              WHERE id = $1
              LIMIT 1`,
            [req.params.id]
        );
        if (!result.rows.length) {
            return res.status(404).send('Adjunto no encontrado.');
        }
        const attachment = result.rows[0];
        res.setHeader('Content-Type', attachment.mime_type || 'application/octet-stream');
        res.setHeader('Content-Disposition', `attachment; filename="${attachment.file_name}"`);
        const absolutePath = resolveQuoteAttachmentStoragePath(attachment.storage_path);
        if (absolutePath && fs.existsSync(absolutePath)) {
            return res.sendFile(absolutePath);
        }
        const buffer = Buffer.from(String(attachment.content_base64 || ''), 'base64');
        if (!buffer.length) {
            return res.status(404).send('Archivo adjunto no encontrado en disco.');
        }
        res.send(buffer);
    } catch (error) {
        res.status(500).send(error.message || 'No fue posible descargar el adjunto.');
    }
});

