app.post('/api/planificacion/procesos', async (req, res) => {
    try {
        const { nombre, orden_secuencia, color_hex, icono, es_paralelo, activo, calendario_id } = req.body || {};
        if (!nombre || !orden_secuencia) {
            return res.status(400).json({ ok: false, error: 'nombre y orden_secuencia son requeridos.' });
        }
        const processKey = normalizePlanningKey(nombre);
        const result = await pgQuery(`
            INSERT INTO production_process_definitions (
                process_key, process_name, sequence_order, color_hex, icon_key, is_parallel, is_active, calendario_id
            ) VALUES ($1,$2,$3,$4,$5,$6,$7,$8::uuid)
            RETURNING
                id AS id_proceso,
                process_key,
                process_name AS nombre,
                sequence_order AS orden_secuencia,
                color_hex,
                icon_key AS icono,
                is_parallel AS es_paralelo,
                is_active AS activo
        `, [processKey, nombre, Number(orden_secuencia), color_hex || '#378ADD', icono || '[P]', Boolean(es_paralelo), activo !== false, calendario_id || null]);
        res.json({ ok: true, data: result.rows[0] });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible crear el proceso de planificación.' });
    }
});

app.put('/api/planificacion/procesos/:id', async (req, res) => {
    try {
        const { nombre, orden_secuencia, color_hex, icono, es_paralelo, activo } = req.body || {};
        const cambiaCalendario = Object.prototype.hasOwnProperty.call(req.body || {}, 'calendario_id');
        const result = await pgQuery(`
            UPDATE production_process_definitions
            SET process_name = COALESCE($1, process_name),
                sequence_order = COALESCE($2, sequence_order),
                color_hex = COALESCE($3, color_hex),
                icon_key = COALESCE($4, icon_key),
                is_parallel = COALESCE($5, is_parallel),
                is_active = COALESCE($6, is_active),
                calendario_id = CASE WHEN $8::boolean THEN $9::uuid ELSE calendario_id END,
                updated_at = NOW()
            WHERE id = $7::uuid
            RETURNING
                id AS id_proceso,
                process_key,
                process_name AS nombre,
                sequence_order AS orden_secuencia,
                color_hex,
                icon_key AS icono,
                is_parallel AS es_paralelo,
                is_active AS activo
        `, [nombre || null, orden_secuencia ? Number(orden_secuencia) : null, color_hex || null, icono || null, typeof es_paralelo === 'boolean' ? es_paralelo : null, typeof activo === 'boolean' ? activo : null, req.params.id, cambiaCalendario, cambiaCalendario ? (req.body.calendario_id || null) : null]);
        if (!result.rows.length) {
            return res.status(404).json({ ok: false, error: 'Proceso no encontrado.' });
        }
        res.json({ ok: true, data: result.rows[0] });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible actualizar el proceso.' });
    }
});

app.delete('/api/planificacion/procesos/:id', async (req, res) => {
    try {
        const countResult = await pgQuery(`SELECT COUNT(*)::int AS total FROM proceso_maquina WHERE proceso_id = $1::uuid`, [req.params.id]);
        if (Number(countResult.rows[0]?.total || 0) > 0) {
            return res.status(400).json({ ok: false, error: 'Tiene máquinas asignadas. Quítalas primero.' });
        }
        await pgQuery(`DELETE FROM production_process_definitions WHERE id = $1::uuid`, [req.params.id]);
        res.json({ ok: true });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible eliminar el proceso.' });
    }
});

app.put('/api/planificacion/procesos-orden', async (req, res) => {
    try {
        const ids = Array.isArray(req.body?.ids) ? req.body.ids.map(String) : [];
        if (!ids.length) return res.status(400).json({ ok: false, error: 'Debes indicar el orden de los procesos.' });
        await pgQuery(`
            UPDATE production_process_definitions p
            SET sequence_order = o.posicion, updated_at = NOW()
            FROM unnest($1::uuid[]) WITH ORDINALITY AS o(id, posicion)
            WHERE p.id = o.id
        `, [ids]);
        res.json({ ok: true });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar el orden de los procesos.' });
    }
});

