// date.nager.at no trae nombre en español para Guatemala (name === localName, ambos en inglés).
const FERIADOS_GT_NOMBRES_ES = Object.freeze({
    "new year's day": 'Año Nuevo',
    'maundy thursday': 'Jueves Santo',
    'good friday': 'Viernes Santo',
    'holy saturday': 'Sábado Santo',
    'easter sunday': 'Domingo de Resurrección',
    "international workers' day": 'Día del Trabajo',
    'army day': 'Día del Ejército',
    'independence day': 'Día de la Independencia',
    'revolution day': 'Día de la Revolución',
    "all saints' day": 'Día de Todos los Santos',
    'christmas eve': 'Nochebuena',
    'christmas day': 'Navidad',
    "new year's eve": 'Fin de Año'
});

async function fetchFeriadosGuatemalaDesdeAPI(anio) {
    const url = `https://date.nager.at/api/v3/PublicHolidays/${anio}/GT`;
    const response = await fetch(url, { signal: AbortSignal.timeout(10000) });
    if (!response.ok) throw new Error(`API de feriados respondió ${response.status}`);
    const data = await response.json();
    return (Array.isArray(data) ? data : [])
        .map((item) => {
            const nombreOriginal = item.localName || item.name || 'Feriado';
            const nombre = FERIADOS_GT_NOMBRES_ES[String(nombreOriginal).toLowerCase()] || nombreOriginal;
            return { fecha: String(item.date || '').slice(0, 10), nombre };
        })
        .filter((item) => /^\d{4}-\d{2}-\d{2}$/.test(item.fecha));
}

async function sincronizarFeriadosGuatemala(anio) {
    const feriados = await fetchFeriadosGuatemalaDesdeAPI(anio);
    let insertados = 0;
    for (const feriado of feriados) {
        const { rowCount } = await pgQuery(
            `INSERT INTO dias_feriados (fecha, nombre, recurrente, activo)
             VALUES ($1::date, $2, false, true)
             ON CONFLICT (fecha) DO NOTHING`,
            [feriado.fecha, feriado.nombre]
        );
        if (rowCount) insertados += 1;
    }
    return { anio, total: feriados.length, insertados };
}

// Se revisa una vez al iniciar el servidor: si al año actual (o al siguiente, desde
// octubre) le faltan feriados en la BD, los trae solo de date.nager.at. Así no hay que
// escribirlos a mano cada enero. Nunca truena el arranque si la API falla (fail-open).
async function asegurarFeriadosDelAnio() {
    const ahora = new Date();
    const anioActual = ahora.getFullYear();
    const anios = ahora.getMonth() >= 9 ? [anioActual, anioActual + 1] : [anioActual];
    for (const anio of anios) {
        try {
            const { rows } = await pgQuery(
                `SELECT count(*)::int AS total FROM dias_feriados WHERE EXTRACT(YEAR FROM fecha) = $1`,
                [anio]
            );
            if (Number(rows[0]?.total || 0) === 0) {
                const resultado = await sincronizarFeriadosGuatemala(anio);
                console.log(`[feriados] ${resultado.insertados} feriados de Guatemala cargados para ${anio} desde date.nager.at`);
            }
        } catch (error) {
            console.warn(`[feriados] No se pudo sincronizar el año ${anio} desde date.nager.at: ${error.message}`);
        }
    }
}

