// Resumen de los próximos N días para la alerta de calendario en Seguimiento:
// por cada día dice si es fin de semana y qué calendarios tienen una excepción
// (feriado, mantenimiento, etc.) ese día — así el planificador ve de un vistazo
// qué se le viene encima aunque no haya hecho ninguna preparación manual.
app.get('/api/planificacion/calendarios/proximos-eventos', async (req, res) => {
    try {
        const dias = Math.min(92, Math.max(1, Number(req.query.dias) || 4));
        const today = capacityDateKey(new Date());
        const endDate = capacityDateKey(capacityAddDays(today, dias - 1));
        const [exceptionsRes, calendarsRes] = await Promise.all([
            pgQuery(`
                SELECT e.exception_date, e.exception_type, e.description,
                       e.override_start_hour, e.override_end_hour,
                       c.id AS calendar_id, c.calendar_name, c.resource_type, c.resource_name
                  FROM resource_calendar_exceptions e
                  JOIN resource_calendars c ON c.id = e.calendar_id
                 WHERE e.is_active = TRUE AND c.is_active = TRUE
                   AND e.exception_date BETWEEN $1 AND $2
                 ORDER BY e.exception_date
            `, [today, endDate]),
            pgQuery(`SELECT id, calendar_name FROM resource_calendars WHERE is_active = TRUE`)
        ]);
        const byDate = new Map();
        (exceptionsRes.rows || []).forEach((row) => {
            const dateKey = capacityDateKey(row.exception_date);
            if (!byDate.has(dateKey)) byDate.set(dateKey, []);
            byDate.get(dateKey).push({
                calendarId: String(row.calendar_id),
                calendarName: row.calendar_name,
                resourceType: row.resource_type,
                resourceName: row.resource_name,
                exceptionType: row.exception_type,
                description: row.description || '',
                hasOverrideHours: row.override_start_hour !== null && row.override_end_hour !== null
            });
        });
        const days = [];
        for (let i = 0; i < dias; i++) {
            const dateKey = capacityDateKey(capacityAddDays(today, i));
            const dow = new Date(`${dateKey}T00:00:00.000Z`).getUTCDay();
            days.push({
                date: dateKey,
                isWeekend: dow === 0 || dow === 6,
                events: byDate.get(dateKey) || []
            });
        }
        res.json({ ok: true, data: { days, totalCalendars: (calendarsRes.rows || []).length } });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar los proximos eventos de calendario.' });
    }
});

