// Modificar un turno crea un bloque de planeación nuevo: el turno vigente se
// cierra (valid_to = el día antes de la fecha efectiva) y se inserta uno nuevo
// con los valores editados desde esa fecha — nunca se sobreescribe el que ya
// rigió, para poder saber después qué turno aplicó en qué fechas.
app.put('/api/planificacion/calendarios/:id/turnos/:shiftId', async (req, res) => {
    try {
        const { shiftId } = req.params;
        const { shift_name, day_of_week, start_hour, end_hour, is_active, effective_from } = req.body;
        const current = await pgQuery(`SELECT * FROM resource_shifts WHERE id = $1`, [shiftId]);
        if (!current.rows.length) return res.status(404).json({ ok: false, error: 'Turno no encontrado.' });
        const row = current.rows[0];

        if (is_active === false) {
            const closeFrom = effective_from || capacityDateKey(new Date());
            const result = await pgQuery(
                `UPDATE resource_shifts SET valid_to = ($1::date - INTERVAL '1 day')::date WHERE id = $2 RETURNING *`,
                [closeFrom, shiftId]
            );
            invalidateFiniteCapacityCache();
            return res.json({ ok: true, data: result.rows[0] });
        }

        const effectiveFrom = effective_from || capacityDateKey(new Date());
        const nextShiftName = shift_name ?? row.shift_name;
        const nextDay = day_of_week ?? row.day_of_week;
        const nextStart = start_hour ?? row.start_hour;
        const nextEnd = end_hour ?? row.end_hour;

        const result = await withTransaction(async (client) => {
            await client.query(
                `UPDATE resource_shifts SET valid_to = ($1::date - INTERVAL '1 day')::date WHERE id = $2`,
                [effectiveFrom, shiftId]
            );
            const inserted = await client.query(`
                INSERT INTO resource_shifts (calendar_id, shift_name, day_of_week, start_hour, end_hour, valid_from, created_by)
                VALUES ($1, $2, $3, $4, $5, $6::date, $7)
                RETURNING *
            `, [row.calendar_id, nextShiftName, nextDay, nextStart, nextEnd, effectiveFrom, getRequestUserName(req)]);
            await client.query(`UPDATE resource_shifts SET superseded_by = $1 WHERE id = $2`, [inserted.rows[0].id, shiftId]);
            return inserted.rows[0];
        });
        invalidateFiniteCapacityCache();
        res.json({ ok: true, data: result });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible actualizar el turno.' });
    }
});

// Igual que editar: "eliminar" un turno vigente lo cierra desde la fecha
// efectiva en vez de borrar el historial. Solo se borra de verdad si el turno
// nunca llegó a regir (su valid_from todavía no ha pasado).
app.delete('/api/planificacion/calendarios/:id/turnos/:shiftId', async (req, res) => {
    try {
        const { shiftId } = req.params;
        const effectiveFrom = req.body?.effective_from || capacityDateKey(new Date());
        const current = await pgQuery(`SELECT * FROM resource_shifts WHERE id = $1`, [shiftId]);
        if (!current.rows.length) return res.status(404).json({ ok: false, error: 'Turno no encontrado.' });
        const row = current.rows[0];
        const rowValidFrom = capacityDateKey(row.valid_from);
        if (rowValidFrom > effectiveFrom) {
            await pgQuery(`DELETE FROM resource_shifts WHERE id = $1`, [shiftId]);
        } else {
            await pgQuery(
                `UPDATE resource_shifts SET valid_to = ($1::date - INTERVAL '1 day')::date WHERE id = $2`,
                [effectiveFrom, shiftId]
            );
        }
        invalidateFiniteCapacityCache();
        res.json({ ok: true });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible eliminar el turno.' });
    }
});

app.post('/api/planificacion/calendarios/:id/excepciones', async (req, res) => {
    try {
        const { id } = req.params;
        const { exception_date, exception_type, description, override_start_hour, override_end_hour } = req.body;
        if (!exception_date) {
            return res.status(400).json({ ok: false, error: 'exception_date es requerido.' });
        }
        const result = await pgQuery(`
            INSERT INTO resource_calendar_exceptions (calendar_id, exception_date, exception_type, description, override_start_hour, override_end_hour)
            VALUES ($1, $2, $3, $4, $5, $6)
            ON CONFLICT (calendar_id, exception_date) DO UPDATE
            SET exception_type = EXCLUDED.exception_type,
                description = EXCLUDED.description,
                override_start_hour = EXCLUDED.override_start_hour,
                override_end_hour = EXCLUDED.override_end_hour,
                is_active = TRUE
            RETURNING *
        `, [id, exception_date, exception_type || 'closure', description || '', override_start_hour || null, override_end_hour || null]);
        invalidateFiniteCapacityCache();
        res.json({ ok: true, data: result.rows[0] });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible crear la excepción.' });
    }
});

app.put('/api/planificacion/calendarios/:id/excepciones/:exceptionId', async (req, res) => {
    try {
        const { exceptionId } = req.params;
        const { exception_date, exception_type, description, override_start_hour, override_end_hour, is_active } = req.body;
        const result = await pgQuery(`
            UPDATE resource_calendar_exceptions
            SET exception_date = COALESCE($2, exception_date),
                exception_type = COALESCE($3, exception_type),
                description = COALESCE($4, description),
                override_start_hour = COALESCE($5, override_start_hour),
                override_end_hour = COALESCE($6, override_end_hour),
                is_active = COALESCE($7, is_active)
            WHERE id = $1
            RETURNING *
        `, [exceptionId, exception_date, exception_type, description, override_start_hour, override_end_hour, is_active]);
        if (!result.rows.length) return res.status(404).json({ ok: false, error: 'Excepción no encontrada.' });
        invalidateFiniteCapacityCache();
        res.json({ ok: true, data: result.rows[0] });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible actualizar la excepción.' });
    }
});

app.delete('/api/planificacion/calendarios/:id/excepciones/:exceptionId', async (req, res) => {
    try {
        const { exceptionId } = req.params;
        const result = await pgQuery(`DELETE FROM resource_calendar_exceptions WHERE id = $1 RETURNING id`, [exceptionId]);
        if (!result.rows.length) return res.status(404).json({ ok: false, error: 'Excepción no encontrada.' });
        invalidateFiniteCapacityCache();
        res.json({ ok: true });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible eliminar la excepción.' });
    }
});

app.get('/api/planificacion/calendarios/:id/capacidad', async (req, res) => {
    try {
        const { id } = req.params;
        const { desde, hasta } = req.query;
        const fromDate = desde || new Date().toISOString().slice(0, 10);
        const toDate = hasta || new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);
        const [shiftsResult, exceptionsResult, feriados] = await Promise.all([
            pgQuery(`SELECT * FROM resource_shifts WHERE calendar_id = $1 AND is_active = TRUE`, [id]),
            pgQuery(`SELECT * FROM resource_calendar_exceptions WHERE calendar_id = $1 AND exception_date BETWEEN $2 AND $3 AND is_active = TRUE`, [id, fromDate, toDate]),
            cargarFeriados()
        ]);
        const shifts = shiftsResult.rows;
        const exceptions = exceptionsResult.rows;
        const capacityByDate = {};
        const current = new Date(fromDate);
        const end = new Date(toDate);
        while (current <= end) {
            const dateStr = current.toISOString().slice(0, 10);
            const dow = current.getDay();
            const exception = exceptions.find(e => e.exception_date === dateStr);
            if (esFeriado(feriados, dateStr)) {
                capacityByDate[dateStr] = { hours: 0, type: 'feriado', description: 'Feriado nacional' };
            } else if (exception && exception.exception_type === 'closure') {
                capacityByDate[dateStr] = { hours: 0, type: 'closure', description: exception.description };
            } else if (exception && exception.override_start_hour !== null && exception.override_end_hour !== null) {
                const hours = Math.max(0, exception.override_end_hour - exception.override_start_hour);
                capacityByDate[dateStr] = { hours, type: 'override', description: exception.description };
            } else {
                const dayShifts = shifts.filter(s => s.day_of_week === dow);
                const totalHours = dayShifts.reduce((sum, s) => sum + Math.max(0, s.end_hour - s.start_hour), 0);
                capacityByDate[dateStr] = { hours: totalHours, type: 'regular', shifts: dayShifts.length };
            }
            current.setDate(current.getDate() + 1);
        }
        const totalHours = Object.values(capacityByDate).reduce((sum, d) => sum + d.hours, 0);
        const workDays = Object.values(capacityByDate).filter(d => d.hours > 0).length;
        res.json({ ok: true, data: { calendarId: id, fromDate, toDate, totalHours, workDays, daily: capacityByDate } });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible calcular la capacidad.' });
    }
});

// ═══════════════════════════════════════════════════════════════════
// MOTOR DE CAPACIDAD FINITA — Finite Capacity Planning Engine
// ═══════════════════════════════════════════════════════════════════

async function getCalendarCapacityHours(calendarId, fromDate, toDate) {
    const [shiftsRes, excRes, feriados] = await Promise.all([
        pgQuery(`SELECT * FROM resource_shifts WHERE calendar_id = $1 AND is_active = TRUE`, [calendarId]),
        pgQuery(`SELECT * FROM resource_calendar_exceptions WHERE calendar_id = $1 AND exception_date BETWEEN $2 AND $3 AND is_active = TRUE`, [calendarId, fromDate, toDate]),
        cargarFeriados()
    ]);
    const shifts = shiftsRes.rows;
    const exceptions = excRes.rows;
    const capacityByDate = {};
    const current = new Date(fromDate + 'T00:00:00');
    const end = new Date(toDate + 'T23:59:59');
    while (current <= end) {
        const dateStr = current.toISOString().slice(0, 10);
        const dow = current.getDay();
        const exception = exceptions.find(e => e.exception_date?.toISOString?.() === dateStr || e.exception_date === dateStr);
        if (esFeriado(feriados, dateStr)) {
            capacityByDate[dateStr] = 0;
        } else if (exception && exception.exception_type === 'closure') {
            capacityByDate[dateStr] = 0;
        } else if (exception && exception.override_start_hour !== null && exception.override_end_hour !== null) {
            capacityByDate[dateStr] = Math.max(0, Number(exception.override_end_hour) - Number(exception.override_start_hour));
        } else {
            const dayShifts = shifts.filter(s => s.day_of_week === dow);
            capacityByDate[dateStr] = dayShifts.reduce((sum, s) => sum + Math.max(0, Number(s.end_hour) - Number(s.start_hour)), 0);
        }
        current.setDate(current.getDate() + 1);
    }
    return capacityByDate;
}

// ── Feriados nacionales (dias_feriados) ───────────────────────────────────
// Carga una vez y devuelve dos Set para lookup O(1):
//   exactas     → 'YYYY-MM-DD' (feriados de un año puntual, p.ej. Semana Santa)
//   recurrentes → 'MM-DD'      (feriados de fecha fija, válidos todos los años)
async function cargarFeriados() {
    const { rows } = await pgQuery(`SELECT fecha, recurrente FROM dias_feriados WHERE activo = TRUE`);
    const exactas = new Set();
    const recurrentes = new Set();
    rows.forEach((row) => {
        const key = row.fecha instanceof Date
            ? row.fecha.toISOString().slice(0, 10)
            : String(row.fecha || '').slice(0, 10);
        if (!key) return;
        if (row.recurrente) recurrentes.add(key.slice(5));
        else exactas.add(key);
    });
    return { exactas, recurrentes };
}

function esFeriado(feriados, dateKey) {
    if (!feriados || !dateKey) return false;
    return feriados.exactas.has(dateKey) || feriados.recurrentes.has(dateKey.slice(5));
}

// ── Disponibilidad de un recurso en un día ────────────────────────────────
// Fuente ÚNICA de "¿en qué franjas horarias trabaja este recurso este día?".
// La usan el motor de capacidad (hacia adelante) y el cálculo de fechas
// compromiso (hacia atrás). Devuelve [{ startHour, endHour }] en horas
// decimales; [] = día no disponible.
//
// Prioridad:
//   1. Feriado nacional activo                        → []  (cierre total)
//   2. Escenario: inactivo / fecha cerrada            → []
//   3. Escenario: override hoursPerDay                → esa franja
//   4. Excepción del calendario del recurso: closure  → []
//   5. Excepción del calendario del recurso: override → esa franja
//   6. Turnos del calendario para ese día de semana
//   7. Fallback: L–V, 07:00 + capacityMinutes del proceso
//   (+ extraHoursPerDay del escenario se suma a la última franja)
const SQL_RECURSOS_CADENA = `
    SELECT pm.id::text AS id,
           m.nombre AS resource_code,
           m.nombre AS resource_name,
           'machine' AS resource_type,
           p.process_key,
           p.process_name,
           m.id AS maquina_id,
           (SELECT mp.id FROM production_machine_profiles mp
             WHERE mp.machine_id = m.id AND mp.is_active = TRUE
             ORDER BY mp.updated_at DESC LIMIT 1) AS machine_profile_id,
           (SELECT mp.oee_target FROM production_machine_profiles mp
             WHERE mp.machine_id = m.id AND mp.is_active = TRUE
             ORDER BY mp.updated_at DESC LIMIT 1) AS oee_target,
           pm.calendario_id AS calendar_id
    FROM proceso_maquina pm
    JOIN maquina m ON m.id = pm.maquina_id
    JOIN production_process_definitions p ON p.id = pm.proceso_id
    WHERE p.is_active = TRUE
    UNION ALL
    SELECT 'proceso:' || p.id::text AS id,
           p.process_name AS resource_code,
           p.process_name AS resource_name,
           'process' AS resource_type,
           p.process_key,
           p.process_name,
           NULL::uuid AS maquina_id,
           NULL::uuid AS machine_profile_id,
           NULL::numeric AS oee_target,
           p.calendario_id AS calendar_id
    FROM production_process_definitions p
    WHERE p.is_active = TRUE
      AND NOT EXISTS (SELECT 1 FROM proceso_maquina pm WHERE pm.proceso_id = p.id)
`;

function disponibilidadRecursoEnDia(recurso, dateKey, contexto = {}) {
    const {
        turnosPorCalendario = new Map(),
        excepcionesPorCalendario = new Map(),
        feriados = null,
        costsConfig = {},
        procesoClave = ''
    } = contexto;

    if (esFeriado(feriados, dateKey)) return [];

    const adjustment = recurso.scenarioAdjustment || {};
    const closedDates = new Set(
        (Array.isArray(adjustment.closedDates) ? adjustment.closedDates : []).map(capacityDateKey)
    );
    if (adjustment.active === false || closedDates.has(dateKey)) return [];

    const day = new Date(`${dateKey}T00:00:00.000Z`).getUTCDay();

    const overrideHours = Number(adjustment.hoursPerDay || 0);
    if (overrideHours > 0) {
        const startHour = Number(adjustment.startHour ?? 7);
        return [{ startHour, endHour: Math.min(24, startHour + overrideHours) }];
    }

    const exception = recurso.calendarId
        ? excepcionesPorCalendario.get(recurso.calendarId)?.get(dateKey)
        : null;
    // Cualquier excepción sin horario alternativo explícito = "no disponible"
    // ese día; el tipo (closure/mantenimiento/…) es solo etiqueta para la UI.
    const hasOverrideHours = exception
        && exception.override_start_hour !== null
        && exception.override_end_hour !== null;
    if (exception && !hasOverrideHours) return [];

    let intervals = [];
    if (hasOverrideHours) {
        intervals = [{
            startHour: Number(exception.override_start_hour),
            endHour: Number(exception.override_end_hour)
        }];
    } else if (recurso.calendarId) {
        intervals = (turnosPorCalendario.get(recurso.calendarId) || [])
            .filter((shift) => Number(shift.day_of_week) === day
                && shift.valid_from <= dateKey
                && (!shift.valid_to || shift.valid_to >= dateKey))
            .map((shift) => ({ startHour: Number(shift.start_hour), endHour: Number(shift.end_hour) }));
    }

    if (!intervals.length && day >= 1 && day <= 5) {
        const processDefault = procesoClave ? findCostProcessDefault(costsConfig, procesoClave) : null;
        const capacityMin = Number(processDefault?.capacityMinutes || 480);
        const hoursFromDefault = Math.max(1, capacityMin / 60);
        intervals = [{ startHour: 7, endHour: Math.min(24, 7 + hoursFromDefault) }];
    }

    const extraHours = Math.max(0, Number(adjustment.extraHoursPerDay || 0));
    if (extraHours > 0 && intervals.length) {
        const last = intervals[intervals.length - 1];
        last.endHour = Math.min(24, last.endHour + extraHours);
    }

    return intervals.filter((interval) => interval.endHour > interval.startHour);
}

const CAPACITY_DAY_MS = 86400000;
const CAPACITY_LOCAL_UTC_OFFSET_HOURS = 6;
let finiteCapacityEngineCache = { key: '', expiresAt: 0, result: null };

function capacityDateKey(value = new Date()) {
    if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value.trim())) {
        return value.trim();
    }
    const date = value instanceof Date ? value : new Date(value);
    if (Number.isNaN(date.getTime())) return '';
    return new Date(date.getTime() - (CAPACITY_LOCAL_UTC_OFFSET_HOURS * 3600000))
        .toISOString()
        .slice(0, 10);
}

function capacityDateAtHour(dateKey, decimalHour = 0) {
    const date = new Date(`${dateKey}T00:00:00.000Z`);
    date.setTime(date.getTime() + ((Number(decimalHour || 0) + CAPACITY_LOCAL_UTC_OFFSET_HOURS) * 3600000));
    return date;
}

function capacityAddDays(dateKey, days = 1) {
    const date = new Date(`${dateKey}T00:00:00.000Z`);
    date.setUTCDate(date.getUTCDate() + Number(days || 0));
    return date.toISOString().slice(0, 10);
}

function capacityRound(value, decimals = 2) {
    const factor = 10 ** decimals;
    return Math.round(Number(value || 0) * factor) / factor;
}

// ── Planificación hacia atrás: fecha compromiso por proceso ───────────────
// Resta `horas` de trabajo a partir de `hasta` recorriendo el calendario del
// recurso HACIA ATRÁS (misma disponibilidad que el motor hacia adelante:
// feriados + turnos + excepciones). Devuelve el instante de inicio.
function restarHorasDisponibles(recurso, hasta, horas, contexto = {}) {
    let restante = Math.max(0, Number(horas || 0));
    if (!(hasta instanceof Date) || Number.isNaN(hasta.getTime())) return null;
    if (restante <= 0.00001) return new Date(hasta);
    let cursor = new Date(hasta);
    for (let guarda = 0; guarda < 1460 && restante > 0.00001; guarda += 1) {
        const dateKey = capacityDateKey(cursor);
        if (!dateKey) return null;
        const intervals = disponibilidadRecursoEnDia(recurso, dateKey, contexto)
            .slice()
            .sort((a, b) => b.startHour - a.startHour); // de la franja más tardía a la más temprana
        for (const it of intervals) {
            const iniFranja = capacityDateAtHour(dateKey, it.startHour);
            const finFranja = capacityDateAtHour(dateKey, it.endHour);
            const finTramo = new Date(Math.min(cursor.getTime(), finFranja.getTime()));
            if (finTramo <= iniFranja) continue;
            const horasDisp = (finTramo.getTime() - iniFranja.getTime()) / 3600000;
            const usar = Math.min(restante, horasDisp);
            const iniTramo = new Date(finTramo.getTime() - usar * 3600000);
            restante -= usar;
            cursor = iniTramo;
            if (restante <= 0.00001) break;
        }
        if (restante > 0.00001) {
            const prevKey = capacityAddDays(dateKey, -1);
            cursor = capacityDateAtHour(prevKey, 24);
        }
    }
    return restante > 0.00001 ? null : cursor;
}

function restarDiasHabiles(dateObj, dias, feriados) {
    let d = new Date(dateObj);
    let n = Math.max(0, Math.round(Number(dias || 0)));
    while (n > 0) {
        d = new Date(d.getTime() - CAPACITY_DAY_MS);
        const dk = capacityDateKey(d);
        const dow = new Date(`${dk}T00:00:00.000Z`).getUTCDay();
        if (dow !== 0 && dow !== 6 && !esFeriado(feriados, dk)) n -= 1;
    }
    return d;
}

// Calcula fecha_compromiso_inicio/fin de cada proceso de una orden restando
// desde la fecha de entrega hacia atrás. Ignora contención de máquina (eso lo
// da la proyección del motor); solo respeta calendario laboral + feriados.
async function recalcularCompromisos(codigoOrden) {
    if (!codigoOrden) return { ok: false, motivo: 'sin-codigo' };
    const planRes = await pgQuery(`SELECT * FROM orden_planificacion WHERE codigo_orden = $1 LIMIT 1`, [codigoOrden]);
    const plan = planRes.rows[0];
    if (!plan) return { ok: false, motivo: 'sin-planificacion' };
    const anclaFecha = plan.fecha_entrega_programada || plan.fecha_entrega_prometida;
    if (!anclaFecha) return { ok: false, motivo: 'sin-fecha-entrega' };

    const procRes = await pgQuery(
        `SELECT id, secuencia, clave_proceso, perfil_maquina_id, maquina_id, duracion_horas, transicion_min
           FROM orden_proceso WHERE codigo_orden = $1`,
        [codigoOrden]
    );
    // Ordenar por el flujo canónico (diseño→…→empaque), NO por `secuencia`, que
    // en datos migrados puede estar desordenada.
    const flowPos = new Map(PRODUCTION_FLOW_SEQUENCE.map((k, i) => [k, i]));
    const procesos = procRes.rows.slice().sort((a, b) => {
        const pa = flowPos.get(canonicalProductionFlowKey(a.clave_proceso)) ?? 900 + Number(a.secuencia || 0);
        const pb = flowPos.get(canonicalProductionFlowKey(b.clave_proceso)) ?? 900 + Number(b.secuencia || 0);
        return pa - pb || Number(a.secuencia || 0) - Number(b.secuencia || 0);
    });
    if (!procesos.length) return { ok: false, motivo: 'sin-procesos' };

    const [feriados, shiftsRes, excRes, recursosRes] = await Promise.all([
        cargarFeriados(),
        pgQuery(`SELECT * FROM resource_shifts WHERE is_active = TRUE`),
        pgQuery(`SELECT * FROM resource_calendar_exceptions WHERE is_active = TRUE`),
        pgQuery(SQL_RECURSOS_CADENA)
    ]);
    const costsConfig = await loadCostsConfig();
    const turnosPorCalendario = new Map();
    (shiftsRes.rows || []).forEach((row) => {
        const k = String(row.calendar_id);
        if (!turnosPorCalendario.has(k)) turnosPorCalendario.set(k, []);
        turnosPorCalendario.get(k).push({
            ...row,
            valid_from: capacityDateKey(row.valid_from) || '0000-01-01',
            valid_to: row.valid_to ? capacityDateKey(row.valid_to) : null
        });
    });
    const excepcionesPorCalendario = new Map();
    (excRes.rows || []).forEach((row) => {
        const k = String(row.calendar_id);
        if (!excepcionesPorCalendario.has(k)) excepcionesPorCalendario.set(k, new Map());
        const dk = row.exception_date instanceof Date ? row.exception_date.toISOString().slice(0, 10) : String(row.exception_date || '').slice(0, 10);
        excepcionesPorCalendario.get(k).set(dk, row);
    });
    const calPorProceso = new Map();
    const calPorProcesoMaquina = new Map();
    (recursosRes.rows || []).forEach((row) => {
        const clave = canonicalProductionFlowKey(row.process_key);
        const cal = row.calendar_id ? String(row.calendar_id) : null;
        if (row.maquina_id) calPorProcesoMaquina.set(`${clave}|${row.maquina_id}`, cal);
        else calPorProceso.set(clave, cal);
    });

    const anclaISO = anclaFecha instanceof Date
        ? anclaFecha.toISOString().slice(0, 10)
        : String(anclaFecha).slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(anclaISO)) return { ok: false, motivo: 'fecha-entrega-invalida' };
    const anclaBase = restarDiasHabiles(new Date(`${anclaISO}T22:00:00.000Z`), plan.dias_buffer_entrega, feriados);
    const contextoBase = { turnosPorCalendario, excepcionesPorCalendario, feriados, costsConfig };

    let finSiguiente = anclaBase;
    const updates = [];
    for (let i = procesos.length - 1; i >= 0; i -= 1) {
        const p = procesos[i];
        const claveProceso = canonicalProductionFlowKey(p.clave_proceso);
        const calId = p.maquina_id
            ? (calPorProcesoMaquina.get(`${claveProceso}|${p.maquina_id}`) || null)
            : (calPorProceso.get(claveProceso) || null);
        const recurso = { scenarioAdjustment: {}, calendarId: calId };
        const ctx = { ...contextoBase, procesoClave: p.clave_proceso };
        const finCompromiso = new Date(finSiguiente.getTime() - Math.max(0, Number(p.transicion_min || 0)) * 60000);
        const inicioCompromiso = restarHorasDisponibles(recurso, finCompromiso, Number(p.duracion_horas || 0), ctx) || finCompromiso;
        updates.push({ id: p.id, ini: inicioCompromiso, fin: finCompromiso });
        finSiguiente = inicioCompromiso;
    }
    for (const u of updates) {
        const iniOk = u.ini instanceof Date && !Number.isNaN(u.ini.getTime());
        const finOk = u.fin instanceof Date && !Number.isNaN(u.fin.getTime());
        if (!iniOk && !finOk) continue;
        await pgQuery(
            `UPDATE orden_proceso SET fecha_compromiso_inicio = $2, fecha_compromiso_fin = $3, actualizado_en = actualizado_en WHERE id = $1`,
            [u.id, iniOk ? u.ini : null, finOk ? u.fin : null]
        );
    }
    const alertaRes = await pgQuery(
        `SELECT bool_or(atraso_proyeccion OR atraso_real) AS alerta FROM vista_orden_proceso WHERE codigo_orden = $1`,
        [codigoOrden]
    );
    await pgQuery(
        `UPDATE orden_planificacion SET alerta_atraso = COALESCE($2, false), actualizado_en = NOW() WHERE codigo_orden = $1`,
        [codigoOrden, alertaRes.rows[0]?.alerta || false]
    );
    return { ok: true, procesos: updates.length };
}

// Escribe fecha_plan_inicio/fin de cada proceso desde la proyección del motor
// de capacidad finita (agenda hacia adelante con contención de máquina). Esto
// hace que atraso_proyeccion de la vista tenga sentido.
async function aplicarProyeccionAOrdenProceso() {
    const engine = await getFiniteCapacityResult({ horizonDays: 60 }).catch(() => null);
    if (!engine || !Array.isArray(engine.orders)) return { ok: false, motivo: 'motor-sin-resultado' };
    let n = 0;
    for (const orden of engine.orders) {
        for (const route of (orden.routes || [])) {
            if (!route.routeId || (!route.projectedStart && !route.projectedEnd)) continue;
            await pgQuery(
                `UPDATE orden_proceso SET fecha_plan_inicio = $2::timestamptz, fecha_plan_fin = $3::timestamptz, actualizado_en = actualizado_en
                  WHERE id = $1::uuid`,
                [route.routeId, route.projectedStart || null, route.projectedEnd || null]
            ).catch(() => null);
            n += 1;
        }
    }
    // refrescar alerta_atraso ahora que hay fecha_plan_*
    await pgQuery(`
        UPDATE orden_planificacion op SET alerta_atraso = COALESCE(v.alerta, false), actualizado_en = NOW()
        FROM (SELECT codigo_orden, bool_or(atraso_proyeccion OR atraso_real) AS alerta
                FROM vista_orden_proceso GROUP BY codigo_orden) v
       WHERE v.codigo_orden = op.codigo_orden
    `).catch(() => null);

    // Órdenes con una fecha ya comprometida con el cliente (bloqueo suave) que,
    // después de este recálculo, ya no alcanza — se avisan, nunca se mueven solas.
    const conflictos = await pgQuery(`
        SELECT op.codigo_orden, o.customer_name, op.fecha_entrega_prometida,
               MAX(r.fecha_plan_fin) AS nueva_fecha_proyectada
          FROM orden_planificacion op
          JOIN flexo_orders o ON o.order_code = op.codigo_orden
          JOIN orden_proceso r ON r.codigo_orden = op.codigo_orden
         WHERE op.fecha_comprometida_bloqueada = TRUE
           AND op.alerta_atraso = TRUE
           AND o.delivered_on IS NULL
         GROUP BY op.codigo_orden, o.customer_name, op.fecha_entrega_prometida
    `).catch(() => ({ rows: [] }));

    return { ok: true, procesos: n, conflictosCompromiso: conflictos.rows || [] };
}

// Vista previa SIN guardar nada — compara lo que ya está guardado contra lo
// que el motor calcularía si se aplicara, para que Planeación vea el impacto
// real antes de decidir. Ver [[project_motor_replanificacion_futuro]].
async function previsualizarProyeccionAOrdenProceso() {
    const engine = await getFiniteCapacityResult({ horizonDays: 60 }).catch(() => null);
    if (!engine || !Array.isArray(engine.orders)) return { ok: false, motivo: 'motor-sin-resultado' };

    const routeIds = [];
    engine.orders.forEach((orden) => (orden.routes || []).forEach((route) => {
        if (route.routeId) routeIds.push(route.routeId);
    }));
    const actuales = routeIds.length
        ? (await pgQuery(`SELECT id::text, fecha_plan_fin FROM orden_proceso WHERE id = ANY($1::uuid[])`, [routeIds])).rows
        : [];
    const actualPorRuta = new Map(actuales.map((r) => [r.id, r.fecha_plan_fin]));

    const bloqueadas = await pgQuery(`
        SELECT codigo_orden, fecha_entrega_prometida FROM orden_planificacion WHERE fecha_comprometida_bloqueada = TRUE
    `);
    const fechaComprometidaPorOrden = new Map(bloqueadas.rows.map((r) => [r.codigo_orden, r.fecha_entrega_prometida]));

    const cambios = [];
    for (const orden of engine.orders) {
        let actualMax = null, nuevoMax = null;
        for (const route of (orden.routes || [])) {
            if (!route.routeId) continue;
            const actual = actualPorRuta.get(route.routeId);
            if (actual && (!actualMax || new Date(actual) > new Date(actualMax))) actualMax = actual;
            if (route.projectedEnd && (!nuevoMax || new Date(route.projectedEnd) > new Date(nuevoMax))) nuevoMax = route.projectedEnd;
        }
        if (!nuevoMax) continue;
        const diffMs = actualMax ? (new Date(nuevoMax).getTime() - new Date(actualMax).getTime()) : null;
        const diffDias = diffMs !== null ? Math.round(diffMs / 86400000) : null;
        // Solo listar cambios reales (más de unas horas de diferencia) para no
        // llenar la vista previa de ruido por redondeos.
        if (diffDias === null || Math.abs(diffMs) < 3600000) continue;
        const fechaComprometida = fechaComprometidaPorOrden.get(orden.orderCode) || null;
        const enRiesgoDeCompromiso = !!(fechaComprometida && new Date(nuevoMax) > new Date(fechaComprometida));
        cambios.push({
            codigoOrden: orden.orderCode,
            cliente: orden.customerName || '',
            fechaAntes: actualMax,
            fechaDespues: nuevoMax,
            diasDiferencia: diffDias,
            seAtrasa: diffDias > 0,
            fechaComprometida,
            enRiesgoDeCompromiso
        });
    }
    cambios.sort((a, b) => (b.enRiesgoDeCompromiso - a.enRiesgoDeCompromiso) || (Math.abs(b.diasDiferencia) - Math.abs(a.diasDiferencia)));

    return {
        ok: true,
        totalOrdenesRevisadas: engine.orders.length,
        totalConCambio: cambios.length,
        totalEnRiesgoDeCompromiso: cambios.filter((c) => c.enRiesgoDeCompromiso).length,
        cambios
    };
}

app.get('/api/planificacion/proyeccion/previsualizar', async (req, res) => {
    try {
        const r = await previsualizarProyeccionAOrdenProceso();
        res.json(r);
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible previsualizar el recálculo.' });
    }
});

app.post('/api/planificacion/proyeccion/aplicar', async (req, res) => {
    try {
        const r = await aplicarProyeccionAOrdenProceso();
        res.json({ ok: r.ok, resultado: r });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible aplicar la proyección.' });
    }
});

// Bloqueo suave de fecha comprometida: Planeación marca una orden como "ya
// prometida al cliente" para que el recálculo manual avise en vez de moverla
// en silencio (ver conflictosCompromiso en aplicarProyeccionAOrdenProceso).
app.patch('/api/planificacion/:codigo/bloqueo-comprometido', async (req, res) => {
    try {
        const codigo = String(req.params.codigo || '').trim();
        const bloqueada = Boolean(req.body?.bloqueada);
        if (!codigo) return res.status(400).json({ ok: false, error: 'Falta el código de orden.' });
        const actor = getRequestUserName(req);
        await pgQuery(`
            UPDATE orden_planificacion
               SET fecha_comprometida_bloqueada = $2,
                   bloqueo_comprometido_por = CASE WHEN $2 THEN $3 ELSE NULL END,
                   bloqueo_comprometido_en = CASE WHEN $2 THEN NOW() ELSE NULL END,
                   actualizado_en = NOW()
             WHERE codigo_orden = $1
        `, [codigo, bloqueada, actor]);
        res.json({ ok: true, bloqueada });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar el bloqueo de fecha comprometida.' });
    }
});

// Marca real de urgencia — la usa el cajón "Estimar" de Seguimiento cuando
// alguien marca una orden como urgente de verdad (no solo para previsualizar).
app.patch('/api/planificacion/:codigo/prioridad', async (req, res) => {
    try {
        const codigo = String(req.params.codigo || '').trim();
        const prioridad = String(req.body?.prioridad || '').trim().toLowerCase();
        if (!codigo) return res.status(400).json({ ok: false, error: 'Falta el código de orden.' });
        if (!['normal', 'urgente'].includes(prioridad)) {
            return res.status(400).json({ ok: false, error: 'Prioridad inválida.' });
        }
        await pgQuery(
            `UPDATE orden_planificacion SET prioridad = $2, actualizado_en = NOW() WHERE codigo_orden = $1`,
            [codigo, prioridad]
        );
        res.json({ ok: true, prioridad });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar la prioridad.' });
    }
});

function normalizeCapacityScenario(value = {}) {
    const source = value && typeof value === 'object' ? value : {};
    const resourceAdjustments = Array.isArray(source.resourceAdjustments)
        ? source.resourceAdjustments
        : Array.isArray(source.resources)
            ? source.resources
            : [];
    return {
        name: sanitizeAdminUserText(source.name || source.scenarioName || ''),
        resourceAdjustments,
        addedResources: Array.isArray(source.addedResources) ? source.addedResources : []
    };
}

function invalidateFiniteCapacityCache() {
    finiteCapacityEngineCache = { key: '', expiresAt: 0, result: null };
}

async function getFiniteCapacityResult(options = {}) {
    const scenario = normalizeCapacityScenario(options.scenario || {});
    const fromDate = capacityDateKey(options.fromDate || new Date());
    const horizonDays = Math.max(1, Math.min(365, Number(options.horizonDays || 30)));
    const hasScenario = scenario.resourceAdjustments.length > 0 || scenario.addedResources.length > 0;
    const cacheKey = `${fromDate}|${horizonDays}`;
    if (!hasScenario && finiteCapacityEngineCache.key === cacheKey && finiteCapacityEngineCache.expiresAt > Date.now() && finiteCapacityEngineCache.result) {
        return finiteCapacityEngineCache.result;
    }
    const result = await runFiniteCapacityEngine({ ...options, fromDate, horizonDays, scenario });
    if (!hasScenario) {
        finiteCapacityEngineCache = {
            key: cacheKey,
            expiresAt: Date.now() + 30000,
            result
        };
    }
    return result;
}

async function runFiniteCapacityEngine(options = {}) {
    const scenario = normalizeCapacityScenario(options.scenario || {});
    const fromDate = capacityDateKey(options.fromDate || new Date());
    const horizonDays = Math.max(1, Math.min(365, Number(options.horizonDays || 30)));
    const horizonDate = capacityAddDays(fromDate, horizonDays - 1);
    const schedulingLimitDate = capacityAddDays(fromDate, Math.max(horizonDays, 365));
    const fromInstant = capacityDateAtHour(fromDate, 0);
    const costsConfig = await loadCostsConfig();
    const feriados = await cargarFeriados();

    const [routesRes, resourcesRes, calendarsRes, shiftsRes, exceptionsRes] = await Promise.all([
        pgQuery(`
            SELECT r.id,
                   r.codigo_orden AS order_code,
                   r.codigo_cotizacion AS quote_code,
                   r.codigo_linea AS line_code,
                   r.secuencia AS sequence_order,
                   r.clave_proceso AS process_key,
                   r.nombre_proceso AS process_name,
                   r.perfil_maquina_id AS machine_profile_id,
                   (SELECT opm.maquina_id FROM orden_proceso opm WHERE opm.id = r.id) AS maquina_id,
                   r.depende_de_id AS dependency_route_id,
                   r.duracion_horas AS duration_hours,
                   CASE r.estado
                       WHEN 'EN_MARCHA' THEN 'RUN'
                       WHEN 'PREPARACION' THEN 'SETUP'
                       WHEN 'EN_PARO' THEN 'PARO'
                       ELSE r.estado
                   END AS route_status,
                   r.datos_extra AS route_payload,
                   r.fecha_plan_inicio AS planned_start_at,
                   r.fecha_plan_fin AS planned_end_at,
                   r.creado_en AS created_at,
                   o.delivered_on,
                   COALESCE(o.customer_name, o.raw_data->'quote_snapshot'->>'customer_name', '') AS customer_name,
                   COALESCE(
                       o.raw_data->'line_summary'->>'job_name',
                       o.raw_data->'line_summary'->>'product_name',
                       o.raw_data->'line_snapshot'->>'jobName',
                       o.product_code,
                       ''
                   ) AS job_name,
                   COALESCE(
                       opl.fecha_entrega_programada::timestamptz,
                       opl.fecha_entrega_prometida::timestamptz,
                       NULLIF(o.raw_data->'quote_snapshot'->>'due_on', '')::timestamptz,
                       o.delivered_on
                   ) AS promised_date
            FROM vista_orden_proceso r
            JOIN flexo_orders o ON o.order_code = r.codigo_orden
            LEFT JOIN orden_planificacion opl ON opl.codigo_orden = r.codigo_orden
            WHERE r.estado <> 'COMPLETADO'
              AND o.delivered_on IS NULL
              AND LOWER(COALESCE(o.order_status, o.raw_data->>'status', '')) NOT IN ('entregada', 'completada', 'cerrada', 'cancelada')
              AND COALESCE(o.estado_detencion, '') NOT IN ('DETENIDA', 'ANULADA')
            ORDER BY promised_date NULLS LAST, r.codigo_orden, r.secuencia
        `),
        pgQuery(SQL_RECURSOS_CADENA),
        pgQuery(`SELECT * FROM resource_calendars WHERE is_active = TRUE`),
        pgQuery(`
            SELECT * FROM resource_shifts
             WHERE is_active = TRUE
               AND valid_from <= $2
               AND (valid_to IS NULL OR valid_to >= $1)
             ORDER BY day_of_week, start_hour
        `, [fromDate, schedulingLimitDate]),
        pgQuery(`SELECT * FROM resource_calendar_exceptions WHERE is_active = TRUE AND exception_date BETWEEN $1 AND $2`, [fromDate, schedulingLimitDate])
    ]);

    const routes = routesRes.rows || [];
    // El Gantt (gantt-agrupado) identifica cada ruta por el id VIEJO cuando la orden
    // viene migrada (datos_extra.migrado_de_route_id), para que /gantt/mover siguiera
    // funcionando con enlaces guardados de antes de la consolidación. Este motor arma
    // sus rutas con el id NUEVO (orden_proceso.id). Sin esta traducción, "positions"
    // nunca coincidía con "id_ruta" del Gantt y el botón "Cap. Finita" no movía nada.
    const idRutaGantt = new Map();
    routes.forEach((route) => {
        const legacyId = route.route_payload && route.route_payload.migrado_de_route_id;
        idRutaGantt.set(String(route.id), legacyId ? String(legacyId) : String(route.id));
    });
    const calendars = calendarsRes.rows || [];
    const shiftsByCalendar = new Map();
    const exceptionsByCalendar = new Map();
    (shiftsRes.rows || []).forEach((row) => {
        const key = String(row.calendar_id);
        if (!shiftsByCalendar.has(key)) shiftsByCalendar.set(key, []);
        shiftsByCalendar.get(key).push({
            ...row,
            valid_from: capacityDateKey(row.valid_from) || fromDate,
            valid_to: row.valid_to ? capacityDateKey(row.valid_to) : null
        });
    });
    (exceptionsRes.rows || []).forEach((row) => {
        const key = String(row.calendar_id);
        if (!exceptionsByCalendar.has(key)) exceptionsByCalendar.set(key, new Map());
        const exceptionDate = row.exception_date instanceof Date
            ? row.exception_date.toISOString().slice(0, 10)
            : String(row.exception_date || '').slice(0, 10);
        exceptionsByCalendar.get(key).set(exceptionDate, row);
    });

    const calendarById = new Map(calendars.map((row) => [String(row.id), row]));

    const adjustmentByResource = new Map();
    scenario.resourceAdjustments.forEach((row) => {
        const keys = [row.resourceId, row.resourceCode, row.resourceName].map((value) => normalizePlanningKey(value)).filter(Boolean);
        keys.forEach((key) => adjustmentByResource.set(key, row));
    });

    const resources = (resourcesRes.rows || []).map((row) => {
        const adjustment = adjustmentByResource.get(normalizePlanningKey(row.id))
            || adjustmentByResource.get(normalizePlanningKey(row.resource_code))
            || adjustmentByResource.get(normalizePlanningKey(row.resource_name))
            || {};
        const baseUnits = 1;
        const capacityUnits = Math.max(0.1, Number(adjustment.capacityUnits ?? adjustment.units ?? baseUnits));
        const efficiencyFactor = Math.max(0.1, Math.min(1.5, Number(adjustment.efficiencyFactor ?? row.oee_target ?? 1)));
        const calendar = calendarById.get(String(row.calendar_id || '')) || null;
        const skillMap = new Map();
        (Array.isArray(adjustment.skillProcessKeys) ? adjustment.skillProcessKeys : []).forEach((processKey) => {
            skillMap.set(canonicalProductionFlowKey(processKey), { proficiency: 1, maxParallelJobs: 1 });
        });
        return {
            id: String(row.id),
            resourceCode: row.resource_code,
            resourceName: row.resource_name,
            resourceType: row.resource_type,
            processKey: canonicalProductionFlowKey(row.process_key),
            processName: row.process_name,
            maquinaId: row.maquina_id ? String(row.maquina_id) : '',
            machineProfileId: row.machine_profile_id ? String(row.machine_profile_id) : '',
            calendarId: calendar?.id ? String(calendar.id) : '',
            calendar,
            sinHorario: !calendar,
            capacityUnits,
            efficiencyFactor,
            scenarioAdjustment: adjustment,
            skillMap,
            laneCount: Math.max(1, Math.floor(capacityUnits)),
            lanes: [],
            totalLoadHours: 0,
            totalWaitHours: 0,
            routeCount: 0,
            dailyLoad: {},
            assignedRouteIds: []
        };
    });

    scenario.addedResources.forEach((row, index) => {
        const processKey = canonicalProductionFlowKey(row.processKey);
        const calendar = calendarById.get(String(row.calendarId || '')) || null;
        const capacityUnits = Math.max(0.1, Number(row.capacityUnits || 1));
        resources.push({
            id: `scenario-${index + 1}`,
            resourceCode: row.resourceCode || `scenario:${index + 1}`,
            resourceName: row.resourceName || `Recurso simulado ${index + 1}`,
            resourceType: row.resourceType || 'operator',
            processKey,
            maquinaId: '',
            machineProfileId: '',
            calendarId: calendar?.id ? String(calendar.id) : '',
            calendar,
            sinHorario: !calendar,
            capacityUnits,
            efficiencyFactor: Math.max(0.1, Math.min(1.5, Number(row.efficiencyFactor || 1))),
            scenarioAdjustment: row,
            skillMap: new Map((Array.isArray(row.skillProcessKeys) ? row.skillProcessKeys : [processKey]).filter(Boolean).map((key) => [canonicalProductionFlowKey(key), { proficiency: 1, maxParallelJobs: 1 }])),
            laneCount: Math.max(1, Math.floor(capacityUnits)),
            lanes: [],
            totalLoadHours: 0,
            totalWaitHours: 0,
            routeCount: 0,
            dailyLoad: {},
            assignedRouteIds: []
        });
    });

    resources.forEach((resource) => {
        resource.lanes = Array.from({ length: resource.laneCount }, (_, index) => ({
            index,
            availableAt: new Date(fromInstant)
        }));
    });

    // Envoltorio delgado sobre disponibilidadRecursoEnDia (nivel de módulo).
    // La lógica vive ahí para que el retroceso de fechas compromiso use
    // exactamente la misma disponibilidad que este motor hacia adelante.
    function resourceIntervalsForDay(resource, dateKey, processKey = '') {
        return disponibilidadRecursoEnDia(resource, dateKey, {
            turnosPorCalendario: shiftsByCalendar,
            excepcionesPorCalendario: exceptionsByCalendar,
            feriados,
            costsConfig,
            procesoClave: processKey
        });
    }

    function proficiencyFor(resource, processKey) {
        const skill = resource.skillMap.get(processKey);
        if (skill) return Math.max(0.1, Number(skill.proficiency || 1));
        return resource.processKey === processKey ? 1 : 0;
    }

    function lanesForProcess(resource, processKey) {
        const skill = resource.skillMap.get(processKey);
        const maxParallelJobs = skill
            ? Math.max(1, Number(skill.maxParallelJobs || 1))
            : resource.laneCount;
        return resource.lanes.slice(0, Math.min(resource.lanes.length, maxParallelJobs));
    }

    function scheduleLane(resource, lane, earliestAt, durationHours, processKey, commit = false) {
        const proficiency = proficiencyFor(resource, processKey);
        if (proficiency <= 0) return null;
        const productiveRate = Math.max(0.05, resource.efficiencyFactor * proficiency);
        let cursor = new Date(Math.max(lane.availableAt.getTime(), earliestAt.getTime()));
        let remaining = Math.max(0, Number(durationHours || 0));
        let start = null;
        const segments = [];
        for (let guard = 0; remaining > 0.00001 && guard < 730; guard += 1) {
            const dateKey = capacityDateKey(cursor);
            if (!dateKey || dateKey > schedulingLimitDate) return null;
            const intervals = resourceIntervalsForDay(resource, dateKey, processKey);
            let consumedToday = false;
            for (const interval of intervals) {
                const intervalStart = capacityDateAtHour(dateKey, interval.startHour);
                const intervalEnd = capacityDateAtHour(dateKey, interval.endHour);
                const segmentStart = new Date(Math.max(cursor.getTime(), intervalStart.getTime()));
                if (segmentStart >= intervalEnd) continue;
                const clockHoursAvailable = (intervalEnd - segmentStart) / 3600000;
                const productiveHoursAvailable = clockHoursAvailable * productiveRate;
                const productiveHours = Math.min(remaining, productiveHoursAvailable);
                const elapsedHours = productiveHours / productiveRate;
                const segmentEnd = new Date(segmentStart.getTime() + (elapsedHours * 3600000));
                if (!start) start = segmentStart;
                segments.push({ date: dateKey, hours: productiveHours });
                remaining -= productiveHours;
                cursor = segmentEnd;
                consumedToday = true;
                if (remaining <= 0.00001) break;
            }
            if (remaining > 0.00001) {
                const nextDate = capacityAddDays(dateKey, 1);
                cursor = capacityDateAtHour(nextDate, 0);
                if (!consumedToday && nextDate > schedulingLimitDate) return null;
            }
        }
        if (!start || remaining > 0.00001) return null;
        const result = { start, end: cursor, segments, laneIndex: lane.index, productiveRate };
        if (commit) {
            lane.availableAt = new Date(cursor);
            resource.totalLoadHours += Number(durationHours || 0);
            resource.routeCount += 1;
            segments.forEach((segment) => {
                resource.dailyLoad[segment.date] = Number(resource.dailyLoad[segment.date] || 0) + Number(segment.hours || 0);
            });
        }
        return result;
    }

    function candidateResources(route) {
        const processKey = canonicalProductionFlowKey(route.process_key);
        const delProceso = resources.filter((resource) => proficiencyFor(resource, processKey) > 0);
        if (route.maquina_id) {
            const exacta = delProceso.filter((resource) => resource.maquinaId === String(route.maquina_id));
            if (exacta.length) return exacta;
        }
        return delProceso;
    }
    const procesosEnCadena = new Set(resources.map((resource) => resource.processKey));

    function capacityForResourceDay(resource, dateKey) {
        const intervalHours = resourceIntervalsForDay(resource, dateKey)
            .reduce((sum, interval) => sum + Math.max(0, interval.endHour - interval.startHour), 0);
        return intervalHours * resource.capacityUnits * resource.efficiencyFactor;
    }

    const routesByOrder = new Map();
    routes.forEach((route) => {
        if (!routesByOrder.has(route.order_code)) routesByOrder.set(route.order_code, []);
        routesByOrder.get(route.order_code).push(route);
    });
    const orderGroups = Array.from(routesByOrder.values()).sort((left, right) => {
        const leftDate = left[0]?.promised_date ? new Date(left[0].promised_date).getTime() : Number.MAX_SAFE_INTEGER;
        const rightDate = right[0]?.promised_date ? new Date(right[0].promised_date).getTime() : Number.MAX_SAFE_INTEGER;
        return leftDate - rightDate || String(left[0]?.order_code || '').localeCompare(String(right[0]?.order_code || ''));
    });

    const routeSchedules = new Map();
    const orderSummaries = [];
    for (const orderRoutes of orderGroups) {
        orderRoutes.sort((a, b) => Number(a.sequence_order || 0) - Number(b.sequence_order || 0));
        let previousEnd = new Date(fromInstant);
        const orderSummary = {
            orderCode: orderRoutes[0]?.order_code || '',
            customerName: orderRoutes[0]?.customer_name || '',
            jobName: orderRoutes[0]?.job_name || '',
            promisedDate: orderRoutes[0]?.promised_date || null,
            routes: [],
            earliestStart: null,
            latestEnd: null,
            totalWaitHours: 0,
            totalWaitDays: 0,
            projectedLate: false
        };
        let chainBlocked = false;
        for (const route of orderRoutes) {
            if (!procesosEnCadena.has(canonicalProductionFlowKey(route.process_key))) {
                const fueraDeCadena = {
                    routeId: String(route.id),
                    idRuta: idRutaGantt.get(String(route.id)) || String(route.id),
                    orderCode: route.order_code,
                    processKey: canonicalProductionFlowKey(route.process_key),
                    processName: route.process_name,
                    resourceId: null,
                    resourceCode: '',
                    resourceName: 'No está en la Cadena de Procesos',
                    machineName: 'No está en la Cadena de Procesos',
                    durationHours: Math.max(0, Number(route.duration_hours || 0)),
                    projectedStart: null,
                    projectedEnd: null,
                    waitHours: 0,
                    waitDays: 0,
                    queueAheadHours: 0,
                    status: 'fuera-de-cadena'
                };
                routeSchedules.set(String(route.id), fueraDeCadena);
                orderSummary.routes.push(fueraDeCadena);
                continue;
            }
            const explicitDependency = route.dependency_route_id ? routeSchedules.get(String(route.dependency_route_id)) : null;
            if (chainBlocked || explicitDependency?.status === 'no-resource' || explicitDependency?.status === 'blocked-dependency') {
                const blockedSchedule = {
                    routeId: String(route.id),
                    idRuta: idRutaGantt.get(String(route.id)) || String(route.id),
                    orderCode: route.order_code,
                    processKey: canonicalProductionFlowKey(route.process_key),
                    processName: route.process_name,
                    resourceId: null,
                    resourceCode: '',
                    resourceName: 'Bloqueado por dependencia',
                    machineName: 'Bloqueado por dependencia',
                    durationHours: Math.max(0, Number(route.duration_hours || 0)),
                    projectedStart: null,
                    projectedEnd: null,
                    waitHours: 0,
                    waitDays: 0,
                    queueAheadHours: 0,
                    status: 'blocked-dependency'
                };
                routeSchedules.set(String(route.id), blockedSchedule);
                orderSummary.routes.push(blockedSchedule);
                chainBlocked = true;
                continue;
            }
            const earliestAt = explicitDependency?.projectedEnd
                ? new Date(Math.max(previousEnd.getTime(), new Date(explicitDependency.projectedEnd).getTime()))
                : new Date(previousEnd);
            const durationHours = Math.max(0, Number(route.duration_hours || 0));
            const processKey = canonicalProductionFlowKey(route.process_key);
            const candidates = candidateResources(route);
            let best = null;
            for (const resource of candidates) {
                for (const lane of lanesForProcess(resource, processKey)) {
                    const preview = scheduleLane(resource, lane, earliestAt, durationHours || 0.01, processKey, false);
                    if (!preview) continue;
                    if (!best || preview.end < best.preview.end) best = { resource, lane, preview };
                }
            }
            if (!best) {
                const missingSchedule = {
                    routeId: String(route.id),
                    idRuta: idRutaGantt.get(String(route.id)) || String(route.id),
                    orderCode: route.order_code,
                    processKey,
                    processName: route.process_name,
                    resourceId: null,
                    resourceCode: '',
                    resourceName: 'Sin recurso disponible',
                    machineName: 'Sin recurso disponible',
                    durationHours,
                    projectedStart: null,
                    projectedEnd: null,
                    waitHours: 0,
                    waitDays: 0,
                    queueAheadHours: 0,
                    status: 'no-resource'
                };
                routeSchedules.set(String(route.id), missingSchedule);
                orderSummary.routes.push(missingSchedule);
                chainBlocked = true;
                continue;
            }
            const queueAheadHours = best.resource.totalLoadHours;
            const committed = scheduleLane(best.resource, best.lane, earliestAt, durationHours || 0.01, processKey, true);
            best.resource.assignedRouteIds.push(String(route.id));
            const waitHours = Math.max(0, (committed.start - earliestAt) / 3600000);
            best.resource.totalWaitHours += waitHours;
            const schedule = {
                routeId: String(route.id),
                    idRuta: idRutaGantt.get(String(route.id)) || String(route.id),
                orderCode: route.order_code,
                processKey,
                processName: route.process_name,
                resourceId: best.resource.id,
                resourceCode: best.resource.resourceCode,
                resourceName: best.resource.resourceName,
                machineProfileId: best.resource.machineProfileId || null,
                maquinaId: best.resource.maquinaId || null,
                sinHorario: best.resource.sinHorario,
                machineName: best.resource.resourceName,
                resourceType: best.resource.resourceType,
                durationHours,
                projectedStart: committed.start.toISOString(),
                projectedEnd: committed.end.toISOString(),
                waitHours: capacityRound(waitHours, 2),
                waitDays: capacityRound(waitHours / 24, 2),
                queueAheadHours: capacityRound(queueAheadHours, 2),
                status: 'scheduled'
            };
            routeSchedules.set(String(route.id), schedule);
            orderSummary.routes.push(schedule);
            previousEnd = new Date(committed.end);
            if (!orderSummary.earliestStart || committed.start < new Date(orderSummary.earliestStart)) orderSummary.earliestStart = committed.start.toISOString();
            if (!orderSummary.latestEnd || committed.end > new Date(orderSummary.latestEnd)) orderSummary.latestEnd = committed.end.toISOString();
            orderSummary.totalWaitHours += waitHours;
        }
        orderSummary.totalWaitHours = capacityRound(orderSummary.totalWaitHours, 2);
        orderSummary.totalWaitDays = capacityRound(orderSummary.totalWaitHours / 24, 2);
        orderSummary.projectedLate = Boolean(orderSummary.promisedDate && orderSummary.latestEnd && new Date(orderSummary.latestEnd) > new Date(orderSummary.promisedDate));
        orderSummaries.push(orderSummary);
    }

    const resourceResults = resources.map((resource) => {
        const dailyLoad = [];
        let totalCapacityHours = 0;
        let activeDays = 0;
        for (let offset = 0; offset < horizonDays; offset += 1) {
            const date = capacityAddDays(fromDate, offset);
            const capacity = capacityForResourceDay(resource, date);
            const hours = Number(resource.dailyLoad[date] || 0);
            totalCapacityHours += capacity;
            if (capacity > 0) activeDays += 1;
            dailyLoad.push({
                date,
                hours: capacityRound(hours, 2),
                capacity: capacityRound(capacity, 2),
                utilizationPct: capacity > 0 ? capacityRound((hours / capacity) * 100, 1) : 0
            });
        }
        const avgDailyCapacity = activeDays > 0 ? totalCapacityHours / activeDays : 0;
        const utilizationPct = totalCapacityHours > 0 ? (resource.totalLoadHours / totalCapacityHours) * 100 : (resource.totalLoadHours > 0 ? 999 : 0);
        const queueHours = Math.max(0, resource.totalLoadHours - totalCapacityHours);
        const queueDays = avgDailyCapacity > 0 ? queueHours / avgDailyCapacity : (queueHours > 0 ? 999 : 0);
        return {
            resourceId: resource.id,
            resourceCode: resource.resourceCode,
            machineProfileId: resource.machineProfileId || null,
            machineName: resource.resourceName,
            resourceName: resource.resourceName,
            resourceType: resource.resourceType,
            processKey: resource.processKey,
            processName: resource.processName || '',
            maquinaId: resource.maquinaId || null,
            calendarId: resource.calendarId || null,
            sinHorario: resource.sinHorario,
            capacityUnits: resource.capacityUnits,
            efficiencyFactor: resource.efficiencyFactor,
            totalCapacityHours: capacityRound(totalCapacityHours, 2),
            totalLoadHours: capacityRound(resource.totalLoadHours, 2),
            utilizationPct: capacityRound(utilizationPct, 1),
            excessHours: capacityRound(Math.max(0, resource.totalLoadHours - totalCapacityHours), 2),
            queueHours: capacityRound(queueHours, 2),
            queueDays: capacityRound(queueDays, 1),
            isBottleneck: utilizationPct > 100,
            isPrimaryBottleneck: false,
            routeCount: resource.routeCount,
            dailyLoad
        };
    }).filter((resource) => resource.routeCount > 0 || resource.resourceType !== 'process');

    resourceResults.sort((a, b) => b.queueDays - a.queueDays || b.utilizationPct - a.utilizationPct);
    if (resourceResults.length && resourceResults[0].queueHours > 0) resourceResults[0].isPrimaryBottleneck = true;
    const bottlenecks = resourceResults.filter((resource) => resource.isBottleneck || resource.isPrimaryBottleneck);
    const resourceResultById = new Map(resourceResults.map((resource) => [resource.resourceId, resource]));
    orderSummaries.forEach((order) => {
        order.routes.forEach((route) => {
            const resource = resourceResultById.get(route.resourceId);
            route.isBottleneck = Boolean(resource?.isBottleneck || resource?.isPrimaryBottleneck);
            route.resourceUtilizationPct = Number(resource?.utilizationPct || 0);
        });
    });
    const lateOrders = orderSummaries.filter((order) => order.projectedLate);

    return {
        computedAt: new Date().toISOString(),
        fromDate,
        horizonDate,
        horizonDays,
        scenarioName: scenario.name || '',
        totalResources: resourceResults.length,
        totalPendingRoutes: routes.length,
        resources: resourceResults,
        orders: orderSummaries,
        bottlenecks,
        sinHorario: resources
            .filter((resource) => resource.sinHorario && !String(resource.id).startsWith('scenario-'))
            .map((resource) => ({ proceso: resource.processName || resource.processKey, maquina: resource.maquinaId ? resource.resourceName : '' })),
        summary: {
            avgUtilization: resourceResults.length > 0
                ? capacityRound(resourceResults.reduce((sum, resource) => sum + resource.utilizationPct, 0) / resourceResults.length, 1)
                : 0,
            bottleneckCount: bottlenecks.length,
            totalQueueHours: capacityRound(resourceResults.reduce((sum, resource) => sum + resource.queueHours, 0), 2),
            maxQueueDays: resourceResults.length > 0 ? capacityRound(Math.max(...resourceResults.map((resource) => resource.queueDays)), 1) : 0,
            projectedLateOrders: lateOrders.length,
            projectedOnTimeOrders: Math.max(0, orderSummaries.length - lateOrders.length)
        }
    };
}

