app.get('/api/produccion/flujo', async (req, res) => {
    try {
        await ensurePlanningRoutesForLiveOrders();
        const result = await pgQuery(`
            WITH live_order_meta AS (
                SELECT
                    o.order_code,
                    o.quote_code,
                    o.line_code,
                    o.machine_name,
                    o.product_code,
                    o.material_code,
                    o.die_code,
                    o.ordered_quantity,
                    o.customer_name,
                    o.salesperson_name,
                    o.created_at,
                    o.delivered_on,
                    o.order_status,
                    COALESCE(
                        o.raw_data#>>'{line_summary,job_name}',
                        o.raw_data#>>'{line_summary,product_name}',
                        o.raw_data#>>'{line_snapshot,jobName}'
                    ) AS rd_product_name,
                    NULLIF(COALESCE(
                        o.raw_data#>>'{line_snapshot,materialFeet}',
                        o.raw_data#>>'{totals,total_feet}'
                    ), '')::numeric AS rd_planned_feet,
                    lower(COALESCE(o.order_status, o.raw_data->>'status', '')) AS legacy_status
                FROM flexo_orders o
                WHERE o.delivered_on IS NULL
            )
            SELECT
                vp.id::text AS route_id,
                vp.codigo_orden AS order_code,
                vp.codigo_cotizacion AS quote_code,
                vp.codigo_linea AS line_code,
                vp.clave_proceso AS process_key,
                vp.nombre_proceso AS process_name,
                vp.estado,
                vp.secuencia AS sequence_order,
                vp.fecha_plan_inicio AS planned_start_at,
                vp.duracion_horas AS duration_hours,
                vp.fecha_real_inicio AS actual_start_at,
                vp.fecha_real_fin AS actual_end_at,
                vp.estado_dependencia AS dependency_status,
                vp.perfil_maquina_id::text AS machine_profile_id,
                COALESCE(vp.nombre_maquina, lo.machine_name, '') AS machine_name,
                lo.product_code,
                lo.material_code,
                lo.die_code,
                lo.ordered_quantity,
                lo.customer_name AS rd_customer_name,
                lo.salesperson_name AS rd_salesperson_name,
                lo.rd_product_name,
                lo.rd_planned_feet,
                lo.created_at AS order_created_at,
                COALESCE(op.prioridad, 'normal') AS prioridad,
                op.orden_manual,
                vp.suspendida_produccion,
                vp.suspendida_motivo,
                vp.suspendida_en,
                vp.suspendida_por
            FROM vista_orden_proceso vp
            JOIN live_order_meta lo ON lo.order_code = vp.codigo_orden
            LEFT JOIN orden_planificacion op ON op.codigo_orden = vp.codigo_orden
            WHERE vp.estado <> 'COMPLETADO'
              AND (vp.depende_de_id IS NULL OR vp.estado_dependencia = 'COMPLETADO')
              AND COALESCE(op.lanzado_gantt, FALSE) = TRUE
              AND NOT (
                lo.delivered_on IS NOT NULL
                OR lo.legacy_status IN ('entregada','completada','cerrada','cancelada')
              )
            ORDER BY vp.secuencia, op.orden_manual NULLS LAST, vp.actualizado_en, vp.codigo_orden
        `);

        const processOrder = new Map(PRODUCTION_FLOW_SEQUENCE.map((key, index) => [key, index + 1]));
        const routes = [];
        const machinesByProcess = {};
        const machineProfileIds = [...new Set(result.rows.map(r => r.machine_profile_id).filter(Boolean))];
        let specsMap = {};
        if (machineProfileIds.length) {
            const specsResult = await pgQuery(`
                SELECT machine_profile_id::text AS profile_id, spec_group, spec_key, spec_value
                FROM production_machine_specs
                WHERE machine_profile_id = ANY($1::uuid[])
            `, [machineProfileIds]);
            specsResult.rows.forEach(spec => {
                if (!specsMap[spec.profile_id]) specsMap[spec.profile_id] = [];
                specsMap[spec.profile_id].push(spec);
            });
        }
        result.rows.forEach((row) => {
            const processKey = canonicalProductionFlowKey(row.process_key || row.process_name);
            if (!PRODUCTION_FLOW_SEQUENCE.includes(processKey)) return;
            const route = {
                routeId: row.route_id,
                orderCode: row.order_code,
                quoteCode: row.quote_code || '',
                lineCode: row.line_code || '',
                processKey,
                processName: PRODUCTION_FLOW_LABELS[processKey] || row.process_name || processKey,
                routeStatus: SEGUIMIENTO_ESTADO_API[row.estado] || 'PENDIENTE',
                sequenceOrder: Number(row.sequence_order || processOrder.get(processKey) || 999),
                plannedStartAt: row.planned_start_at || null,
                actualStartAt: row.actual_start_at || null,
                durationHours: Number(row.duration_hours || 0),
                machineName: row.machine_name || '',
                machineProfileId: row.machine_profile_id || null,
                machineSpecs: row.machine_profile_id ? (specsMap[row.machine_profile_id] || []) : [],
                customerName: row.rd_customer_name || '',
                salespersonName: row.rd_salesperson_name || '',
                productName: row.rd_product_name || row.product_code || row.order_code,
                materialCode: row.material_code || '',
                dieCode: row.die_code || '',
                quantity: Number(row.ordered_quantity || 0),
                plannedFeet: Number(row.rd_planned_feet || 0),
                createdAt: row.order_created_at,
                prioridad: row.prioridad || 'normal',
                suspendidaProduccion: !!row.suspendida_produccion,
                suspendidaMotivo: row.suspendida_motivo || '',
                suspendidaEn: row.suspendida_en || null,
                suspendidaPor: row.suspendida_por || ''
            };
            routes.push(route);
            if (route.machineName) {
                if (!machinesByProcess[processKey]) machinesByProcess[processKey] = new Set();
                machinesByProcess[processKey].add(route.machineName);
            }
        });

        // La cola de Tintas solo debe mostrar órdenes que de verdad necesitan que alguien
        // formule un color especial (tinta tipo 'directo'). El paso 'tintas' en orden_proceso
        // se sigue creando para toda orden con impresión cotizada (no se toca esa parte, para
        // no afectar dependencias/capacidad de Planificación) — acá solo se filtra lo que ve
        // el operario. Las de solo CMYK/adicionales no aportan nada a Tintas.
        {
            const tintasRoutes = routes.filter((r) => r.processKey === 'tintas');
            if (tintasRoutes.length) {
                const pairs = [...new Set(tintasRoutes.map((r) => `${r.quoteCode}${r.lineCode}`))]
                    .map((k) => k.split(''));
                const quoteCodes = pairs.map((p) => p[0]);
                const lineCodes = pairs.map((p) => p[1]);
                const calcRows = await pgQuery(`
                    SELECT DISTINCT ON (quote_code, line_code) quote_code, line_code, ui_state
                    FROM flexo_calculations
                    WHERE (quote_code, line_code) IN (SELECT unnest($1::text[]), unnest($2::text[]))
                    ORDER BY quote_code, line_code, created_at DESC
                `, [quoteCodes, lineCodes]).catch(() => ({ rows: [] }));
                const hasDirectByKey = new Map();
                calcRows.rows.forEach((row) => {
                    const uiState = row.ui_state || {};
                    const types = Array.isArray(uiState.types) ? uiState.types : [];
                    const headerStations = Array.isArray(uiState.printStages?.[0]?.inkStations) ? uiState.printStages[0].inkStations : [];
                    let stationsAll = [];
                    if (types.length) {
                        types.forEach((t, idx) => {
                            const st = Array.isArray(t?.inkStations) ? t.inkStations : [];
                            stationsAll = stationsAll.concat((idx === 0 && !st.length) ? headerStations : st);
                        });
                    } else {
                        stationsAll = headerStations;
                    }
                    const hasDirect = stationsAll.some((s) => s && s.tipo === 'directo');
                    hasDirectByKey.set(`${row.quote_code}${row.line_code}`, hasDirect);
                });
                const keepRouteIds = new Set(
                    tintasRoutes
                        .filter((r) => hasDirectByKey.get(`${r.quoteCode}${r.lineCode}`) === true)
                        .map((r) => r.routeId)
                );
                const filtered = routes.filter((r) => r.processKey !== 'tintas' || keepRouteIds.has(r.routeId));
                routes.length = 0;
                routes.push(...filtered);
            }
        }

        // Hidratación del reloj de la pausa: el estado EN_PARO ya viene de orden_proceso,
        // pero el momento en que empezó la pausa y su motivo viven en el último evento
        // 'paro' abierto (production_route_events). Sin esto el reloj de la pausa se
        // reinicia a 0 cada vez que el operario recarga la pantalla o entra desde otra
        // computadora.
        const pausedRouteIds = routes.filter(r => r.routeStatus === 'PARO').map(r => r.routeId);
        if (pausedRouteIds.length) {
            const pausaRows = await pgQuery(`
                SELECT DISTINCT ON (e.orden_proceso_id)
                    e.orden_proceso_id::text AS opid,
                    e.id::text              AS event_id,
                    e.event_type,
                    e.notes,
                    e.operator_name,
                    e.created_at
                FROM production_route_events e
                WHERE e.orden_proceso_id = ANY($1::uuid[])
                ORDER BY e.orden_proceso_id, e.created_at DESC, e.id DESC
            `, [pausedRouteIds]);
            const pausaByRoute = new Map();
            pausaRows.rows.forEach((row) => {
                const et = String(row.event_type || '').trim().toLowerCase();
                if (et !== 'paro' && et !== 'suspender') return;
                pausaByRoute.set(row.opid, row);
            });
            routes.forEach((route) => {
                const p = pausaByRoute.get(route.routeId);
                if (!p) return;
                route.pausedSince = p.created_at;
                route.pauseLabel = p.notes || '';
                route.pauseEventId = p.event_id;
                route.pauseOperator = p.operator_name || '';
            });
        }

        // Devoluciones abiertas de estas órdenes: para pintar "esperando a Tintas/Preprensa"
        // en la tarjeta del proceso de origen y bloquear el botón Reanudar hasta que el
        // ticket haya vuelto (tenedor_actual IS NULL).
        const flujoOrderCodes = [...new Set(routes.map(r => r.orderCode))];
        if (flujoOrderCodes.length) {
            const devRows = await pgQuery(`
                SELECT id::text AS id, codigo_orden, proceso_origen, orden_proceso_origen_id::text AS opid,
                       motivo, clasificacion, estado, tenedor_actual, creado_en
                FROM devolucion_proceso
                WHERE codigo_orden = ANY($1) AND estado = 'abierta'
            `, [flujoOrderCodes]);
            const devByRoute = new Map();
            devRows.rows.forEach((d) => { if (d.opid) devByRoute.set(d.opid, d); });
            routes.forEach((route) => {
                const d = devByRoute.get(route.routeId);
                if (!d) return;
                route.devolucion = {
                    id: d.id,
                    motivo: d.motivo,
                    clasificacion: d.clasificacion || '',
                    tenedorActual: d.tenedor_actual || null,
                    creadoEn: d.creado_en
                };
            });
        }

        // Historial de eventos por ruta: la lista "Historial de Eventos" que ve el operario
        // vivía solo en memoria del navegador y desaparecía al cerrar/recargar la orden.
        // Se hidrata aquí desde production_route_events (la fuente real) para que sobreviva.
        const allRouteIds = routes.map(r => r.routeId);
        if (allRouteIds.length) {
            const eventRows = await pgQuery(`
                SELECT orden_proceso_id::text AS opid, event_type, operator_name, notes, created_at
                FROM production_route_events
                WHERE orden_proceso_id = ANY($1::uuid[])
                ORDER BY created_at DESC, id DESC
            `, [allRouteIds]);
            const eventsByRoute = new Map();
            eventRows.rows.forEach((row) => {
                if (!eventsByRoute.has(row.opid)) eventsByRoute.set(row.opid, []);
                eventsByRoute.get(row.opid).push({
                    eventType: row.event_type,
                    operatorName: row.operator_name || '',
                    notes: row.notes || '',
                    createdAt: row.created_at
                });
            });
            routes.forEach((route) => {
                route.events = eventsByRoute.get(route.routeId) || [];
            });
        }

        const counts = {};
        routes.forEach((route) => {
            counts[route.processKey] = (counts[route.processKey] || 0) + 1;
        });

        res.json({
            ok: true,
            user: getRequestUserName(req),
            processes: PRODUCTION_FLOW_SEQUENCE.map((key, index) => ({
                key,
                label: PRODUCTION_FLOW_LABELS[key],
                order: index + 1,
                activeCount: counts[key] || 0,
                machines: Array.from(machinesByProcess[key] || [])
            })),
            routes
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el flujo de producción.' });
    }
});

// Buscar órdenes: con `process` busca solo en la cola de ese proceso (como antes). Sin
// `process` — cuando el operador todavía no eligió ningún proceso arriba — busca en TODAS
// las órdenes, tomando para cada una su proceso actual (el primero sin completar; si ya
// completó todos, el último). El front usa ese processKey para saber dónde abrirla.
app.get('/api/produccion/buscar-ordenes', async (req, res) => {
    try {
        const rawProcess = String(req.query.process || '').trim();
        const processKey = rawProcess ? canonicalProductionFlowKey(rawProcess) : '';
        if (rawProcess && (!processKey || !PRODUCTION_FLOW_SEQUENCE.includes(processKey))) {
            return res.status(400).json({ ok: false, error: 'Proceso no válido.' });
        }
        const term = sanitizeAdminUserText(req.query.q || '').trim();
        const like = `%${term.replace(/[\\%_]/g, '\\$&')}%`;

        const pasosCte = processKey
            ? `SELECT vp.codigo_orden, vp.clave_proceso, vp.estado, vp.fecha_real_inicio, vp.fecha_real_fin
                 FROM vista_orden_proceso vp
                 LEFT JOIN orden_planificacion op ON op.codigo_orden = vp.codigo_orden
                WHERE vp.clave_proceso = $1
                  AND COALESCE(op.lanzado_gantt, FALSE) = TRUE`
            : `SELECT vp.codigo_orden, vp.clave_proceso, vp.secuencia, vp.estado, vp.fecha_real_inicio, vp.fecha_real_fin
                 FROM vista_orden_proceso vp
                 LEFT JOIN orden_planificacion op ON op.codigo_orden = vp.codigo_orden
                WHERE COALESCE(op.lanzado_gantt, FALSE) = TRUE`;
        const actualCte = processKey
            ? `SELECT codigo_orden, clave_proceso, estado AS route_estado,
                      fecha_real_inicio AS worked_started_at, fecha_real_fin AS worked_ended_at
                 FROM pasos`
            : `SELECT DISTINCT ON (codigo_orden) codigo_orden, clave_proceso, estado AS route_estado,
                      fecha_real_inicio AS worked_started_at, fecha_real_fin AS worked_ended_at
                 FROM pasos
                ORDER BY codigo_orden, (estado <> 'COMPLETADO') DESC,
                         CASE WHEN estado <> 'COMPLETADO' THEN secuencia ELSE -secuencia END`;
        const params = processKey ? [processKey, term, like] : [term, like];
        const termIdx = processKey ? 2 : 1;
        const likeIdx = processKey ? 3 : 2;

        const result = await pgQuery(`
            WITH pasos AS (${pasosCte}),
            actual AS (${actualCte}),
            ordenes AS (
                SELECT
                    actual.codigo_orden AS order_code,
                    actual.clave_proceso AS process_key,
                    actual.route_estado,
                    actual.worked_started_at,
                    actual.worked_ended_at,
                    fo.customer_name,
                    fo.contact_name,
                    fo.salesperson_name,
                    fo.material_nombre,
                    COALESCE(NULLIF(fo.barniz_tipo_vigente, ''), fo.barniz_tipo) AS varnish_type,
                    COALESCE(NULLIF(fo.troquel_codigo_vigente, ''), fo.die_code) AS die_code,
                    fo.estado_detencion,
                    fo.created_at,
                    COALESCE(
                        fo.raw_data#>>'{line_summary,job_name}',
                        fo.raw_data#>>'{line_summary,product_name}',
                        fo.raw_data#>>'{line_snapshot,jobName}',
                        fo.product_code
                    ) AS product_name,
                    NULLIF(concat_ws(', ',
                        NULLIF(fo.tinta_est1_pantone_ref, ''), NULLIF(fo.tinta_est2_pantone_ref, ''),
                        NULLIF(fo.tinta_est3_pantone_ref, ''), NULLIF(fo.tinta_est4_pantone_ref, ''),
                        NULLIF(fo.tinta_est5_pantone_ref, ''), NULLIF(fo.tinta_est6_pantone_ref, ''),
                        NULLIF(fo.tinta_est7_pantone_ref, ''), NULLIF(fo.tinta_est8_pantone_ref, '')
                    ), '') AS inks
                FROM actual
                JOIN flexo_orders fo ON fo.order_code = actual.codigo_orden
            )
            SELECT * FROM ordenes
            WHERE ($${termIdx} = '' OR (
                order_code ILIKE $${likeIdx} OR customer_name ILIKE $${likeIdx} OR contact_name ILIKE $${likeIdx}
                OR salesperson_name ILIKE $${likeIdx} OR material_nombre ILIKE $${likeIdx} OR die_code ILIKE $${likeIdx}
                OR varnish_type ILIKE $${likeIdx} OR product_name ILIKE $${likeIdx} OR inks ILIKE $${likeIdx}
            ))
            ORDER BY COALESCE(worked_ended_at, worked_started_at, created_at) DESC
            LIMIT 60
        `, params);

        const orders = result.rows.map(row => ({
            orderCode: row.order_code,
            processKey: row.process_key || processKey || '',
            productName: row.product_name || row.order_code,
            customerName: row.customer_name || '',
            contactName: row.contact_name || '',
            salespersonName: row.salesperson_name || '',
            substrateName: row.material_nombre || '',
            varnishType: row.varnish_type || '',
            dieCode: row.die_code || '',
            inks: row.inks || '',
            routeStatus: SEGUIMIENTO_ESTADO_API[row.route_estado] || row.route_estado || '',
            detentionStatus: row.estado_detencion || '',
            workedStartedAt: row.worked_started_at || null,
            workedEndedAt: row.worked_ended_at || null,
            createdAt: row.created_at
        }));

        res.json({ ok: true, orders });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible buscar órdenes.' });
    }
});

// Trae el detalle de UNA orden en UN proceso, sin importar su estado (pendiente,
// en curso, pausada o ya completada) — usado por "Buscar Orden" para poder volver
// a abrir una orden que ya no aparece en la cola activa (por ejemplo, para agregar
// un proceso adicional o hacer un cambio después de que ya se dio por terminada).
app.get('/api/produccion/orden-proceso/:orderCode/:process', async (req, res) => {
    try {
        const processKey = canonicalProductionFlowKey(String(req.params.process || ''));
        if (!processKey || !PRODUCTION_FLOW_SEQUENCE.includes(processKey)) {
            return res.status(400).json({ ok: false, error: 'Proceso no válido.' });
        }
        const orderCode = sanitizeAdminUserText(req.params.orderCode || '').trim();
        if (!orderCode) {
            return res.status(400).json({ ok: false, error: 'Orden no válida.' });
        }

        const result = await pgQuery(`
            SELECT
                vp.id::text AS route_id,
                vp.codigo_orden AS order_code,
                vp.codigo_cotizacion AS quote_code,
                vp.codigo_linea AS line_code,
                vp.clave_proceso AS process_key,
                vp.nombre_proceso AS process_name,
                vp.estado,
                vp.secuencia AS sequence_order,
                vp.fecha_plan_inicio AS planned_start_at,
                vp.duracion_horas AS duration_hours,
                vp.fecha_real_inicio AS actual_start_at,
                vp.fecha_real_fin AS actual_end_at,
                vp.perfil_maquina_id::text AS machine_profile_id,
                COALESCE(vp.nombre_maquina, fo.machine_name, '') AS machine_name,
                fo.product_code,
                fo.material_code,
                fo.die_code,
                fo.ordered_quantity,
                fo.customer_name,
                COALESCE(
                    fo.raw_data#>>'{line_summary,job_name}',
                    fo.raw_data#>>'{line_summary,product_name}',
                    fo.raw_data#>>'{line_snapshot,jobName}'
                ) AS rd_product_name,
                NULLIF(COALESCE(
                    fo.raw_data#>>'{line_snapshot,materialFeet}',
                    fo.raw_data#>>'{totals,total_feet}'
                ), '')::numeric AS rd_planned_feet,
                fo.created_at AS order_created_at,
                vp.suspendida_produccion,
                vp.suspendida_motivo,
                vp.suspendida_en,
                vp.suspendida_por
            FROM vista_orden_proceso vp
            JOIN flexo_orders fo ON fo.order_code = vp.codigo_orden
            WHERE vp.codigo_orden = $1 AND vp.clave_proceso = $2
            LIMIT 1
        `, [orderCode, processKey]);

        const row = result.rows[0];
        if (!row) {
            return res.status(404).json({ ok: false, error: 'No se encontró esa orden en ese proceso.' });
        }

        const planRes = await pgQuery(`SELECT lanzado_gantt FROM orden_planificacion WHERE codigo_orden = $1 LIMIT 1`, [orderCode]);
        const op = planRes.rows[0] || {};
        if (!op.lanzado_gantt) {
            return res.status(400).json({ ok: false, error: 'Esta orden aún no ha recibido la marca de Seguimiento.' });
        }

        let machineSpecs = [];
        if (row.machine_profile_id) {
            const specsResult = await pgQuery(`
                SELECT spec_group, spec_key, spec_value
                FROM production_machine_specs
                WHERE machine_profile_id = $1
            `, [row.machine_profile_id]);
            machineSpecs = specsResult.rows;
        }

        const route = {
            routeId: row.route_id,
            orderCode: row.order_code,
            quoteCode: row.quote_code || '',
            lineCode: row.line_code || '',
            processKey,
            processName: PRODUCTION_FLOW_LABELS[processKey] || row.process_name || processKey,
            routeStatus: SEGUIMIENTO_ESTADO_API[row.estado] || 'PENDIENTE',
            sequenceOrder: Number(row.sequence_order || 999),
            plannedStartAt: row.planned_start_at || null,
            actualStartAt: row.actual_start_at || null,
            durationHours: Number(row.duration_hours || 0),
            machineName: row.machine_name || '',
            machineProfileId: row.machine_profile_id || null,
            machineSpecs,
            customerName: row.customer_name || '',
            productName: row.rd_product_name || row.product_code || row.order_code,
            materialCode: row.material_code || '',
            dieCode: row.die_code || '',
            quantity: Number(row.ordered_quantity || 0),
            plannedFeet: Number(row.rd_planned_feet || 0),
            createdAt: row.order_created_at,
            prioridad: 'normal',
            suspendidaProduccion: !!row.suspendida_produccion,
            suspendidaMotivo: row.suspendida_motivo || '',
            suspendidaEn: row.suspendida_en || null,
            suspendidaPor: row.suspendida_por || ''
        };

        res.json({ ok: true, route });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar esa orden.' });
    }
});

function normalizeReportDate(value, fallback = null) {
    const text = String(value || '').trim();
    if (!text) return fallback;
    const date = new Date(`${text}T00:00:00`);
    return Number.isNaN(date.getTime()) ? fallback : text;
}

function normalizeConsumptionFamily(value) {
    const text = String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase();
    if (text.includes('barniz')) return 'barniz';
    if (text.includes('laminad')) return 'laminado';
    if (text.includes('foil') || text.includes('estamp')) return 'foil';
    if (text.includes('tinta') || text.includes('ink') || text.includes('pantone') || text.includes('cmyk')) return 'tinta';
    if (text.includes('sustrat') || text.includes('film') || text.includes('papel') || text.includes('bopp') || text.includes('pet') || text.includes('opp')) return 'sustrato';
    if (text.includes('troquel')) return 'troquel';
    return text.trim() || 'material';
}

function processAllowsConsumption(processKey, family) {
    const process = canonicalProductionFlowKey(processKey);
    const itemFamily = normalizeConsumptionFamily(family);
    if (itemFamily === 'troquel') return true;
    if (process === 'impresion') return ['sustrato', 'tinta', 'barniz', 'laminado', 'foil'].includes(itemFamily);
    if (process === 'barnizado') return itemFamily === 'barniz';
    if (process === 'laminado') return itemFamily === 'laminado';
    if (process === 'estampado') return itemFamily === 'foil';
    if (process === 'rebobinado' || process === 'empaque') return ['sustrato', 'material'].includes(itemFamily);
    return false;
}

function addConsumptionMaterial(list, item = {}) {
    const sapItemCode = sanitizeAdminUserText(item.sapItemCode || item.itemCode || item.materialCode || item.code);
    const materialName = sanitizeAdminUserText(item.materialName || item.itemName || item.name || item.description || sapItemCode);
    if (!sapItemCode && !materialName) return;
    const family = normalizeConsumptionFamily(item.family || item.materialFamily || materialName || sapItemCode);
    const key = `${sapItemCode || materialName}|${family}`;
    if (list.some((row) => row.key === key)) return;
    list.push({
        key,
        sapItemCode,
        materialName,
        materialFamily: family,
        plannedQuantity: Number(item.plannedQuantity || item.quantity || item.qty || 0),
        unitCode: sanitizeAdminUserText(item.unitCode || item.unit || item.unitHint || ''),
        source: sanitizeAdminUserText(item.source || ''),
        motivoIndice: item.motivoIndice !== undefined && item.motivoIndice !== null && item.motivoIndice !== '' ? Number(item.motivoIndice) : null,
        motivoNombre: sanitizeAdminUserText(item.motivoNombre || ''),
        tintaTipo: sanitizeAdminUserText(item.tintaTipo || '')
    });
}

// Tintas reales por motivo/estación, tal como se capturaron en el apartado de
// Motivos del cálculo (calculo_motivo_tintas). Es la fuente de verdad — el
// snapshot plano en raw_data.printing puede quedarse desactualizado.
async function fetchOrderMotivoTintas(quoteCode, lineCode) {
    if (!quoteCode || !lineCode) return [];
    const result = await pgQuery(
        `SELECT t.motivo_indice, t.estacion_indice, t.tipo_tinta, t.etiqueta, t.pantone_id, t.cobertura_pct,
                m.nombre AS motivo_nombre
           FROM calculo_motivo_tintas t
           LEFT JOIN calculo_motivos m
             ON m.quote_code = t.quote_code AND m.line_code = t.line_code AND m.motivo_indice = t.motivo_indice
          WHERE t.quote_code = $1 AND t.line_code = $2 AND t.activo = true
          ORDER BY t.motivo_indice, t.estacion_indice`,
        [quoteCode, lineCode]
    );
    return result.rows;
}

// Troquel real por motivo (flexo_products guarda un die_code por motivo/versión,
// que puede diferir entre motivos de una misma orden).
async function fetchOrderMotivoDieCodes(quoteCode, lineCode) {
    if (!quoteCode || !lineCode) return [];
    const result = await pgQuery(
        `SELECT DISTINCT motivo_indice, motivo_nombre, die_code
           FROM flexo_products
          WHERE quote_code = $1 AND line_code = $2 AND die_code IS NOT NULL AND die_code != ''
          ORDER BY motivo_indice`,
        [quoteCode, lineCode]
    );
    return result.rows;
}

// Desglose real por motivo de la orden, para mostrar en la pantalla de
// detalle (orden-produccion.js): cada motivo con su propia info (tintas
// reales por estación, versiones, sellos, troquel/producto), tal como se
// cotizó — vive en calculo_motivos/calculo_motivo_tintas/calculo_versiones,
// no en el snapshot congelado de raw_data.resumen_creacion.
// Procesos adicionales cotizados (fila libre de descripción/costo/comentario,
// proceso "Procesos Adicionales" del cálculo) — vive en ui_state.additional,
// no es por motivo, es a nivel de línea completa.
async function buildOrderProcesosAdicionales(orden) {
    const quoteCode = orden?.quote_code;
    const lineCode = orden?.line_code;
    if (!quoteCode || !lineCode) return null;
    const result = await pgQuery(
        `SELECT ui_state FROM flexo_calculations WHERE quote_code = $1 AND line_code = $2 ORDER BY created_at DESC LIMIT 1`,
        [quoteCode, lineCode]
    );
    const rows = Array.isArray(result.rows[0]?.ui_state?.additional) ? result.rows[0].ui_state.additional : [];
    const filtered = rows.filter((row) => String(row?.description || row?.comments || '').trim());
    if (!filtered.length) return null;
    return filtered.map((row) => ({
        descripcion: String(row.description || '').trim(),
        comentario: String(row.comments || '').trim()
    }));
}

// Troquel de la orden — el código del troquel cotizado (die_code) YA está en flexo_orders/
// flexo_products/flexo_calculations, y coincide con troquel.codigo del inventario. Se usa
// ese cruce directo (no calculo_troquel/id_troquel_fisico, que hoy no tiene ningún registro
// poblado en producción — verificado 2026-09-05). Devuelve columnas cotizadas (catálogo +
// die_teeth/die_rows/die_repeats de la orden) y las *_vigente que Preprensa/Impresión pueden
// ajustar en producción, más los cilindros de inventario con el mismo dentado (montaje).
async function buildTroquelInfoParaOrden(orden, prod0, calc) {
    const codigoCotizado = orden.die_code || prod0.die_code || calc.die_code || '';
    const codigoVigente = orden.troquel_codigo_vigente || '';
    const codigoBusqueda = codigoVigente || codigoCotizado;
    if (!codigoBusqueda) return { troquel: null, cilindrosCompatibles: [] };
    const troquelRes = await pgQuery(
        `SELECT codigo, descripcion, ancho_mm, largo_mm, dientes, repeticiones, formato,
                montaje_troquel, estructura_troquel, tipo_troquel, tension, gap_in,
                elongacion_pct, desarrollo_cm, desarrollo_in, ancho_total_troquel_in,
                largo_total_troquel_in, vida_util_golpes_usados, vida_util_golpes_restantes,
                vida_util_golpes_total, image_url
           FROM troquel WHERE codigo = $1 LIMIT 1`,
        [codigoBusqueda]
    );
    const t = troquelRes.rows[0] || null;
    let cilindrosCompatibles = [];
    if (t && t.dientes) {
        const cilRes = await pgQuery(
            `SELECT codigo, nombre, tipo, dientes, desarrollo_mm, ancho_util_mm, ancho_total_mm, estado
               FROM cilindro WHERE dientes = $1 AND activo = TRUE ORDER BY codigo`,
            [t.dientes]
        );
        cilindrosCompatibles = cilRes.rows;
    }
    return {
        troquel: {
            codigoCotizado, codigoVigente,
            tipoVigente: orden.troquel_tipo_vigente || '',
            dientesCotizado: orden.die_teeth != null ? Number(orden.die_teeth) : (t ? t.dientes : null),
            dientesVigente: orden.troquel_dientes_z_vigente != null ? Number(orden.troquel_dientes_z_vigente) : null,
            repeticionesCotizado: orden.die_repeats != null ? Number(orden.die_repeats) : (t ? t.repeticiones : null),
            repeticionVigenteIn: orden.troquel_repeticion_vigente_in != null ? Number(orden.troquel_repeticion_vigente_in) : null,
            filasCotizado: orden.die_rows != null ? Number(orden.die_rows) : null,
            forma: orden.troquel_forma || prod0.troquel_forma || calc.troquel_forma || '',
            camisaMagneticaVigente: orden.troquel_camisa_magnetica_vigente || '',
            presionCorteVigente: orden.troquel_presion_corte_vigente != null ? Number(orden.troquel_presion_corte_vigente) : null,
            notasVigente: orden.troquel_notas_vigente || '',
            catalogo: t ? {
                descripcion: t.descripcion || '', formato: t.formato || '', tipoTroquel: t.tipo_troquel || '',
                anchoMm: t.ancho_mm != null ? Number(t.ancho_mm) : null, largoMm: t.largo_mm != null ? Number(t.largo_mm) : null,
                montaje: t.montaje_troquel || '', estructura: t.estructura_troquel || '', tension: t.tension || '',
                gapIn: t.gap_in != null ? Number(t.gap_in) : null, elongacionPct: t.elongacion_pct != null ? Number(t.elongacion_pct) : null,
                desarrolloIn: t.desarrollo_in != null ? Number(t.desarrollo_in) : null, desarrolloCm: t.desarrollo_cm != null ? Number(t.desarrollo_cm) : null,
                anchoTotalIn: t.ancho_total_troquel_in != null ? Number(t.ancho_total_troquel_in) : null,
                largoTotalIn: t.largo_total_troquel_in != null ? Number(t.largo_total_troquel_in) : null,
                vidaUtilUsados: t.vida_util_golpes_usados != null ? Number(t.vida_util_golpes_usados) : null,
                vidaUtilRestantes: t.vida_util_golpes_restantes != null ? Number(t.vida_util_golpes_restantes) : null,
                vidaUtilTotal: t.vida_util_golpes_total != null ? Number(t.vida_util_golpes_total) : null,
                imagenUrl: t.image_url || ''
            } : null
        },
        cilindrosCompatibles: cilindrosCompatibles.map((c) => ({
            codigo: c.codigo, nombre: c.nombre || '', tipo: c.tipo || '', dientes: c.dientes,
            desarrolloMm: c.desarrollo_mm != null ? Number(c.desarrollo_mm) : null,
            anchoUtilMm: c.ancho_util_mm != null ? Number(c.ancho_util_mm) : null,
            anchoTotalMm: c.ancho_total_mm != null ? Number(c.ancho_total_mm) : null,
            estado: c.estado || ''
        }))
    };
}

async function buildOrderMotivosDetalle(orden) {
    const quoteCode = orden?.quote_code;
    const lineCode = orden?.line_code;
    if (!quoteCode || !lineCode) return null;
    const [motivosResult, versionesResult, productosResult, calcResult] = await Promise.all([
        pgQuery(
            `SELECT motivo_indice, nombre, cantidad
               FROM calculo_motivos WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice`,
            [quoteCode, lineCode]
        ),
        pgQuery(
            `SELECT motivo_indice, version_indice, nombre, descripcion, cantidad
               FROM calculo_versiones WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice, version_indice`,
            [quoteCode, lineCode]
        ),
        pgQuery(
            `SELECT motivo_indice, die_code, product_code, finished_product_sku,
                    product_name, material_name, product_type, output_type, surface_type,
                    codigo_producto_cliente, width_inches, length_inches,
                    bcm_anilox, barniz_tipo, barniz_zonificado,
                    anilox_code_vigente, viscosity_vigente, temperature_vigente, ink_type_vigente,
                    pantone_ref_vigente, barniz_tipo_vigente, barniz_zona_vigente, barniz_zonif_vigente,
                    uv_power_vigente, uv_temp_vigente, mes_viscosidad_promedio, mes_temperatura_promedio,
                    tiempo_real_planeacion_horas, tiempo_proceso_planeacion_horas,
                    tiempo_real_diseno_horas, tiempo_proceso_diseno_horas,
                    tiempo_real_preprensa_horas, tiempo_proceso_preprensa_horas,
                    tiempo_real_visto_bueno_horas, tiempo_proceso_visto_bueno_horas,
                    tiempo_real_programacion_horas, tiempo_proceso_programacion_horas,
                    tiempo_real_tintas_horas, tiempo_proceso_tintas_horas,
                    tiempo_real_impresion_horas, tiempo_proceso_impresion_horas,
                    tiempo_real_rebobinado_horas, tiempo_proceso_rebobinado_horas,
                    tiempo_real_empaque_horas, tiempo_proceso_empaque_horas
               FROM flexo_products WHERE quote_code = $1 AND line_code = $2 AND motivo_indice IS NOT NULL ORDER BY motivo_indice`,
            [quoteCode, lineCode]
        ),
        pgQuery(
            `SELECT ui_state, width_inches, length_inches, pies_totales_sustrato, pies_sustrato_neto
               FROM flexo_calculations WHERE quote_code = $1 AND line_code = $2 ORDER BY created_at DESC LIMIT 1`,
            [quoteCode, lineCode]
        )
    ]);
    if (!motivosResult.rows.length) return null;
    const uiState = calcResult.rows[0]?.ui_state || {};
    const uiStateTypes = Array.isArray(uiState.types) ? uiState.types : [];
    const headerInkStations = Array.isArray(uiState.printStages?.[0]?.inkStations) ? uiState.printStages[0].inkStations : [];
    // Modelo vigente de tintas por motivo: station.tipo (proceso/directo/adicional/barniz)
    // + tintaRefId contra los catálogos reales de tintas.* — reemplaza el modelo legado
    // basado en inkType (cmyk/blanco/pantone) que el negocio está retirando. Ese modelo
    // vigente vive en types[idx].inkStations para TODOS los motivos, incluido el 0;
    // printStages[0].inkStations solo conserva el modelo legado y se usa como respaldo
    // únicamente cuando types[0] quedó vacío (cálculos antiguos).
    const inkStationsForMotivo = (idx) => {
        const typeStations = Array.isArray(uiStateTypes[idx]?.inkStations) ? uiStateTypes[idx].inkStations : [];
        if (idx === 0 && !typeStations.length) return headerInkStations;
        return typeStations;
    };

    const procesoAdicionalIds = new Set();
    const directoIds = new Set();
    motivosResult.rows.forEach((motivo) => {
        inkStationsForMotivo(motivo.motivo_indice).forEach((station) => {
            if (!station?.tipo || !station?.tintaRefId) return;
            if (station.tipo === 'proceso' || station.tipo === 'adicional') procesoAdicionalIds.add(station.tintaRefId);
            else if (station.tipo === 'directo') directoIds.add(station.tintaRefId);
        });
    });
    const [tintasProductosResult, tintasRecetasResult] = await Promise.all([
        procesoAdicionalIds.size ? pgQuery(`SELECT id::text, nombre, color FROM tintas.productos WHERE id = ANY($1::uuid[])`, [[...procesoAdicionalIds]]) : { rows: [] },
        directoIds.size ? pgQuery(`SELECT id::text, nombre, color_hex FROM tintas.pantones_recetas WHERE id = ANY($1::uuid[])`, [[...directoIds]]) : { rows: [] }
    ]);
    // tintas.productos.color es un NOMBRE ("Cian", "Magenta"...), no un hex — el inventario de
    // tintas todavía no guarda un color real para procesos/adicionales. Se traduce el nombre
    // estándar a su hex representativo; si el nombre no es uno de los conocidos, no hay color
    // (no hay conversor de Pantone para inventar uno).
    const PROCESS_COLOR_HEX = {
        cian: '#00aeef', cyan: '#00aeef',
        magenta: '#ec008c',
        amarillo: '#ffe800', yellow: '#ffe800',
        negro: '#1a1a1a', black: '#1a1a1a',
        blanco: '#f5f5f5', white: '#f5f5f5'
    };
    const tintaNameById = new Map();
    const tintaColorById = new Map();
    tintasProductosResult.rows.forEach((r) => {
        tintaNameById.set(r.id, r.nombre);
        const hex = PROCESS_COLOR_HEX[String(r.color || '').trim().toLowerCase()];
        if (hex) tintaColorById.set(r.id, hex);
    });
    tintasRecetasResult.rows.forEach((r) => { tintaNameById.set(r.id, r.nombre); if (r.color_hex) tintaColorById.set(r.id, r.color_hex); });

    // Consumo de tinta = misma fórmula que usa calcMotivoInkStationRow() en el cálculo
    // (área impresa × cobertura × BCM anilox × factor de transferencia × densidad),
    // multiplicada por la razón de merma. printedAreaIn2 usa el ancho/largo real de la
    // etiqueta (columnas ya guardadas); mermaRatio se deriva de pies totales/netos de
    // sustrato — el mismo concepto que ya usa el cálculo ("igual que Sustrato ya hace
    // con la longitud"), sin reimplementar el motor de merma completo.
    const calcRow = calcResult.rows[0] || {};
    const labelAreaIn2 = Number(calcRow.width_inches || orden.width_inches || 0) * Number(calcRow.length_inches || orden.length_inches || 0);
    const piesNeto = Number(calcRow.pies_sustrato_neto || orden.pies_sustrato_neto || 0);
    const piesTotal = Number(calcRow.pies_totales_sustrato || orden.pies_totales_sustrato || 0);
    const mermaRatio = piesNeto > 0 && piesTotal > 0 ? piesTotal / piesNeto : 1;
    const sinImpresion = orden.sin_impresion === true;

    return motivosResult.rows.map((motivo) => {
        const idx = motivo.motivo_indice;
        const producto = productosResult.rows.find((p) => p.motivo_indice === idx) || null;
        const stations = inkStationsForMotivo(idx).filter((s) => s?.tipo);
        const printedAreaIn2 = sinImpresion ? 0 : labelAreaIn2 * (Number(motivo.cantidad) || 0);
        let consumoTotalKg = 0;
        return {
            indice: idx,
            nombre: motivo.nombre || `Motivo ${idx + 1}`,
            cantidad: Number(motivo.cantidad) || 0,
            proceso: stations.filter((s) => s.tipo === 'proceso').length,
            directo: stations.filter((s) => s.tipo === 'directo').length,
            adicional: stations.filter((s) => s.tipo === 'adicional').length,
            sellos: Math.max(0, Number(uiStateTypes[idx]?.plates) || 0),
            tintas: stations.map((s, i) => {
                const coveragePct = Number(s.coveragePct) || 0;
                const aniloxBcm = Number(s.aniloxBcm) || 0;
                const transferFactor = Number(s.transferFactor) || 0;
                const inkDensity = Number(s.inkDensity) || 0;
                const netConsumptionKg = (printedAreaIn2 * (coveragePct / 100) * aniloxBcm * transferFactor * inkDensity * 0.001) / 1000;
                const consumptionKg = netConsumptionKg * mermaRatio;
                if (s.active !== false) consumoTotalKg += consumptionKg;
                return {
                estacion: i,
                tipo: s.tipo,
                etiqueta: tintaNameById.get(String(s.tintaRefId)) || s.inkLabel || '',
                // Respaldo cuando el cálculo no trae tintaRefId (cotizaciones viejas guardan solo
                // el nombre en inkLabel, sin enlazar a tintas.productos) — se intenta igual con el
                // nombre tal cual, para que Proceso/Cian/Magenta/etc. siempre tengan un color real.
                color: tintaColorById.get(String(s.tintaRefId)) || PROCESS_COLOR_HEX[String(s.inkLabel || '').trim().toLowerCase()] || null,
                coberturaPct: s.coveragePct != null ? Number(s.coveragePct) : null,
                consumoKg: consumptionKg > 0 ? Number(consumptionKg.toFixed(4)) : null,
                activo: s.active !== false,
                bcmAnilox: Number(s.aniloxBcm) || null,
                factorTransferencia: Number(s.transferFactor) || null,
                densidad: Number(s.inkDensity) || null
                };
            }),
            consumoTotalKg: consumoTotalKg > 0 ? Number(consumoTotalKg.toFixed(4)) : null,
            versiones: versionesResult.rows
                .filter((v) => v.motivo_indice === idx)
                .map((v) => {
                    // Consumo por versión: misma tasa de consumo por pulgada² del motivo
                    // (mismas tintas/cobertura), aplicada a la cantidad propia de la versión
                    // — cada versión (ej. "uvas" vs "fresas" de un mismo motivo) tiene su
                    // propia tirada y por lo tanto su propio consumo real.
                    const versionAreaIn2 = sinImpresion ? 0 : labelAreaIn2 * (Number(v.cantidad) || 0);
                    const ratePerIn2 = printedAreaIn2 > 0 ? consumoTotalKg / printedAreaIn2 : 0;
                    const versionConsumoKg = versionAreaIn2 * ratePerIn2;
                    const versionUi = uiStateTypes[idx]?.versions?.[v.version_indice] || {};
                    return {
                        indice: v.version_indice,
                        nombre: v.nombre || `Versión ${v.version_indice + 1}`,
                        descripcion: v.descripcion || '',
                        cantidad: Number(v.cantidad) || 0,
                        sellos: Math.max(0, Number(versionUi.additionalPlates) || 0),
                        consumoKg: versionConsumoKg > 0 ? Number(versionConsumoKg.toFixed(4)) : null
                    };
                }),
            producto: producto ? {
                codigo: producto.product_code || '',
                sku: producto.finished_product_sku || '',
                nombre: producto.product_name || '',
                materialName: producto.material_name || '',
                productType: producto.product_type || '',
                outputType: producto.output_type || '',
                surfaceType: producto.surface_type || '',
                skuCliente: producto.codigo_producto_cliente || '',
                widthIn: producto.width_inches != null ? Number(producto.width_inches) : null,
                lengthIn: producto.length_inches != null ? Number(producto.length_inches) : null,
                dieCode: producto.die_code || '',
                parametros: {
                    aniloxBcmCotizado: producto.bcm_anilox != null ? Number(producto.bcm_anilox) : null,
                    aniloxCodeVigente: producto.anilox_code_vigente || '',
                    viscosidadVigente: producto.viscosity_vigente != null ? Number(producto.viscosity_vigente) : null,
                    viscosidadPromedio: producto.mes_viscosidad_promedio != null ? Number(producto.mes_viscosidad_promedio) : null,
                    temperaturaVigente: producto.temperature_vigente != null ? Number(producto.temperature_vigente) : null,
                    temperaturaPromedio: producto.mes_temperatura_promedio != null ? Number(producto.mes_temperatura_promedio) : null,
                    tipoTintaVigente: producto.ink_type_vigente || '',
                    pantoneVigente: producto.pantone_ref_vigente || '',
                    barnizTipoCotizado: producto.barniz_tipo || '',
                    barnizTipoVigente: producto.barniz_tipo_vigente || '',
                    barnizZonificadoCotizado: producto.barniz_zonificado === true,
                    barnizZonifVigente: producto.barniz_zonif_vigente || '',
                    barnizZonaVigente: producto.barniz_zona_vigente || '',
                    uvPowerVigente: producto.uv_power_vigente != null ? Number(producto.uv_power_vigente) : null,
                    uvTempVigente: producto.uv_temp_vigente != null ? Number(producto.uv_temp_vigente) : null
                },
                tiempos: PRODUCTION_TIMING_SUMMARY_KEYS.map((key) => ({
                    etapa: key,
                    real: producto[`tiempo_real_${key}_horas`] != null ? Number(producto[`tiempo_real_${key}_horas`]) : null,
                    proceso: producto[`tiempo_proceso_${key}_horas`] != null ? Number(producto[`tiempo_proceso_${key}_horas`]) : null
                }))
            } : null
        };
    });
}

// Información de Sellos para la ficha de la orden: origen (Costo Externo / Inventario /
// Fabricación Interna), y por motivo la cantidad de sellos, pulgadas² por sello,
// pulgadas² por motivo y el acumulado. Los datos nacen del cálculo (flexo_calculations.ui_state.plates):
// en modo Costo Externo ya existen las filas por motivo (rowsAuto); en los demás modos se
// deriva el tamaño de sello con la misma fórmula del cálculo (desarrollo de troquel + ancho
// de material + "Exceso Sellos" a ambos lados) y el conteo de sellos por motivo (types[].plates).
async function buildOrderSellosFicha(orden) {
    const quoteCode = orden?.quote_code;
    const lineCode = orden?.line_code;
    if (!quoteCode || !lineCode) return null;
    const calcResult = await pgQuery(
        `SELECT ui_state FROM flexo_calculations WHERE quote_code = $1 AND line_code = $2 ORDER BY created_at DESC LIMIT 1`,
        [quoteCode, lineCode]
    );
    const uiState = calcResult.rows[0]?.ui_state || {};
    const plates = (uiState.plates && typeof uiState.plates === 'object') ? uiState.plates : {};
    if (plates.chargePlates === false) return null;

    const modo = String(plates.plateMode || '').trim().toLowerCase();
    const ORIGEN_ETIQUETAS = { external: 'Costo Externo', inventory: 'Sellos en Inventario', create: 'Fabricación Interna' };
    const origen = ORIGEN_ETIQUETAS[modo] || null;
    const esExterno = modo === 'external';

    const num = (v) => { const x = Number(v); return Number.isFinite(x) ? x : 0; };
    const jobName = String(uiState.header?.jobName || '').trim();

    // Tamaño de UN sello, misma fórmula del cálculo: (desarrollo de troquel + 2·exceso) ×
    // (ancho de material + 2·exceso). Sirve de respaldo cuando el cálculo no guardó las filas
    // por motivo (rowsAuto), para que el cliente pueda armar la tabla con motivos_detalle.
    const costsConfig = await loadCostsConfig().catch(() => ({}));
    const excesoIn = num(costsConfig?.general?.excesoSellosIn) || 0.5;
    const dieDevIn = num(uiState.troquel?.cylinderDevelopmentIn);
    const matWidthIn = num(uiState.header?.rollWidthIn);
    const plateWidthIn = dieDevIn > 0 ? dieDevIn + excesoIn * 2 : 0;
    const plateHeightIn = matWidthIn > 0 ? matWidthIn + excesoIn * 2 : 0;
    const inPorSello = (plateWidthIn > 0 && plateHeightIn > 0) ? Number((plateWidthIn * plateHeightIn).toFixed(4)) : 0;

    let filas = [];
    const rowsAuto = Array.isArray(plates.rowsAuto) ? plates.rowsAuto : [];
    if (rowsAuto.length) {
        filas = rowsAuto.map((row, i) => {
            const sellos = num(row.cantidad);
            const filaInPorSello = num(row.inPorSello) || inPorSello;
            const inTotalMotivo = num(row.inTotalMotivo) || (sellos * filaInPorSello);
            return {
                detalle: String(row.detalle || row.defaultDetalle || (i === 0 && jobName ? jobName : `Motivo ${i + 1}`)),
                sellos,
                inPorSello: Number(filaInPorSello.toFixed(4)),
                inTotalMotivo: Number(inTotalMotivo.toFixed(4))
            };
        });
    } else {
        const types = Array.isArray(uiState.types) ? uiState.types : [];
        filas = types.map((type, idx) => {
            const sellos = Math.max(0, num(type.plates) || (num(type.inkStationPlates) + num(type.estampadoPlates)));
            return {
                detalle: String(type.nombre_motivo || (idx === 0 && jobName ? jobName : `Motivo ${idx + 1}`)),
                sellos,
                inPorSello,
                inTotalMotivo: Number((sellos * inPorSello).toFixed(4))
            };
        }).filter((f) => f.sellos > 0 || f.inTotalMotivo > 0);
    }

    let descripcion = '';
    let comentario = '';
    if (esExterno) {
        const extRows = Array.isArray(plates.external) ? plates.external : [];
        descripcion = extRows.map((r) => String(r?.description || '').trim()).filter(Boolean).join(' · ');
        comentario = extRows.map((r) => String(r?.comments || '').trim()).filter(Boolean).join(' · ');
    }

    const totalSellos = filas.reduce((s, f) => s + (f.sellos || 0), 0);
    const totalIn2 = Number(filas.reduce((s, f) => s + (f.inTotalMotivo || 0), 0).toFixed(4));

    if (!filas.length && !descripcion && !origen) return null;

    return { origen, esExterno, descripcion, comentario, inPorSello, filas, totalSellos, totalIn2 };
}

async function collectOrderConsumptionMaterials(orderRow, processKey = 'impresion') {
    const raw = orderRow?.raw_data || {};
    const materials = [];
    const printing = raw.printing || {};
    const lineSnapshot = raw.line_snapshot || raw.lineSnapshot || {};
    const calcResult = orderQuotedResult(orderRow) || raw.calculation_result || raw.result || raw.calculationResult || {};
    addConsumptionMaterial(materials, {
        sapItemCode: orderRow.material_code || lineSnapshot.materialCode || printing.materialCode,
        materialName: lineSnapshot.materialName || printing.materialName || orderRow.material_code,
        family: 'sustrato',
        plannedQuantity: feetToMetersOrNull(calcResult?.sustrato?.totalLengthFeet || calcResult?.sustrato?.linealFeet || printing.materialFeet || lineSnapshot.materialFeet || raw.totals?.total_feet),
        unitCode: 'm',
        source: 'orden'
    });
    const inkTotalKg = Number(calcResult?.print?.inkConsumption || 0);
    const motivoTintaRows = await fetchOrderMotivoTintas(orderRow.quote_code, orderRow.line_code);
    if (motivoTintaRows.length) {
        const multipleMotivos = new Set(motivoTintaRows.map((r) => r.motivo_indice)).size > 1;
        const perStationKg = pickFirstMeaningfulNumber(
            orderRow.consumo_tinta_por_color_lb ? Number(orderRow.consumo_tinta_por_color_lb) * 0.45359237 : 0,
            inkTotalKg > 0 ? inkTotalKg / motivoTintaRows.length : 0,
            0
        );
        const TINTA_TIPO_LABELS = { cmyk: 'Tinta Proceso', blanco: 'Tinta Blanca', pantone: 'Tinta Directa (Pantone)' };
        motivoTintaRows.forEach((row) => {
            const tipo = String(row.tipo_tinta || '').toLowerCase();
            const baseLabel = row.etiqueta || TINTA_TIPO_LABELS[tipo] || 'Tinta';
            const materialName = multipleMotivos && row.motivo_nombre ? `${baseLabel} — ${row.motivo_nombre}` : baseLabel;
            addConsumptionMaterial(materials, {
                materialName,
                family: 'tinta',
                plannedQuantity: perStationKg,
                unitCode: 'kg',
                source: 'tintas_motivo',
                motivoIndice: row.motivo_indice,
                motivoNombre: row.motivo_nombre || '',
                tintaTipo: tipo
            });
        });
    } else {
        // Fallback legado: órdenes sin filas tipadas en calculo_motivo_tintas
        // (creadas antes de esta migración) — se usa el snapshot plano de la orden.
        const hasCmyk = printing.hasCmyk === true || lineSnapshot.cmyk === true || raw.line_snapshot?.raw_data?.['GENERAL | CMYK'] === true || String(raw.line_snapshot?.raw_data?.CMYK || '').toLowerCase() === 'si';
        if (hasCmyk && inkTotalKg > 0) {
            addConsumptionMaterial(materials, {
                materialName: 'Tinta Proceso (CMYK)',
                family: 'tinta',
                plannedQuantity: inkTotalKg,
                unitCode: 'kg',
                source: 'tintas'
            });
        }
        (Array.isArray(printing.inks) ? printing.inks : []).forEach((ink) => addConsumptionMaterial(materials, {
            sapItemCode: ink.sapItemCode || ink.materialCode || ink.code,
            materialName: ink.materialName || ink.name,
            family: 'tinta',
            plannedQuantity: pickFirstMeaningfulNumber(ink.consumptionKg, ink.consumptionLb ? ink.consumptionLb / 2.2046226218 : 0, ink.quantity ? ink.quantity / 2.2046226218 : 0),
            unitCode: 'kg',
            source: 'tintas'
        }));
        (Array.isArray(printing.inkNames) ? printing.inkNames : []).forEach((name) => addConsumptionMaterial(materials, {
            materialName: name,
            family: 'tinta',
            unitCode: 'kg',
            source: 'tintas'
        }));
    }
    const motivoDieCodes = await fetchOrderMotivoDieCodes(orderRow.quote_code, orderRow.line_code);
    if (motivoDieCodes.length) {
        const multipleDies = new Set(motivoDieCodes.map((r) => r.die_code)).size > 1;
        motivoDieCodes.forEach((row) => addConsumptionMaterial(materials, {
            sapItemCode: row.die_code,
            materialName: multipleDies && row.motivo_nombre ? `Troquel ${row.die_code} — ${row.motivo_nombre}` : `Troquel ${row.die_code}`,
            family: 'troquel',
            plannedQuantity: 1,
            unitCode: 'pz',
            source: 'motivos',
            motivoIndice: row.motivo_indice,
            motivoNombre: row.motivo_nombre || ''
        }));
    } else if (orderRow.die_code) {
        addConsumptionMaterial(materials, {
            sapItemCode: orderRow.die_code,
            materialName: `Troquel ${orderRow.die_code}`,
            family: 'troquel',
            plannedQuantity: 1,
            unitCode: 'pz',
            source: 'orden'
        });
    }
    const addFinish = (finish) => {
        const family = normalizeConsumptionFamily(finish.key || finish.processKey || finish.label || finish.materialName);
        if (!['barniz', 'laminado', 'foil'].includes(family)) return;
        const detail = sanitizeAdminUserText(finish.detail || finish.varnish || finish.laminate || finish.foil || finish.type || '');
        const baseName = finish.materialName || finish.processLabel || finish.label || finish.processName || finish.materialId || '';
        const materialName = detail && baseName && !baseName.toLowerCase().includes(detail.toLowerCase())
            ? `${baseName} (${detail})`
            : baseName || detail || family;
        addConsumptionMaterial(materials, {
            sapItemCode: finish.sapItemCode || finish.materialCode || finish.materialId || finish.itemCode,
            materialName,
            family,
            plannedQuantity: family === 'barniz'
                ? pickFirstMeaningfulNumber(finish.materialConsumptionKg, finish.materialConsumptionLb ? finish.materialConsumptionLb * 0.45359237 : 0, finish.quantity ? (family === 'laminado' || family === 'foil' ? finish.quantity : finish.quantity * 0.45359237) : 0)
                : feetToMetersOrNull(pickFirstMeaningfulNumber(finish.materialFeet, finish.quantity, 0)),
            unitCode: family === 'barniz' ? 'kg' : 'm',
            source: 'acabados'
        });
    };
    const addPrintInline = (inline) => {
        if (!inline || !processObjectLooksActive(inline)) return;
        addFinish(inline);
    };
    (Array.isArray(calcResult.print?.items) ? calcResult.print.items : []).forEach((printItem) => {
        (Array.isArray(printItem?.inlineItems) ? printItem.inlineItems : []).forEach(addPrintInline);
    });
    (Array.isArray(printing.finishes) ? printing.finishes : []).forEach(addFinish);
    (Array.isArray(calcResult.finishes?.items) ? calcResult.finishes.items : []).forEach(addFinish);
    (Array.isArray(raw.sapExport?.bom?.payload?.Components) ? raw.sapExport.bom.payload.Components : []).forEach((component) => addConsumptionMaterial(materials, {
        sapItemCode: component.ItemCode,
        materialName: component.ItemName,
        family: component.Source,
        plannedQuantity: component.Quantity,
        unitCode: component.UnitHint,
        source: 'bom'
    }));

    if (!materials.length) {
        const uiState = raw.Estado_UI || raw.line_snapshot?.uiState || {};
        const uiSubstrate = uiState.substrate || {};
        if (uiSubstrate.materialId) {
            const substrateQty = pickFirstMeaningfulNumber(
                calcResult?.sustrato?.totalLengthFeet,
                calcResult?.sustrato?.linealFeet,
                raw['GENERAL | SUSTRATO | CONSUMO PIES'],
                raw['Material | Pies Segun Proceso Productivo'],
                raw.totals?.total_feet,
                lineSnapshot?.materialFeet
            );
            addConsumptionMaterial(materials, {
                sapItemCode: uiSubstrate.materialId,
                materialName: pickFirstValue(raw['GENERAL | MATERIAL'], raw['Material | Tipo Segun Proceso Productivo'], uiSubstrate.materialId),
                family: 'sustrato',
                plannedQuantity: feetToMetersOrNull(substrateQty),
                unitCode: 'm',
                source: 'estado_ui'
            });
        }
        const uiStages = Array.isArray(uiState.printStages) ? uiState.printStages : [];
        uiStages.forEach((stage) => {
            const inlineFinishes = stage.inlineFinishes || {};
            Object.keys(inlineFinishes).forEach((key) => {
                const finish = inlineFinishes[key];
                if (!finish?.active) return;
                const family = normalizeConsumptionFamily(key);
                if (!['barniz', 'laminado', 'foil'].includes(family)) return;
                let materialId = finish.materialId || '';
                let materialName = finish.materialName || '';
                if (!materialId && family === 'barniz') {
                    materialId = pickFirstValue(raw['CONV | BARNIZ | MATERIAL ID'], raw['BARNIZ | MATERIAL ID'], '');
                    materialName = pickFirstValue(raw['CONV | BARNIZ | MATERIAL'], raw['BARNIZ | MATERIAL'], 'Barniz');
                }
                if (!materialId) return;
                const consumptionKg = pickFirstMeaningfulNumber(finish.materialConsumptionKg, finish.materialConsumptionLb ? finish.materialConsumptionLb * 0.45359237 : 0, finish.materialBase, 0);
                addConsumptionMaterial(materials, {
                    sapItemCode: materialId,
                    materialName: materialName || materialId,
                    family,
                    plannedQuantity: consumptionKg,
                    unitCode: 'kg',
                    source: 'estado_ui'
                });
            });
        });
        const uiFinishes = Array.isArray(uiState.finishes) ? uiState.finishes : [];
        uiFinishes.forEach((finish) => {
            if (!finish?.active) return;
            const family = normalizeConsumptionFamily(finish.processKey || finish.slotKey || finish.key);
            if (!['barniz', 'laminado', 'foil'].includes(family)) return;
            let materialId = finish.materialId || '';
            let materialName = finish.materialName || finish.description || '';
            if (!materialId && family === 'barniz') {
                materialId = pickFirstValue(raw['CONV | BARNIZ | MATERIAL ID'], raw['BARNIZ | MATERIAL ID'], '');
                materialName = pickFirstValue(raw['CONV | BARNIZ | MATERIAL'], raw['BARNIZ | MATERIAL'], 'Barniz');
            }
            if (!materialId) return;
            const consumptionKg = pickFirstMeaningfulNumber(finish.materialConsumptionKg, finish.materialConsumptionLb ? finish.materialConsumptionLb * 0.45359237 : 0, finish.materialBase, 0);
            const consumptionQty = family === 'laminado'
                ? feetToMetersOrNull(pickFirstMeaningfulNumber(calcResult?.sustrato?.totalLengthFeet, calcResult?.sustrato?.linealFeet, raw.totals?.total_feet, lineSnapshot?.materialFeet, 0))
                : consumptionKg;
            const consumptionUnit = family === 'laminado' ? 'm' : 'kg';
            const extra = {};
            if (family === 'foil' && finish.supplyWidthIn) {
                extra.supplyWidthIn = finish.supplyWidthIn;
            }
            addConsumptionMaterial(materials, {
                sapItemCode: materialId,
                materialName: materialName || materialId,
                family,
                plannedQuantity: consumptionQty,
                unitCode: consumptionUnit,
                source: 'estado_ui',
                ...extra
            });
        });
        const uiTroquel = uiState.troquel || {};
        if (uiTroquel.dieCode) {
            addConsumptionMaterial(materials, {
                sapItemCode: uiTroquel.dieCode,
                materialName: pickFirstValue(uiTroquel.dieDescription, `Troquel ${uiTroquel.dieCode}`),
                family: 'troquel',
                plannedQuantity: 1,
                unitCode: 'pz',
                source: 'estado_ui'
            });
        }
    }
    return materials.filter((item) => processAllowsConsumption(processKey, item.materialFamily));
}

function planningMaterialApprovalKey(item = {}) {
    return [
        sanitizeAdminUserText(item.kind || item.sourceType || 'base'),
        sanitizeAdminUserText(item.processKey || item.process_key || ''),
        sanitizeAdminUserText(item.sapItemCode || item.sap_item_code || item.materialCode || ''),
        sanitizeAdminUserText(item.materialName || item.material_name || ''),
        sanitizeAdminUserText(item.materialFamily || item.material_family || '')
    ].join('|');
}

function getPlanningMaterialApprovals(rawData = {}) {
    const control = getOrderPlanningControl(rawData);
    const approvals = rawData?.planning_control?.materialApprovals
        || rawData?.planningControl?.materialApprovals
        || control.materialApprovals
        || {};
    return approvals && typeof approvals === 'object' && !Array.isArray(approvals) ? approvals : {};
}

async function collectPlanningMaterialChecklist(orderRow = {}, processKeys = [], historyRows = []) {
    const raw = orderRow.raw_data || {};
    const approvals = getPlanningMaterialApprovals(raw);
    const rows = [];
    const addRow = (item = {}, sourceType = 'base') => {
        const normalized = {
            sourceType,
            processKey: canonicalProductionFlowKey(item.processKey || item.process_key || ''),
            sapItemCode: sanitizeAdminUserText(item.sapItemCode || item.sap_item_code || item.materialCode || ''),
            materialName: sanitizeAdminUserText(item.materialName || item.material_name || item.itemName || ''),
            materialFamily: normalizeConsumptionFamily(item.materialFamily || item.material_family || item.family || item.materialName || item.material_name),
            plannedQuantity: Number(item.plannedQuantity || item.quantity || 0),
            unitCode: sanitizeAdminUserText(item.unitCode || item.unit_code || ''),
            reason: sanitizeAdminUserText(item.reason || ''),
            requestedBy: sanitizeAdminUserText(item.requestedBy || item.requested_by || ''),
            requestedAt: item.requestedAt || item.requested_at || null,
            sapStatus: sanitizeAdminUserText(item.sapStatus || item.sap_status || ''),
            source: sanitizeAdminUserText(item.source || '')
        };
        if (!normalized.materialName && !normalized.sapItemCode) return;
        normalized.approvalKey = planningMaterialApprovalKey(normalized);
        const approval = approvals[normalized.approvalKey] || {};
        normalized.checked = approval.checked === true;
        normalized.checkedAt = approval.checkedAt || null;
        normalized.checkedBy = approval.checkedBy || '';
        if (rows.some((row) => row.approvalKey === normalized.approvalKey)) return;
        rows.push(normalized);
    };

    for (const processKey of processKeys) {
        const materials = await collectOrderConsumptionMaterials(orderRow, processKey);
        materials.forEach((material) => addRow({ ...material, processKey }, 'base'));
    }
    historyRows.forEach((row) => addRow(row, 'registro'));
    return rows;
}

function normalizePlanningAttachment(item = {}, fallback = {}) {
    const id = item.id ? String(item.id) : '';
    const label = sanitizeAdminUserText(item.file_name || item.fileName || item.label || item.key || fallback.label || 'Adjunto');
    const mimeType = sanitizeAdminUserText(item.mime_type || item.mimeType || '');
    const value = sanitizeAdminUserText(item.value || item.url || '');
    return {
        id,
        label,
        value,
        mimeType,
        notes: sanitizeAdminUserText(item.notes || ''),
        uploadedBy: sanitizeAdminUserText(item.uploaded_by || item.uploadedBy || ''),
        createdAt: item.created_at || item.createdAt || null,
        sizeBytes: Number(item.size_bytes || item.sizeBytes || 0),
        downloadUrl: id ? `/api/adjuntos/${encodeURIComponent(id)}/download` : value,
        isImage: mimeType.startsWith('image/') || /^data:image\//i.test(value)
    };
}

function isPlanningArtworkAttachment(item = {}) {
    const text = [
        item.notes,
        item.label,
        item.value,
        item.mimeType
    ].map((value) => String(value || '').toLowerCase()).join(' ');
    return text.includes('arte_orden') || text.includes('arte') || text.includes('artwork');
}

async function collectPlanningOrderAttachments(orderRow = {}) {
    const raw = orderRow.raw_data || {};
    const quoteCode = orderRow.quote_code || raw.source_quote_code || raw.quote_snapshot?.quote_code || '';
    const lineCodes = new Set([orderRow.line_code, raw.source_line_code].filter(Boolean));
    (Array.isArray(raw.related_lines) ? raw.related_lines : []).forEach((line) => {
        const code = line?.summary?.line_code || line?.detail?.lineCode;
        if (code) lineCodes.add(code);
    });

    const attachments = [];
    (Array.isArray(raw.attachments) ? raw.attachments : []).forEach((item) => {
        attachments.push(normalizePlanningAttachment(item));
    });
    for (const lineCode of lineCodes) {
        const stored = quoteCode && lineCode ? await getStoredAttachments(quoteCode, lineCode) : [];
        stored.forEach((item) => attachments.push(normalizePlanningAttachment(item, { label: lineCode })));
    }
    const seen = new Set();
    return attachments.filter((item) => {
        const key = item.id || `${item.label}|${item.value}|${item.createdAt || ''}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

app.get('/api/reporterias/gerencial', async (req, res) => {
    try {
        await ensurePlanningRoutesForLiveOrders();
        const dateFrom = normalizeReportDate(req.query.dateFrom);
        const dateTo = normalizeReportDate(req.query.dateTo);
        const scopedDateFilter = (alias, field = 'created_at') => {
            const params = [];
            const parts = [];
            if (dateFrom) {
                params.push(dateFrom);
                parts.push(`${alias}.${field} >= $${params.length}::date`);
            }
            if (dateTo) {
                params.push(dateTo);
                parts.push(`${alias}.${field} < ($${params.length}::date + INTERVAL '1 day')`);
            }
            return { where: parts.length ? `WHERE ${parts.join(' AND ')}` : '', params };
        };
        const withCondition = (filter, condition) => ({
            where: filter.where ? `${filter.where} AND ${condition}` : `WHERE ${condition}`,
            params: filter.params
        });
        const quoteFilter = scopedDateFilter('q');
        const orderFilter = scopedDateFilter('o');
        const costFilter = scopedDateFilter('fc');
        const consumptionFilter = scopedDateFilter('pmcr', 'requested_at');
        const yieldFilter = scopedDateFilter('wl');
        const auditFilter = scopedDateFilter('al', 'changed_at');
        const routeFilter = scopedDateFilter('r');
        const routeFilterNew = scopedDateFilter('r', 'creado_en');
        const dieFilter = withCondition(costFilter, `COALESCE(NULLIF(fc.die_code,''), NULLIF(fc.raw_data->>'TROQUEL',''), NULLIF(fc.raw_data->>'CODIGO TROQUEL','')) IS NOT NULL`);
        const inkFilter = withCondition(consumptionFilter, `(LOWER(COALESCE(pmcr.material_family,'')) LIKE '%tinta%' OR LOWER(COALESCE(pmcr.material_name,'')) LIKE '%tinta%' OR LOWER(COALESCE(pmcr.material_name,'')) LIKE '%ink%')`);
        const [
            quotesResult,
            productionResult,
            costsResult,
            consumptionResult,
            yieldResult,
            auditResult,
            quoteTrendResult,
            quoteStatusResult,
            processLoadResult,
            machineLoadResult,
            dieUsageResult,
            inkConsumptionResult,
            materialFamilyResult
        ] = await Promise.all([
            pgQuery(`
                SELECT
                    COUNT(*)::int AS total,
                    COUNT(*) FILTER (WHERE LOWER(COALESCE(status,'')) IN ('aprobada','aprobado','cerrada','cerrado'))::int AS approved,
                    COUNT(*) FILTER (WHERE LOWER(COALESCE(status,'')) IN ('rechazada','rechazado'))::int AS rejected,
                    COUNT(*) FILTER (WHERE COALESCE(status,'') = '')::int AS without_status
                FROM quotes q
                ${quoteFilter.where}
            `, quoteFilter.params),
            pgQuery(`
                SELECT
                    COUNT(*)::int AS total_orders,
                    COUNT(*) FILTER (WHERE EXISTS (
                        SELECT 1 FROM orden_proceso r WHERE r.codigo_orden = o.order_code AND r.estado = 'COMPLETADO'
                    ))::int AS with_completed_process,
                    COUNT(*) FILTER (WHERE EXISTS (
                        SELECT 1 FROM orden_proceso r WHERE r.codigo_orden = o.order_code AND r.estado IN ('EN_MARCHA','PREPARACION','EN_PARO')
                    ))::int AS active_orders
                FROM flexo_orders o
                ${orderFilter.where}
            `, orderFilter.params),
            pgQuery(`
                SELECT
                    COUNT(*)::int AS calculations,
                    COALESCE(SUM(total_cost),0) AS total_cost,
                    COALESCE(AVG(unit_price),0) AS avg_unit_price
                FROM flexo_calculations fc
                ${costFilter.where}
            `, costFilter.params),
            pgQuery(`
                SELECT
                    COUNT(*)::int AS total_requests,
                    COUNT(*) FILTER (WHERE sap_status = 'PENDIENTE')::int AS pending,
                    COUNT(*) FILTER (WHERE sap_status = 'ENVIADO')::int AS sent,
                    COUNT(*) FILTER (WHERE sap_status = 'ERROR')::int AS errors,
                    COALESCE(SUM(quantity),0) AS quantity
                FROM production_material_consumption_requests pmcr
                ${consumptionFilter.where}
            `, consumptionFilter.params),
            pgQuery(`
                SELECT
                    COALESCE(SUM(metros_consumidos),0) AS metros_consumidos,
                    COALESCE(SUM(metros_utiles),0) AS metros_utiles,
                    COALESCE(SUM(merma_setup_metros + merma_tiraje_metros),0) AS merma_metros
                FROM production_waste_logs wl
                ${yieldFilter.where}
            `, yieldFilter.params),
            pgQuery(`
                SELECT
                    module_key,
                    COUNT(*)::int AS total
                FROM audit_log al
                ${auditFilter.where}
                GROUP BY module_key
                ORDER BY total DESC
                LIMIT 10
            `, auditFilter.params),
            pgQuery(`
                SELECT TO_CHAR(q.created_at::date, 'DD/MM') AS label, COUNT(*)::int AS total
                FROM quotes q
                ${quoteFilter.where}
                GROUP BY q.created_at::date
                ORDER BY q.created_at::date DESC
                LIMIT 14
            `, quoteFilter.params),
            pgQuery(`
                SELECT COALESCE(NULLIF(status,''), 'Sin estado') AS label, COUNT(*)::int AS total
                FROM quotes q
                ${quoteFilter.where}
                GROUP BY COALESCE(NULLIF(status,''), 'Sin estado')
                ORDER BY total DESC
                LIMIT 8
            `, quoteFilter.params),
            pgQuery(`
                SELECT r.nombre_proceso AS label, COUNT(*)::int AS orders, COALESCE(SUM(r.duracion_horas),0) AS hours
                FROM orden_proceso r
                ${routeFilterNew.where}
                GROUP BY r.nombre_proceso
                ORDER BY hours DESC, orders DESC
                LIMIT 10
            `, routeFilterNew.params),
            pgQuery(`
                SELECT
                    COALESCE(NULLIF(o.machine_name,''), NULLIF(r.datos_extra->>'sourceMachineName',''), NULLIF(r.datos_extra->>'capacityResourceName',''), r.nombre_proceso, 'Sin máquina') AS label,
                    COUNT(*)::int AS orders,
                    COALESCE(SUM(r.duracion_horas),0) AS hours
                FROM orden_proceso r
                LEFT JOIN flexo_orders o ON o.order_code = r.codigo_orden
                ${routeFilterNew.where}
                GROUP BY COALESCE(NULLIF(o.machine_name,''), NULLIF(r.datos_extra->>'sourceMachineName',''), NULLIF(r.datos_extra->>'capacityResourceName',''), r.nombre_proceso, 'Sin máquina')
                ORDER BY hours DESC, orders DESC
                LIMIT 10
            `, routeFilterNew.params),
            pgQuery(`
                SELECT COALESCE(NULLIF(fc.die_code,''), NULLIF(fc.raw_data->>'TROQUEL',''), NULLIF(fc.raw_data->>'CODIGO TROQUEL',''), 'Sin troquel') AS label,
                       COUNT(*)::int AS total,
                       COALESCE(SUM(fc.total_cost),0) AS cost
                FROM flexo_calculations fc
                ${dieFilter.where}
                GROUP BY COALESCE(NULLIF(fc.die_code,''), NULLIF(fc.raw_data->>'TROQUEL',''), NULLIF(fc.raw_data->>'CODIGO TROQUEL',''), 'Sin troquel')
                ORDER BY total DESC
                LIMIT 10
            `, dieFilter.params),
            pgQuery(`
                SELECT COALESCE(NULLIF(pmcr.material_name,''), 'Tintas') AS label,
                       COALESCE(SUM(pmcr.quantity),0) AS quantity,
                       COUNT(*)::int AS requests
                FROM production_material_consumption_requests pmcr
                ${inkFilter.where}
                GROUP BY COALESCE(NULLIF(pmcr.material_name,''), 'Tintas')
                ORDER BY quantity DESC, requests DESC
                LIMIT 10
            `, inkFilter.params),
            pgQuery(`
                SELECT COALESCE(NULLIF(pmcr.material_family,''), 'Sin familia') AS label,
                       COALESCE(SUM(pmcr.quantity),0) AS quantity,
                       COUNT(*)::int AS requests
                FROM production_material_consumption_requests pmcr
                ${consumptionFilter.where}
                GROUP BY COALESCE(NULLIF(pmcr.material_family,''), 'Sin familia')
                ORDER BY quantity DESC, requests DESC
                LIMIT 10
            `, consumptionFilter.params)
        ]);
        const quoteSummary = quotesResult.rows[0] || {};
        const productionSummary = productionResult.rows[0] || {};
        const costSummary = costsResult.rows[0] || {};
        const consumptionSummary = consumptionResult.rows[0] || {};
        const yieldSummary = yieldResult.rows[0] || {};
        const metrosConsumidos = Number(yieldSummary.metros_consumidos || 0);
        res.json({
            ok: true,
            filters: { dateFrom: dateFrom || '', dateTo: dateTo || '' },
            reports: {
                initial: {
                    quotes: Number(quoteSummary.total || 0),
                    orders: Number(productionSummary.total_orders || 0),
                    activeOrders: Number(productionSummary.active_orders || 0),
                    pendingSapConsumptions: Number(consumptionSummary.pending || 0)
                },
                quotations: quoteSummary,
                production: productionSummary,
                costs: costSummary,
                consumptions: consumptionSummary,
                yields: {
                    ...yieldSummary,
                    yieldPct: metrosConsumidos > 0 ? Number(((Number(yieldSummary.metros_utiles || 0) / metrosConsumidos) * 100).toFixed(2)) : 0
                },
                orderStatus: await buildOrderStatusReport(),
                audit: auditResult.rows || [],
                quoteTrend: (quoteTrendResult.rows || []).reverse(),
                quoteStatus: quoteStatusResult.rows || [],
                processLoad: processLoadResult.rows || [],
                machineLoad: machineLoadResult.rows || [],
                dieUsage: dieUsageResult.rows || [],
                inkConsumption: inkConsumptionResult.rows || [],
                materialFamily: materialFamilyResult.rows || []
            }
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar la reportería gerencial.' });
    }
});

async function buildOrderStatusReport() {
    const result = await pgQuery(`
        SELECT
            clave_proceso AS process_key,
            nombre_proceso AS process_name,
            CASE estado
                WHEN 'EN_MARCHA' THEN 'RUN'
                WHEN 'PREPARACION' THEN 'SETUP'
                WHEN 'EN_PARO' THEN 'PARO'
                ELSE estado
            END AS route_status,
            COUNT(*)::int AS total
        FROM orden_proceso
        GROUP BY clave_proceso, nombre_proceso, estado
        ORDER BY nombre_proceso, route_status
    `);
    return result.rows || [];
}

// Filtros compartidos por los reportes de rentabilidad y materia prima sobre flexo_calculations.
// Devuelve el fragmento WHERE (sin la palabra WHERE) y los parámetros posicionales.
function buildFlexoCalcReportFilter(query) {
    const parts = [];
    const params = [];
    const dateFrom = normalizeReportDate(query.dateFrom);
    const dateTo = normalizeReportDate(query.dateTo);
    if (dateFrom) { params.push(dateFrom); parts.push(`fc.created_at >= $${params.length}::date`); }
    if (dateTo) { params.push(dateTo); parts.push(`fc.created_at < ($${params.length}::date + INTERVAL '1 day')`); }
    const vendedor = String(query.vendedor || '').trim();
    if (vendedor) { params.push(vendedor); parts.push(`LOWER(TRIM(COALESCE(fc.salesperson_name,''))) = LOWER(TRIM($${params.length}))`); }
    const cliente = String(query.cliente || '').trim();
    if (cliente) { params.push(cliente); parts.push(`(LOWER(TRIM(COALESCE(fc.customer_name,''))) = LOWER(TRIM($${params.length})) OR COALESCE(fc.customer_code,'') = $${params.length})`); }
    const producto = String(query.producto || '').trim();
    if (producto) { params.push(producto); parts.push(`COALESCE(fc.product_code,'') = $${params.length}`); }
    return { where: parts.length ? parts.join(' AND ') : 'TRUE', params };
}

const FLEXO_MP_SUM_SQL = `(COALESCE(fc.costo_sustrato,0) + COALESCE(fc.subtotal_tinta,0) + COALESCE(fc.barniz_costo_total,0)
    + COALESCE(fc.laminado_costo_total,0) + COALESCE(fc.embosado_costo_cliche,0) + COALESCE(fc.merma_total_costo,0))`;

app.get('/api/reporterias/rentabilidad', async (req, res) => {
    try {
        const { where, params } = buildFlexoCalcReportFilter(req.query);
        const baseWhere = `fc.subtotal_cost > 0 AND fc.industrial_subtotal > 0 AND (${where})`;
        const [kpiResult, lineasResult, mesResult, costsConfig] = await Promise.all([
            pgQuery(`
                SELECT
                    COUNT(*)::int AS lineas,
                    COALESCE(SUM(fc.subtotal_cost),0) AS venta,
                    COALESCE(SUM(GREATEST(fc.industrial_subtotal, COALESCE(fc.overhead_cost,0))),0) AS costo,
                    COALESCE(SUM(fc.industrial_subtotal),0) AS costo_directo,
                    COALESCE(SUM(fc.subtotal_cost - GREATEST(fc.industrial_subtotal, COALESCE(fc.overhead_cost,0))),0) AS utilidad,
                    COALESCE(SUM(${FLEXO_MP_SUM_SQL}),0) AS materia_prima,
                    COALESCE(SUM(GREATEST(COALESCE(fc.overhead_cost,0) - fc.industrial_subtotal, 0)),0) AS overhead
                FROM flexo_calculations fc
                WHERE ${baseWhere}
            `, params),
            pgQuery(`
                SELECT
                    fc.quote_code, fc.line_code,
                    COALESCE(NULLIF(fc.customer_name,''), fc.customer_code, 'Sin cliente') AS cliente,
                    COALESCE(NULLIF(fc.salesperson_name,''), 'Sin vendedor') AS vendedor,
                    COALESCE(NULLIF(fc.job_name,''), fc.product_code, '') AS trabajo,
                    fc.product_code,
                    fc.quantity,
                    fc.subtotal_cost AS venta,
                    GREATEST(fc.industrial_subtotal, COALESCE(fc.overhead_cost,0)) AS costo,
                    fc.subtotal_cost - GREATEST(fc.industrial_subtotal, COALESCE(fc.overhead_cost,0)) AS utilidad,
                    ${FLEXO_MP_SUM_SQL} AS materia_prima,
                    fc.created_at
                FROM flexo_calculations fc
                WHERE ${baseWhere}
                ORDER BY fc.created_at DESC
                LIMIT 300
            `, params),
            pgQuery(`
                SELECT
                    TO_CHAR(date_trunc('month', fc.created_at), 'YYYY-MM') AS mes,
                    COALESCE(SUM(fc.subtotal_cost),0) AS venta,
                    COALESCE(SUM(GREATEST(fc.industrial_subtotal, COALESCE(fc.overhead_cost,0))),0) AS costo,
                    COALESCE(SUM(fc.subtotal_cost - GREATEST(fc.industrial_subtotal, COALESCE(fc.overhead_cost,0))),0) AS utilidad,
                    COALESCE(SUM(${FLEXO_MP_SUM_SQL}),0) AS materia_prima
                FROM flexo_calculations fc
                WHERE ${baseWhere}
                GROUP BY 1
                ORDER BY 1
            `, params),
            loadCostsConfig()
        ]);
        const materiaPrimaMaximaPct = Number(costsConfig?.general?.materiaPrimaMaximaPct ?? 55);
        const k = kpiResult.rows[0] || {};
        const venta = Number(k.venta || 0);
        const costo = Number(k.costo || 0);
        const utilidad = Number(k.utilidad || 0);
        const materiaPrima = Number(k.materia_prima || 0);
        const costoDirecto = Number(k.costo_directo || 0);
        const pct = (num, den) => (den > 0 ? Number(((num / den) * 100).toFixed(2)) : null);
        const lineas = (lineasResult.rows || []).map((row) => {
            const v = Number(row.venta || 0);
            const c = Number(row.costo || 0);
            const u = Number(row.utilidad || 0);
            const mp = Number(row.materia_prima || 0);
            const qty = Number(row.quantity || 0);
            return {
                quoteCode: row.quote_code,
                lineCode: row.line_code,
                cliente: row.cliente,
                vendedor: row.vendedor,
                trabajo: row.trabajo,
                productCode: row.product_code,
                cantidad: qty,
                venta: v,
                costo: c,
                utilidad: u,
                materiaPrima: mp,
                margenPct: pct(u, v),
                markupPct: pct(u, c),
                materiaPrimaPct: pct(mp, v),
                superaMateriaPrima: v > 0 && ((mp / v) * 100) > materiaPrimaMaximaPct,
                utilidadUnidad: qty > 0 ? Number((u / qty).toFixed(6)) : null,
                fecha: row.created_at
            };
        });
        const rankeables = lineas.filter((row) => row.margenPct !== null);
        res.json({
            ok: true,
            filtros: {
                dateFrom: normalizeReportDate(req.query.dateFrom) || '',
                dateTo: normalizeReportDate(req.query.dateTo) || '',
                vendedor: String(req.query.vendedor || ''),
                cliente: String(req.query.cliente || ''),
                producto: String(req.query.producto || '')
            },
            kpis: {
                lineas: Number(k.lineas || 0),
                venta,
                costo,
                utilidad,
                materiaPrima,
                overhead: Number(k.overhead || 0),
                margenPct: pct(utilidad, venta),
                markupPct: pct(utilidad, costo),
                materiaPrimaPct: pct(materiaPrima, venta),
                costoConversionPct: pct(costoDirecto - materiaPrima, venta),
                costoDirecto,
                materiaPrimaMaximaPct
            },
            lineas,
            porMes: (mesResult.rows || []).map((row) => ({
                mes: row.mes,
                venta: Number(row.venta || 0),
                costo: Number(row.costo || 0),
                utilidad: Number(row.utilidad || 0),
                margenPct: pct(Number(row.utilidad || 0), Number(row.venta || 0)),
                materiaPrimaPct: pct(Number(row.materia_prima || 0), Number(row.venta || 0)),
                superaMateriaPrima: Number(row.venta || 0) > 0 && ((Number(row.materia_prima || 0) / Number(row.venta || 0)) * 100) > materiaPrimaMaximaPct
            })),
            rankingTop: [...rankeables].sort((a, b) => b.margenPct - a.margenPct).slice(0, 10),
            rankingBottom: [...rankeables].sort((a, b) => a.margenPct - b.margenPct).slice(0, 10)
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el reporte de rentabilidad.' });
    }
});

app.get('/api/reporterias/materia-prima', async (req, res) => {
    try {
        const { where, params } = buildFlexoCalcReportFilter(req.query);
        const baseWhere = `fc.subtotal_cost > 0 AND (${where})`;
        const [totalResult, productoResult, mesResult, costsConfig] = await Promise.all([
            pgQuery(`
                SELECT
                    COUNT(*)::int AS lineas,
                    COALESCE(SUM(fc.subtotal_cost),0) AS venta,
                    COALESCE(SUM(fc.costo_sustrato),0) AS sustrato,
                    COALESCE(SUM(fc.subtotal_tinta),0) AS tintas,
                    COALESCE(SUM(fc.barniz_costo_total),0) AS barniz,
                    COALESCE(SUM(fc.laminado_costo_total),0) AS laminado,
                    COALESCE(SUM(fc.embosado_costo_cliche),0) AS estampado,
                    COALESCE(SUM(fc.merma_total_costo),0) AS merma,
                    COALESCE(SUM(${FLEXO_MP_SUM_SQL}),0) AS materia_prima
                FROM flexo_calculations fc
                WHERE ${baseWhere}
            `, params),
            pgQuery(`
                SELECT
                    COALESCE(NULLIF(fc.product_code,''), 'Sin producto') AS producto,
                    COALESCE(MAX(NULLIF(fc.job_name,'')), '') AS nombre,
                    COUNT(*)::int AS lineas,
                    COALESCE(SUM(fc.subtotal_cost),0) AS venta,
                    COALESCE(SUM(${FLEXO_MP_SUM_SQL}),0) AS materia_prima
                FROM flexo_calculations fc
                WHERE ${baseWhere}
                GROUP BY 1
                ORDER BY materia_prima DESC
                LIMIT 20
            `, params),
            pgQuery(`
                SELECT
                    TO_CHAR(date_trunc('month', fc.created_at), 'YYYY-MM') AS mes,
                    COALESCE(SUM(fc.subtotal_cost),0) AS venta,
                    COALESCE(SUM(${FLEXO_MP_SUM_SQL}),0) AS materia_prima
                FROM flexo_calculations fc
                WHERE ${baseWhere}
                GROUP BY 1
                ORDER BY 1
            `, params),
            loadCostsConfig()
        ]);
        const t = totalResult.rows[0] || {};
        const venta = Number(t.venta || 0);
        const pct = (num) => (venta > 0 ? Number(((Number(num || 0) / venta) * 100).toFixed(2)) : null);
        const componentes = [
            { clave: 'sustrato', label: 'Sustrato', monto: Number(t.sustrato || 0) },
            { clave: 'tintas', label: 'Tintas', monto: Number(t.tintas || 0) },
            { clave: 'barniz', label: 'Barniz', monto: Number(t.barniz || 0) },
            { clave: 'laminado', label: 'Laminado', monto: Number(t.laminado || 0) },
            { clave: 'estampado', label: 'Estampado', monto: Number(t.estampado || 0) },
            { clave: 'merma', label: 'Merma', monto: Number(t.merma || 0) }
        ].map((row) => ({ ...row, pct: pct(row.monto) }));
        res.json({
            ok: true,
            filtros: {
                dateFrom: normalizeReportDate(req.query.dateFrom) || '',
                dateTo: normalizeReportDate(req.query.dateTo) || '',
                vendedor: String(req.query.vendedor || ''),
                cliente: String(req.query.cliente || ''),
                producto: String(req.query.producto || '')
            },
            kpis: {
                lineas: Number(t.lineas || 0),
                venta,
                materiaPrima: Number(t.materia_prima || 0),
                materiaPrimaPct: pct(t.materia_prima),
                materiaPrimaMaximaPct: Number(costsConfig?.general?.materiaPrimaMaximaPct ?? 55)
            },
            componentes,
            porProducto: (productoResult.rows || []).map((row) => ({
                producto: row.producto,
                nombre: row.nombre || '',
                lineas: Number(row.lineas || 0),
                venta: Number(row.venta || 0),
                materiaPrima: Number(row.materia_prima || 0),
                materiaPrimaPct: Number(row.venta || 0) > 0 ? Number(((Number(row.materia_prima || 0) / Number(row.venta || 0)) * 100).toFixed(2)) : null
            })),
            porMes: (mesResult.rows || []).map((row) => ({
                mes: row.mes,
                venta: Number(row.venta || 0),
                materiaPrima: Number(row.materia_prima || 0),
                materiaPrimaPct: Number(row.venta || 0) > 0 ? Number(((Number(row.materia_prima || 0) / Number(row.venta || 0)) * 100).toFixed(2)) : null
            }))
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el reporte de materia prima.' });
    }
});

// Procesos con actividad en vivo ahora mismo (SETUP/RUN/PARO) para el indicador parpadeante
// verde de las tarjetas de proceso (igual al "En curso" de produccion.html) — quién trabaja,
// desde cuándo, en qué máquina. Endpoint aparte y liviano (no reutiliza /seguimiento) para no
// tocar esa agregación ya compleja.
app.get('/api/ordenes-produccion/:codigo/procesos-en-vivo', async (req, res) => {
    try {
        const result = await pgQuery(
            `SELECT r.clave_proceso, r.estado, r.fecha_real_inicio,
                    COALESCE(r.nombre_maquina, '') AS machine_name,
                    ev.operator_name
               FROM vista_orden_proceso r
          LEFT JOIN LATERAL (
                    SELECT operator_name FROM production_route_events
                     WHERE orden_proceso_id = r.id
                     ORDER BY created_at DESC LIMIT 1
               ) ev ON TRUE
              WHERE r.codigo_orden = $1 AND r.estado IN ('PREPARACION', 'EN_MARCHA', 'EN_PARO')`,
            [req.params.codigo]
        );
        res.json({
            ok: true,
            procesos: result.rows.map((row) => ({
                processKey: canonicalProductionFlowKey(row.clave_proceso),
                routeStatus: SEGUIMIENTO_ESTADO_API[row.estado] || row.estado,
                actualStartAt: row.fecha_real_inicio,
                machineName: row.machine_name || '',
                operatorName: row.operator_name || ''
            }))
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar los procesos en vivo.' });
    }
});

