async function enviarProductoTerminadoSap(orderCode, { cantidad, dryRun = false } = {}) {
    const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
    if (!orderResult.rows.length) throw new Error('Orden no encontrada.');
    const order = orderResult.rows[0];
    if (order.sap_producto_terminado_doc_entry && !dryRun) {
        const err = new Error(`Esta orden ya tiene una entrada de Producto Terminado en SAP: ${order.sap_producto_terminado_doc_entry}.`);
        err.yaExistia = true; err.docEntry = order.sap_producto_terminado_doc_entry;
        throw err;
    }
    const cant = Number(cantidad || order.produced_quantity || order.ordered_quantity || 0);
    if (!(cant > 0) && !dryRun) throw new Error('Debes indicar la cantidad producida.');
    const itemCode = order.finished_product_sku || order.product_code;
    if (!itemCode) throw new Error('La orden no tiene un código de producto terminado (SKU) definido.');

    const sapConfig = await loadSapConfig(pgQuery);
    const response = await createInventoryEntry({
        pgQuery, config: sapConfig, dryRun,
        body: { comments: `Producto Terminado - ${order.order_code}`, items: [{ itemCode, quantity: cant || 0 }] }
    });
    if (dryRun) return { preview: response };
    const docEntry = String(response?.DocEntry ?? response?.docEntry ?? '');
    if (docEntry) {
        await pgQuery(`UPDATE flexo_orders SET sap_producto_terminado_doc_entry = $2 WHERE order_code = $1`, [order.order_code, docEntry]);
        // Paso 5: producto terminado listo. Deja la factura preparada. Si el modo
        // automático está activo, se encola de una vez; si no, queda el aviso
        // "confirmar factura" en la orden (sección Estado en SAP).
        if (!order.sap_factura_doc_entry) {
            if (sapConfig.sapFacturaAutomatica) {
                await pgQuery(`UPDATE flexo_orders SET sap_factura_confirmacion = 'AUTOMATICA' WHERE order_code = $1`, [order.order_code]);
                try { await encolarEnvioSap(pgQuery, { tipo: 'factura', referencia: order.order_code, creadoPor: 'automatico' }); } catch (_) {}
            } else {
                await pgQuery(`UPDATE flexo_orders SET sap_factura_confirmacion = 'PENDIENTE' WHERE order_code = $1`, [order.order_code]);
            }
        }
    }
    return { docEntry, response };
}

async function enviarFacturaSap(orderCode, { dryRun = false } = {}) {
    const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
    if (!orderResult.rows.length) throw new Error('Orden no encontrada.');
    const order = orderResult.rows[0];
    if (order.sap_factura_doc_entry && !dryRun) {
        const err = new Error(`Esta orden ya tiene una Factura en SAP: ${order.sap_factura_doc_entry}.`);
        err.yaExistia = true; err.docEntry = order.sap_factura_doc_entry;
        throw err;
    }
    if (!order.sap_orden_venta_doc_entry && !dryRun) {
        throw new Error('Esta orden todavía no tiene una Orden de Venta en SAP. Envíala primero.');
    }
    const sapConfig = await loadSapConfig(pgQuery);
    const response = await createInvoice({
        pgQuery, config: sapConfig, dryRun,
        body: { docEntry: Number(order.sap_orden_venta_doc_entry) || 0, baseLine: 0, orderCode: order.order_code }
    });
    if (dryRun) return { preview: response };
    const docEntry = String(response?.DocEntry ?? response?.docEntry ?? '');
    if (docEntry) {
        await pgQuery(
            `UPDATE flexo_orders SET sap_factura_doc_entry = $2, sap_factura_confirmacion = 'CONFIRMADA' WHERE order_code = $1`,
            [order.order_code, docEntry]
        );
    }
    return { docEntry, response };
}

// Intenta el envío directo; si falla (y no es "ya existía"), lo deja en la cola
// sap_envios_pendientes para que el worker reintente y quede visible en Envíos.
async function enviarSapConRespaldoEnCola({ tipo, referencia, payload = {}, creadoPor = '', ejecutar }) {
    try {
        return await ejecutar();
    } catch (error) {
        if (!error.yaExistia) {
            try { await encolarEnvioSap(pgQuery, { tipo, referencia, payload, creadoPor }); } catch (_) {}
        }
        throw error;
    }
}

