// ── Sección "Estado en SAP" de la orden: estado por documento, reintento por
// documento y consulta en vivo contra la bandeja del conector (sap_outbox).
const SAP_DOCS_ORDEN = [
    { tipo: 'articulo', etiqueta: 'Artículo Terminado', columna: 'sap_articulo_creado', outbox: 'item' },
    { tipo: 'orden_venta', etiqueta: 'Orden de Venta', columna: 'sap_orden_venta_doc_entry', outbox: 'sales-order' },
    { tipo: 'bom', etiqueta: 'Lista de Materiales', columna: 'sap_bom_creado', outbox: 'product-tree' },
    { tipo: 'orden_produccion', etiqueta: 'Orden de Producción', columna: 'sap_orden_produccion_doc_entry', outbox: 'production-order' },
    { tipo: 'salida_materiales', etiqueta: 'Salida de Materiales', columna: 'sap_salida_materiales_doc_entry', outbox: 'inventory-exit' },
    { tipo: 'producto_terminado', etiqueta: 'Entrada de Producto Terminado', columna: 'sap_producto_terminado_doc_entry', outbox: 'inventory-entry' },
    { tipo: 'factura', etiqueta: 'Factura', columna: 'sap_factura_doc_entry', outbox: 'invoice' }
];

async function construirEstadoSapOrden(orderCode) {
    const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
    if (!orderResult.rows.length) return null;
    const order = orderResult.rows[0];
    const envios = await listarEnviosSap(pgQuery, { referencia: orderCode, limit: 200 });
    const enviosPorTipo = {};
    for (const e of envios) {
        if (!enviosPorTipo[e.tipo]) enviosPorTipo[e.tipo] = e;
    }
    const documentos = SAP_DOCS_ORDEN.map((def) => {
        const valor = order[def.columna];
        const envio = enviosPorTipo[def.tipo] || null;
        let estado = 'no_iniciado';
        if (valor) estado = 'creado';
        else if (envio && envio.estado === 'fallido') estado = 'fallido';
        else if (envio && ['pendiente', 'procesando'].includes(envio.estado)) estado = 'en_cola';
        else if (envio && envio.estado === 'enviado') estado = 'creado';
        return {
            tipo: def.tipo,
            etiqueta: def.etiqueta,
            estado,
            docEntry: valor || '',
            intentos: envio ? envio.intentos : 0,
            ultimoError: envio ? (envio.ultimo_error || '') : '',
            claseError: envio ? (envio.ultimo_error_clase || '') : '',
            envioId: envio ? envio.id : null,
            actualizadoEn: envio ? envio.actualizado_en : null
        };
    });
    return {
        orderCode,
        facturaConfirmacion: order.sap_factura_confirmacion || '',
        avisoFactura: order.sap_producto_terminado_doc_entry && !order.sap_factura_doc_entry
            && (order.sap_factura_confirmacion || '') === 'PENDIENTE',
        documentos
    };
}

