app.post('/api/ordenes-produccion/:codigo/seguimiento/marca', async (req, res) => {
    try {
        const codigo = req.params.codigo;
        const processKey = normalizeOrderTrackingStepKey(req.body?.processKey);
        const marked = req.body?.marked !== false;
        if (!processKey) return res.status(400).json({ ok: false, error: 'Se requiere processKey.' });

        const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [codigo]);
        if (!orderResult.rows.length) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });

        const rawData = orderResult.rows[0].raw_data || {};
        const actor = getRequestUserName(req);
        const actorPhoto = getRequestUserPhotoUrl(req);
        const now = new Date().toISOString();

        if (marked) {
            const gateError = await verifyOrderTrackingStepGate(codigo, processKey, rawData);
            if (gateError) return res.status(400).json({ ok: false, error: gateError });
            if (processKey === 'empaque') {
                try {
                    await crearLoteFromEmpaqueMark(orderResult.rows[0], req.body?.loteData, req);
                } catch (loteError) {
                    return res.status(loteError.status || 500).json({ ok: false, error: loteError.message || 'No fue posible crear el lote de producto terminado.' });
                }
            }
        }

        let nextRawData = rawData;
        if (processKey === 'solicitud_vendedor') {
            nextRawData = withUpdatedOrderPlanningControl(nextRawData, marked ? {
                salesReleased: true,
                salesReleasedAt: now,
                salesReleasedBy: actor,
                planningStatus: 'PENDIENTE_PLANIFICACION',
                launchedToGantt: false,
                launchedAt: null,
                launchedBy: '',
                returnedAt: null,
                returnedBy: '',
                returnReason: ''
            } : {
                salesReleased: false,
                salesReleasedAt: null,
                salesReleasedBy: '',
                planningStatus: 'PENDIENTE_VENTAS',
                launchedToGantt: false,
                launchedAt: null,
                launchedBy: ''
            });
        } else if (processKey === 'planeacion') {
            const control = getOrderPlanningControl(nextRawData);
            nextRawData = withUpdatedOrderPlanningControl(nextRawData, marked ? {
                salesReleased: true,
                planningStatus: 'EN_GANTT',
                launchedToGantt: true,
                launchedAt: now,
                launchedBy: actor,
                returnReason: ''
            } : {
                salesReleased: true,
                planningStatus: control.salesReleased ? 'PENDIENTE_PLANIFICACION' : 'PENDIENTE_VENTAS',
                launchedToGantt: false,
                launchedAt: null,
                launchedBy: ''
            });
        }

        if (nextRawData !== rawData) {
            await pgQuery(`UPDATE flexo_orders SET raw_data = $2::jsonb WHERE order_code = $1`, [codigo, JSON.stringify(nextRawData)]);
        }
        // Modelo nuevo: pasos sintéticos → orden_planificacion; procesos reales →
        // cambiarEstadoProceso (que ya hace estado + evento + espejo + marcas).
        if (processKey === 'solicitud_vendedor') {
            await pgQuery(`UPDATE orden_planificacion SET liberado_ventas = $2, liberado_ventas_en = CASE WHEN $2 THEN NOW() ELSE NULL END, liberado_ventas_por = $3, estado_planificacion = CASE WHEN $2 THEN 'PENDIENTE_PLANIFICACION' ELSE 'PENDIENTE_VENTAS' END, actualizado_en = NOW() WHERE codigo_orden = $1`, [codigo, marked, actor]).catch(() => null);
        } else if (processKey === 'planeacion') {
            await pgQuery(`UPDATE orden_planificacion SET lanzado_gantt = $2, lanzado_gantt_en = CASE WHEN $2 THEN NOW() ELSE NULL END, lanzado_gantt_por = $3, estado_planificacion = CASE WHEN $2 THEN 'EN_GANTT' ELSE 'PENDIENTE_PLANIFICACION' END, actualizado_en = NOW() WHERE codigo_orden = $1`, [codigo, marked, actor]).catch(() => null);
            if (marked) await autoCompleteDesignIfNotQuoted(codigo, actor);
        } else {
            try {
                await cambiarEstadoProceso(codigo, marked ? 'COMPLETADO' : 'PENDIENTE', { actor, codigoOrden: codigo, claveProceso: processKey, permitirReapertura: !marked });
            } catch (stepError) {
                return res.status(stepError.statusCode || 400).json({ ok: false, error: stepError.message || 'No fue posible actualizar la marca.' });
            }
        }
        res.json({ ok: true, processKey, marked });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible actualizar la marca.' });
    }
});

app.post('/api/ordenes-produccion/:codigo/seguimiento/completar', async (req, res) => {
    try {
        const codigo = req.params.codigo;
        const processKey = String(req.body?.processKey || '').trim();
        const notes = String(req.body?.notes || '').trim();
        if (!processKey) return res.status(400).json({ ok: false, error: 'Se requiere processKey.' });

        // Map special process keys to planning actions
        if (processKey === 'solicitud_vendedor') {
            // Trigger release-sales
            const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [codigo]);
            if (!orderResult.rows.length) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });
            const rawData = orderResult.rows[0].raw_data || {};
            const actor = getRequestUserName(req);
            const nextRawData = withUpdatedOrderPlanningControl(rawData, {
                salesReleased: true,
                salesReleasedAt: new Date().toISOString(),
                salesReleasedBy: actor,
                planningStatus: 'PENDIENTE_PLANIFICACION',
                launchedToGantt: false,
                launchedAt: null, launchedBy: '',
                returnedAt: null, returnedBy: '', returnReason: ''
            });
            await pgQuery(`UPDATE flexo_orders SET raw_data = $2::jsonb WHERE order_code = $1`, [codigo, JSON.stringify(nextRawData)]);
            await pgQuery(`UPDATE orden_planificacion SET liberado_ventas = true, liberado_ventas_en = NOW(), liberado_ventas_por = $2, estado_planificacion = 'PENDIENTE_PLANIFICACION', actualizado_en = NOW() WHERE codigo_orden = $1`, [codigo, actor]).catch(() => null);
            syncOrderProductionTimingSummary(codigo).catch(() => null);
            return res.json({ ok: true, message: 'Solicitud registrada. Orden enviada a planificación.', processKey });
        }

        if (processKey === 'planeacion') {
            // Trigger launch-gantt
            const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [codigo]);
            if (!orderResult.rows.length) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });
            const rawData = orderResult.rows[0].raw_data || {};
            const control = getOrderPlanningControl(rawData);
            if (control.planningStatus !== 'PENDIENTE_PLANIFICACION' && control.planningStatus !== 'EN_GANTT') {
                return res.status(400).json({ ok: false, error: 'La orden debe estar pendiente de planificación.' });
            }
            const actor = getRequestUserName(req);
            const nextRawData = withUpdatedOrderPlanningControl(rawData, {
                salesReleased: true, planningStatus: 'EN_GANTT',
                launchedToGantt: true, launchedAt: new Date().toISOString(), launchedBy: actor,
                returnReason: ''
            });
            await pgQuery(`UPDATE flexo_orders SET raw_data = $2::jsonb WHERE order_code = $1`, [codigo, JSON.stringify(nextRawData)]);
            await pgQuery(`UPDATE orden_planificacion SET lanzado_gantt = true, lanzado_gantt_en = NOW(), lanzado_gantt_por = $2, estado_planificacion = 'EN_GANTT', actualizado_en = NOW() WHERE codigo_orden = $1`, [codigo, actor]).catch(() => null);
            const refreshedOrder = { ...orderResult.rows[0], raw_data: nextRawData };
            try { await ensurePlanningRoutesForOrder(refreshedOrder, null, { replaceExisting: true }); } catch (e) { /* non-critical */ }
            await autoCompleteDesignIfNotQuoted(codigo, actor);
            syncOrderProductionTimingSummary(codigo).catch(() => null);
            // Paso 3 del correo: al liberar planificación se encolan la Lista de
            // Materiales (OITT), la Orden de Producción (OWOR) y la Salida de
            // Materiales (IGE1). El worker reintenta si aún faltan materiales verificados.
            try {
                await encolarEnvioSap(pgQuery, { tipo: 'bom', referencia: codigo, creadoPor: actor });
                await encolarEnvioSap(pgQuery, { tipo: 'orden_produccion', referencia: codigo, creadoPor: actor });
                await encolarEnvioSap(pgQuery, { tipo: 'salida_materiales', referencia: codigo, creadoPor: actor });
            } catch (sapQueueError) {
                console.error('No fue posible encolar los envíos SAP de planificación:', sapQueueError.message);
            }
            return res.json({ ok: true, message: 'Orden lanzada a Gantt.', processKey });
        }

        // Generic route step completion — record event on matching route
        const canonicalKey = canonicalProductionFlowKey(processKey) || processKey;
        const orderResult = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [codigo]);
        if (!orderResult.rows.length) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });
        const gateError = await verifyOrderTrackingStepGate(codigo, canonicalKey, orderResult.rows[0].raw_data || {});
        if (gateError) return res.status(400).json({ ok: false, error: gateError });
        if (canonicalKey === 'empaque') {
            try {
                await crearLoteFromEmpaqueMark(orderResult.rows[0], req.body?.loteData, req);
            } catch (loteError) {
                return res.status(loteError.status || 500).json({ ok: false, error: loteError.message || 'No fue posible crear el lote de producto terminado.' });
            }
        }
        const routeResult = await pgQuery(
            `SELECT id FROM orden_proceso WHERE codigo_orden = $1 AND clave_proceso = $2 ORDER BY secuencia LIMIT 1`,
            [codigo, canonicalKey]
        );
        if (!routeResult.rows.length) {
            return res.status(404).json({ ok: false, error: `No existe una ruta de producción para el proceso "${canonicalKey}" en esta orden.` });
        }
        {
            const routeId = routeResult.rows[0].id;
            const actor = getRequestUserName(req);
            // cambiarEstadoProceso hace: estado + fecha_real_fin + evento + espejo
            // (production_order_routes.route_status) + order_tracking_marks.
            try {
                await cambiarEstadoProceso(routeId, 'COMPLETADO', { actor, motivo: notes, permitirReapertura: true });
            } catch (stepError) {
                return res.status(stepError.statusCode || 400).json({ ok: false, error: stepError.message || 'No fue posible completar el paso.' });
            }

            // Artes reales capturados al completar Diseño/Preprensa — varios por
            // proceso, con imagen de referencia (redimensionada, no archivo final).
            if (canonicalKey === 'diseno' || canonicalKey === 'preprensa') {
                const artesInput = Array.isArray(req.body?.artes) ? req.body.artes : [];
                for (const arte of artesInput) {
                    const nombreArte = sanitizeAdminUserText(arte?.nombre || '');
                    if (!nombreArte && !arte?.imagenBase64) continue;
                    let imagenUrl = null;
                    if (arte?.imagenBase64) {
                        try { imagenUrl = await guardarImagenArte(arte.imagenBase64, codigo); } catch (e) { /* imagen opcional */ }
                    }
                    await pgQuery(
                        `INSERT INTO produccion_artes (orden_codigo, ruta_id, proceso_clave, nombre_arte, imagen_url, creado_por)
                         VALUES ($1, $2, $3, $4, $5, $6)`,
                        [codigo, routeId, canonicalKey, nombreArte || null, imagenUrl, actor]
                    );
                }
            }
        }
        syncOrderProductionTimingSummary(codigo).catch(() => null);
        res.json({ ok: true, message: 'Paso completado.', processKey: canonicalKey });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible completar el paso.' });
    }
});

app.post('/api/ordenes-produccion/:codigo/seguimiento/vb-revert', async (req, res) => {
    try {
        const codigo = req.params.codigo;
        const targetKey = String(req.body?.targetKey || '').trim();
        const reason = String(req.body?.reason || '').trim();
        if (!targetKey || !reason) return res.status(400).json({ ok: false, error: 'Se requiere targetKey y motivo.' });

        // Find and reset the target route
        const canonicalTargetKey = canonicalProductionFlowKey(targetKey) || targetKey;
        const routeResult = await pgQuery(
            `SELECT id FROM orden_proceso WHERE codigo_orden = $1 AND clave_proceso = $2 ORDER BY secuencia LIMIT 1`,
            [codigo, canonicalTargetKey]
        );
        if (!routeResult.rows.length) {
            return res.status(404).json({ ok: false, error: `No existe una ruta de producción para el proceso "${canonicalTargetKey}" en esta orden.` });
        }
        {
            const routeId = routeResult.rows[0].id;
            await cambiarEstadoProceso(routeId, 'PENDIENTE', {
                actor: getRequestUserName(req),
                motivo: 'VB solicitó correcciones: ' + reason,
                permitirReapertura: true
            }).catch(() => null);
        }
        syncOrderProductionTimingSummary(codigo).catch(() => null);
        res.json({ ok: true, message: 'Paso revertido para correcciones.' });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible revertir el paso.' });
    }
});

app.delete('/api/ordenes-produccion/:codigo', async (req, res) => {
    try {
        const codigo = String(req.params.codigo || '').trim();
        if (!codigo) {
            return res.status(400).json({ error: 'Código de orden inválido.' });
        }
        const existing = await pgQuery(`SELECT id FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [codigo]);
        if (!existing.rows.length) {
            return res.status(404).json({ error: 'Orden no encontrada.' });
        }
        await pgQuery(`DELETE FROM flexo_orders WHERE order_code = $1`, [codigo]);
        res.json({ ok: true, orderCode: codigo });
    } catch (error) {
        const status = Number(error.statusCode) || (/no encontrada/i.test(error.message || '') ? 404 : 400);
        res.status(status).json({ error: error.message || 'No fue posible eliminar la orden.' });
    }
});

app.get('/api/mes/contexto', async (req, res) => {
    try {
        await ensurePlanningRoutesForLiveOrders();
        const area = String(req.query.area || 'operario').trim().toLowerCase();
        const routeId = String(req.query.routeId || '').trim();
        const orderCode = String(req.query.orderCode || '').trim();
        const processFilter = canonicalProductionFlowKey(req.query.process || '');
        const plateKeys = ['sellos', 'preprensa', 'diseno', 'visto_bueno'];
        const targetPlateArea = area === 'sellos';
        const productionPriority = ['tintas', 'impresion', 'acabados', 'rebobinado', 'empaque'];
        const platePriority = ['diseno', 'preprensa', 'visto_bueno', 'sellos'];
        const filters = [];
        const values = [];

        if (routeId) {
            values.push(routeId);
            filters.push(`vp.id = $${values.length}::uuid`);
        } else if (orderCode) {
            values.push(orderCode);
            filters.push(`vp.codigo_orden = $${values.length}`);
        }

        if (targetPlateArea) {
            values.push(plateKeys);
            filters.push(`vp.clave_proceso = ANY($${values.length}::text[])`);
        } else {
            values.push(plateKeys);
            filters.push(`NOT (vp.clave_proceso = ANY($${values.length}::text[]))`);
        }
        if (processFilter) {
            const aliases = processFilter === 'acabados'
                ? ['acabados', 'barnizado', 'laminado', 'estampado', 'embosado', 'troquelado', 'numeracion']
                : [processFilter];
            values.push(aliases);
            filters.push(`vp.clave_proceso = ANY($${values.length}::text[])`);
        }
        filters.push(`vp.estado <> 'COMPLETADO'`);
        filters.push(`(vp.depende_de_id IS NULL OR vp.estado_dependencia = 'COMPLETADO')`);
        filters.push(`COALESCE(op.lanzado_gantt, FALSE) = TRUE`);

        const whereClause = filters.length ? `WHERE ${filters.join(' AND ')}` : '';
        const priorityList = targetPlateArea ? platePriority : productionPriority;
        const priorityCase = priorityList
            .map((key, index) => `WHEN '${key}' THEN ${index}`)
            .join(' ');
        const routeResult = await pgQuery(`
            SELECT
                vp.id::text AS route_id,
                vp.datos_extra->>'migrado_de_route_id' AS legacy_route_id,
                vp.codigo_orden AS order_code,
                vp.codigo_cotizacion AS quote_code,
                vp.codigo_linea AS line_code,
                vp.clave_proceso AS process_key,
                vp.nombre_proceso AS process_name,
                vp.estado,
                vp.secuencia AS sequence_order,
                vp.transicion_min AS transition_cost_min,
                vp.duracion_horas AS duration_hours,
                vp.fecha_real_inicio AS actual_start_at,
                vp.fecha_real_fin AS actual_end_at,
                mp.id::text AS machine_profile_id,
                mp.machine_name,
                mp.velocidad_nominal_m_min,
                mp.oee_target,
                mp.setup_minutes,
                mp.hourly_machine_cost,
                mp.hourly_operator_cost,
                o.material_code,
                o.die_code,
                o.ordered_quantity,
                o.machine_name AS quoted_machine_name,
                o.raw_data,
                o.created_at AS order_created_at
            FROM vista_orden_proceso vp
            JOIN flexo_orders o ON o.order_code = vp.codigo_orden
            LEFT JOIN orden_planificacion op ON op.codigo_orden = vp.codigo_orden
            LEFT JOIN production_machine_profiles mp ON mp.id = vp.perfil_maquina_id
            ${whereClause}
            ORDER BY
                CASE lower(coalesce(vp.clave_proceso, ''))
                    ${priorityCase}
                    ELSE 99
                END,
                CASE
                    WHEN coalesce(mp.machine_name, '') <> '' OR coalesce(o.machine_name, '') <> '' THEN 0
                    ELSE 1
                END,
                CASE vp.estado
                    WHEN 'EN_MARCHA' THEN 0
                    WHEN 'PREPARACION' THEN 1
                    WHEN 'EN_PARO' THEN 2
                    WHEN 'PENDIENTE' THEN 3
                    WHEN 'COMPLETADO' THEN 4
                    ELSE 5
                END,
                vp.actualizado_en DESC,
                vp.codigo_orden,
                vp.secuencia
            LIMIT 1
        `, values);

        const route = routeResult.rows[0];
        if (!route) {
            return res.status(404).json({ ok: false, error: 'No se encontró una ruta activa para el MES solicitado.' });
        }

        // Bitácora y merma ligadas por orden_proceso_id.
        const procesoId = route.route_id;
        const [eventsResult, wasteResult, specsResult] = await Promise.all([
            pgQuery(`
                SELECT
                    e.id::text AS id,
                    e.orden_proceso_id::text AS route_id,
                    e.operator_name,
                    e.event_type,
                    e.notes,
                    e.created_at,
                    sr.id::text AS stop_reason_id,
                    sr.reason_group,
                    sr.reason_code,
                    sr.description AS stop_reason_description
                FROM production_route_events e
                LEFT JOIN production_stop_reasons sr ON sr.id = e.stop_reason_id
                WHERE e.orden_proceso_id = $1::uuid
                ORDER BY e.created_at DESC
                LIMIT 50
            `, [procesoId]),
            pgQuery(`
                SELECT
                    id::text AS id,
                    orden_proceso_id::text AS route_id,
                    metros_consumidos,
                    merma_setup_metros,
                    merma_tiraje_metros,
                    metros_utiles,
                    velocidad_final_m_min,
                    anilox_line,
                    cylinder_pressure,
                    notes,
                    created_at
                FROM production_waste_logs
                WHERE orden_proceso_id = $1::uuid
                ORDER BY created_at DESC
                LIMIT 1
            `, [procesoId]),
            route.machine_profile_id ? pgQuery(`
                SELECT spec_group, spec_key, spec_value
                FROM production_machine_specs
                WHERE machine_profile_id = $1::uuid
            `, [route.machine_profile_id]) : { rows: [] }
        ]);

        const raw = route.raw_data || {};
        const lineSummary = raw.line_summary || {};
        const lineSnapshot = raw.line_snapshot || {};
        const customerName = raw.customer_name || '';
        const productName = lineSummary.job_name || lineSummary.product_name || route.order_code;
        const tintCount = Number(lineSnapshot.pantoneCount || lineSnapshot.tintCount || 0);
        const materialFeet = Number(lineSnapshot.materialFeet || route.ordered_quantity || 0);

        const firstSetup = eventsResult.rows.find((event) => String(event.event_type || '').toLowerCase() === 'setup');
        const firstRun = eventsResult.rows.find((event) => String(event.event_type || '').toLowerCase() === 'run');
        const firstCompleted = eventsResult.rows.find((event) => String(event.event_type || '').toLowerCase() === 'completado');

        res.json({
            ok: true,
            data: {
                routeId: route.route_id,
                orderCode: route.order_code,
                quoteCode: route.quote_code || '',
                lineCode: route.line_code || '',
                processKey: route.process_key,
                processName: route.process_name,
                routeStatus: SEGUIMIENTO_ESTADO_API[route.estado] || 'PENDIENTE',
                sequenceOrder: route.sequence_order,
                customerName,
                productName,
                tintCount,
                plannedFeet: materialFeet,
                materialCode: route.material_code || '',
                dieCode: route.die_code || '',
                machineName: route.machine_name || route.quoted_machine_name || '',
                velocidad_nominal_m_min: Number(route.velocidad_nominal_m_min || 0),
                oeeTarget: Number(route.oee_target || 0),
                setupMinutes: Number(route.setup_minutes || 0),
                hourlyMachineCost: Number(route.hourly_machine_cost || 0),
                hourlyOperatorCost: Number(route.hourly_operator_cost || 0),
                machineProfileId: route.machine_profile_id || null,
                machineSpecs: specsResult.rows || [],
                createdAt: route.order_created_at,
                requestedAt: raw.requested_at || raw.updated_at || route.order_created_at,
                events: eventsResult.rows,
                latestWaste: wasteResult.rows[0] || null,
                timestamps: {
                    setupAt: firstSetup?.created_at || null,
                    runAt: firstRun?.created_at || null,
                    completedAt: firstCompleted?.created_at || route.actual_end_at || null
                },
                raw
            }
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el contexto MES.' });
    }
});

app.get('/api/planificacion/dashboard-kpi', async (req, res) => {
    try {
        const [summaryResult, machineResult, varianceResult, stopResult] = await Promise.all([
            pgQuery(`
                WITH waste AS (
                    SELECT
                        SUM(metros_consumidos) AS metros_consumidos,
                        SUM(metros_utiles) AS metros_utiles
                    FROM production_waste_logs
                )
                SELECT
                    COUNT(*)::int AS total_routes,
                    COUNT(*) FILTER (WHERE estado = 'COMPLETADO')::int AS completed_routes,
                    COUNT(*) FILTER (WHERE estado = 'EN_MARCHA')::int AS running_routes,
                    COUNT(*) FILTER (WHERE estado = 'EN_PARO')::int AS stopped_routes,
                    COALESCE((SELECT metros_consumidos FROM waste), 0) AS metros_consumidos,
                    COALESCE((SELECT metros_utiles FROM waste), 0) AS metros_utiles
                FROM orden_proceso
            `),
            pgQuery(`
                WITH machine_base AS (
                    SELECT
                        mp.id,
                        mp.machine_name,
                        mp.velocidad_nominal_m_min,
                        COUNT(r.id) AS total_routes,
                        COUNT(*) FILTER (WHERE r.estado = 'EN_MARCHA') AS running_routes,
                        COUNT(*) FILTER (WHERE r.estado = 'EN_PARO') AS stopped_routes,
                        COUNT(*) FILTER (WHERE r.estado = 'COMPLETADO') AS completed_routes,
                        AVG(CASE
                            WHEN COALESCE(w.velocidad_final_m_min, 0) > 0 AND COALESCE(mp.velocidad_nominal_m_min, 0) > 0
                                THEN LEAST(1, w.velocidad_final_m_min / NULLIF(mp.velocidad_nominal_m_min, 0))
                            ELSE NULL
                        END) AS performance_ratio,
                        SUM(COALESCE(w.metros_consumidos, 0)) AS metros_consumidos,
                        SUM(COALESCE(w.metros_utiles, 0)) AS metros_utiles
                    FROM production_machine_profiles mp
                    LEFT JOIN orden_proceso r ON r.perfil_maquina_id = mp.id
                    LEFT JOIN LATERAL (
                        SELECT *
                        FROM production_waste_logs w
                        WHERE (r.datos_extra->>'migrado_de_route_id') ~ '^[0-9a-fA-F-]{36}$'
                          AND w.route_id = (r.datos_extra->>'migrado_de_route_id')::uuid
                        ORDER BY w.created_at DESC
                        LIMIT 1
                    ) w ON TRUE
                    WHERE mp.is_active = TRUE
                    GROUP BY mp.id, mp.machine_name, mp.velocidad_nominal_m_min
                )
                SELECT
                    id::text AS machine_id,
                    machine_name,
                    total_routes,
                    running_routes,
                    stopped_routes,
                    completed_routes,
                    ROUND(
                        GREATEST(
                            0,
                            CASE
                                WHEN total_routes > 0 THEN 1 - (stopped_routes::numeric / total_routes::numeric)
                                ELSE 0.85
                            END
                        ) * 100, 2
                    ) AS availability_pct,
                    ROUND(COALESCE(performance_ratio, 0.8) * 100, 2) AS performance_pct,
                    ROUND(
                        CASE
                            WHEN COALESCE(metros_consumidos, 0) > 0 THEN (metros_utiles / NULLIF(metros_consumidos, 0)) * 100
                            ELSE 95
                        END
                    , 2) AS quality_pct
                FROM machine_base
                ORDER BY machine_name
            `),
            pgQuery(`
                SELECT
                    nombre_proceso AS process_name,
                    ROUND(AVG(COALESCE(duracion_horas, 0) * 60), 2) AS plan_minutes,
                    ROUND(AVG(
                        CASE
                            WHEN fecha_real_inicio IS NOT NULL AND fecha_real_fin IS NOT NULL
                                THEN EXTRACT(EPOCH FROM (fecha_real_fin - fecha_real_inicio)) / 60
                            ELSE NULL
                        END
                    ), 2) AS real_minutes
                FROM orden_proceso
                GROUP BY nombre_proceso
                ORDER BY nombre_proceso
            `),
            pgQuery(`
                SELECT
                    COALESCE(sr.reason_group, 'Sin grupo') AS reason_group,
                    COALESCE(sr.description, 'Sin motivo') AS reason_description,
                    COUNT(*)::int AS total
                FROM production_route_events e
                LEFT JOIN production_stop_reasons sr ON sr.id = e.stop_reason_id
                WHERE lower(COALESCE(e.event_type, '')) = 'paro'
                GROUP BY COALESCE(sr.reason_group, 'Sin grupo'), COALESCE(sr.description, 'Sin motivo')
                ORDER BY total DESC, reason_group, reason_description
                LIMIT 12
            `)
        ]);

        const summary = summaryResult.rows[0] || {};
        const machineMetrics = (machineResult.rows || []).map((row) => {
            const availability = Number(row.availability_pct || 0);
            const performance = Number(row.performance_pct || 0);
            const quality = Number(row.quality_pct || 0);
            const oee = Number(((availability * performance * quality) / 10000).toFixed(2));
            return {
                machineId: row.machine_id,
                machineName: row.machine_name,
                totalRoutes: Number(row.total_routes || 0),
                runningRoutes: Number(row.running_routes || 0),
                stoppedRoutes: Number(row.stopped_routes || 0),
                completedRoutes: Number(row.completed_routes || 0),
                availabilityPct: availability,
                performancePct: performance,
                qualityPct: quality,
                oeePct: oee
            };
        });

        const average = (items, key, fallback = 0) => {
            if (!items.length) return fallback;
            return Number((items.reduce((acc, item) => acc + Number(item[key] || 0), 0) / items.length).toFixed(2));
        };

        const deliveredOnTime = Number(summary.completed_routes || 0);
        const delayedRoutes = Number(summary.stopped_routes || 0);
        const qualityGlobal = Number(
            Number(summary.metros_consumidos || 0) > 0
                ? ((Number(summary.metros_utiles || 0) / Number(summary.metros_consumidos || 0)) * 100).toFixed(2)
                : 95
        );
        const capacityEngine = await getFiniteCapacityResult({ horizonDays: 30 }).catch(() => null);

        res.json({
            ok: true,
            data: {
                summary: {
                    totalRoutes: Number(summary.total_routes || 0),
                    completedRoutes: deliveredOnTime,
                    runningRoutes: Number(summary.running_routes || 0),
                    stoppedRoutes: delayedRoutes,
                    oeeAverage: average(machineMetrics, 'oeePct', 0),
                    availabilityAverage: average(machineMetrics, 'availabilityPct', 0),
                    performanceAverage: average(machineMetrics, 'performancePct', 0),
                    qualityAverage: qualityGlobal
                },
                machines: machineMetrics,
                otd: {
                    deliveredOnTime,
                    delayedRoutes,
                    weeklyOtdPct: Number(
                        (deliveredOnTime + delayedRoutes) > 0
                            ? ((deliveredOnTime / (deliveredOnTime + delayedRoutes)) * 100).toFixed(2)
                            : 0
                    ),
                    delayedItems: machineMetrics
                        .filter((item) => item.stoppedRoutes > 0)
                        .slice(0, 6)
                        .map((item) => ({
                            code: item.machineName,
                            customer: 'Planificación',
                            delay: `+${item.stoppedRoutes}`,
                            cause: 'Paros activos en rutas'
                        }))
                },
                variance: (varianceResult.rows || [])
                    .filter((row) => Number(row.plan_minutes || 0) > 0 || Number(row.real_minutes || 0) > 0)
                    .map((row) => ({
                        processName: row.process_name,
                        planMinutes: Number(row.plan_minutes || 0),
                        realMinutes: Number(row.real_minutes || 0),
                        variancePct: Number(row.plan_minutes || 0) > 0
                            ? Number((((Number(row.real_minutes || 0) - Number(row.plan_minutes || 0)) / Number(row.plan_minutes || 0)) * 100).toFixed(2))
                            : 0
                    })),
                stops: (stopResult.rows || []).map((row) => ({
                    group: row.reason_group,
                    reason: row.reason_description,
                    total: Number(row.total || 0)
                })),
                capacity: capacityEngine ? {
                    computedAt: capacityEngine.computedAt,
                    summary: capacityEngine.summary,
                    bottlenecks: capacityEngine.bottlenecks,
                    resources: capacityEngine.resources,
                    projectedLateOrders: capacityEngine.orders
                        .filter((order) => order.projectedLate)
                        .map((order) => ({
                            orderCode: order.orderCode,
                            customerName: order.customerName,
                            jobName: order.jobName,
                            promisedDate: order.promisedDate,
                            latestEnd: order.latestEnd
                        }))
                } : null
            }
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el dashboard KPI.' });
    }
});

// Fases cronometradas dentro del proceso de Impresión. Cada fase se marca con un
// par de eventos <fase>_inicio / <fase>_fin en production_route_events (no cambian el
// estado del proceso, solo desglosan su duración). El cotizado ya vive en
// tiempo_<fase>_min; aquí se calcula el _vigente real.
const FASES_IMPRESION = ['montaje', 'setup', 'corrida', 'limpieza'];
const EVENTOS_FASE_IMPRESION = new Set(FASES_IMPRESION.flatMap((f) => [`${f}_inicio`, `${f}_fin`]));

// Recalcula tiempo_<fase>_inicio/fin/min_vigente y tiempo_total_impresion_min_vigente a
// partir de los eventos de marca del proceso, descontando de cada fase el tiempo de las
// pausas ('paro' hasta el siguiente evento) que caen dentro de su rango. Espeja el
// resumen a flexo_orders y a los flexo_products de la orden.
async function syncCapturaFasesImpresion(proc) {
    if (!proc || !proc.id || !proc.codigo_orden) return;
    const evs = (await pgQuery(
        `SELECT event_type, created_at FROM production_route_events
          WHERE orden_proceso_id = $1::uuid ORDER BY created_at ASC`,
        [proc.id]
    )).rows;
    if (!evs.length) return;

    const pausas = [];
    for (let i = 0; i < evs.length; i++) {
        if (String(evs[i].event_type).trim().toLowerCase() !== 'paro') continue;
        const desde = new Date(evs[i].created_at).getTime();
        const hasta = i + 1 < evs.length ? new Date(evs[i + 1].created_at).getTime() : desde;
        if (hasta > desde) pausas.push([desde, hasta]);
    }
    const pausaEnRango = (ini, fin) => pausas.reduce((acc, [pd, ph]) => {
        const lo = Math.max(ini, pd);
        const hi = Math.min(fin, ph);
        return acc + (hi > lo ? hi - lo : 0);
    }, 0);

    const cols = {};
    let totalMin = 0;
    for (const fase of FASES_IMPRESION) {
        const ini = [...evs].reverse().find((e) => e.event_type === `${fase}_inicio`);
        const fin = [...evs].reverse().find((e) => e.event_type === `${fase}_fin`);
        cols[`tiempo_${fase}_inicio_vigente`] = ini ? ini.created_at : null;
        cols[`tiempo_${fase}_fin_vigente`] = fin ? fin.created_at : null;
        let min = null;
        if (ini && fin) {
            const a = new Date(ini.created_at).getTime();
            const b = new Date(fin.created_at).getTime();
            if (b > a) {
                min = Math.round(((b - a - pausaEnRango(a, b)) / 60000) * 100) / 100;
                if (min < 0) min = 0;
                totalMin += min;
            }
        }
        cols[`tiempo_${fase}_min_vigente`] = min;
    }
    cols.tiempo_total_impresion_min_vigente = totalMin > 0 ? Math.round(totalMin * 100) / 100 : null;
    cols.impresion_captura_actualizado_en = new Date().toISOString();

    const keys = Object.keys(cols);
    const setClause = keys.map((k, i) => `${k} = $${i + 2}`).join(', ');
    await pgQuery(`UPDATE flexo_orders SET ${setClause} WHERE order_code = $1`, [proc.codigo_orden, ...keys.map((k) => cols[k])]);

    const ordRow = (await pgQuery(
        `SELECT quote_code, line_code, product_code FROM flexo_orders WHERE order_code = $1 LIMIT 1`,
        [proc.codigo_orden]
    )).rows[0];
    if (!ordRow) return;
    let productCodes = [];
    if (ordRow.quote_code && ordRow.line_code) {
        productCodes = (await pgQuery(
            `SELECT DISTINCT product_code FROM flexo_products WHERE quote_code = $1 AND line_code = $2 AND motivo_indice IS NOT NULL`,
            [ordRow.quote_code, ordRow.line_code]
        )).rows.map((r) => r.product_code);
    }
    if (!productCodes.length && ordRow.product_code) productCodes = [ordRow.product_code];
    for (const pc of productCodes) {
        await pgQuery(`UPDATE flexo_products SET ${setClause} WHERE product_code = $1`, [pc, ...keys.map((k) => cols[k])]);
    }
}

// Fases cronometradas dentro del proceso de Rebobinado: Montaje y Tiraje. Al terminar
// Montaje el operario arranca Tiraje con un botón propio ("Iniciar Tiraje"), igual
// mecánica que Impresión pero con columnas rebobinado_tiempo_*_vigente propias (las
// genéricas tiempo_*_vigente son exclusivas de Impresión).
const FASES_REBOBINADO = ['montaje', 'tiraje'];
const EVENTOS_FASE_REBOBINADO = new Set(FASES_REBOBINADO.flatMap((f) => [`${f}_inicio`, `${f}_fin`]));

async function syncCapturaFasesRebobinado(proc) {
    if (!proc || !proc.id || !proc.codigo_orden) return;
    const evs = (await pgQuery(
        `SELECT event_type, created_at FROM production_route_events
          WHERE orden_proceso_id = $1::uuid ORDER BY created_at ASC`,
        [proc.id]
    )).rows;
    if (!evs.length) return;

    const pausas = [];
    for (let i = 0; i < evs.length; i++) {
        if (String(evs[i].event_type).trim().toLowerCase() !== 'paro') continue;
        const desde = new Date(evs[i].created_at).getTime();
        const hasta = i + 1 < evs.length ? new Date(evs[i + 1].created_at).getTime() : desde;
        if (hasta > desde) pausas.push([desde, hasta]);
    }
    const pausaEnRango = (ini, fin) => pausas.reduce((acc, [pd, ph]) => {
        const lo = Math.max(ini, pd);
        const hi = Math.min(fin, ph);
        return acc + (hi > lo ? hi - lo : 0);
    }, 0);

    const cols = {};
    let totalMin = 0;
    for (const fase of FASES_REBOBINADO) {
        const ini = [...evs].reverse().find((e) => e.event_type === `${fase}_inicio`);
        const fin = [...evs].reverse().find((e) => e.event_type === `${fase}_fin`);
        cols[`rebobinado_tiempo_${fase}_inicio_vigente`] = ini ? ini.created_at : null;
        cols[`rebobinado_tiempo_${fase}_fin_vigente`] = fin ? fin.created_at : null;
        let min = null;
        if (ini && fin) {
            const a = new Date(ini.created_at).getTime();
            const b = new Date(fin.created_at).getTime();
            if (b > a) {
                min = Math.round(((b - a - pausaEnRango(a, b)) / 60000) * 100) / 100;
                if (min < 0) min = 0;
                totalMin += min;
            }
        }
        cols[`rebobinado_tiempo_${fase}_min_vigente`] = min;
    }
    cols.rebobinado_tiempo_total_min_vigente = totalMin > 0 ? Math.round(totalMin * 100) / 100 : null;
    cols.rebobinado_captura_actualizado_en = new Date().toISOString();

    const keys = Object.keys(cols);
    const setClause = keys.map((k, i) => `${k} = $${i + 2}`).join(', ');
    await pgQuery(`UPDATE flexo_orders SET ${setClause} WHERE order_code = $1`, [proc.codigo_orden, ...keys.map((k) => cols[k])]);

    const ordRow = (await pgQuery(
        `SELECT quote_code, line_code, product_code FROM flexo_orders WHERE order_code = $1 LIMIT 1`,
        [proc.codigo_orden]
    )).rows[0];
    if (!ordRow) return;
    let productCodes = [];
    if (ordRow.quote_code && ordRow.line_code) {
        productCodes = (await pgQuery(
            `SELECT DISTINCT product_code FROM flexo_products WHERE quote_code = $1 AND line_code = $2 AND motivo_indice IS NOT NULL`,
            [ordRow.quote_code, ordRow.line_code]
        )).rows.map((r) => r.product_code);
    }
    if (!productCodes.length && ordRow.product_code) productCodes = [ordRow.product_code];
    for (const pc of productCodes) {
        await pgQuery(`UPDATE flexo_products SET ${setClause} WHERE product_code = $1`, [pc, ...keys.map((k) => cols[k])]);
    }
}

// Distancia consumida por fase de Rebobinado (Montaje/Tiraje), declarada obligatoriamente al
// finalizar cada fase. De ahí se derivan los 3 % de merma (montaje, tiraje, total = suma)
// contra la distancia cotizada — alimentan la curva de rendimiento, no se muestran al operario.
async function capturarDistanciaFaseRebobinado(proc, fase, distanciaM) {
    const ordRow = (await pgQuery(`SELECT quote_code, line_code FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [proc.codigo_orden])).rows[0];
    if (!ordRow) return;
    const { quote_code: quoteCode, line_code: lineCode } = ordRow;

    const distRow = (await pgQuery(
        `SELECT valor_cotizado FROM valores_produccion_motivo
          WHERE quote_code = $1 AND line_code = $2 AND proceso = 'rebobinado' AND campo = 'rebobinado_distancia_recorrida_m' LIMIT 1`,
        [quoteCode, lineCode]
    )).rows[0];
    const distanciaCotizada = distRow ? Number(distRow.valor_cotizado) || 0 : 0;
    const pct = distanciaCotizada > 0 ? Math.round((distanciaM / distanciaCotizada) * 100 * 10000) / 10000 : 0;

    const colDist = `rebobinado_distancia_${fase}_m_vigente`;
    const colPct = `rebobinado_merma_${fase}_pct_vigente`;
    await pgQuery(`UPDATE flexo_orders SET ${colDist} = $1, ${colPct} = $2, rebobinado_captura_actualizado_en = NOW() WHERE order_code = $3`,
        [distanciaM, pct, proc.codigo_orden]);
    await pgQuery(`UPDATE flexo_products SET ${colDist} = $1, ${colPct} = $2 WHERE quote_code = $3 AND line_code = $4`,
        [distanciaM, pct, quoteCode, lineCode]);

    const totales = (await pgQuery(
        `SELECT rebobinado_distancia_montaje_m_vigente AS m, rebobinado_distancia_tiraje_m_vigente AS t,
                rebobinado_merma_montaje_pct_vigente AS mp, rebobinado_merma_tiraje_pct_vigente AS tp
           FROM flexo_orders WHERE order_code = $1`,
        [proc.codigo_orden]
    )).rows[0] || {};
    const sumaDistancia = (Number(totales.m) || 0) + (Number(totales.t) || 0);
    const sumaPct = (Number(totales.mp) || 0) + (Number(totales.tp) || 0);

    await pgQuery(`UPDATE flexo_orders SET rebobinado_distancia_recorrida_m_vigente = $1, rebobinado_merma_operacion_pct_vigente = $2 WHERE order_code = $3`,
        [sumaDistancia, sumaPct, proc.codigo_orden]);
    await pgQuery(`UPDATE flexo_products SET rebobinado_distancia_recorrida_m_vigente = $1, rebobinado_merma_operacion_pct_vigente = $2 WHERE quote_code = $3 AND line_code = $4`,
        [sumaDistancia, sumaPct, quoteCode, lineCode]);
    await pgQuery(
        `UPDATE valores_produccion_motivo SET valor_producido = $1
          WHERE quote_code = $2 AND line_code = $3 AND proceso = 'rebobinado' AND campo = 'rebobinado_distancia_recorrida_m'`,
        [String(Math.round(sumaDistancia * 100) / 100), quoteCode, lineCode]
    );
}

// Impresión: al finalizar la fase de Montaje o Tiraje(corrida), guarda los metros de merma
// que reportó el operario como valor PRODUCIDO — en valores_produccion_motivo (proceso
// 'impresion') y en la columna *_vigente de flexo_orders/flexo_products. El cotizado no se
// toca (lo siembra seedValoresProduccionMotivo desde el cálculo).
async function capturarMetrosFaseImpresion(proc, campo, metros) {
    const ordRow = (await pgQuery(`SELECT quote_code, line_code FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [proc.codigo_orden])).rows[0];
    if (!ordRow) return;
    const { quote_code: quoteCode, line_code: lineCode } = ordRow;
    const valor = String(Math.round(Number(metros) * 100) / 100);
    const colVigente = campo === 'impresion_merma_montaje_m' ? 'impresion_merma_montaje_m_vigente' : 'impresion_merma_corrida_m_vigente';
    await pgQuery(
        `UPDATE valores_produccion_motivo SET valor_producido = $1
          WHERE quote_code = $2 AND line_code = $3 AND proceso = 'impresion' AND campo = $4`,
        [valor, quoteCode, lineCode, campo]
    );
    await pgQuery(`UPDATE flexo_orders SET ${colVigente} = $1, impresion_captura_actualizado_en = NOW() WHERE order_code = $2`,
        [valor, proc.codigo_orden]).catch(() => {});
    await pgQuery(`UPDATE flexo_products SET ${colVigente} = $1 WHERE quote_code = $2 AND line_code = $3`,
        [valor, quoteCode, lineCode]).catch(() => {});
}

// ════════════════════════════════════════════════════════════════════════════
// SUMATORIA DE FASES POR OPERARIO — tiempo y merma de paro, desglosados por fase
// (Montaje/Setup/Corrida/Limpieza en Impresión, Montaje/Tiraje en Rebobinado, una
// sola fase "Trabajo" en el resto) y, dentro de cada fase, por cada operario que
// participó. No hay tabla nueva: se recalcula leyendo production_route_events,
// igual que ya hacen syncCapturaFasesImpresion/Rebobinado con sus columnas
// *_vigente. El cambio de operario se marca con el evento 'operario_cambio' que
// manda produccion.html cuando alguien ficha con su PIN a media fase.
//
// La columna "merma" de esta sumatoria es SOLO la merma de paro (desperdicio_m,
// ya en metros) — no se mezcla con impresion_merma_montaje_m_vigente ni con los
// porcentajes de rebobinado_merma_*_pct_vigente, que son otra cosa (consumo de
// fase / % vs. cotizado) y ya se muestran aparte en la orden. Mezclarlos sería
// sumar unidades distintas (metros con porcentajes) y el número saldría mal.
const FASES_POR_PROCESO_SUMATORIA = { impresion: FASES_IMPRESION, rebobinado: FASES_REBOBINADO };
const FASE_GENERICA_SUMATORIA = ['trabajo'];

function fasesDeProcesoSumatoria(procKey) {
    return FASES_POR_PROCESO_SUMATORIA[procKey] || FASE_GENERICA_SUMATORIA;
}

async function calcularSumatoriaFases(proc) {
    const procKey = canonicalProductionFlowKey(proc.clave_proceso) || proc.clave_proceso;
    const fases = fasesDeProcesoSumatoria(procKey);
    const esGenerica = fases === FASE_GENERICA_SUMATORIA;

    const evs = (await pgQuery(
        `SELECT event_type, operator_name, created_at, desperdicio_m FROM production_route_events
          WHERE orden_proceso_id = $1::uuid ORDER BY created_at ASC`,
        [proc.id]
    )).rows;
    if (!evs.length) return { fases: [], totalMinutos: 0, totalMerma: 0 };

    // Mismo criterio de pausas que syncCapturaFasesImpresion: cada 'paro' resta tiempo
    // hasta el siguiente evento (o hasta ahora, si sigue en pausa).
    const pausas = [];
    for (let i = 0; i < evs.length; i++) {
        if (String(evs[i].event_type).trim().toLowerCase() !== 'paro') continue;
        const desde = new Date(evs[i].created_at).getTime();
        const hasta = i + 1 < evs.length ? new Date(evs[i + 1].created_at).getTime() : Date.now();
        if (hasta > desde) pausas.push([desde, hasta]);
    }
    const pausaEnRango = (ini, fin) => pausas.reduce((acc, [pd, ph]) => {
        const lo = Math.max(ini, pd), hi = Math.min(fin, ph);
        return acc + (hi > lo ? hi - lo : 0);
    }, 0);
    const mermasParo = evs
        .filter((e) => String(e.event_type).trim().toLowerCase() === 'paro' && Number(e.desperdicio_m) > 0)
        .map((e) => ({ ts: new Date(e.created_at).getTime(), merma: Number(e.desperdicio_m) }));

    const resultado = [];
    let totalMinutos = 0, totalMerma = 0;

    for (const fase of fases) {
        let inicioEv, finEv;
        if (esGenerica) {
            inicioEv = evs.find((e) => String(e.event_type).trim().toLowerCase() === 'run');
            finEv = [...evs].reverse().find((e) => String(e.event_type).trim().toLowerCase() === 'completado');
        } else {
            inicioEv = [...evs].reverse().find((e) => e.event_type === `${fase}_inicio`);
            finEv = [...evs].reverse().find((e) => e.event_type === `${fase}_fin`);
        }
        if (!inicioEv) continue;
        const iniMs = new Date(inicioEv.created_at).getTime();
        const finMs = finEv ? new Date(finEv.created_at).getTime() : Date.now();
        if (finMs <= iniMs) continue;

        const cambios = evs
            .filter((e) => String(e.event_type).trim().toLowerCase() === 'operario_cambio'
                && new Date(e.created_at).getTime() > iniMs && new Date(e.created_at).getTime() < finMs)
            .map((e) => ({ ts: new Date(e.created_at).getTime(), operador: e.operator_name || 'Sin operario' }));
        const puntos = [{ ts: iniMs, operador: inicioEv.operator_name || 'Sin operario' }, ...cambios, { ts: finMs, operador: null }];

        const porOperario = {};
        let faseMinutos = 0, faseMerma = 0;
        for (let i = 0; i < puntos.length - 1; i++) {
            const segIni = puntos[i].ts, segFin = puntos[i + 1].ts;
            const neto = Math.max(0, (segFin - segIni) - pausaEnRango(segIni, segFin));
            const min = Math.round((neto / 60000) * 100) / 100;
            const mermaSeg = mermasParo
                .filter((m) => m.ts >= segIni && m.ts < segFin)
                .reduce((s, m) => s + m.merma, 0);
            const nombre = puntos[i].operador || 'Sin operario';
            if (!porOperario[nombre]) porOperario[nombre] = { operador: nombre, minutos: 0, merma: 0 };
            porOperario[nombre].minutos += min;
            porOperario[nombre].merma += mermaSeg;
            faseMinutos += min;
            faseMerma += mermaSeg;
        }

        faseMinutos = Math.round(faseMinutos * 100) / 100;
        faseMerma = Math.round(faseMerma * 10000) / 10000;
        totalMinutos += faseMinutos;
        totalMerma += faseMerma;
        resultado.push({
            fase,
            minutos: faseMinutos,
            merma: faseMerma,
            abierto: !finEv,
            operarios: Object.values(porOperario)
                .map((o) => ({ operador: o.operador, minutos: Math.round(o.minutos * 100) / 100, merma: Math.round(o.merma * 10000) / 10000 }))
                .sort((a, b) => b.minutos - a.minutos)
        });
    }

    return {
        fases: resultado,
        totalMinutos: Math.round(totalMinutos * 100) / 100,
        totalMerma: Math.round(totalMerma * 10000) / 10000
    };
}

app.get('/api/mes/sumatoria-fases', async (req, res) => {
    try {
        const routeId = String(req.query.routeId || '').trim();
        const orderCode = String(req.query.orderCode || '').trim();
        const proceso = String(req.query.proceso || '').trim();
        if (!routeId && !(orderCode && proceso)) {
            return res.status(400).json({ ok: false, error: 'Indica routeId, o orderCode y proceso.' });
        }
        const proc = routeId
            ? await resolverOrdenProceso(routeId)
            : await resolverOrdenProceso(null, { codigoOrden: orderCode, claveProceso: proceso });
        if (!proc) return res.status(404).json({ ok: false, error: 'No se encontró el proceso de la orden.' });
        const sumatoria = await calcularSumatoriaFases(proc);
        res.json({ ok: true, orderCode: proc.codigo_orden, proceso: proc.clave_proceso, ...sumatoria });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible calcular la sumatoria de fases.' });
    }
});

app.post('/api/mes/evento', async (req, res) => {
    try {
        const { routeId, operatorName, eventType, stopReasonId, notes, desperdicioMetros, desperdicioKg, distanciaConsumidaM } = req.body || {};
        if (!routeId || !eventType) {
            return res.status(400).json({ ok: false, error: 'Debes indicar routeId y eventType.' });
        }

        const activeOperator = pickFirstValue(sanitizeAdminUserText(operatorName), getRequestUserName(req));
        const mermaMetros = Math.max(0, Number(desperdicioMetros) || 0);
        const mermaKg = Math.max(0, Number(desperdicioKg) || 0);

        const proc = await resolverOrdenProceso(routeId);
        if (!proc) return res.status(404).json({ ok: false, error: 'No se encontró el proceso de la orden.' });
        const legacyRouteId = /^[0-9a-fA-F-]{36}$/.test(String(proc.datos_extra?.migrado_de_route_id || ''))
            ? proc.datos_extra.migrado_de_route_id : null;
        const procKey = canonicalProductionFlowKey(proc.clave_proceso) || proc.clave_proceso;
        const eventTypeLower = String(eventType).trim().toLowerCase();

        // Compuerta: Rebobinado e Impresión exigen la distancia consumida (m) al finalizar
        // Montaje o Tiraje (en Impresión el "tiraje" es el evento 'corrida') — de ahí salen los
        // metros de merma reales de esa fase.
        let distanciaFaseM = null;
        const esFinFaseRebob = procKey === 'rebobinado' && (eventTypeLower === 'montaje_fin' || eventTypeLower === 'tiraje_fin');
        const esFinFaseImpr = procKey === 'impresion' && (eventTypeLower === 'montaje_fin' || eventTypeLower === 'corrida_fin');
        if (esFinFaseRebob || esFinFaseImpr) {
            distanciaFaseM = Math.max(0, Number(distanciaConsumidaM) || 0);
        }

        const eventoInsert = await pgQuery(`
            INSERT INTO production_route_events (
                orden_proceso_id, route_id, operator_name, event_type, stop_reason_id, notes, desperdicio_m, desperdicio_kg
            ) VALUES ($1::uuid,$2::uuid,$3,$4,$5,$6,$7,$8)
            RETURNING id::text AS id
        `, [proc.id, legacyRouteId, activeOperator || null, eventType, stopReasonId || null, notes || null, mermaMetros, mermaKg]);
        const eventoCrudoId = eventoInsert.rows[0]?.id || null;
        const eventoCrudoRegistrado = true;

        // Suspender Producción: como un Pausar (mismo estado EN_PARO, mismo reloj detenido), pero
        // además queda marcada para que Planificación la vea en su lista de urgentes — la marca
        // vive aparte del estado para no tocar el resto de la máquina de estados existente.
        // Cualquier operario la puede reanudar (evento 'run') sin esperar a Planificación; al
        // reanudar se limpia la marca sola.
        if (eventTypeLower === 'suspender') {
            await pgQuery(
                `UPDATE orden_proceso SET suspendida_produccion = true, suspendida_motivo = $2,
                    suspendida_en = NOW(), suspendida_por = $3, suspendida_revisada_en = NULL, suspendida_revisada_por = NULL
                 WHERE id = $1::uuid`,
                [proc.id, notes || null, activeOperator || null]
            );
        } else if (eventTypeLower === 'run') {
            await pgQuery(
                `UPDATE orden_proceso SET suspendida_produccion = false WHERE id = $1::uuid AND suspendida_produccion = true`,
                [proc.id]
            );
        }

        // Marca de fase de Impresión (montaje/setup/corrida/limpieza · inicio/fin): recalcula el
        // desglose de tiempo real y, al finalizar Montaje o Tiraje(corrida), guarda los metros
        // de merma que reportó el operario.
        if (procKey === 'impresion' && EVENTOS_FASE_IMPRESION.has(String(eventType).trim().toLowerCase())) {
            await syncCapturaFasesImpresion(proc).catch(() => {});
            if (distanciaFaseM !== null) {
                const campoMerma = eventTypeLower === 'montaje_fin' ? 'impresion_merma_montaje_m' : 'impresion_merma_corrida_m';
                await capturarMetrosFaseImpresion(proc, campoMerma, distanciaFaseM).catch(() => {});
            }
        }
        // Marca de fase de Rebobinado (montaje/tiraje · inicio/fin).
        if (procKey === 'rebobinado' && EVENTOS_FASE_REBOBINADO.has(eventTypeLower)) {
            await syncCapturaFasesRebobinado(proc).catch(() => {});
            if (distanciaFaseM !== null) {
                const fase = eventTypeLower === 'montaje_fin' ? 'montaje' : 'tiraje';
                await capturarDistanciaFaseRebobinado(proc, fase, distanciaFaseM).catch(() => {});
            }
        }

        // Empaque completado: sella la fecha "disponible para despacho" (no editable por el operario).
        if (procKey === 'empaque' && String(eventType).trim().toLowerCase() === 'completado') {
            await pgQuery(
                `UPDATE flexo_orders SET empaque_disponible_despacho_vigente = NOW(), empaque_captura_actualizado_en = NOW() WHERE order_code = $1`,
                [proc.codigo_orden]
            ).catch(() => {});
            await pgQuery(
                `UPDATE flexo_products fp SET empaque_disponible_despacho_vigente = NOW()
                   FROM flexo_orders fo
                  WHERE fo.order_code = $1 AND fp.quote_code = fo.quote_code AND fp.line_code = fo.line_code`,
                [proc.codigo_orden]
            ).catch(() => {});
        }

        // Desperdicio por causa: al registrar un paro con desperdicio, se suma a la merma real de
        // la orden y de sus productos (columnas *_vigente). El desglose por motivo vive en la vista
        // vw_merma_por_causa / GET /api/mes/merma-por-causa.
        if (String(eventType).trim().toLowerCase() === 'paro' && (mermaMetros > 0 || mermaKg > 0)) {
            const ordRow = { order_code: proc.codigo_orden };
            if (ordRow?.order_code) {
                await pgQuery(`
                    UPDATE flexo_orders fo SET
                        merma_paros_m_vigente = COALESCE((SELECT SUM(e.desperdicio_m) FROM production_route_events e
                            JOIN orden_proceso op ON op.id = e.orden_proceso_id
                            WHERE op.codigo_orden = $1 AND LOWER(e.event_type) = 'paro'), 0),
                        merma_paros_kg_vigente = COALESCE((SELECT SUM(e.desperdicio_kg) FROM production_route_events e
                            JOIN orden_proceso op ON op.id = e.orden_proceso_id
                            WHERE op.codigo_orden = $1 AND LOWER(e.event_type) = 'paro'), 0),
                        vigente_actualizado_en = NOW()
                     WHERE fo.order_code = $1
                `, [ordRow.order_code]);
                await pgQuery(`
                    UPDATE flexo_products fp SET
                        merma_paros_m_vigente = fo.merma_paros_m_vigente,
                        merma_paros_kg_vigente = fo.merma_paros_kg_vigente
                    FROM flexo_orders fo
                    WHERE fo.order_code = $1
                      AND fp.quote_code = fo.quote_code AND fp.line_code = fo.line_code
                `, [ordRow.order_code]);
            }
        }

        const statusMap = { setup: 'PREPARACION', run: 'EN_MARCHA', paro: 'EN_PARO', suspender: 'EN_PARO', completado: 'COMPLETADO' };
        const nextStatus = statusMap[String(eventType).trim().toLowerCase()];
        if (nextStatus) {
            // Compuerta: no completar Impresión sin Fecha de Entrega.
            if (nextStatus === 'COMPLETADO' && procKey === 'impresion') {
                const gateError = await verifyOrderTrackingStepGate(proc.codigo_orden, 'impresion', {});
                if (gateError) return res.status(400).json({ ok: false, error: gateError });
            }
            // Compuerta: no completar Rebobinado sin "Productos por Rollo" — sin ese dato el
            // operario de Empaque no puede trabajar.
            if (nextStatus === 'COMPLETADO' && procKey === 'rebobinado') {
                const pxr = await pgQuery(
                    `SELECT valor_producido, valor_cotizado FROM valores_produccion_motivo
                      WHERE quote_code = $1 AND line_code = $2 AND proceso = 'rebobinado' AND campo = 'productos_por_rollo'
                      LIMIT 1`,
                    [proc.codigo_cotizacion, proc.codigo_linea]
                );
                let tienePxr = Boolean(pxr.rows[0] && (String(pxr.rows[0].valor_producido || '').trim() || String(pxr.rows[0].valor_cotizado || '').trim()));
                if (!tienePxr) {
                    const fallbackOrder = await pgQuery(
                        `SELECT labels_per_roll FROM flexo_orders WHERE order_code = $1 LIMIT 1`,
                        [proc.codigo_orden]
                    ).catch(() => ({ rows: [] }));
                    if (fallbackOrder.rows[0] && Number(fallbackOrder.rows[0].labels_per_roll) > 0) {
                        tienePxr = true;
                    }
                }
                if (!tienePxr) {
                    return res.status(400).json({ ok: false, error: 'No se puede completar Rebobinado: falta indicar "Productos por Rollo".' });
                }
            }
            // Compuerta de Planeación desactivada a solicitud del usuario (20260904):
            // Tintas/Impresión ya no requieren que "Planeación" esté COMPLETADO para arrancar.
            // if (nextStatus === 'EN_MARCHA' && (procKey === 'tintas' || procKey === 'impresion')) {
            //     const planRow = await pgQuery(
            //         `SELECT estado FROM orden_proceso WHERE codigo_orden = $1 AND clave_proceso = 'programacion' ORDER BY secuencia LIMIT 1`,
            //         [proc.codigo_orden]
            //     );
            //     const planEstado = planRow.rows[0]?.estado;
            //     if (planEstado && planEstado !== 'COMPLETADO') {
            //         return res.status(400).json({ ok: false, error: 'No se puede iniciar este proceso: falta marcar "Planeación" (sustratos e inventario) en Seguimiento de la orden.' });
            //     }
            // }
            try {
                await cambiarEstadoProceso(proc.id, nextStatus, {
                    actor: activeOperator,
                    notes: notes || '',
                    registrarEvento: !eventoCrudoRegistrado,
                    // Si el proceso ya estaba COMPLETADO y el operario toca "Iniciar" de nuevo
                    // (evento 'run'), eso ES la acción explícita de abrir un nuevo ciclo de
                    // trabajo (montaje/tiraje nuevo) — no hace falta pantalla de reapertura aparte.
                    permitirReapertura: eventTypeLower === 'run',
                    motivo: eventTypeLower === 'run' && proc.estado === 'COMPLETADO' ? 'Nuevo ciclo de trabajo' : (notes || '')
                });
            } catch (transErr) {
                return res.status(Number(transErr.statusCode) || 400).json({ ok: false, error: transErr.message });
            }
        }

        // Reanudación tras una devolución: si este proceso tenía una devolución que
        // ya volvió del todo (tenedor_actual NULL), al reanudar (run) se cierra el
        // ticket, se calcula el tiempo de espera y los tres costos.
        if (eventTypeLower === 'run') {
            await cerrarDevolucionAlReanudar(proc, activeOperator).catch((e) => console.error('cerrar devolución al reanudar:', e.message));
        }

        res.json({ ok: true, event: { id: eventoCrudoId, routeId, eventType, operatorName: activeOperator, createdAt: new Date().toISOString() } });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar el evento MES.' });
    }
});

// Historial de ciclos de un proceso (para el modal "Iniciar" cuando ese proceso ya se completó
// antes): todos los eventos de production_route_events de ese proceso/orden, en orden. El
// frontend los agrupa en ciclos separando cada vez que aparece un evento 'completado'.
app.get('/api/produccion/ciclos', async (req, res) => {
    try {
        const orderCode = String(req.query.orden || req.query.orderCode || '').trim();
        const claveProceso = String(req.query.proceso || '').trim();
        if (!orderCode || !claveProceso) {
            return res.status(400).json({ ok: false, error: 'Debes indicar orden y proceso.' });
        }
        const proc = await resolverOrdenProceso(null, { codigoOrden: orderCode, claveProceso });
        if (!proc) return res.status(404).json({ ok: false, error: 'No se encontró el proceso de la orden.' });
        const evs = await pgQuery(
            `SELECT event_type, operator_name, notes, created_at
               FROM production_route_events
              WHERE orden_proceso_id = $1::uuid
              ORDER BY created_at ASC`,
            [proc.id]
        );
        res.json({ ok: true, procesoId: proc.id, estadoActual: proc.estado, eventos: evs.rows });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el historial de ciclos.' });
    }
});

// Desperdicio por causa (motivo de paro) de una orden — desglose + total.
app.get('/api/mes/merma-por-causa', async (req, res) => {
    try {
        const orderCode = String(req.query.orderCode || '').trim();
        if (!orderCode) {
            return res.status(400).json({ ok: false, error: 'Debes indicar orderCode.' });
        }
        const result = await pgQuery(
            `SELECT motivo_paro, grupo_motivo, cantidad_paros, desperdicio_m, desperdicio_kg
               FROM vw_merma_por_causa WHERE order_code = $1
              ORDER BY desperdicio_m DESC NULLS LAST`,
            [orderCode]
        );
        const totalMetros = result.rows.reduce((s, r) => s + Number(r.desperdicio_m || 0), 0);
        const totalKg = result.rows.reduce((s, r) => s + Number(r.desperdicio_kg || 0), 0);
        res.json({ ok: true, data: result.rows, totalMetros, totalKg });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar la merma por causa.' });
    }
});

// Tiempos reales de Rebobinado (Montaje/Tiraje/Total), calculados por syncCapturaFasesRebobinado
// a partir de los eventos de fase — de solo lectura, el operario no los edita a mano.
app.get('/api/mes/rebobinado-tiempos', async (req, res) => {
    try {
        const orderCode = String(req.query.orderCode || '').trim();
        if (!orderCode) {
            return res.status(400).json({ ok: false, error: 'Debes indicar orderCode.' });
        }
        const result = await pgQuery(
            `SELECT rebobinado_tiempo_montaje_min_vigente AS montaje_min,
                    rebobinado_tiempo_tiraje_min_vigente AS tiraje_min,
                    rebobinado_tiempo_total_min_vigente AS total_min,
                    rebobinado_tiempo_montaje_inicio_vigente AS montaje_inicio,
                    rebobinado_tiempo_montaje_fin_vigente AS montaje_fin,
                    rebobinado_tiempo_tiraje_inicio_vigente AS tiraje_inicio,
                    rebobinado_tiempo_tiraje_fin_vigente AS tiraje_fin,
                    rebobinado_distancia_montaje_m_vigente AS montaje_m,
                    rebobinado_distancia_tiraje_m_vigente AS tiraje_m,
                    rebobinado_distancia_recorrida_m_vigente AS total_m
               FROM flexo_orders WHERE order_code = $1 LIMIT 1`,
            [orderCode]
        );
        res.json({ ok: true, data: result.rows[0] || {} });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar los tiempos de rebobinado.' });
    }
});

// Tiempos reales de las fases de Impresión (Montaje / Tiraje=corrida) para reconstruir el
