// Resumen por orden para el panel de Historial de Producción: una fila por orden (no por
// evento) con cliente, producto, cantidad, acabados, en qué proceso está parada hoy y cuánto
// tiempo lleva. Solo incluye órdenes que ya tuvieron al menos un proceso arrancado.
app.get('/api/mes/historial-ordenes', async (req, res) => {
    try {
        const q = sanitizeAdminUserText(req.query.q || '').trim();
        const like = `%${q.replace(/[\\%_]/g, '\\$&')}%`;
        const limit = Math.min(200, Math.max(1, Number(req.query.limit) || 100));

        const result = await pgQuery(`
            WITH procesos AS (
                SELECT vp.codigo_orden, vp.secuencia, vp.nombre_proceso, vp.estado,
                       vp.fecha_real_inicio, vp.fecha_real_fin
                  FROM vista_orden_proceso vp
            ),
            resumen AS (
                SELECT codigo_orden,
                       MIN(fecha_real_inicio) AS inicio,
                       MAX(fecha_real_fin) AS fin_ultimo,
                       COUNT(*) FILTER (WHERE fecha_real_inicio IS NOT NULL) AS pasos_trabajados,
                       COUNT(*) FILTER (WHERE estado <> 'COMPLETADO') AS pasos_pendientes
                  FROM procesos
                 GROUP BY codigo_orden
            ),
            actual AS (
                SELECT DISTINCT ON (codigo_orden) codigo_orden,
                       nombre_proceso AS proceso_actual, estado AS estado_actual
                  FROM procesos
                 WHERE estado <> 'COMPLETADO'
                 ORDER BY codigo_orden, secuencia
            )
            SELECT fo.order_code, fo.customer_name, fo.ordered_quantity, fo.estado_detencion,
                   COALESCE(
                       fo.raw_data#>>'{line_summary,job_name}',
                       fo.raw_data#>>'{line_summary,product_name}',
                       fo.raw_data#>>'{line_snapshot,jobName}',
                       fo.product_code
                   ) AS product_name,
                   COALESCE(NULLIF(fo.barniz_tipo_vigente, ''), fo.barniz_tipo) AS barniz_tipo,
                   fo.laminado_tipo, fo.estampado_tipo,
                   COALESCE(NULLIF(fo.troquel_codigo_vigente, ''), fo.die_code) AS die_code,
                   r.inicio, r.fin_ultimo, r.pasos_pendientes,
                   a.proceso_actual, a.estado_actual
              FROM flexo_orders fo
              JOIN resumen r ON r.codigo_orden = fo.order_code
              LEFT JOIN actual a ON a.codigo_orden = fo.order_code
             WHERE r.pasos_trabajados > 0
               AND ($1 = '' OR (
                   fo.order_code ILIKE $2 OR fo.customer_name ILIKE $2 OR
                   COALESCE(fo.raw_data#>>'{line_summary,job_name}', fo.product_code) ILIKE $2 OR
                   a.proceso_actual ILIKE $2
               ))
             ORDER BY COALESCE(r.fin_ultimo, r.inicio) DESC
             LIMIT $3
        `, [q, like, limit]);

        const orders = result.rows.map((row) => {
            const acabados = [];
            if (row.barniz_tipo) acabados.push(`Barniz: ${row.barniz_tipo}`);
            if (row.laminado_tipo) acabados.push(`Laminado: ${row.laminado_tipo}`);
            if (row.estampado_tipo) acabados.push(`Estampado: ${row.estampado_tipo}`);
            if (row.die_code) acabados.push(`Troquel: ${row.die_code}`);
            const enProceso = Number(row.pasos_pendientes) > 0;
            let estado = 'PENDIENTE';
            if (row.estado_detencion === 'DETENIDA' || row.estado_detencion === 'ANULADA') estado = row.estado_detencion;
            else if (!enProceso) estado = 'COMPLETADO';
            else if (row.estado_actual === 'EN_MARCHA' || row.estado_actual === 'PREPARACION') estado = 'EN_MARCHA';
            else if (row.estado_actual === 'EN_PARO') estado = 'EN_PARO';
            const inicio = row.inicio || null;
            const fin = enProceso ? null : (row.fin_ultimo || null);
            const finParaDuracion = fin || new Date();
            const duracionMin = inicio ? Math.max(0, Math.round((new Date(finParaDuracion) - new Date(inicio)) / 60000)) : 0;
            return {
                orderCode: row.order_code,
                customerName: row.customer_name || '',
                productName: row.product_name || row.order_code,
                quantity: row.ordered_quantity != null ? Number(row.ordered_quantity) : null,
                acabados,
                currentProcess: enProceso ? (row.proceso_actual || '') : '',
                estado,
                enProceso,
                startedAt: inicio,
                endedAt: fin,
                durationMinutes: duracionMin
            };
        });

        res.json({ ok: true, orders });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el historial de órdenes.' });
    }
});

// Historial general de producción: combina los eventos de marca (production_route_events,
// vía orden_proceso) con los cambios de valores producidos (valores_produccion_historial, vía
// valores_produccion_motivo + flexo_orders). Sin orderCode devuelve la actividad más reciente
// de todas las órdenes; con `q` filtra por cualquier variable visible (orden, proceso, campo,
// etiqueta, valores, operario, notas).
app.get('/api/mes/historial', async (req, res) => {
    try {
        const orderCode = String(req.query.orderCode || '').trim();
        const q = String(req.query.q || '').trim().toLowerCase();
        const limit = Math.min(500, Math.max(1, Number(req.query.limit) || 200));

        const eventosParams = [];
        let eventosWhere = '1=1';
        if (orderCode) { eventosParams.push(orderCode); eventosWhere += ` AND op.codigo_orden = $${eventosParams.length}`; }
        const eventos = await pgQuery(`
            SELECT e.created_at AS fecha, op.codigo_orden AS order_code, op.nombre_proceso, op.clave_proceso,
                   e.event_type, e.operator_name, e.notes, e.desperdicio_m, e.desperdicio_kg
              FROM production_route_events e
              JOIN orden_proceso op ON op.id = e.orden_proceso_id
             WHERE ${eventosWhere}
             ORDER BY e.created_at DESC
             LIMIT 500
        `, eventosParams);

        const valoresParams = [];
        let valoresWhere = '1=1';
        if (orderCode) { valoresParams.push(orderCode); valoresWhere += ` AND fo.order_code = $${valoresParams.length}`; }
        const valores = await pgQuery(`
            SELECT h.creado_en AS fecha, fo.order_code, vm.proceso, vm.campo, vm.etiqueta, vm.unidad,
                   vm.valor_cotizado, h.valor_anterior, h.valor_nuevo, h.cambiado_por, h.justificacion
              FROM valores_produccion_historial h
              JOIN valores_produccion_motivo vm ON vm.id = h.valor_id
              JOIN flexo_orders fo ON fo.quote_code = vm.quote_code AND fo.line_code = vm.line_code
             WHERE ${valoresWhere}
             ORDER BY h.creado_en DESC
             LIMIT 500
        `, valoresParams);

        let combined = [
            ...eventos.rows.map((r) => ({
                tipo: 'evento', fecha: r.fecha, orderCode: r.order_code, proceso: r.nombre_proceso,
                claveProceso: r.clave_proceso, evento: r.event_type, operador: r.operator_name, notas: r.notes,
                desperdicioMetros: Number(r.desperdicio_m) || 0, desperdicioKg: Number(r.desperdicio_kg) || 0
            })),
            ...valores.rows.map((r) => ({
                tipo: 'valor', fecha: r.fecha, orderCode: r.order_code, proceso: r.proceso,
                campo: r.campo, etiqueta: r.etiqueta, unidad: r.unidad || '',
                valorCotizado: r.valor_cotizado, valorAnterior: r.valor_anterior, valorNuevo: r.valor_nuevo,
                operador: r.cambiado_por, justificacion: r.justificacion
            }))
        ];
        if (q) {
            combined = combined.filter((r) => JSON.stringify(r).toLowerCase().includes(q));
        }
        combined.sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
        res.json({ ok: true, data: combined.slice(0, limit) });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el historial.' });
    }
});

app.post('/api/mes/mermas', async (req, res) => {
    try {
        const {
            routeId,
            metros_consumidos,
            merma_setup_metros,
            merma_tiraje_metros,
            velocidad_final_m_min,
            aniloxLine,
            cylinderPressure,
            notes
        } = req.body || {};
        if (!routeId) {
            return res.status(400).json({ ok: false, error: 'Debes indicar routeId.' });
        }
        const procMerma = await resolverOrdenProceso(routeId);
        if (!procMerma) return res.status(404).json({ ok: false, error: 'No se encontró el proceso de la orden.' });
        const legacyRouteId = /^[0-9a-fA-F-]{36}$/.test(String(procMerma.datos_extra?.migrado_de_route_id || ''))
            ? procMerma.datos_extra.migrado_de_route_id : null;
        await pgQuery(`
            INSERT INTO production_waste_logs (
                orden_proceso_id, route_id, metros_consumidos, merma_setup_metros, merma_tiraje_metros,
                velocidad_final_m_min, anilox_line, cylinder_pressure, notes
            ) VALUES ($1::uuid,$2::uuid,$3,$4,$5,$6,$7,$8,$9)
        `, [
            procMerma.id,
            legacyRouteId,
            Number(metros_consumidos || 0),
            Number(merma_setup_metros || 0),
            Number(merma_tiraje_metros || 0),
            Number(velocidad_final_m_min || 0),
            aniloxLine || null,
            cylinderPressure || null,
            notes || null
        ]);
        res.json({ ok: true });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar la declaración de merma.' });
    }
});

