// Control de Aprobaciones — todas las órdenes activas en el proceso 'visto_bueno' con su
// estado derivado y días esperando (desde el último evento, o desde que la orden llegó a
// Aprobaciones si nunca se ha marcado nada). Alimenta tanto la tabla como el calendario de
// la pantalla de control (planificacion/aprobaciones-control.html).
app.get('/api/produccion-aprobaciones-control', async (req, res) => {
    try {
        const ordenesRes = await pgQuery(`
            SELECT vp.codigo_orden AS order_code, vp.actualizado_en AS entro_a_aprobaciones,
                   fo.customer_name, q.customer_name AS quote_customer_name, q.salesperson_name
              FROM vista_orden_proceso vp
              JOIN flexo_orders fo ON fo.order_code = vp.codigo_orden
              LEFT JOIN quotes q ON q.quote_code = fo.quote_code
             WHERE vp.clave_proceso = 'visto_bueno' AND vp.estado <> 'COMPLETADO'
               AND fo.delivered_on IS NULL
        `);
        const codigos = ordenesRes.rows.map((r) => r.order_code);
        let ultimoEventoPorOrden = {};
        if (codigos.length) {
            const histRes = await pgQuery(
                `SELECT DISTINCT ON (order_code) order_code, evento, motivo, categoria, registrado_en
                   FROM vb_historial WHERE order_code = ANY($1)
                  ORDER BY order_code, registrado_en DESC`,
                [codigos]
            );
            histRes.rows.forEach((h) => { ultimoEventoPorOrden[h.order_code] = h; });
        }
        const ahora = Date.now();
        // Solo "pendiente de recibir": ya se enviaron al cliente y todavía no hay respuesta.
        // Las que nunca se enviaron no se persiguen acá — si llegaron a Aprobaciones y nadie
        // las envió, esa fue una decisión de alguien, no un pendiente de esta lista.
        const items = ordenesRes.rows.map((r) => {
            const ultimo = ultimoEventoPorOrden[r.order_code] || null;
            const estado = estadoAprobacionDesdeUltimoEvento(ultimo?.evento || null);
            const desde = ultimo?.registrado_en || r.entro_a_aprobaciones;
            const diasEsperando = desde ? Math.floor((ahora - new Date(desde).getTime()) / 86400000) : 0;
            return {
                orderCode: r.order_code,
                cliente: r.quote_customer_name || r.customer_name || '',
                vendedor: r.salesperson_name || '',
                estado,
                desde,
                diasEsperando,
                ultimoCategoria: ultimo?.evento === 'cambios_cliente' ? (VB_CATEGORIAS_CAMBIO_LABEL[ultimo.categoria] || ultimo.categoria || '') : '',
                ultimoMotivo: ultimo?.evento === 'cambios_cliente' ? (ultimo.motivo || '') : ''
            };
        }).filter((it) => it.estado === 'pendiente_recibir')
          .sort((a, b) => b.diasEsperando - a.diasEsperando);

        const eventosRes = await pgQuery(
            `SELECT order_code, evento, registrado_en FROM vb_historial
              WHERE registrado_en >= NOW() - INTERVAL '90 days' ORDER BY registrado_en DESC`
        );

        res.json({ ok: true, data: { items, eventos: eventosRes.rows } });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el control de aprobaciones.' });
    }
});

// ════════════════════════════════════════════════════════════════════════════
// PRODUCCIONES SUSPENDIDAS — lista de urgentes para Planificación (botón "Suspender
// Producción" en la pantalla de planta). Cada fila es un proceso (orden_proceso) marcado
// suspendida_produccion = true; se apaga solo cuando alguien reanuda el proceso (evento 'run'
// en /api/mes/evento), no acá — "revisar" solo deja constancia de que Planificación ya la vio.
// ════════════════════════════════════════════════════════════════════════════
app.get('/api/planificacion/producciones-suspendidas', async (req, res) => {
    try {
        const result = await pgQuery(`
            SELECT op.id::text AS route_id, op.codigo_orden AS order_code, op.clave_proceso AS process_key,
                   op.nombre_proceso AS process_name, op.suspendida_motivo, op.suspendida_en, op.suspendida_por,
                   op.suspendida_revisada_en, op.suspendida_revisada_por,
                   fo.customer_name, q.customer_name AS quote_customer_name,
                   COALESCE(fo.raw_data#>>'{line_snapshot,productName}', fo.product_code) AS product_name,
                   fo.estado_detencion
              FROM orden_proceso op
              JOIN flexo_orders fo ON fo.order_code = op.codigo_orden
              LEFT JOIN quotes q ON q.quote_code = fo.quote_code
             WHERE op.suspendida_produccion = true
             ORDER BY op.suspendida_en ASC
        `);
        const items = result.rows.map((r) => ({
            routeId: r.route_id,
            orderCode: r.order_code,
            processKey: r.process_key,
            processName: PRODUCTION_FLOW_LABELS[r.process_key] || r.process_name || r.process_key,
            cliente: r.quote_customer_name || r.customer_name || '',
            producto: r.product_name || '',
            motivo: r.suspendida_motivo || '',
            suspendidaEn: r.suspendida_en,
            suspendidaPor: r.suspendida_por || '',
            revisadaEn: r.suspendida_revisada_en,
            revisadaPor: r.suspendida_revisada_por || '',
            ordenDetenida: r.estado_detencion === 'DETENIDA' || r.estado_detencion === 'ANULADA'
        }));
        res.json({ ok: true, data: items });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar las producciones suspendidas.' });
    }
});

app.post('/api/planificacion/producciones-suspendidas/:routeId/revisar', async (req, res) => {
    try {
        const { routeId } = req.params;
        const actor = getRequestUserName(req);
        const result = await pgQuery(
            `UPDATE orden_proceso SET suspendida_revisada_en = NOW(), suspendida_revisada_por = $2
              WHERE id = $1::uuid AND suspendida_produccion = true
              RETURNING id`,
            [routeId, actor]
        );
        if (!result.rows.length) return res.status(404).json({ ok: false, error: 'No se encontró esa suspensión (puede que ya se haya reanudado).' });
        res.json({ ok: true });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible marcar como revisada.' });
    }
});

// ════════════════════════════════════════════════════════════════════════════
// PANEL DE DISEÑO (produccion-diseno.html) — paso Diseño del módulo Producción
// ════════════════════════════════════════════════════════════════════════════
const DISENO_ACABADO_ACTIVO = (v) => {
    const t = String(v ?? '').trim().toLowerCase();
    return Boolean(t) && !['no', 'ninguno', 'ninguna', 'n/a', 'sin', 'false', 'null', '0', '-', ''].includes(t);
};

app.get('/api/produccion-diseno', async (req, res) => {
    try {
        const orderCode = String(req.query.orden || req.query.orderCode || '').trim();
        if (!orderCode) return res.status(400).json({ ok: false, error: 'Falta el parámetro ?orden.' });
        const ordRes = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
        const orden = ordRes.rows[0];
        if (!orden) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });

        const planRes = await pgQuery(`SELECT lanzado_gantt FROM orden_planificacion WHERE codigo_orden = $1 LIMIT 1`, [orderCode]);
        const lanzadoGantt = Boolean(planRes.rows[0]?.lanzado_gantt);
        if (!lanzadoGantt) {
            return res.status(400).json({ ok: false, error: 'Esta orden aún no ha recibido la marca de Seguimiento.' });
        }

        const [motivos, prodRes, calcRes, quoteRes, artesRes, archivosRes] = await Promise.all([
            buildOrderMotivosDetalle(orden),
            pgQuery(
                `SELECT motivo_indice, width_inches, length_inches, quantity,
                        barniz_tipo, barniz_zonificado, laminado_tipo, estampado_tipo, embosado_tipo,
                        die_code, numerado_tipo, application_type, troquel_forma,
                        diseno_forma_vigente, diseno_orientacion_vigente, diseno_sangrado_vigente_in, diseno_notas_cliente_vigente
                   FROM flexo_products WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice`,
                [orden.quote_code, orden.line_code]
            ),
            pgQuery(
                `SELECT width_inches, length_inches,
                        COALESCE(troquel_forma, raw_data->>'troquel_forma', raw_data->'line_snapshot'->>'troquelForma', raw_data->'line_snapshot'->>'troquel_forma') AS troquel_forma,
                        COALESCE(barniz_tipo, raw_data->>'barniz_tipo', raw_data->'line_snapshot'->>'barnizTipo', raw_data->'line_snapshot'->>'barniz_tipo') AS barniz_tipo,
                        COALESCE(barniz_zonificado, (raw_data->'line_snapshot'->>'barnizZonificado')::boolean, (raw_data->'line_snapshot'->>'barniz_zonificado')::boolean) AS barniz_zonificado,
                        COALESCE(laminado_tipo, raw_data->>'laminado_tipo', raw_data->'line_snapshot'->>'laminadoTipo', raw_data->'line_snapshot'->>'laminado_tipo') AS laminado_tipo,
                        COALESCE(estampado_tipo, raw_data->>'estampado_tipo', raw_data->'line_snapshot'->>'estampadoTipo', raw_data->'line_snapshot'->>'estampado_tipo') AS estampado_tipo,
                        COALESCE(die_code, raw_data->>'die_code', raw_data->'line_snapshot'->>'dieCode', raw_data->'line_snapshot'->>'die_code') AS die_code,
                        COALESCE(tipo_trabajo, raw_data->>'tipo_trabajo', raw_data->'line_snapshot'->>'tipoTrabajo', raw_data->'line_snapshot'->>'tipo_trabajo') AS tipo_trabajo,
                        COALESCE(product_type, raw_data->>'product_type', raw_data->'line_snapshot'->>'productType', raw_data->'line_snapshot'->>'product_type') AS product_type,
                        COALESCE(codigo_producto_cliente, raw_data->>'codigo_producto_cliente', raw_data->'line_snapshot'->>'codigoProductoCliente', raw_data->'line_snapshot'->>'codigo_producto_cliente') AS codigo_producto_cliente,
                        COALESCE(referencia_cliente, raw_data->>'referencia_cliente', raw_data->'line_snapshot'->>'referenciaCliente', raw_data->'line_snapshot'->>'referencia_cliente') AS referencia_cliente,
                        COALESCE(referencia_comentario, raw_data->>'referencia_comentario', raw_data->'line_snapshot'->>'referenciaComentario', raw_data->'line_snapshot'->>'referencia_comentario') AS referencia_comentario,
                        COALESCE(referencia_cambios, raw_data->>'referencia_cambios', raw_data->'line_snapshot'->>'referenciaCambios', raw_data->'line_snapshot'->>'referencia_cambios') AS referencia_cambios,
                        COALESCE(insumos_cliente, raw_data->>'insumos_cliente', raw_data->'line_snapshot'->>'insumosCliente', raw_data->'line_snapshot'->>'insumos_cliente') AS insumos_cliente,
                        COALESCE(ambiente_aplicacion, raw_data->>'ambiente_aplicacion', raw_data->'line_snapshot'->>'ambienteAplicacion', raw_data->'line_snapshot'->>'ambiente_aplicacion') AS ambiente_aplicacion,
                        COALESCE(material_nombre, raw_data->>'material_nombre', raw_data->'line_snapshot'->>'materialNombre', raw_data->'line_snapshot'->>'material_nombre') AS material_nombre,
                        COALESCE(finished_product_sku, raw_data->>'finished_product_sku', raw_data->'line_snapshot'->>'finishedProductSku', raw_data->'line_snapshot'->>'finished_product_sku') AS finished_product_sku
                   FROM flexo_calculations
                  WHERE quote_code = $1 AND line_code = $2 ORDER BY created_at DESC LIMIT 1`,
                [orden.quote_code, orden.line_code]
            ),
            pgQuery(`SELECT customer_name, salesperson_name FROM quotes WHERE quote_code = $1 LIMIT 1`, [orden.quote_code]),
            pgQuery(
                `SELECT id, motivo_indice, version_indice, nombre_arte, imagen_url, creado_por, creado_en
                   FROM produccion_artes WHERE orden_codigo = $1 ORDER BY creado_en ASC`,
                [orderCode]
            ),
            pgQuery(
                `SELECT id, motivo_indice, version_indice, nombre_archivo, tipo, categoria, estado,
                        tamano_bytes, creado_por, creado_en, aprobado_por, aprobado_en
                   FROM diseno_archivos WHERE orden_codigo = $1 ORDER BY creado_en ASC`,
                [orderCode]
            )
        ]);

        const prod0 = prodRes.rows[0] || {};
        const calc = calcRes.rows[0] || {};
        const wIn = Number(calc.width_inches || prod0.width_inches || orden.width_inches || 0);
        const lIn = Number(calc.length_inches || prod0.length_inches || orden.length_inches || 0);
        const toMm = (inch) => (inch > 0 ? Math.round(inch * 25.4 * 10) / 10 : null);
        const prodByMotivo = new Map(prodRes.rows.map((r) => [r.motivo_indice, r]));

        const artesByKey = {};
        artesRes.rows.forEach((a) => {
            const k = `${a.motivo_indice ?? 0}:${a.version_indice ?? 0}`;
            (artesByKey[k] = artesByKey[k] || []).push({ id: a.id, url: a.imagen_url, nombre: a.nombre_arte, por: a.creado_por, en: a.creado_en });
        });

        // Acabados que a Diseño le importan: Barniz (con reservado), Laminado, Estampado (con color de foil),
        // Troquelado (con número de troquel). Se leen de producto → orden → cálculo.
        const disenoTroquelInfo = await buildTroquelInfoParaOrden(orden, prod0, calc);
        const acabVal = (k) => prod0[k] || orden[k] || calc[k] || '';
        const barnizTipo = acabVal('barniz_tipo');
        const barnizZonif = (prod0.barniz_zonificado ?? orden.barniz_zonificado ?? calc.barniz_zonificado) === true;
        const barnizZona = prod0.barniz_zona_vigente || orden.barniz_zona_vigente || '';
        const laminadoTipo = acabVal('laminado_tipo');
        const estampadoTipo = acabVal('estampado_tipo');
        const foilColor = prod0.foil_color_vigente || orden.foil_color_vigente || '';
        const dieCode = prod0.troquel_codigo_vigente || orden.troquel_codigo_vigente || acabVal('die_code');
        const acabados = [
            {
                nombre: 'Barniz',
                activo: DISENO_ACABADO_ACTIVO(barnizTipo),
                detalle: [barnizTipo, barnizZonif ? ('Reservado' + (barnizZona ? ` (${barnizZona})` : '')) : ''].filter(Boolean).join(' · ')
            },
            { nombre: 'Laminado', activo: DISENO_ACABADO_ACTIVO(laminadoTipo), detalle: laminadoTipo },
            {
                nombre: 'Estampado',
                activo: DISENO_ACABADO_ACTIVO(estampadoTipo),
                detalle: [estampadoTipo, foilColor].filter(Boolean).join(' · ')
            },
            { nombre: 'Troquelado', activo: DISENO_ACABADO_ACTIVO(dieCode), detalle: dieCode }
        ];

        // Cambios del cliente todavía sin resolver: los registrados después del último 'enviado'
        // (si nunca se volvió a enviar, todos). Alimenta el cartel de advertencia del panel.
        const cambiosClienteRes = await pgQuery(
            `SELECT categoria, motivo, registrado_en, registrado_por FROM vb_historial
              WHERE order_code = $1 AND evento = 'cambios_cliente'
                AND registrado_en > COALESCE(
                    (SELECT MAX(registrado_en) FROM vb_historial WHERE order_code = $1 AND evento = 'enviado'),
                    TIMESTAMPTZ '1970-01-01')
              ORDER BY registrado_en`,
            [orderCode]
        );
        const cambiosCliente = cambiosClienteRes.rows.map((r) => ({
            categoria: VB_CATEGORIAS_CAMBIO_LABEL[r.categoria] || r.categoria || '',
            motivo: r.motivo || '',
            por: r.registrado_por || '',
            en: r.registrado_en || null
        }));

        res.json({
            ok: true,
            data: {
                orden: {
                    codigo: orderCode,
                    cliente: quoteRes.rows[0]?.customer_name || orden.customer_name || '',
                    vendedor: quoteRes.rows[0]?.salesperson_name || '',
                    estado: orden.order_status || '',
                    actualizado: orden.vigente_actualizado_en || null
                },
                // Información General (pestaña nueva): datos de identidad del pedido que hoy
                // viven a nivel de orden (constantes entre motivos) — Referencia/Insumos vienen
                // de la Solicitud del vendedor; Tipo de Etiquetado/Tipo de Salida ya existían.
                general: {
                    // "Tipo de Trabajo" (Nuevo/Repetición/Muestra/…, lo que elige el vendedor en el
                    // Cálculo) es un dato DISTINTO de "Nombre del Trabajo" (el título/descripción del
                    // trabajo) — no confundirlos, ver [[project_referencia_insumos_aplicacion_columnas]].
                    // Respaldo al cálculo (calc): la orden es una foto del momento en que se creó —
                    // si el vendedor llena Referencia/Insumos/SKU Cliente en el cálculo DESPUÉS de
                    // creada la orden, la orden no se actualiza sola. Mientras no exista un mecanismo
                    // que sincronice la orden ya creada, se usa el cálculo como respaldo en vivo.
                    tipoTrabajo: orden.tipo_trabajo || calc.tipo_trabajo || '',
                    nombreTrabajo: orden.job_name || '',
                    tipoProducto: orden.product_type || calc.product_type || '',
                    referencia: orden.referencia_cliente || calc.referencia_cliente || '',
                    referenciaComentario: orden.referencia_comentario || calc.referencia_comentario || '',
                    referenciaCambios: orden.referencia_cambios || calc.referencia_cambios || '',
                    insumosCliente: orden.insumos_cliente || calc.insumos_cliente || '',
                    aplicacion: orden.ambiente_aplicacion || calc.ambiente_aplicacion || '',
                    tipoEtiquetado: orden.application_type || '',
                    tipoSalida: orden.output_type || '',
                    // Respaldo a nivel de orden para cuando el motivo todavía no tiene fila propia
                    // en flexo_products (línea sin producto creado) — la orden ya trae su propia
                    // copia de estos datos desde que se creó.
                    materialName: orden.material_nombre || calc.material_nombre || '',
                    skuLocal: orden.finished_product_sku || calc.finished_product_sku || '',
                    skuCliente: orden.codigo_producto_cliente || calc.codigo_producto_cliente || ''
                },
                cambiosCliente,
                medida: { anchoIn: wIn || null, largoIn: lIn || null, anchoMm: toMm(wIn), largoMm: toMm(lIn) },
                spec: {
                    // Forma la define el TROQUEL (troquel_forma en calc/orden/producto). Solo lectura en el panel.
                    formaTroquel: orden.troquel_forma || prod0.troquel_forma || calc.troquel_forma || '',
                    forma: orden.diseno_forma_vigente || prod0.diseno_forma_vigente || '',
                    sangradoIn: (orden.diseno_sangrado_vigente_in ?? prod0.diseno_sangrado_vigente_in) != null
                        ? Number(orden.diseno_sangrado_vigente_in ?? prod0.diseno_sangrado_vigente_in) : null,
                    notas: orden.diseno_notas_cliente_vigente || prod0.diseno_notas_cliente_vigente || ''
                },
                acabados,
                troquel: disenoTroquelInfo.troquel,
                cilindrosCompatibles: disenoTroquelInfo.cilindrosCompatibles,
                aprobacion: {
                    aprobadoPor: orden.diseno_aprobado_por || '',
                    aprobadoEn: orden.diseno_aprobado_en || null,
                    borradorEn: orden.diseno_borrador_guardado_en || null
                },
                archivos: (archivosRes.rows || []).map((a) => ({
                    id: a.id,
                    motivoIndice: a.motivo_indice,
                    versionIndice: a.version_indice,
                    nombre: a.nombre_archivo,
                    tipo: a.tipo || (a.nombre_archivo || '').split('.').pop().toUpperCase(),
                    categoria: a.categoria || '',
                    estado: a.estado || 'referencia',
                    tamanoBytes: Number(a.tamano_bytes || 0),
                    por: a.creado_por || '',
                    en: a.creado_en || null,
                    aprobadoPor: a.aprobado_por || '',
                    aprobadoEn: a.aprobado_en || null
                })),
                motivos: (motivos || []).map((m) => ({
                    ...m,
                    versiones: (m.versiones || []).map((v) => ({ ...v, artes: artesByKey[`${m.indice}:${v.indice}`] || [] }))
                }))
            }
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el panel de diseño.' });
    }
});

// Panel de Tintas — mismo formato que el Panel de Diseño (Tintas aprueba la receta que
// definió Preprensa, viendo arte/acabados/especificación). Aprobación y archivos técnicos
// propios de Tintas; arte, especificación y acabados se leen de la misma orden (compartidos).
app.get('/api/produccion-tintas', async (req, res) => {
    try {
        const orderCode = String(req.query.orden || req.query.orderCode || '').trim();
        if (!orderCode) return res.status(400).json({ ok: false, error: 'Falta el parámetro ?orden.' });
        const ordRes = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
        const orden = ordRes.rows[0];
        if (!orden) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });

        const [motivos, prodRes, calcRes, quoteRes, artesRes, archivosRes] = await Promise.all([
            buildOrderMotivosDetalle(orden),
            pgQuery(
                `SELECT motivo_indice, width_inches, length_inches, quantity,
                        barniz_tipo, barniz_zonificado, laminado_tipo, estampado_tipo, embosado_tipo,
                        die_code, numerado_tipo, application_type, troquel_forma,
                        diseno_forma_vigente, diseno_orientacion_vigente, diseno_sangrado_vigente_in, diseno_notas_cliente_vigente
                   FROM flexo_products WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice`,
                [orden.quote_code, orden.line_code]
            ),
            pgQuery(
                `SELECT width_inches, length_inches,
                        COALESCE(troquel_forma, raw_data->>'troquel_forma', raw_data->'line_snapshot'->>'troquelForma', raw_data->'line_snapshot'->>'troquel_forma') AS troquel_forma,
                        COALESCE(barniz_tipo, raw_data->>'barniz_tipo', raw_data->'line_snapshot'->>'barnizTipo', raw_data->'line_snapshot'->>'barniz_tipo') AS barniz_tipo,
                        COALESCE(barniz_zonificado, (raw_data->'line_snapshot'->>'barnizZonificado')::boolean, (raw_data->'line_snapshot'->>'barniz_zonificado')::boolean) AS barniz_zonificado,
                        COALESCE(laminado_tipo, raw_data->>'laminado_tipo', raw_data->'line_snapshot'->>'laminadoTipo', raw_data->'line_snapshot'->>'laminado_tipo') AS laminado_tipo,
                        COALESCE(estampado_tipo, raw_data->>'estampado_tipo', raw_data->'line_snapshot'->>'estampadoTipo', raw_data->'line_snapshot'->>'estampado_tipo') AS estampado_tipo,
                        COALESCE(die_code, raw_data->>'die_code', raw_data->'line_snapshot'->>'dieCode', raw_data->'line_snapshot'->>'die_code') AS die_code
                   FROM flexo_calculations
                  WHERE quote_code = $1 AND line_code = $2 ORDER BY created_at DESC LIMIT 1`,
                [orden.quote_code, orden.line_code]
            ),
            pgQuery(`SELECT customer_name, salesperson_name FROM quotes WHERE quote_code = $1 LIMIT 1`, [orden.quote_code]),
            pgQuery(
                `SELECT id, motivo_indice, version_indice, nombre_arte, imagen_url, creado_por, creado_en
                   FROM produccion_artes WHERE orden_codigo = $1 ORDER BY creado_en ASC`,
                [orderCode]
            ),
            pgQuery(
                `SELECT id, motivo_indice, version_indice, nombre_archivo, tipo, categoria, estado,
                        tamano_bytes, creado_por, creado_en, aprobado_por, aprobado_en
                   FROM tintas_archivos WHERE orden_codigo = $1 ORDER BY creado_en ASC`,
                [orderCode]
            )
        ]);

        const prod0 = prodRes.rows[0] || {};
        const calc = calcRes.rows[0] || {};
        const wIn = Number(calc.width_inches || prod0.width_inches || orden.width_inches || 0);
        const lIn = Number(calc.length_inches || prod0.length_inches || orden.length_inches || 0);
        const toMm = (inch) => (inch > 0 ? Math.round(inch * 25.4 * 10) / 10 : null);

        const artesByKey = {};
        artesRes.rows.forEach((a) => {
            const k = `${a.motivo_indice ?? 0}:${a.version_indice ?? 0}`;
            (artesByKey[k] = artesByKey[k] || []).push({ id: a.id, url: a.imagen_url, nombre: a.nombre_arte, por: a.creado_por, en: a.creado_en });
        });

        const acabVal = (k) => prod0[k] || orden[k] || calc[k] || '';
        const barnizTipo = acabVal('barniz_tipo');
        const barnizZonif = (prod0.barniz_zonificado ?? orden.barniz_zonificado ?? calc.barniz_zonificado) === true;
        const barnizZona = prod0.barniz_zona_vigente || orden.barniz_zona_vigente || '';
        const laminadoTipo = acabVal('laminado_tipo');
        const estampadoTipo = acabVal('estampado_tipo');
        const foilColor = prod0.foil_color_vigente || orden.foil_color_vigente || '';
        const dieCode = prod0.troquel_codigo_vigente || orden.troquel_codigo_vigente || acabVal('die_code');
        const acabados = [
            {
                nombre: 'Barniz',
                activo: DISENO_ACABADO_ACTIVO(barnizTipo),
                detalle: [barnizTipo, barnizZonif ? ('Reservado' + (barnizZona ? ` (${barnizZona})` : '')) : ''].filter(Boolean).join(' · ')
            },
            { nombre: 'Laminado', activo: DISENO_ACABADO_ACTIVO(laminadoTipo), detalle: laminadoTipo },
            {
                nombre: 'Estampado',
                activo: DISENO_ACABADO_ACTIVO(estampadoTipo),
                detalle: [estampadoTipo, foilColor].filter(Boolean).join(' · ')
            },
            { nombre: 'Troquelado', activo: DISENO_ACABADO_ACTIVO(dieCode), detalle: dieCode }
        ];

        // Cambios del cliente todavía sin resolver: los registrados después del último 'enviado'
        // (si nunca se volvió a enviar, todos). Alimenta el cartel de advertencia del panel.
        const cambiosClienteRes = await pgQuery(
            `SELECT categoria, motivo, registrado_en, registrado_por FROM vb_historial
              WHERE order_code = $1 AND evento = 'cambios_cliente'
                AND registrado_en > COALESCE(
                    (SELECT MAX(registrado_en) FROM vb_historial WHERE order_code = $1 AND evento = 'enviado'),
                    TIMESTAMPTZ '1970-01-01')
              ORDER BY registrado_en`,
            [orderCode]
        );
        const cambiosCliente = cambiosClienteRes.rows.map((r) => ({
            categoria: VB_CATEGORIAS_CAMBIO_LABEL[r.categoria] || r.categoria || '',
            motivo: r.motivo || '',
            por: r.registrado_por || '',
            en: r.registrado_en || null
        }));

        res.json({
            ok: true,
            data: {
                orden: {
                    codigo: orderCode,
                    cliente: quoteRes.rows[0]?.customer_name || orden.customer_name || '',
                    vendedor: quoteRes.rows[0]?.salesperson_name || '',
                    estado: orden.order_status || '',
                    actualizado: orden.vigente_actualizado_en || null
                },
                general: {
                    tipoTrabajo: orden.tipo_trabajo || calc.tipo_trabajo || '',
                    nombreTrabajo: orden.job_name || '',
                    tipoProducto: orden.product_type || calc.product_type || '',
                    referencia: orden.referencia_cliente || calc.referencia_cliente || '',
                    referenciaComentario: orden.referencia_comentario || calc.referencia_comentario || '',
                    referenciaCambios: orden.referencia_cambios || calc.referencia_cambios || '',
                    insumosCliente: orden.insumos_cliente || calc.insumos_cliente || '',
                    aplicacion: orden.ambiente_aplicacion || calc.ambiente_aplicacion || '',
                    tipoEtiquetado: orden.application_type || '',
                    tipoSalida: orden.output_type || '',
                    materialName: orden.material_nombre || calc.material_nombre || '',
                    skuLocal: orden.finished_product_sku || calc.finished_product_sku || '',
                    skuCliente: orden.codigo_producto_cliente || calc.codigo_producto_cliente || ''
                },
                cambiosCliente,
                medida: { anchoIn: wIn || null, largoIn: lIn || null, anchoMm: toMm(wIn), largoMm: toMm(lIn) },
                spec: {
                    formaTroquel: orden.troquel_forma || prod0.troquel_forma || calc.troquel_forma || '',
                    forma: orden.diseno_forma_vigente || prod0.diseno_forma_vigente || '',
                    sangradoIn: (orden.diseno_sangrado_vigente_in ?? prod0.diseno_sangrado_vigente_in) != null
                        ? Number(orden.diseno_sangrado_vigente_in ?? prod0.diseno_sangrado_vigente_in) : null,
                    notas: orden.diseno_notas_cliente_vigente || prod0.diseno_notas_cliente_vigente || ''
                },
                acabados,
                aprobacion: {
                    aprobadoPor: orden.tintas_aprobado_por || '',
                    aprobadoEn: orden.tintas_aprobado_en || null
                },
                archivos: (archivosRes.rows || []).map((a) => ({
                    id: a.id,
                    motivoIndice: a.motivo_indice,
                    versionIndice: a.version_indice,
                    nombre: a.nombre_archivo,
                    tipo: a.tipo || (a.nombre_archivo || '').split('.').pop().toUpperCase(),
                    categoria: a.categoria || '',
                    estado: a.estado || 'referencia',
                    tamanoBytes: Number(a.tamano_bytes || 0),
                    por: a.creado_por || '',
                    en: a.creado_en || null,
                    aprobadoPor: a.aprobado_por || '',
                    aprobadoEn: a.aprobado_en || null
                })),
                motivos: (motivos || []).map((m) => ({
                    ...m,
                    versiones: (m.versiones || []).map((v) => ({ ...v, artes: artesByKey[`${m.indice}:${v.indice}`] || [] }))
                }))
            }
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el panel de tintas.' });
    }
});

// Panel de Preprensa — misma información del arte que Diseño (motivos, versiones, imágenes,
// forma/sangrado, acabados), de solo lectura: Preprensa la consulta pero no la edita ni sube
// archivos/aprueba desde acá todavía (eso queda pendiente de definir aparte). Se le agrega el
// detalle de Montaje y Troquel — troquel físico asignado al cálculo y cilindros compatibles
// por dentado — que es información propia de Preprensa y no existe en el panel de Diseño.
app.get('/api/produccion-preprensa', async (req, res) => {
    try {
        const orderCode = String(req.query.orden || req.query.orderCode || '').trim();
        if (!orderCode) return res.status(400).json({ ok: false, error: 'Falta el parámetro ?orden.' });
        const ordRes = await pgQuery(`SELECT * FROM flexo_orders WHERE order_code = $1 LIMIT 1`, [orderCode]);
        const orden = ordRes.rows[0];
        if (!orden) return res.status(404).json({ ok: false, error: 'Orden no encontrada.' });

        const planRes = await pgQuery(`SELECT lanzado_gantt FROM orden_planificacion WHERE codigo_orden = $1 LIMIT 1`, [orderCode]);
        const lanzadoGantt = Boolean(planRes.rows[0]?.lanzado_gantt);
        if (!lanzadoGantt) {
            return res.status(400).json({ ok: false, error: 'Esta orden aún no ha recibido la marca de Seguimiento.' });
        }

        const [motivos, prodRes, calcRes, quoteRes, artesRes] = await Promise.all([
            buildOrderMotivosDetalle(orden),
            pgQuery(
                `SELECT motivo_indice, width_inches, length_inches, quantity,
                        barniz_tipo, barniz_zonificado, laminado_tipo, estampado_tipo, embosado_tipo,
                        die_code, numerado_tipo, application_type, troquel_forma,
                        diseno_forma_vigente, diseno_orientacion_vigente, diseno_sangrado_vigente_in, diseno_notas_cliente_vigente
                   FROM flexo_products WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice`,
                [orden.quote_code, orden.line_code]
            ),
            pgQuery(
                `SELECT width_inches, length_inches,
                        COALESCE(troquel_forma, raw_data->>'troquel_forma', raw_data->'line_snapshot'->>'troquelForma', raw_data->'line_snapshot'->>'troquel_forma') AS troquel_forma,
                        COALESCE(barniz_tipo, raw_data->>'barniz_tipo', raw_data->'line_snapshot'->>'barnizTipo', raw_data->'line_snapshot'->>'barniz_tipo') AS barniz_tipo,
                        COALESCE(barniz_zonificado, (raw_data->'line_snapshot'->>'barnizZonificado')::boolean, (raw_data->'line_snapshot'->>'barniz_zonificado')::boolean) AS barniz_zonificado,
                        COALESCE(laminado_tipo, raw_data->>'laminado_tipo', raw_data->'line_snapshot'->>'laminadoTipo', raw_data->'line_snapshot'->>'laminado_tipo') AS laminado_tipo,
                        COALESCE(estampado_tipo, raw_data->>'estampado_tipo', raw_data->'line_snapshot'->>'estampadoTipo', raw_data->'line_snapshot'->>'estampado_tipo') AS estampado_tipo,
                        COALESCE(die_code, raw_data->>'die_code', raw_data->'line_snapshot'->>'dieCode', raw_data->'line_snapshot'->>'die_code') AS die_code,
                        COALESCE(tipo_trabajo, raw_data->>'tipo_trabajo', raw_data->'line_snapshot'->>'tipoTrabajo', raw_data->'line_snapshot'->>'tipo_trabajo') AS tipo_trabajo,
                        COALESCE(product_type, raw_data->>'product_type', raw_data->'line_snapshot'->>'productType', raw_data->'line_snapshot'->>'product_type') AS product_type,
                        COALESCE(codigo_producto_cliente, raw_data->>'codigo_producto_cliente', raw_data->'line_snapshot'->>'codigoProductoCliente', raw_data->'line_snapshot'->>'codigo_producto_cliente') AS codigo_producto_cliente,
                        COALESCE(referencia_cliente, raw_data->>'referencia_cliente', raw_data->'line_snapshot'->>'referenciaCliente', raw_data->'line_snapshot'->>'referencia_cliente') AS referencia_cliente,
                        COALESCE(referencia_comentario, raw_data->>'referencia_comentario', raw_data->'line_snapshot'->>'referenciaComentario', raw_data->'line_snapshot'->>'referencia_comentario') AS referencia_comentario,
                        COALESCE(referencia_cambios, raw_data->>'referencia_cambios', raw_data->'line_snapshot'->>'referenciaCambios', raw_data->'line_snapshot'->>'referencia_cambios') AS referencia_cambios,
                        COALESCE(insumos_cliente, raw_data->>'insumos_cliente', raw_data->'line_snapshot'->>'insumosCliente', raw_data->'line_snapshot'->>'insumos_cliente') AS insumos_cliente,
                        COALESCE(ambiente_aplicacion, raw_data->>'ambiente_aplicacion', raw_data->'line_snapshot'->>'ambienteAplicacion', raw_data->'line_snapshot'->>'ambiente_aplicacion') AS ambiente_aplicacion,
                        COALESCE(material_nombre, raw_data->>'material_nombre', raw_data->'line_snapshot'->>'materialNombre', raw_data->'line_snapshot'->>'material_nombre') AS material_nombre,
                        COALESCE(finished_product_sku, raw_data->>'finished_product_sku', raw_data->'line_snapshot'->>'finishedProductSku', raw_data->'line_snapshot'->>'finished_product_sku') AS finished_product_sku
                   FROM flexo_calculations
                  WHERE quote_code = $1 AND line_code = $2 ORDER BY created_at DESC LIMIT 1`,
                [orden.quote_code, orden.line_code]
            ),
            pgQuery(`SELECT customer_name, salesperson_name FROM quotes WHERE quote_code = $1 LIMIT 1`, [orden.quote_code]),
            pgQuery(
                `SELECT id, motivo_indice, version_indice, nombre_arte, imagen_url, creado_por, creado_en
                   FROM produccion_artes WHERE orden_codigo = $1 ORDER BY creado_en ASC`,
                [orderCode]
            )
        ]);

        const prod0 = prodRes.rows[0] || {};
        const calc = calcRes.rows[0] || {};
        const wIn = Number(calc.width_inches || prod0.width_inches || orden.width_inches || 0);
        const lIn = Number(calc.length_inches || prod0.length_inches || orden.length_inches || 0);
        const toMm = (inch) => (inch > 0 ? Math.round(inch * 25.4 * 10) / 10 : null);

        const artesByKey = {};
        artesRes.rows.forEach((a) => {
            const k = `${a.motivo_indice ?? 0}:${a.version_indice ?? 0}`;
            (artesByKey[k] = artesByKey[k] || []).push({ id: a.id, url: a.imagen_url, nombre: a.nombre_arte, por: a.creado_por, en: a.creado_en });
        });

        const acabVal = (k) => prod0[k] || orden[k] || calc[k] || '';
        const barnizTipo = acabVal('barniz_tipo');
        const barnizZonif = (prod0.barniz_zonificado ?? orden.barniz_zonificado ?? calc.barniz_zonificado) === true;
        const barnizZona = prod0.barniz_zona_vigente || orden.barniz_zona_vigente || '';
        const laminadoTipo = acabVal('laminado_tipo');
        const estampadoTipo = acabVal('estampado_tipo');
        const foilColor = prod0.foil_color_vigente || orden.foil_color_vigente || '';
        const dieCode = prod0.troquel_codigo_vigente || orden.troquel_codigo_vigente || acabVal('die_code');
        const acabados = [
            {
                nombre: 'Barniz',
                activo: DISENO_ACABADO_ACTIVO(barnizTipo),
                detalle: [barnizTipo, barnizZonif ? ('Reservado' + (barnizZona ? ` (${barnizZona})` : '')) : ''].filter(Boolean).join(' · ')
            },
            { nombre: 'Laminado', activo: DISENO_ACABADO_ACTIVO(laminadoTipo), detalle: laminadoTipo },
            {
                nombre: 'Estampado',
                activo: DISENO_ACABADO_ACTIVO(estampadoTipo),
                detalle: [estampadoTipo, foilColor].filter(Boolean).join(' · ')
            },
            { nombre: 'Troquelado', activo: DISENO_ACABADO_ACTIVO(dieCode), detalle: dieCode }
        ];

        const { troquel, cilindrosCompatibles } = await buildTroquelInfoParaOrden(orden, prod0, calc);

        res.json({
            ok: true,
            data: {
                orden: {
                    codigo: orderCode,
                    cliente: quoteRes.rows[0]?.customer_name || orden.customer_name || '',
                    vendedor: quoteRes.rows[0]?.salesperson_name || '',
                    estado: orden.order_status || '',
                    actualizado: orden.vigente_actualizado_en || null
                },
                // Información General (mismo bloque que /api/produccion-diseno) — sin esto el
                // panel de Preprensa mostraba Tipo de Trabajo/Producto/SKU/Tipo de Salida vacíos
                // aunque el dato sí estuviera guardado en flexo_orders/flexo_calculations.
                general: {
                    tipoTrabajo: orden.tipo_trabajo || calc.tipo_trabajo || '',
                    nombreTrabajo: orden.job_name || '',
                    tipoProducto: orden.product_type || calc.product_type || '',
                    referencia: orden.referencia_cliente || calc.referencia_cliente || '',
                    referenciaComentario: orden.referencia_comentario || calc.referencia_comentario || '',
                    referenciaCambios: orden.referencia_cambios || calc.referencia_cambios || '',
                    insumosCliente: orden.insumos_cliente || calc.insumos_cliente || '',
                    aplicacion: orden.ambiente_aplicacion || calc.ambiente_aplicacion || '',
                    tipoEtiquetado: orden.application_type || '',
                    tipoSalida: orden.output_type || '',
                    materialName: orden.material_nombre || calc.material_nombre || '',
                    skuLocal: orden.finished_product_sku || calc.finished_product_sku || '',
                    skuCliente: orden.codigo_producto_cliente || calc.codigo_producto_cliente || ''
                },
                medida: { anchoIn: wIn || null, largoIn: lIn || null, anchoMm: toMm(wIn), largoMm: toMm(lIn) },
                spec: {
                    formaTroquel: orden.troquel_forma || prod0.troquel_forma || calc.troquel_forma || '',
                    forma: orden.diseno_forma_vigente || prod0.diseno_forma_vigente || '',
                    sangradoIn: (orden.diseno_sangrado_vigente_in ?? prod0.diseno_sangrado_vigente_in) != null
                        ? Number(orden.diseno_sangrado_vigente_in ?? prod0.diseno_sangrado_vigente_in) : null,
                    notas: orden.diseno_notas_cliente_vigente || prod0.diseno_notas_cliente_vigente || ''
                },
                acabados,
                troquel,
                cilindrosCompatibles,
                motivos: (motivos || []).map((m) => ({
                    ...m,
                    versiones: (m.versiones || []).map((v) => ({ ...v, artes: artesByKey[`${m.indice}:${v.indice}`] || [] }))
                }))
            }
        });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible cargar el panel de preprensa.' });
    }
});

// Sube (o reemplaza) la imagen de referencia de una versión.
app.post('/api/produccion/artes', async (req, res) => {
    try {
        const { orderCode, orden, motivoIndice, versionIndice, nombre, imagenBase64, proceso } = req.body || {};
        const codigo = String(orderCode || orden || '').trim();
        if (!codigo || !imagenBase64) return res.status(400).json({ ok: false, error: 'Debes indicar la orden y la imagen.' });
        const claveProceso = proceso === 'tintas' ? 'tintas' : 'diseno';
        const actor = getRequestUserName(req);
        let imagenUrl = null;
        try { imagenUrl = await guardarImagenArte(imagenBase64, codigo); } catch (e) { /* imagen inválida */ }
        if (!imagenUrl) return res.status(400).json({ ok: false, error: 'La imagen no es válida.' });
        const rutaRes = await pgQuery(
            `SELECT id FROM orden_proceso WHERE codigo_orden = $1 AND clave_proceso = $2 ORDER BY secuencia LIMIT 1`,
            [codigo, claveProceso]
        );
        const ins = await pgQuery(
            `INSERT INTO produccion_artes (orden_codigo, ruta_id, proceso_clave, nombre_arte, imagen_url, creado_por, motivo_indice, version_indice)
             VALUES ($1,$2,$8,$3,$4,$5,$6,$7)
             RETURNING id, imagen_url, creado_por, creado_en`,
            [
                codigo, rutaRes.rows[0]?.id || null, (nombre || '').trim() || null, imagenUrl, actor || null,
                motivoIndice != null && motivoIndice !== '' ? Number(motivoIndice) : null,
                versionIndice != null && versionIndice !== '' ? Number(versionIndice) : null,
                claveProceso
            ]
        );
        res.json({ ok: true, arte: { id: ins.rows[0].id, url: ins.rows[0].imagen_url, por: ins.rows[0].creado_por, en: ins.rows[0].creado_en } });
    } catch (error) {
        res.status(500).json({ ok: false, error: error.message || 'No fue posible guardar el arte.' });
    }
});

