async function ensureOfficialQueriesSchema() {
    await pgQuery(`
        CREATE TABLE IF NOT EXISTS official_queries (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            clave TEXT NOT NULL UNIQUE,
            etiqueta TEXT NOT NULL DEFAULT '',
            modulo TEXT NOT NULL DEFAULT 'inventarios-sap',
            sql_text TEXT NOT NULL DEFAULT '',
            is_active BOOLEAN NOT NULL DEFAULT TRUE,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    `);
    // Semilla SOLO si la clave no existe: si un día se edita una consulta desde la
    // pantalla, reiniciar el servidor no debe borrar esa edición.
    for (const consulta of CONSULTAS_OFICIALES_INVENTARIOS) {
        await pgQuery(`
            INSERT INTO official_queries (clave, etiqueta, modulo, sql_text)
            VALUES ($1, $2, 'inventarios-sap', $3)
            ON CONFLICT (clave) DO NOTHING
        `, [consulta.clave, consulta.etiqueta, consulta.sql]);
    }
    for (const consulta of CONSULTAS_OFICIALES_FLUJOS) {
        await pgQuery(`
            INSERT INTO official_queries (clave, etiqueta, modulo, sql_text)
            VALUES ($1, $2, 'automatizacion-sap', $3)
            ON CONFLICT (clave) DO NOTHING
        `, [consulta.clave, consulta.etiqueta, consulta.sql]);
    }
}

app.get('/api/costos/consultas-oficiales', async (req, res) => {
    try {
        const incluirFlujos = String(req.query.flujos || '') === '1';
        const result = await pgQuery(`
            SELECT clave, etiqueta, modulo, sql_text
              FROM official_queries
             WHERE is_active = TRUE
               AND modulo = 'inventarios-sap'
          ORDER BY clave
        `);
        const respuesta = { consultas: result.rows.map((row) => ({
            clave: row.clave,
            etiqueta: row.etiqueta,
            sql: row.sql_text
        })) };
        if (incluirFlujos) {
            const flujosDb = await pgQuery(`
                SELECT clave, etiqueta, sql_text
                  FROM official_queries
                 WHERE is_active = TRUE
                   AND modulo = 'automatizacion-sap'
              ORDER BY clave
            `);
            const definiciones = getSapMirrorProcessDefinitions();
            respuesta.flujos = flujosDb.rows.map((row) => {
                const def = definiciones.find((d) => d.clave === row.clave);
                return {
                    clave: row.clave,
                    etiqueta: row.etiqueta || def?.etiqueta || row.clave,
                    entidades: def?.entidades || '',
                    sql: row.sql_text,
                    sqlRelacionadas: [],
                    nota: def?.nota || '',
                    editable: true
                };
            });
        }
        res.json(respuesta);
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar las consultas oficiales.' });
    }
});

app.get('/api/costos/consultas-oficiales/:clave', async (req, res) => {
    try {
        const result = await pgQuery(`
            SELECT clave, etiqueta, modulo, sql_text, updated_at
              FROM official_queries
             WHERE is_active = TRUE
               AND clave = $1
        `, [String(req.params.clave || '')]);
        if (!result.rows.length) {
            return res.status(404).json({ error: 'No existe esa consulta oficial.' });
        }
        const row = result.rows[0];
        res.json({ consulta: { clave: row.clave, etiqueta: row.etiqueta, modulo: row.modulo, sql: row.sql_text, updatedAt: row.updated_at } });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar la consulta oficial.' });
    }
});

app.put('/api/costos/consultas-oficiales/:clave', async (req, res) => {
    try {
        const clave = String(req.params.clave || '').trim();
        const sqlText = String(req.body?.sql || '');
        if (!clave) return res.status(400).json({ error: 'Falta la clave de la consulta.' });
        if (!sqlText.trim()) return res.status(400).json({ error: 'La consulta no puede quedar vacía.' });
        const result = await pgQuery(`
            UPDATE official_queries
               SET sql_text = $2, updated_at = NOW()
             WHERE clave = $1
         RETURNING clave, etiqueta, modulo, sql_text, updated_at
        `, [clave, sqlText]);
        if (!result.rows.length) {
            return res.status(404).json({ error: 'No existe esa consulta oficial.' });
        }
        const row = result.rows[0];
        res.json({ ok: true, consulta: { clave: row.clave, etiqueta: row.etiqueta, sql: row.sql_text, updatedAt: row.updated_at } });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible guardar la consulta oficial.' });
    }
});

app.get('/api/costos/inventarios-sap', async (req, res) => {
    try {
        const search = String(req.query.search || '').trim().toLowerCase().slice(0, 80);
        const categoriasSolicitadas = String(req.query.categorias || '')
            .split(',')
            .map((valor) => valor.trim())
            .filter(Boolean);
        const categorias = categoriasSolicitadas.length
            ? SAP_INVENTARIO_CATEGORIAS.filter((categoria) => categoriasSolicitadas.includes(categoria.clave))
            : SAP_INVENTARIO_CATEGORIAS;
        // Cada artículo guarda el código de clasificación de SAP (p. ej. "1"); el mapeo
        // traduce ese código a la categoría flexo (p. ej. "Sustrato"). Se resuelve aquí
        // para poder filtrar por categoría real en la consulta.
        const mappings = await pgQuery(`
            SELECT source_value, flexo_category
              FROM inventory_classification_mappings
             WHERE is_active = TRUE
        `);
        const categoriaPorFuente = new Map(
            mappings.rows.map((row) => [
                String(row.source_value || '').trim().toLowerCase(),
                String(row.flexo_category || '').trim().toLowerCase()
            ])
        );
        const resultado = [];
        for (const categoria of categorias) {
            const valores = [];
            const filtros = [];
            const fuentesCategoriaSet = new Set(
                [...categoriaPorFuente.entries()]
                    .filter(([, nombreCategoria]) => categoria.mapeo.includes(nombreCategoria))
                    .map(([codigoFuente]) => codigoFuente)
            );
            const condicionesMapeo = [...fuentesCategoriaSet].map((codigoFuente) => {
                valores.push(codigoFuente);
                return `LOWER(TRIM(classification_source_value)) = $${valores.length}`;
            });
            const condicionesTexto = categoria.incluye.map((regla) => {
                valores.push(regla.modo === 'prefijo' ? `${regla.patron}%` : `%${regla.patron}%`);
                return `LOWER(item_name) LIKE $${valores.length}`;
            });
            const exclusionesTexto = categoria.excluye.map((palabra) => {
                valores.push(`%${palabra}%`);
                return `LOWER(item_name) NOT LIKE $${valores.length}`;
            });
            const exclusionesGrupo = categoria.gruposExcluidos.map((grupo) => {
                valores.push(grupo);
                return `LOWER(TRIM(item_group_code)) <> $${valores.length}`;
            });
            let condicionGrupoFijo = '';
            if (categoria.grupoFijo) {
                valores.push(categoria.grupoFijo);
                condicionGrupoFijo = `LOWER(TRIM(item_group_code)) = $${valores.length}`;
            }
            const condicionesInclusion = [...condicionesMapeo, ...condicionesTexto];
            if (condicionGrupoFijo) {
                filtros.push(condicionesInclusion.length
                    ? `(${condicionGrupoFijo} OR ${condicionesInclusion.map((c) => `(${c})`).join(' OR ')})`
                    : condicionGrupoFijo);
            } else if (condicionesInclusion.length) {
                filtros.push(condicionesInclusion.map((condicion) => `(${condicion})`).join(' OR '));
            }
            filtros.push(...exclusionesTexto, ...exclusionesGrupo);
            if (search) {
                valores.push(`%${search}%`);
                filtros.push(`(LOWER(item_name) LIKE $${valores.length} OR LOWER(item_code) LIKE $${valores.length})`);
            }
            const result = await pgQuery(`
                SELECT item_code, item_name, item_group_code, classification_source_value,
                       on_hand, available_quantity, COALESCE(sales_unit_msr, buy_unit_msr) AS uom,
                       price, currency, ancho_mm, gramaje_g_m2, calibre_micras, proveedor, marca, synced_at
                  FROM sap_items
                 WHERE ${filtros.join(' AND ')}
              ORDER BY item_name ASC, item_code ASC
                 LIMIT 2000
            `, valores);
            const filas = result.rows.map((row) => ({
                ...row,
                via: matchSapInventarioCategoria(row, categoria, fuentesCategoriaSet).via
            }));
            const conClasificacion = filas.filter((row) => row.via === 'clasificacion').length;
            const conTexto = filas.length - conClasificacion;
            const conExistencia = filas.filter((row) => Number(row.on_hand || 0) > 0).length;
            const conPrecio = filas.filter((row) => Number(row.price || 0) > 0).length;
            const ultimaSync = filas.reduce((maxima, row) => {
                const fecha = row.synced_at ? new Date(row.synced_at).getTime() : 0;
                return Number.isFinite(fecha) && fecha > maxima ? fecha : maxima;
            }, 0);
            resultado.push({
                clave: categoria.clave,
                etiqueta: categoria.etiqueta,
                consulta: categoria.consulta,
                total: filas.length,
                limiteAlcanzado: filas.length >= 2000,
                conClasificacion,
                conTexto,
                conExistencia,
                conPrecio,
                ultimaSync: ultimaSync ? new Date(ultimaSync).toISOString() : null,
                filas
            });
        }
        res.json({ categorias: resultado });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar los inventarios SAP.' });
    }
});

app.post('/api/flexo/calculo/guardar', async (req, res) => {
    try {
        const incomingPayload = req.body || {};
        const payload = { ...incomingPayload };
        const quoteCode = pickFirstValue(payload.quoteCode, payload.quote_code);
        const currentLineCode = pickFirstValue(payload.originalLineCode, payload.lineCode, payload.line_code);
        if (!quoteCode || !currentLineCode) {
            return res.status(400).json({ error: 'Debes indicar quoteCode y lineCode.' });
        }

        const existing = await pgQuery(
            `SELECT calculation_code, raw_data,
                    quantity_changes_additional, quantity_changes_by_types, quantity_changes_total,
                    change_time_minutes, change_machine_hour_cost, change_labor_hour_cost,
                    change_operators, change_waste_cost, change_additional_prep_cost,
                    quote_code, line_code, customer_code, customer_name, salesperson_name, department, job_name, line_status,
                    application_type, output_type, quantity_types, quantity_changes, core_width, core_diameter, labels_per_roll, cmyk_enabled, width_inches, length_inches, material_nombre, material_nombre
               FROM flexo_calculations
              WHERE quote_code = $1 AND line_code = $2
              ORDER BY created_at DESC NULLS LAST
              LIMIT 1`,
            [quoteCode, currentLineCode]
        );

        if (!existing.rows.length) {
            return res.status(404).json({ error: 'No se encontró la línea a guardar.' });
        }
        const existingGroup = normalizeFrontBackGroup(existing.rows[0].raw_data || {});
        if (existingGroup && existingGroup.role === 'elemento') {
            const groupContext = await loadFrontBackGroupContext(quoteCode, { quote_code: quoteCode, line_code: currentLineCode, raw_data: existing.rows[0].raw_data });
            const groupQuantity = frontBackLineQuantity(groupContext.groupLine);
            payload.quantityProducts = groupQuantity;
        }

        const lineCode = pickFirstValue(payload.lineCode, payload.line_code, currentLineCode);
        const machineName = await resolveSingleInventoryMachineName(payload.machineName);
        const { rawData, changeMeta, resolved } = buildCalculationRawData({
            quote_code: quoteCode,
            line_code: lineCode,
            customer_code: payload.customerCode,
            customer_name: payload.customerName,
            salesperson_name: payload.salespersonName,
            process_type: payload.processType,
            material_code: payload.materialId,
            material_name: payload.materialName,
            die_code: payload.dieId,
            machine_name: machineName,
            quantityProducts: payload.quantityProducts,
            quantityTypes: payload.quantityTypes,
            quantityChanges: payload.quantityChanges,
            quantityChangesAdditional: payload.quantityChangesAdditional,
            changeCost: payload.changeCost,
            types: payload.types,
            widthInches: payload.widthInches,
            lengthInches: payload.lengthInches,
            stationCount: payload.stationCount,
            labelsPerRoll: payload.labelsPerRoll,
            coreWidth: payload.uiState?.coreWidth ?? payload.coreWidth,
            coreDiameter: payload.uiState?.coreDiameter ?? payload.coreDiameter,
            applicationType: payload.applicationType,
            applicationEnvironment: payload.applicationEnvironment,
            surfaceType: payload.surfaceType,
            outputType: payload.outputType,
            cmyk: payload.cmyk,
            uiState: payload.uiState,
            total_cost: payload.finalTotal,
            unit_price: payload.unitPrice,
            status: payload.lineStatus,
            job_name: payload.jobName,
            department: payload.department,
            processResult: payload.processResult
        }, existing.rows[0].raw_data || {}, existing.rows[0]);
        const validationMessages = Array.isArray(payload.validationMessages)
            ? payload.validationMessages.map((item) => sanitizeAdminUserText(item)).filter(Boolean)
            : [];
        const validationSummary = sanitizeAdminUserText(payload.validationSummary, validationMessages.join(' '));
        const validationBlocked = Boolean(payload.validationBlocking || validationSummary);
        rawData['ANALISIS CAMPOS SOLICITUD'] = validationBlocked ? validationSummary : '';
        rawData['ANALISIS CAMPOS FINALIZAR'] = validationBlocked ? validationSummary : '';
        rawData['ANALISIS CAMPOS CREAR ORDEN'] = validationBlocked ? validationSummary : '';
        rawData['ANALISIS CAMPOS PDF'] = validationBlocked ? validationSummary : '';
        rawData['Mensajes_Validacion'] = validationMessages;
        rawData['Validacion_Bloqueada'] = validationBlocked;
        applyCurrencyFieldsToRawData(rawData, payload.exchangeRate ?? payload.exchange_rate);
        if (Object.prototype.hasOwnProperty.call(payload, 'finalized_for_order') || Object.prototype.hasOwnProperty.call(payload, 'finalizedForOrder')) {
            rawData['Finalizado_Para_Orden'] = Boolean(Object.prototype.hasOwnProperty.call(payload, 'finalized_for_order')
                ? payload.finalized_for_order
                : payload.finalizedForOrder);
        }
        const finalizeValidation = proformaBlockingMessagesFromRaw(rawData).join(' ');
        if (Boolean(rawData['Finalizado_Para_Orden']) && finalizeValidation) {
            throw new Error(finalizeValidation);
        }
        const normalizedGroup = normalizeFrontBackGroup(rawData);
        if (normalizedGroup) {
            applyFrontBackQuantityToRawData(rawData, parseLegacyNumber(payload.quantityProducts) ?? 0);
        }
        applyCalculationLineSummary(rawData, {
            quote_code: quoteCode,
            line_code: lineCode,
            product_code: payload.productCode,
            customer_code: payload.customerCode,
            process_type: payload.processType,
            machine_name: machineName,
            die_code: payload.dieId,
            material_code: payload.materialId,
            quantity: parseLegacyNumber(payload.quantityProducts),
            total_cost: parseLegacyNumber(payload.finalTotal),
            unit_price: parseLegacyNumber(payload.unitPrice)
        });
        const processResult = payload.processResult && typeof payload.processResult === 'object' ? payload.processResult : {};
        const prodColsGuardar = extractProductionColumns(rawData, changeMeta, resolved.processType, resolved.materialName);

        await pgQuery(
            `UPDATE flexo_calculations
                SET line_code = $3,
                    process_type = $4,
                    machine_name = $5,
                    die_code = $6,
                    material_code = $7,
                    quantity = $8,
                    subtotal_cost = $9,
                    total_cost = $10,
                    unit_price = $11,
                    customer_name = $13,
                    salesperson_name = $14,
                    job_name = $15,
                    line_status = $16,
                    width_inches = $17,
                    length_inches = $18,
                    labels_per_roll = $19,
                    quantity_types = $20,
                    quantity_changes = $21,
                    core_width = $22,
                    core_diameter = $23,
                    cmyk_enabled = $24,
                    application_type = $25,
                    surface_type = $26,
                    output_type = $27,
                    industrial_subtotal = $28,
                    overhead_cost = $29,
                    margin_amount = $30,
                    prepress_cost = $31,
                    packaging_cost = $32,
                    design_cost = $33,
                    additional_cost = $34,
                    discount_amount = $35,
                    tax_percent = $36,
                    tax_amount = $37,
                    ui_state = $38::jsonb,
                    updated_at = NOW(),
                    raw_data = $12::jsonb
                    ${PRODUCTION_COLUMN_NAMES.map((c, i) => `, ${c} = $${39 + i}`).join('')}
                    , etiquetas_por_caja = $${39 + PRODUCTION_COLUMN_NAMES.length}
                    , tipo_core = $${40 + PRODUCTION_COLUMN_NAMES.length}::jsonb
                    , costo_caja = $${41 + PRODUCTION_COLUMN_NAMES.length}
                    , empaque_tipo_caja = $${42 + PRODUCTION_COLUMN_NAMES.length}
                    , empaque_tipo_bolsa = $${43 + PRODUCTION_COLUMN_NAMES.length}
                    , empaque_cantidad_bolsas = $${44 + PRODUCTION_COLUMN_NAMES.length}
                    , empaque_costo_bolsas = $${45 + PRODUCTION_COLUMN_NAMES.length}
                    , ambiente_aplicacion = $${46 + PRODUCTION_COLUMN_NAMES.length}
              WHERE calculation_code = $1 AND quote_code = $2`,
            [
                existing.rows[0].calculation_code,
                quoteCode,
                lineCode,
                pickFirstValue(payload.processType, 'Convencional'),
                machineName || null,
                pickFirstValue(payload.dieId),
                pickFirstValue(payload.materialId),
                parseLegacyNumber(payload.quantityProducts),
                parseLegacyNumber(processResult.afterDiscount) ?? parseLegacyNumber(payload.finalTotal),
                parseLegacyNumber(payload.finalTotal),
                parseLegacyNumber(payload.unitPrice),
                JSON.stringify(rawData),
                resolved.customerName || null,
                resolved.salespersonName || null,
                resolved.jobName || null,
                resolved.lineStatus || null,
                parseLegacyNumber(resolved.widthInches),
                parseLegacyNumber(resolved.lengthInches),
                parseLegacyNumber(resolved.labelsPerRoll),
                parseLegacyNumber(resolved.quantityTypes),
                parseLegacyNumber(resolved.quantityChanges),
                parseLegacyNumber(resolved.coreWidth),
                resolved.coreDiameter || null,
                Boolean(resolved.cmykEnabled),
                resolved.applicationType || null,
                resolved.surfaceType || null,
                resolved.outputType || null,
                parseLegacyNumber(processResult.industrial) ?? parseLegacyNumber(rawData['GENERAL | 5 | SUBTOTAL']),
                parseLegacyNumber(processResult.overhead),
                parseLegacyNumber(processResult.margin),
                parseLegacyNumber(processResult.prepress?.subtotal),
                parseLegacyNumber(processResult.packaging?.subtotal),
                parseLegacyNumber(processResult.design?.subtotal),
                parseLegacyNumber(processResult.additional?.subtotal),
                parseLegacyNumber(processResult.discount),
                parseLegacyNumber(processResult.taxPct) ?? parseLegacyNumber(rawData['GENERAL | 8 | PORCENTAJE IVA']),
                parseLegacyNumber(processResult.tax) ?? parseLegacyNumber(rawData['GENERAL | 9 | Impuestos']),
                rawData['Estado_UI'] ? JSON.stringify(rawData['Estado_UI']) : null,
                ...PRODUCTION_COLUMN_NAMES.map((c) => prodColsGuardar[c] ?? null),
                parseLegacyNumber(payload.etiquetasPorCaja) ?? 0,
                payload.coreType ? JSON.stringify(payload.coreType) : null,
                parseLegacyNumber(payload.costoCaja) ?? 0,
                sanitizeAdminUserText(payload.tipoCaja) || null,
                sanitizeAdminUserText(payload.tipoBolsa) || null,
                parseLegacyNumber(payload.cantidadBolsas) ?? 0,
                parseLegacyNumber(payload.costoBolsas) ?? 0,
                resolved.ambienteAplicacion || null
            ]
        );

        try {
            await syncCalculoMotivosVersiones(quoteCode, lineCode, payload.uiState, payload.types);
        } catch (syncError) {
            console.error('No fue posible sincronizar calculo_motivos/calculo_versiones:', syncError.message);
        }

        // Trazabilidad del origen del sustrato: se guarda cómo estaba el interruptor de "Origen de
        // Inventario" al momento de guardar y de dónde salió el material, para poder auditarlo después.
        try {
            const trazaConfig = await loadGeneralConfig();
            const modoConfig = String(trazaConfig?.general?.inventorySourceMode || 'local').toLowerCase() === 'sap' ? 'sap' : 'local';
            const materialCode = pickFirstValue(payload.materialId) || '';
            let origen = 'local';
            let sapItemCode = null;
            let fichaOrigen = null;
            if (materialCode && modoConfig === 'sap') {
                const sapHit = await pgQuery(
                    `SELECT item_code, ancho_mm, gramaje_g_m2, calibre_micras FROM sap_items WHERE item_code = $1 LIMIT 1`,
                    [materialCode]
                );
                if (sapHit.rows.length) {
                    origen = 'sap';
                    sapItemCode = materialCode;
                    const f = sapHit.rows[0];
                    fichaOrigen = (Number(f.ancho_mm) > 0 && Number(f.gramaje_g_m2) > 0 && Number(f.calibre_micras) > 0)
                        ? 'sap_datos_completos'
                        : 'sap_datos_incompletos';
                }
            }
            await pgQuery(
                `UPDATE flexo_calculations
                    SET sustrato_origen_inventario = $3,
                        sustrato_origen_config = $4,
                        sustrato_sap_item_code = $5,
                        sustrato_ficha_origen = $6
                  WHERE calculation_code = $1 AND quote_code = $2`,
                [existing.rows[0].calculation_code, quoteCode, origen, modoConfig, sapItemCode, fichaOrigen]
            );
        } catch (trazaError) {
            console.error('No fue posible guardar la trazabilidad de origen del sustrato:', trazaError.message);
        }

        if (normalizedGroup && normalizedGroup.role === 'grupo') {
            await syncFrontBackGroupQuantity({
                quoteCode,
                group: normalizedGroup,
                quantity: parseLegacyNumber(payload.quantityProducts) ?? 0,
                excludeCalculationCode: existing.rows[0].calculation_code
            });
        }

        const detail = await pgQuery(
            `SELECT calculation_code, quote_code, line_code, product_code, customer_code, process_type, machine_name, die_code, material_code,
                    quantity, subtotal_cost, total_cost, unit_price, raw_data,
                    customer_name, salesperson_name, department, job_name, line_status,
                    application_type, output_type, quantity_types, quantity_changes, core_width, core_diameter, labels_per_roll, cmyk_enabled, width_inches, length_inches, material_nombre
               FROM flexo_calculations
              WHERE calculation_code = $1`,
            [existing.rows[0].calculation_code]
        );
        res.json({ calculo: mapFlexoCalculationDetail(detail.rows[0]) });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible guardar el cálculo.' });
    }
});

app.get('/api/flexo/calculo/:quoteCode/:lineCode/motivos', async (req, res) => {
    try {
        const { quoteCode, lineCode } = req.params;
        const [motivos, versiones, tintas] = await Promise.all([
            pgQuery(
                `SELECT motivo_indice, nombre, cantidad, cantidad_tintas, tinta_blanca, doble_blanca, cantidad_pantones
                   FROM calculo_motivos WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice`,
                [quoteCode, lineCode]
            ),
            pgQuery(
                `SELECT motivo_indice, version_indice, nombre, descripcion, cantidad
                   FROM calculo_versiones WHERE quote_code = $1 AND line_code = $2 ORDER BY motivo_indice, version_indice`,
                [quoteCode, lineCode]
            ),
            pgQuery(
                `SELECT t.motivo_indice, t.estacion_indice, t.tipo_tinta, t.etiqueta, t.pantone_id, t.cobertura_pct, t.activo,
                        pb.codigo_pantone, pb.nombre AS pantone_nombre
                   FROM calculo_motivo_tintas t
                   LEFT JOIN tintas.pantones_biblioteca pb ON pb.id = t.pantone_id
                  WHERE t.quote_code = $1 AND t.line_code = $2
                  ORDER BY t.motivo_indice, t.estacion_indice`,
                [quoteCode, lineCode]
            )
        ]);
        res.json({ motivos: motivos.rows, versiones: versiones.rows, tintas: tintas.rows });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar los motivos.' });
    }
});

// Estaciones de la máquina de Impresión del cálculo (modal "Detalle de Máquina"): anilox y
// cilindro del inventario asociados por número de estación. Generalizado entre motivos.
app.get('/api/flexo/calculo/estaciones-maquina', async (req, res) => {
    try {
        const quoteCode = String(req.query.quoteCode || '').trim();
        const lineCode = String(req.query.lineCode || '').trim();
        if (!quoteCode || !lineCode) {
            return res.status(400).json({ error: 'Debes indicar quoteCode y lineCode.' });
        }
        const { rows } = await pgQuery(
            `SELECT numero_estacion, anilox_id, anilox_codigo, cilindro_id, cilindro_codigo
               FROM calculo_estacion_maquina
              WHERE quote_code = $1 AND line_code = $2
              ORDER BY numero_estacion`,
            [quoteCode, lineCode]
        );
        res.json({
            estaciones: rows.map((row) => ({
                numeroEstacion: row.numero_estacion,
                aniloxId: row.anilox_id,
                aniloxCodigo: row.anilox_codigo || '',
                cilindroId: row.cilindro_id,
                cilindroCodigo: row.cilindro_codigo || ''
            }))
        });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible cargar las estaciones de la máquina.' });
    }
});

app.post('/api/flexo/calculo/estaciones-maquina', async (req, res) => {
    try {
        const quoteCode = String(req.body?.quoteCode || '').trim();
        const lineCode = String(req.body?.lineCode || '').trim();
        if (!quoteCode || !lineCode) {
            return res.status(400).json({ error: 'Debes indicar quoteCode y lineCode.' });
        }
        const entrada = Array.isArray(req.body?.estaciones) ? req.body.estaciones : [];
        const idOrNull = (value) => {
            const text = String(value == null ? '' : value).trim();
            return text ? text : null;
        };
        const filas = entrada
            .map((est) => ({
                numeroEstacion: Number(est?.numeroEstacion),
                aniloxId: idOrNull(est?.aniloxId),
                aniloxCodigo: String(est?.aniloxCodigo || '').trim(),
                cilindroId: idOrNull(est?.cilindroId),
                cilindroCodigo: String(est?.cilindroCodigo || '').trim()
            }))
            .filter((est) => Number.isInteger(est.numeroEstacion) && est.numeroEstacion > 0);

        await withTransaction(async (client) => {
            await client.query(
                `DELETE FROM calculo_estacion_maquina WHERE quote_code = $1 AND line_code = $2`,
                [quoteCode, lineCode]
            );
            for (const est of filas) {
                if (!est.aniloxCodigo && !est.cilindroCodigo && est.aniloxId == null && est.cilindroId == null) continue;
                await client.query(
                    `INSERT INTO calculo_estacion_maquina
                        (quote_code, line_code, numero_estacion, anilox_id, anilox_codigo, cilindro_id, cilindro_codigo, actualizado_en)
                     VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
                     ON CONFLICT (quote_code, line_code, numero_estacion)
                     DO UPDATE SET anilox_id = EXCLUDED.anilox_id, anilox_codigo = EXCLUDED.anilox_codigo,
                                   cilindro_id = EXCLUDED.cilindro_id, cilindro_codigo = EXCLUDED.cilindro_codigo,
                                   actualizado_en = NOW()`,
                    [quoteCode, lineCode, est.numeroEstacion, est.aniloxId, est.aniloxCodigo || null, est.cilindroId, est.cilindroCodigo || null]
                );
            }
        });
        res.json({ ok: true });
    } catch (error) {
        res.status(400).json({ error: error.message || 'No fue posible guardar las estaciones de la máquina.' });
    }
});

