app.put('/api/maquinas/:id/estaciones', async (req, res) => {
    try {
        const estaciones = Array.isArray(req.body?.estaciones) ? req.body.estaciones : [];
        await withTransaction(async (client) => {
            for (const est of estaciones) {
                const numero = Number(est?.numeroEstacion ?? est?.numero_estacion);
                if (!Number.isInteger(numero) || numero <= 0) continue;
                const carga = Math.max(0, Number(est?.cargaMinimaMl ?? est?.carga_minima_ml ?? 0));
                await client.query(
                    `INSERT INTO maquina_estacion_config (maquina_id, numero_estacion, carga_minima_ml)
                     VALUES ($1, $2, $3)
                     ON CONFLICT (maquina_id, numero_estacion)
                     DO UPDATE SET carga_minima_ml = EXCLUDED.carga_minima_ml, actualizado_en = NOW()`,
                    [req.params.id, numero, carga]
                );
            }
        });
        res.json({ ok: true });
    } catch (error) {
        res.status(400).json({ error: error.message || 'No fue posible guardar las estaciones de la máquina.' });
    }
});

