// ===================== LICENCIAMIENTO =====================

let _licenciaCache = { ts: 0, valor: null };

async function leerMarcaAguaDb() {
    try {
        const r = await pgQuery('SELECT marca FROM licenciamiento_marca_agua WHERE id = 1');
        const v = r.rows && r.rows[0] && r.rows[0].marca;
        return v ? new Date(v).toISOString() : '';
    } catch (error) {
        return '';
    }
}

async function escribirMarcaAguaDb(iso) {
    try {
        await pgQuery(
            `INSERT INTO licenciamiento_marca_agua (id, marca) VALUES (1, $1)
             ON CONFLICT (id) DO UPDATE SET marca = GREATEST(licenciamiento_marca_agua.marca, EXCLUDED.marca)`,
            [iso]
        );
    } catch (error) {
        // fail-open
    }
}

async function evaluarLicenciaCacheada(opciones) {
    const forzar = opciones && opciones.forzar;
    if (!forzar && _licenciaCache.valor && (Date.now() - _licenciaCache.ts) < 60000) {
        return _licenciaCache.valor;
    }
    let valor;
    try {
        const marcaDb = await leerMarcaAguaDb();
        valor = licenciamiento.estadoActual({ marcaExternaIso: marcaDb });
        licenciamiento.avanzarMarcaAgua(marcaDb);
        escribirMarcaAguaDb(valor.marcaAgua);
    } catch (error) {
        valor = { estado: 'ERROR', permiteCrearOrden: true, etiqueta: 'Licenciamiento no disponible', mensaje: '', diasRestantes: null, exp: null, cliente: '', tipo: '', relojDesfasado: false };
    }
    _licenciaCache = { ts: Date.now(), valor };
    return valor;
}

function invalidarLicenciaCache() {
    _licenciaCache = { ts: 0, valor: null };
}

app.get('/api/licenciamiento/estado', async (req, res) => {
    const est = await evaluarLicenciaCacheada({ forzar: true });
    res.json({
        estado: est.estado,
        etiqueta: est.etiqueta,
        mensaje: est.mensaje,
        diasRestantes: est.diasRestantes,
        exp: est.exp,
        cliente: est.cliente,
        tipo: est.tipo,
        permiteCrearOrden: est.permiteCrearOrden,
        relojDesfasado: est.relojDesfasado
    });
});

app.post('/api/licenciamiento/pastilla', async (req, res) => {
    const session = readErpSessionFromRequest(req);
    if (!session) return res.status(401).json({ ok: false, error: 'Sesión requerida.' });
    const token = String(req.body && req.body.token || '').trim();
    if (!token) return res.status(400).json({ ok: false, error: 'Falta la licencia.' });
    const r = licenciamiento.aplicarPastilla(token);
    if (!r.ok) return res.status(400).json({ ok: false, error: 'Licencia inválida (' + r.motivo + ').' });
    invalidarLicenciaCache();
    console.log('[licenciamiento] pastilla aplicada por', session.username || session.name || '-', '->', r.payload.exp);
    res.json({ ok: true, estado: await evaluarLicenciaCacheada({ forzar: true }) });
});

app.get('/api/licenciamiento/detalle', async (req, res) => {
    const session = readErpSessionFromRequest(req);
    if (!session || !isSuperAdminPermissionName(session.permissionName)) {
        return res.status(403).json({ ok: false, error: 'Solo un administrador puede ver el detalle.' });
    }
    const marcaDb = await leerMarcaAguaDb();
    res.json({ ok: true, detalle: licenciamiento.detalle({ marcaExternaIso: marcaDb }) });
});

// --------- Rescate (URL aparte, ingreso por desafío-respuesta con la llave del proveedor) ---------
// No hay ningún secreto almacenado en el servidor del cliente: la página muestra un
// desafío, el proveedor lo firma con su llave privada (en su generador, offline) y
// el servidor verifica la firma con la llave pública embebida.

const RESCATE_SESSION_SECRET = crypto.randomBytes(32);
const RESCATE_TOKEN_MS = 20 * 60 * 1000;
const RESCATE_DESAFIO_MS = 10 * 60 * 1000;
const desafiosRescate = new Map(); // desafío -> expiración ms (un solo uso)

const rescateLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 30,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Demasiados intentos. Intenta más tarde.' }
});

function comparaSegura(a, b) {
    const ba = Buffer.from(String(a));
    const bb = Buffer.from(String(b));
    if (ba.length !== bb.length) return false;
    return crypto.timingSafeEqual(ba, bb);
}

function emitirTokenRescate() {
    const exp = String(Date.now() + RESCATE_TOKEN_MS);
    const firma = crypto.createHmac('sha256', RESCATE_SESSION_SECRET).update(exp).digest('base64url');
    return Buffer.from(exp).toString('base64url') + '.' + firma;
}

function validarTokenRescate(token) {
    const m = String(token || '').split('.');
    if (m.length !== 2) return false;
    let exp;
    try { exp = Buffer.from(m[0], 'base64url').toString('utf8'); } catch (e) { return false; }
    const firma = crypto.createHmac('sha256', RESCATE_SESSION_SECRET).update(exp).digest('base64url');
    if (!comparaSegura(firma, m[1])) return false;
    return Number(exp) > Date.now();
}

function purgarDesafiosVencidos() {
    const ahora = Date.now();
    for (const [k, v] of desafiosRescate) { if (v < ahora) desafiosRescate.delete(k); }
}

function requireRescate(req, res, next) {
    const h = String(req.get('authorization') || '');
    const token = h.startsWith('Bearer ') ? h.slice(7) : String(req.get('x-rescate-token') || '');
    if (!validarTokenRescate(token)) return res.status(401).json({ ok: false, error: 'No autorizado.' });
    next();
}

app.get('/licencia/rescate', (req, res) => {
    res.sendFile(path.join(__dirname, 'licencia-rescate.html'));
});

app.get('/licencia/rescate/desafio', rescateLimiter, (req, res) => {
    purgarDesafiosVencidos();
    const desafio = 'PLR1-' + crypto.randomBytes(18).toString('base64url') + '-' + new Date().toISOString().slice(0, 10);
    desafiosRescate.set(desafio, Date.now() + RESCATE_DESAFIO_MS);
    res.json({ ok: true, desafio, validoSegundos: RESCATE_DESAFIO_MS / 1000 });
});

app.post('/licencia/rescate/login', rescateLimiter, (req, res) => {
    purgarDesafiosVencidos();
    const desafio = String(req.body && req.body.desafio || '');
    const respuesta = String(req.body && req.body.respuesta || '');
    const vigente = desafiosRescate.has(desafio) && desafiosRescate.get(desafio) >= Date.now();
    desafiosRescate.delete(desafio); // un solo uso, aun si falla
    if (!vigente) {
        licenciamiento.registrarIntentoRescate({ ok: false, ip: req.ip });
        return res.status(400).json({ ok: false, error: 'Desafío inválido o vencido. Genera uno nuevo.' });
    }
    const ok = licenciamiento.verificarFirmaProveedor(desafio, respuesta);
    licenciamiento.registrarIntentoRescate({ ok, ip: req.ip });
    if (!ok) return res.status(401).json({ ok: false, error: 'Firma inválida. Verifica que usaste la llave privada correcta.' });
    res.json({ ok: true, token: emitirTokenRescate() });
});

