// ─── FORGOT PASSWORD ───────────────────────────────────────────────────────
app.post('/api/auth/forgot-password', async (req, res) => {
    try {
        const username = sanitizeAdminUserText(req.body?.username).toLowerCase();
        if (!username) {
            return res.status(400).json({ error: 'Debes ingresar tu nombre de usuario.' });
        }
        if (username === 'admin' || username === 'administrador') {
            return res.status(400).json({ error: 'El usuario de emergencia no puede recuperar su contraseña por este medio.' });
        }
        const user = await findUserByUsername(username);
        if (!user) {
            return res.status(404).json({ error: 'Usuario no encontrado.' });
        }
        if (user.is_active === false) {
            return res.status(403).json({ error: 'Cuenta deshabilitada. Contacta al administrador.' });
        }
        if (!user.email) {
            return res.status(400).json({ error: 'Este usuario no tiene correo electrónico asignado. Contacte al administrador o a su jefatura para el cambio de contraseña.' });
        }
        const smtpConfig = await loadSmtpConfig();
        if (!smtpConfig || !smtpConfig.host || !smtpConfig.user || !smtpConfig.password || !smtpConfig.fromEmail) {
            return res.status(503).json({ error: 'El sistema no tiene configurado el servidor SMTP para envío de correos. Comuníquese con el administrador o con su jefatura para el cambio de contraseña.' });
        }
        const pin = await setResetPin(user.id);
        try {
            await sendPasswordResetPin(user, pin);
            await recordCredentialAudit({ userResponsible: username, userAffected: user.full_name, department: user.department, action: CREDENTIAL_ACTIONS.PIN_GENERATED, result: 'enviado_por_correo', ip: req.ip });
            return res.json({ ok: true, message: 'Se ha enviado un código de recuperación a tu correo electrónico.' });
        } catch (emailError) {
            console.error('Error enviando PIN por correo:', emailError.message);
            await recordCredentialAudit({ userResponsible: username, userAffected: user.full_name, department: user.department, action: CREDENTIAL_ACTIONS.PIN_GENERATED, result: 'correo_fallido', observations: emailError.message, ip: req.ip });
            return res.status(500).json({ error: 'No fue posible enviar el correo. Verifica la configuración SMTP o contacta al administrador.' });
        }
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible procesar la solicitud.' });
    }
});

// ─── ADMIN RESET PASSWORD (PIN generation) ─────────────────────────────────
app.post('/api/admin-users/:id/reset-password', async (req, res) => {
    try {
        const session = readErpSessionFromRequest(req);
        if (!session) return res.status(401).json({ error: 'Sesión no válida.' });
        const requester = await findUserByUsername(session.username);
        if (!requester || !isSuperAdminPermissionName(sanitizeAdminUserText(requester.permission_name))) {
            return res.status(403).json({ error: 'Solo administradores pueden restablecer contraseñas.' });
        }
        const userId = parseInt(req.params.id, 10);
        if (!userId) return res.status(400).json({ error: 'ID de usuario no válido.' });
        const user = await pgQuery(`SELECT id, full_name, email, username FROM admin_users WHERE id = $1`, [userId]);
        if (!user.rows.length) return res.status(404).json({ error: 'Usuario no encontrado.' });
        const target = user.rows[0];

        const { newPassword, forceOnly } = req.body || {};

        if (forceOnly) {
            // Opción B: no se toca la contraseña actual, solo se marca para que la cambie
            await pgQuery(`UPDATE admin_users SET must_change_password = TRUE, updated_at = NOW() WHERE id = $1`, [userId]);
            await recordCredentialAudit({ userResponsible: session.username, userAffected: target.full_name, action: CREDENTIAL_ACTIONS.CREDENTIALS_RESET, observations: 'Forzado sin nueva contraseña', ip: req.ip });
            return res.json({ ok: true, message: 'Se forzó el cambio de contraseña. El usuario deberá definir una nueva en su próximo inicio de sesión, usando la que ya tiene.' });
        }

        // Opción A: el admin fija la contraseña y se la entrega al usuario
        if (!newPassword) {
            return res.status(400).json({ error: 'Debes indicar la nueva contraseña o marcar la opción de solo forzar el cambio.' });
        }
        const passwordError = await validatePasswordPolicy(newPassword);
        if (passwordError) return res.status(400).json({ error: passwordError });

        const hashed = await hashPassword(newPassword);
        await pgQuery(`UPDATE admin_users SET password = $1, must_change_password = TRUE, updated_at = NOW() WHERE id = $2`, [hashed, userId]);
        await recordCredentialAudit({ userResponsible: session.username, userAffected: target.full_name, action: CREDENTIAL_ACTIONS.CREDENTIALS_RESET, ip: req.ip });
        try { await sendPasswordChangedNotification(target); } catch (_) {}

        res.json({ ok: true, message: 'Contraseña restablecida. Comunícasela al usuario; deberá definir una nueva en su próximo inicio de sesión.' });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible restablecer la contraseña.' });
    }
});

// ─── PIN DE ACCESO (login rápido, distinto del PIN de restablecer contraseña) ──────────
app.post('/api/admin-users/:id/pin-acceso', async (req, res) => {
    try {
        const session = readErpSessionFromRequest(req);
        if (!session) return res.status(401).json({ error: 'Sesión no válida.' });
        if (!(await tieneFacultadUsuarios(req, 'puedeAsignarPinAcceso'))) {
            return res.status(403).json({ error: 'Tu permiso no incluye asignar el PIN de acceso. Si lo necesitas, un administrador puede activarlo en tu permiso.' });
        }
        const userId = parseInt(req.params.id, 10);
        if (!userId) return res.status(400).json({ error: 'ID de usuario no válido.' });
        if (await bloqueaCambioSobreSuperAdmin(req, userId)) return res.status(403).json({ error: MENSAJE_USUARIO_PROTEGIDO });
        const user = await pgQuery(`SELECT id, full_name FROM admin_users WHERE id = $1`, [userId]);
        if (!user.rows.length) return res.status(404).json({ error: 'Usuario no encontrado.' });
        const target = user.rows[0];

        const pin = sanitizeAdminUserText(req.body?.pin);
        const resultado = await setAccesoPin(userId, pin);
        if (!resultado.ok) return res.status(400).json({ error: resultado.error });

        await recordCredentialAudit({ userResponsible: session.username, userAffected: target.full_name, action: CREDENTIAL_ACTIONS.CREDENTIALS_RESET, observations: 'PIN de acceso asignado', ip: req.ip });
        res.json({ ok: true, message: 'PIN de acceso asignado.' });
    } catch (error) {
        res.status(500).json({ error: error.message || 'No fue posible asignar el PIN de acceso.' });
    }
});

